const versets: VersetTexte[] = [
  { livre: `Psaumes`, chapitre: 1, verset: 1, texte: `Heureux, bienheureux est l’homme Qui ne cherche pas conseil auprès des gens en révolte, Qui ne s’en va pas flâner sur le sentier des pécheurs, Qui ne va pas s’installer en compagnie des moqueurs.` },
  { livre: `Psaumes`, chapitre: 1, verset: 2, texte: `Heureux, bienheureux celui Qui met sa joie, son bonheur dans le livre du Seigneur Et s’imprègne de ce livre nuit et jour, et jour et nuit.` },
  { livre: `Psaumes`, chapitre: 1, verset: 3, texte: `Il est ferme comme un arbre planté près d’un courant d’eau, Qui donne toujours son fruit quand vient le moment voulu, Et, sans cesse, sa ramure, sans se faner, refleurit. Tout ce qu’il a entrepris, il le réussit.` },
  { livre: `Psaumes`, chapitre: 1, verset: 4, texte: `Tels ne sont pas les méchants, Ils sont pareils à la balle éparpillée par le vent.` },
  { livre: `Psaumes`, chapitre: 1, verset: 5, texte: `Aussi, lors du jugement, ils ne subsisteront pas. Nul pécheur ne paraîtra au Rassemblement des justes` },
  { livre: `Psaumes`, chapitre: 1, verset: 6, texte: `Car le Seigneur prend en charge la voie suivie par les justes, Mais le sentier des méchants est un chemin sans issue.` },
  { livre: `Psaumes`, chapitre: 2, verset: 1, texte: `Pourquoi tant d’effervescence parmi les nations païennes? Et pourquoi donc trament-elles plans et complots insensés?` },
  { livre: `Psaumes`, chapitre: 2, verset: 2, texte: `Pourquoi les rois de la terre se sont-ils tous soulevés Et les grands conspirent-ils contre Dieu et son Messie?` },
  { livre: `Psaumes`, chapitre: 2, verset: 3, texte: `«Debout! clament-ils ensemble, Faisons sauter tous ces liens entravant nos libertés Et jetons au loin leur joug.»` },
  { livre: `Psaumes`, chapitre: 2, verset: 4, texte: `Mais, dans les cieux, sur son trône, Le Seigneur se moque d’eux et les tourne en dérision.` },
  { livre: `Psaumes`, chapitre: 2, verset: 5, texte: `À la fin, dans son courroux, Il les interpellera et les épouvantera, En les frappant de panique.` },
  { livre: `Psaumes`, chapitre: 2, verset: 6, texte: `(Indigné, il leur dira:) «J’ai choisi mon roi moi-même, C’est moi qui l’ai investi sur Sion, montagne sainte».` },
  { livre: `Psaumes`, chapitre: 2, verset: 7, texte: `Je publierai le décret immuable du Seigneur; «Le Seigneur m’a déclaré: “Tu es mon Fils. Aujourd’hui, je fais de toi mon enfant;` },
  { livre: `Psaumes`, chapitre: 2, verset: 8, texte: `Demande-moi: Que veux-tu? Je te donne en héritage tous les peuples de la terre, Tu seras leur souverain et le monde entier lui-même Jusqu’en ses confins lointains sera ta propriété.` },
  { livre: `Psaumes`, chapitre: 2, verset: 9, texte: `Tu mèneras rois et princes comme un berger son troupeau; Avec un sceptre d’airain, tu les réduiras; Comme un vase de potier, tu les briseras”».` },
  { livre: `Psaumes`, chapitre: 2, verset: 10, texte: `C’est pourquoi, rois de la terre, devenez intelligents, Vous qui gouvernez le monde, laissez-vous donc corriger.` },
  { livre: `Psaumes`, chapitre: 2, verset: 11, texte: `Dans la crainte et le respect, adorez et servez Dieu. Exultez en sa présence… mais en tremblant de respect.` },
  { livre: `Psaumes`, chapitre: 2, verset: 12, texte: `Au Fils, rendez votre hommage, sinon il s’irritera Et vous tous, vous périrez dans la voie que vous suivez. Car, promptement et bientôt, sa colère flambera. Heureux, bienheureux les hommes qui se réfugient en lui.` },
  { livre: `Psaumes`, chapitre: 3, verset: 0, texte: `Psaume de David, quand il fuyait devant son fils Absalom.` },
  { livre: `Psaumes`, chapitre: 3, verset: 1, texte: `Ô Éternel! Mes ennemis sont si nombreux! Mes adversaires se sont tous dressés contre moi!` },
  { livre: `Psaumes`, chapitre: 3, verset: 2, texte: `Se sont-ils donc multipliés ceux qui disent à mon sujet: «Maintenant Dieu, son Dieu lui-même, Ne fera rien, plus rien pour lui! Il n’a donc plus rien à attendre, il n’y a plus aucun salut»?` },
  { livre: `Psaumes`, chapitre: 3, verset: 3, texte: `Pourtant, Seigneur, mon défenseur, Toi qui m’entoures, toi qui es comme un bouclier qui me protège, Ô toi ma gloire et mon honneur, Tu me feras marcher encore la tête haute.` },
  { livre: `Psaumes`, chapitre: 3, verset: 4, texte: `À pleine voix, je crie vers toi, Et je t’appelle, ô mon Seigneur. Mon appel parvient jusqu’à toi, À ta montagne sainte, et tu m’exauceras.` },
  { livre: `Psaumes`, chapitre: 3, verset: 5, texte: `À présent, je peux me coucher et m’endormir l’esprit serein, Je me réveillerai en paix car le Seigneur est mon soutien.` },
  { livre: `Psaumes`, chapitre: 3, verset: 6, texte: `Je ne craindrai plus désormais Ces multitudes d’ennemis qui sont postés autour de moi, Ni les innombrables guerriers qui m’assaillent de tous côtés.` },
  { livre: `Psaumes`, chapitre: 3, verset: 7, texte: `Debout, Éternel, lève-toi! Au secours, mon Dieu, sauve-moi! C’est toi qui as toujours porté le coup fatal à l’ennemi Et qui as mis fin aux morsures des infidèles, des méchants.` },
  { livre: `Psaumes`, chapitre: 3, verset: 8, texte: `Du Seigneur seul vient le salut, La victoire lui appartient. Ô Éternel, fais reposer ta bénédiction sur les tiens.` },
  { livre: `Psaumes`, chapitre: 4, verset: 0, texte: `Dédié au chef de chœur. Un psaume de David à chanter avec accompagnement d’instruments à cordes.` },
  { livre: `Psaumes`, chapitre: 4, verset: 1, texte: `Ô Dieu, mon Sauveur, qui me fais justice, qui défends mon droit, Seigneur, réponds-moi lorsque je t’appelle. Tu m’as délivré de toute détresse. Tu as desserré les liens de l’angoisse: Mon cœur est au large. Ô Dieu, dans ta grâce, penche-toi vers moi. Pitié: je t’invoque, daigne m’écouter!` },
  { livre: `Psaumes`, chapitre: 4, verset: 2, texte: `Vous, les hommes, vous, les grands, Jusques à quand donc mépriserez-vous ma gloire, Bafouerez-vous mon honneur? Et jusques à quand poursuivrez-vous des mirages, Aimerez-vous le néant? Pourquoi donner votre cœur à des riens futiles? Pourquoi livrer vos pensées à des illusions?` },
  { livre: `Psaumes`, chapitre: 4, verset: 3, texte: `Sachez-le bien: Le Seigneur sait reconnaître celui qui lui est fidèle Et il comble de faveurs celui qui l’aime en son cœur. Oui, le Seigneur fait merveille: quand j’appelle, il m’entend.` },
  { livre: `Psaumes`, chapitre: 4, verset: 4, texte: `Tremblez et soyez troublés; Cessez de faire le mal. (Pécheurs,) rentrez en vous-mêmes, Laissez parler votre cœur Et faites silence en vous, Quand vous êtes sur vos lits.` },
  { livre: `Psaumes`, chapitre: 4, verset: 5, texte: `Offrez de vrais sacrifices Au Seigneur, d’un cœur sincère. Mettez en lui votre espoir.` },
  { livre: `Psaumes`, chapitre: 4, verset: 6, texte: `Nombreux sont ceux qui nous disent: «De qui viendra le bonheur?» Ô Seigneur! Illumine notre vie par la clarté de ta face.` },
  { livre: `Psaumes`, chapitre: 4, verset: 7, texte: `Tu mets dans mon cœur la joie, plus qu’ils n’en ont jamais eue Quand abondaient leurs moissons, quand coulait leur vin nouveau. Dans mon bonheur avec toi, je suis aussi comblé qu’eux.` },
  { livre: `Psaumes`, chapitre: 4, verset: 8, texte: `Je me couche dans la paix et, aussitôt, je m’endors; Car avec toi seul, Seigneur, mon esprit est en repos: Je suis en sécurité, grâce à toi, dans ma demeure.` },
  { livre: `Psaumes`, chapitre: 5, verset: 0, texte: `Dédié au chef de chœur. Un psaume de David à chanter avec accompagnement d’instruments à vent.` },
  { livre: `Psaumes`, chapitre: 5, verset: 1, texte: `Seigneur, Écoute mes paroles Et comprends mes soupirs.` },
  { livre: `Psaumes`, chapitre: 5, verset: 2, texte: `Ô toi, mon Roi, mon Dieu, écoute mon appel Et daigne être attentif à mon cri de détresse Car c’est toi que je prie!` },
  { livre: `Psaumes`, chapitre: 5, verset: 3, texte: `Seigneur, depuis l’aurore, tu écoutes ma voix, Car, dès le point du jour, je suis tendu vers toi, Prêt à te rencontrer. Je t’expose mes vœux, Puis je reste aux aguets.` },
  { livre: `Psaumes`, chapitre: 5, verset: 4, texte: `Car tu n’es pas un Dieu qui se plairait à voir Commettre des méfaits. Celui qui persévère dans la méchanceté Et qui se livre au mal ne sera pas reçu chez toi.` },
  { livre: `Psaumes`, chapitre: 5, verset: 5, texte: `Les insolents ne pourront pas soutenir ton regard perçant, Tu hais tous ceux qui font le mal,` },
  { livre: `Psaumes`, chapitre: 5, verset: 6, texte: `Tu extirpes tous les menteurs et les créateurs d’illusions. Les hommes sanguinaires et ceux qui trompent leur prochain Sont en horreur à l’Éternel.` },
  { livre: `Psaumes`, chapitre: 5, verset: 7, texte: `Par ta grâce infinie, je peux entrer dans ta maison. Avec le respect qui t’est dû, je m’incline en adoration Dans ton temple sacré.` },
  { livre: `Psaumes`, chapitre: 5, verset: 8, texte: `Aplanis mon chemin vers toi, ô Seigneur, et dirige-moi Afin que je puisse accomplir ce qui sera juste à tes yeux, Car tous mes ennemis m’épient et ils observent ma conduite.` },
  { livre: `Psaumes`, chapitre: 5, verset: 9, texte: `Mais, dans leurs propos, tout est faux Et rien n’est sûr dans leurs paroles. Leur cœur est un gouffre profond et ils ne pensent qu’à détruire. Aussi, quand ils ouvrent la bouche, on dirait que le tombeau s’ouvre, Leur langue se fait enjôleuse et distribue des flatteries.` },
  { livre: `Psaumes`, chapitre: 5, verset: 10, texte: `Ô Dieu, traite-les en coupables et fais échouer leurs projets. Par leurs machinations, qu’ils soient eux-mêmes attrapés, Et, pour leurs méfaits répétés, ô Dieu, qu’ils soient chassés Car ils se sont dressés contre toi et t’ont défié.` },
  { livre: `Psaumes`, chapitre: 5, verset: 11, texte: `En revanche, que tous ceux qui cherchent en toi leur abri Soient à jamais dans l’allégresse, car ils sont sous ta protection. Tu assureras leur victoire Et tous ceux qui aiment ton nom danseront pleins de joie.` },
  { livre: `Psaumes`, chapitre: 5, verset: 12, texte: `Car c’est toi, Éternel, Qui répands tes faveurs sur le juste et qui le bénis. Oui, tu le couvres de ta grâce comme d’un bouclier, Car tu l’entoures et le protèges du rempart de ta bienveillance.` },
  { livre: `Psaumes`, chapitre: 6, verset: 0, texte: `Au chef de chœur. Un psaume de David, à chanter avec accompagnement de harpes à huit cordes.` },
  { livre: `Psaumes`, chapitre: 6, verset: 1, texte: `Ô Seigneur, mon Dieu, malgré ta colère, ne me punis pas Et, dans ton courroux, ne me châtie pas.` },
  { livre: `Psaumes`, chapitre: 6, verset: 2, texte: `Ô Seigneur, mon Dieu, fais-moi voir ta grâce, car je suis sans force. Seigneur, guéris-moi: mes os sont brisés, mes membres tremblants.` },
  { livre: `Psaumes`, chapitre: 6, verset: 3, texte: `Mon être intérieur est en désarroi. Quand donc viendras-tu, Seigneur (pour m’aider)?` },
  { livre: `Psaumes`, chapitre: 6, verset: 4, texte: `Ne voudrais-tu pas revenir vers moi délivrer mon âme Et, dans ton amour, venir me sauver?` },
  { livre: `Psaumes`, chapitre: 6, verset: 5, texte: `Car ceux qui sont morts ne sont plus capables de parler de toi! Qui peut te louer au séjour des morts?` },
  { livre: `Psaumes`, chapitre: 6, verset: 6, texte: `Je suis épuisé, je gémis sans cesse et, toute la nuit, sur mon lit, Je pleure, ma couche est trempée, inondée de larmes,` },
  { livre: `Psaumes`, chapitre: 6, verset: 7, texte: `Mes yeux sont troublés, rougis de chagrin, ma vue a faibli. Par mes ennemis, j’ai beaucoup vieilli.` },
  { livre: `Psaumes`, chapitre: 6, verset: 8, texte: `Retirez-vous tous qui faites le mal! Le Seigneur entend l’appel de mes larmes.` },
  { livre: `Psaumes`, chapitre: 6, verset: 9, texte: `Le Seigneur exauce mes supplications. Le Seigneur accueille mon (humble) prière.` },
  { livre: `Psaumes`, chapitre: 6, verset: 10, texte: `Tous mes ennemis seront confondus et épouvantés, Ils lâcheront pied et reculeront tous subitement. D’un instant à l’autre, ils seront confus.` },
  { livre: `Psaumes`, chapitre: 7, verset: 0, texte: `Complainte de David qu’il chanta au Seigneur au sujet de ce que Cusch, le Benjaminite lui avait dit.` },
  { livre: `Psaumes`, chapitre: 7, verset: 1, texte: `Seigneur, mon Dieu. C’est en toi que j’ai mis ma confiance. Viens, sauve-moi de tous mes oppresseurs! Ils me poursuivent, viens me délivrer!` },
  { livre: `Psaumes`, chapitre: 7, verset: 2, texte: `Sinon mon âme sera déchirée, Lacérée comme la proie d’un lion. Elle sera broyée et mise en pièces Sans que quelqu’un vienne à son secours.` },
  { livre: `Psaumes`, chapitre: 7, verset: 3, texte: `Seigneur, mon Dieu, Si j’ai agi comme (on me le reproche), Si l’injustice est collée à mes mains,` },
  { livre: `Psaumes`, chapitre: 7, verset: 4, texte: `Si j’ai causé du tort à mon ami, Qui, plein de paix, ne voulait que mon bien Si même j’ai dépouillé l’adversaire Qui venait auprès de moi sans défense,` },
  { livre: `Psaumes`, chapitre: 7, verset: 5, texte: `Alors, que mon ennemi me poursuive, Qu’il me rattrape et me piétine à terre, Qu’il traîne mon honneur dans la poussière.` },
  { livre: `Psaumes`, chapitre: 7, verset: 6, texte: `Ô Seigneur, lève-toi dans ta colère, Contre la furie de mes adversaires! Réveille-toi et viens à mon secours, Veille à mes côtés et défends le droit Selon les lois que tu as établies!` },
  { livre: `Psaumes`, chapitre: 7, verset: 7, texte: `Autour de toi que les peuples s’assemblent, Siège au-dessus d’eux dans les lieux très hauts!` },
  { livre: `Psaumes`, chapitre: 7, verset: 8, texte: `Seigneur, toi qui es l’arbitre des peuples, Rends-moi justice, agis selon mon droit! Qu’il me soit fait selon mon innocence!` },
  { livre: `Psaumes`, chapitre: 7, verset: 9, texte: `Mets donc un terme aux méfaits des méchants! Que leurs ravages ne puissent plus nuire! Toi qui es juste et qui lis dans les cœurs, Soutiens le juste et rétablis son droit.` },
  { livre: `Psaumes`, chapitre: 7, verset: 10, texte: `Dieu est celui qui tient mon bouclier. Il sauve tous ceux dont le cœur est droit.` },
  { livre: `Psaumes`, chapitre: 7, verset: 11, texte: `Il est un Dieu puissant et redoutable, Il est juste, il fait sentir chaque jour Son indignation au pécheur coupable:` },
  { livre: `Psaumes`, chapitre: 7, verset: 12, texte: `À celui qui ne se convertit pas. (Que l’ennemi) affûte son épée, Qu’il tende l’arc et s’apprête à viser.` },
  { livre: `Psaumes`, chapitre: 7, verset: 13, texte: `S’il fabrique des engins meurtriers, S’il prépare des flèches enflammées,` },
  { livre: `Psaumes`, chapitre: 7, verset: 14, texte: `Et s’il ourdit un sinistre complot, S’il en conçoit tous les sombres détails, Finalement, il accouche d’un leurre.` },
  { livre: `Psaumes`, chapitre: 7, verset: 15, texte: `Il creuse en terre une fosse profonde, Mais, dans son piège, lui seul tombera.` },
  { livre: `Psaumes`, chapitre: 7, verset: 16, texte: `Son coup se retournera contre lui. Sa cruauté reviendra sur sa tête.` },
  { livre: `Psaumes`, chapitre: 7, verset: 17, texte: `Je louerai le Seigneur pour sa justice, Je chanterai le nom du Dieu très-haut.` },
  { livre: `Psaumes`, chapitre: 8, verset: 0, texte: `Au chef de chœur. Un psaume de David, à chanter avec accompagnement de la harpe de Gat.` },
  { livre: `Psaumes`, chapitre: 8, verset: 1, texte: `Éternel, notre Seigneur, que ton nom est admirable Dans l’univers tout entier! Tu revêts les cieux de ta majesté Et le firmament chante ta splendeur.` },
  { livre: `Psaumes`, chapitre: 8, verset: 2, texte: `Par la bouche des enfants et les cris de nouveau-nés Tu affirmes ta puissance, tu confonds tes détracteurs et imposes le silence à ceux qui, chargés de haine, se rebellent contre toi.` },
  { livre: `Psaumes`, chapitre: 8, verset: 3, texte: `Quand je contemple le ciel que tes doigts ont façonné, Les étoiles et la lune, que tes mains ont disposées,` },
  { livre: `Psaumes`, chapitre: 8, verset: 4, texte: `(Je me dis): «Qu’est-ce que l’homme, pour que tu en prennes soin? Qu’est-ce que le fils de l’homme pour que tu t’intéresses à lui?»` },
  { livre: `Psaumes`, chapitre: 8, verset: 5, texte: `Pourtant, tel que tu l’as fait, il lui manque peu: Un rien, pour qu’il soit égal à Dieu. De beauté, de dignité, d’honneur, tu l’as couronné.` },
  { livre: `Psaumes`, chapitre: 8, verset: 6, texte: `Tu lui donnes de régner sur les œuvres de tes mains. À ses pieds, tu as placé tout ce que tu as créé:` },
  { livre: `Psaumes`, chapitre: 8, verset: 7, texte: `Le bétail, gros ou petit, et les animaux sauvages,` },
  { livre: `Psaumes`, chapitre: 8, verset: 8, texte: `Et les oiseaux dans les airs et les poissons de la mer, Tous les êtres qui parcourent les sentiers des océans.` },
  { livre: `Psaumes`, chapitre: 8, verset: 9, texte: `Éternel, notre Seigneur que ton nom est admirable Dans l’univers tout entier!` },
  { livre: `Psaumes`, chapitre: 9, verset: 0, texte: `Un cantique de David dédié au chef de chœur, à chanter avec accompagnement de hautbois et de harpes.` },
  { livre: `Psaumes`, chapitre: 9, verset: 1, texte: `Je veux te remercier, Seigneur, et te louer de tout mon cœur, Je raconterai tes merveilles.` },
  { livre: `Psaumes`, chapitre: 9, verset: 2, texte: `En toi, j’exulte d’allégresse, oui, tu me fais danser de joie. Je veux chanter ton nom, ô Dieu, et le célébrer, ô Très-Haut.` },
  { livre: `Psaumes`, chapitre: 9, verset: 3, texte: `Mes ennemis font volte-face, ils fléchissent, ils vont tomber, Ils vont périr devant ta face: sous tes coups, ils vont trébucher.` },
  { livre: `Psaumes`, chapitre: 9, verset: 4, texte: `Car tu as pris en mains ma cause et tu as défendu mon droit, Quand tu es monté sur ton trône pour juger en toute équité.` },
  { livre: `Psaumes`, chapitre: 9, verset: 5, texte: `Tu as menacé les païens, tu as fait périr le méchant, Tu as rayé leur nom ignoble pour le temps et l’éternité.` },
  { livre: `Psaumes`, chapitre: 9, verset: 6, texte: `Plus d’ennemis! Ils sont ruinés à tout jamais Car tu as renversé leurs villes, le souvenir en est perdu.` },
  { livre: `Psaumes`, chapitre: 9, verset: 7, texte: `Le Seigneur siège pour toujours, il demeure éternellement. Déjà il a dressé son trône en prévision du jugement.` },
  { livre: `Psaumes`, chapitre: 9, verset: 8, texte: `C’est lui qui va juger le monde avec droiture et équité, Et qui va gouverner les peuples selon la justice et le droit.` },
  { livre: `Psaumes`, chapitre: 9, verset: 9, texte: `Le Seigneur sera le refuge des pauvres et des opprimés, Une retraite inexpugnable, un lieu fort au temps du danger.` },
  { livre: `Psaumes`, chapitre: 9, verset: 10, texte: `C’est pourquoi tous ceux qui connaissent ton nom se confient en toi. Car jamais, toi, tu ne délaisses ceux qui te recherchent, Seigneur.` },
  { livre: `Psaumes`, chapitre: 9, verset: 11, texte: `Chantez votre psaume au Seigneur, à celui qui trône en Sion, Et proclamez en son honneur parmi les peuples ses hauts faits.` },
  { livre: `Psaumes`, chapitre: 9, verset: 12, texte: `Car il poursuit les meurtriers; il en garde le souvenir, Et jamais il n’a oublié le cri plaintif des opprimés.` },
  { livre: `Psaumes`, chapitre: 9, verset: 13, texte: `Pitié, Seigneur! Vois la misère où m’ont réduit mes ennemis, C’est toi qui me fais remonter du seuil des portes de la mort` },
  { livre: `Psaumes`, chapitre: 9, verset: 14, texte: `Pour que je publie tes louanges aux portes de Jérusalem. Je chanterai ta délivrance, célébrant la joie du salut.` },
  { livre: `Psaumes`, chapitre: 9, verset: 15, texte: `Les païens tombent dans la fosse qu’eux-mêmes avaient creusée, Leurs pieds se prennent dans le piège qu’eux-mêmes avaient caché.` },
  { livre: `Psaumes`, chapitre: 9, verset: 16, texte: `Le Seigneur s’est fait reconnaître, il a rendu le jugement: Il a permis que l’infidèle soit pris dans son propre filet.` },
  { livre: `Psaumes`, chapitre: 9, verset: 17, texte: `Les méchants et les infidèles et les païens qui oublient Dieu Retournent au séjour des morts.` },
  { livre: `Psaumes`, chapitre: 9, verset: 18, texte: `Mais le malheureux ou le pauvre n’est pas pour toujours oublié, Et les espoirs des misérables ne sont pas à jamais déçus.` },
  { livre: `Psaumes`, chapitre: 9, verset: 19, texte: `Debout, Seigneur! Ne permets pas au mortel d’être le plus fort! Fais comparaître les nations pour les juger en ta présence!` },
  { livre: `Psaumes`, chapitre: 9, verset: 20, texte: `Inspire-leur, ô Éternel, la crainte et qu’ils en soient remplis, Qu’ils sachent qu’ils sont des mortels.` },
  { livre: `Psaumes`, chapitre: 10, verset: 1, texte: `Pourquoi, Seigneur, es-tu si loin? Pourquoi, Seigneur, te caches-tu aux jours d’angoisse?` },
  { livre: `Psaumes`, chapitre: 10, verset: 2, texte: `Le méchant se gonfle d’orgueil, persécutant les malheureux Qui se consument sous ses coups Et sont pris dans ses traquenards.` },
  { livre: `Psaumes`, chapitre: 10, verset: 3, texte: `Obsédé par sa convoitise, l’impie s’en glorifie. Le ravisseur se félicite d’avoir su exploiter autrui. Il nargue même le Seigneur.` },
  { livre: `Psaumes`, chapitre: 10, verset: 4, texte: `Le méchant, d’un visage hautain, déclare: «Dieu n’existe pas». Il ne va pas chercher plus loin, c’est là le fond de sa pensée.` },
  { livre: `Psaumes`, chapitre: 10, verset: 5, texte: `Il réussit dans ses affaires. Tes jugements sont bien trop hauts pour retenir son attention. Il se moque et n’a que mépris pour tous ceux qui lui tiennent tête.` },
  { livre: `Psaumes`, chapitre: 10, verset: 6, texte: `Il se dit: «Je ne risque rien, je suis à l’abri du malheur Et, pour toujours, inébranlable».` },
  { livre: `Psaumes`, chapitre: 10, verset: 7, texte: `Sa bouche ne fait que maudire, il est trompeur et violent, Sous sa langue inique fleurissent propos injurieux et blessants.` },
  { livre: `Psaumes`, chapitre: 10, verset: 8, texte: `Il est posté en embuscade aux endroits les plus écartés, Dans les hameaux et dans les fermes, pour assassiner l’innocent. Ses yeux épient les malheureux.` },
  { livre: `Psaumes`, chapitre: 10, verset: 9, texte: `Il se tapit dans sa cachette comme un lion dans son fourré; Il s’embusque dans sa retraite pour attaquer de pauvres gens, Et il surprend le malheureux en l’attirant dans son filet.` },
  { livre: `Psaumes`, chapitre: 10, verset: 10, texte: `Il s’accroupit en cachette, sournoisement, Pour retomber de tout son poids sur le faible et le misérable.` },
  { livre: `Psaumes`, chapitre: 10, verset: 11, texte: `Il se dit: «Dieu oubliera vite, il ne regarde pas par là; D’ailleurs, il ne voit jamais rien!»` },
  { livre: `Psaumes`, chapitre: 10, verset: 12, texte: `Debout Éternel, lève-toi! Dieu puissant, élève ta main, et n’oublie pas les malheureux!` },
  { livre: `Psaumes`, chapitre: 10, verset: 13, texte: `Pourquoi laisses-tu le méchant te narguer et te blasphémer? Pourquoi se dit-il en son cœur: «Dieu ne fait jamais rendre compte»?` },
  { livre: `Psaumes`, chapitre: 10, verset: 14, texte: `Pourtant, tu constates le mal, tu vois la peine et la souffrance, Tu veilles pour tout prendre en mains! Le faible s’abandonne à toi, tu viens en aide à l’orphelin.` },
  { livre: `Psaumes`, chapitre: 10, verset: 15, texte: `Brise la force de l’impie! Poursuis le crime de l’injuste, pour qu’on ne le retrouve plus!` },
  { livre: `Psaumes`, chapitre: 10, verset: 16, texte: `Le Seigneur est roi à jamais, Et tous les peuples idolâtres disparaîtront de son pays.` },
  { livre: `Psaumes`, chapitre: 10, verset: 17, texte: `Seigneur, d’une oreille attentive, tu écoutes les malheureux Et tu exauces leur désir. Tu leur redonnes du courage` },
  { livre: `Psaumes`, chapitre: 10, verset: 18, texte: `En faisant droit à l’orphelin, à l’opprimé, à l’exploité, Et pour qu’à jamais le mortel n’inspire plus l’effroi sur terre.` },
  { livre: `Psaumes`, chapitre: 11, verset: 1, texte: `Au chef de chœur. Un psaume de David. J’ai fait du Seigneur mon abri, pourquoi, alors, me répéter: «Prends ton vol, comme un passereau! Sauve-toi, fuis dans la montagne!»?` },
  { livre: `Psaumes`, chapitre: 11, verset: 2, texte: `Vois les méchants bander leur arc, Leur flèche est posée sur la corde pour tirer dans l’obscurité Sur ceux dont le cœur est honnête.` },
  { livre: `Psaumes`, chapitre: 11, verset: 3, texte: `Quand le régime est renversé, que peut faire l’homme loyal?` },
  { livre: `Psaumes`, chapitre: 11, verset: 4, texte: `Le Seigneur est dans son saint temple, Le Seigneur a son trône au ciel, Ses yeux sont ouverts sur le monde, son regard sonde les humains.` },
  { livre: `Psaumes`, chapitre: 11, verset: 5, texte: `Le Seigneur observe le juste, Mais il rejette le méchant et l’homme épris de violence.` },
  { livre: `Psaumes`, chapitre: 11, verset: 6, texte: `Il fait pleuvoir sur les méchants du charbon, du feu et du soufre. Il les expose au vent brûlant, voilà la part qu’il leur réserve.` },
  { livre: `Psaumes`, chapitre: 11, verset: 7, texte: `Car le Seigneur est un Dieu juste, un Dieu qui aime l’équité. Les hommes droits verront sa face.` },
  { livre: `Psaumes`, chapitre: 12, verset: 0, texte: `Au chef de chœur, un psaume de David à chanter avec accompagnement de la harpe à huit cordes.` },
  { livre: `Psaumes`, chapitre: 12, verset: 1, texte: `Au secours, Seigneur! Ceux qui t’aiment disparaissent. La fidélité a fui: On ne peut plus se fier À quelqu’un parmi les hommes.` },
  { livre: `Psaumes`, chapitre: 12, verset: 2, texte: `Chacun trompe son prochain, lui disant des flatteries, Et on parle à ses amis la duplicité au cœur.` },
  { livre: `Psaumes`, chapitre: 12, verset: 3, texte: `Que le Seigneur extermine toutes ces lèvres flatteuses, Et les langues arrogantes discourant avec orgueil.` },
  { livre: `Psaumes`, chapitre: 12, verset: 4, texte: `Qu’il retranche ceux qui disent: «Notre langue nous rend forts, Nos lèvres sont nos alliées, qui dominerait sur nous?»` },
  { livre: `Psaumes`, chapitre: 12, verset: 5, texte: `Mais le Seigneur leur répond: «J’ai vu toute la misère, L’oppression des malheureux, le gémissement des pauvres. Je me lèverai soudain, j’accorderai le salut À tous ceux qui l’attendaient et qui étaient méprisés».` },
  { livre: `Psaumes`, chapitre: 12, verset: 6, texte: `Les promesses du Seigneur sont des promesses sincères, C’est de l’argent affiné, sept fois purifié Au feu dans un creuset sur la terre.` },
  { livre: `Psaumes`, chapitre: 12, verset: 7, texte: `Toi, Seigneur, tu garderas tous ceux qui sont malheureux Et tu nous protégeras contre les gens de ce siècle.` },
  { livre: `Psaumes`, chapitre: 12, verset: 8, texte: `Car des méchants se démènent, paradant de tous côtés, Quand la bassesse domine parmi les enfants des hommes.` },
  { livre: `Psaumes`, chapitre: 13, verset: 1, texte: `Au chef de chœur, psaume de David.` },
  { livre: `Psaumes`, chapitre: 13, verset: 2, texte: `Jusques à quand, ô Éternel, m’oublieras-tu sans cesse? Jusques à quand cacheras-tu pour moi le regard de ta face?` },
  { livre: `Psaumes`, chapitre: 13, verset: 3, texte: `Jusques à quand devrai-je encore ressasser soucis et chagrins, Chaque jour vivre dans l’angoisse? Jusques à quand mon ennemi pourra-t-il triompher de moi?` },
  { livre: `Psaumes`, chapitre: 13, verset: 4, texte: `De grâce, Seigneur, réponds-moi, répands dans mes yeux ta clarté, Sinon je vais mourir.` },
  { livre: `Psaumes`, chapitre: 13, verset: 5, texte: `Sinon mon ennemi dira: «J’ai triomphé, je l’ai vaincu». Mes oppresseurs se réjouiront lorsqu’ils me verront chanceler.` },
  { livre: `Psaumes`, chapitre: 13, verset: 6, texte: `Pour moi, Seigneur, j’ai confiance en ton amour et ta bonté. Déjà, la joie remplit mon cœur à cause de ton (grand) salut. Je veux chanter à l’Éternel, car il m’a comblé de bienfaits.` },
  { livre: `Psaumes`, chapitre: 14, verset: 1, texte: `Au chef de chœur. De David. Ils sont fous, tous ceux qui pensent: «Dieu n’existe pas». Leur conduite est dégradante, ils sont corrompus. Il n’y a plus d’honnête homme, aucun n’agit bien.` },
  { livre: `Psaumes`, chapitre: 14, verset: 2, texte: `Du ciel, le Seigneur observe tout le genre humain: «Reste-t-il un homme sage et qui cherche Dieu?»` },
  { livre: `Psaumes`, chapitre: 14, verset: 3, texte: `Tous sont unis dans le mal, tous sont avilis, Il n’en reste plus d’honnête, même pas un seul.` },
  { livre: `Psaumes`, chapitre: 14, verset: 4, texte: `Ceux qui s’adonnent au vice et qui font le mal Sont-ils sans intelligence? N’ont-ils pas compris? Car ils dévorent mon peuple et mangent mon pain, Mais sans jamais m’invoquer comme leur Seigneur!»` },
  { livre: `Psaumes`, chapitre: 14, verset: 5, texte: `Les voilà pris d’épouvante, ils sont tout tremblants, Car Dieu est avec les justes pour les secourir.` },
  { livre: `Psaumes`, chapitre: 14, verset: 6, texte: `Pensez-vous pouvoir confondre l’espoir des petits? Le Seigneur est leur refuge.` },
  { livre: `Psaumes`, chapitre: 14, verset: 7, texte: `Il vient de Sion pour apporter le salut à (tout) Israël. Le Seigneur ramènera son peuple captif, Jacob criera d’allégresse, Israël, de joie.` },
  { livre: `Psaumes`, chapitre: 15, verset: 1, texte: `Psaume de David. Seigneur, qui peut séjourner dans ton sanctuaire? Seigneur, qui demeurera sur ta colline sacrée?` },
  { livre: `Psaumes`, chapitre: 15, verset: 2, texte: `Celui qui se conduit bien, qui pratique la justice, Qui dit avec loyauté ce qu’il pense dans son cœur,` },
  { livre: `Psaumes`, chapitre: 15, verset: 3, texte: `Qui sait gouverner sa langue et ne lèse pas son frère, N’insulte pas son prochain et ne lui fait pas de tort.` },
  { livre: `Psaumes`, chapitre: 15, verset: 4, texte: `Lui-même, il se sent indigne, il est petit à ses yeux, Mais il honore et estime ceux qui craignent le Seigneur. Il tient toujours sa parole même s’il doit en pâtir.` },
  { livre: `Psaumes`, chapitre: 15, verset: 5, texte: `Jamais, à un taux d’usure, il ne prête son argent. Il refuse qu’on l’achète pour accabler l’innocent. Qui se conduit de la sorte, ne chancellera jamais.` },
  { livre: `Psaumes`, chapitre: 16, verset: 1, texte: `Un chant de David. Ô (mon) Dieu, garde-moi! J’ai cherché en toi mon refuge, en toi, j’ai mis mon espérance.` },
  { livre: `Psaumes`, chapitre: 16, verset: 2, texte: `Je dis à l’Éternel: «Tu es mon maître et mon Seigneur, Tout mon bonheur réside en toi».` },
  { livre: `Psaumes`, chapitre: 16, verset: 3, texte: `Les saints de ce pays, ceux qui sont justes, Ceux qui sont pieux, sont l’objet de mon affection.` },
  { livre: `Psaumes`, chapitre: 16, verset: 4, texte: `On multiplie les dieux et l’on court après les idoles. On se précipite autour d’elles. Je ne prendrai pas part au culte qui leur est voué, Aux libations mêlées de sang. Jamais même leur nom ne sera trouvé dans ma bouche Et ne passera sur mes lèvres.` },
  { livre: `Psaumes`, chapitre: 16, verset: 5, texte: `Le Seigneur est ma part, Il est le calice où je bois, il est mon unique héritage.` },
  { livre: `Psaumes`, chapitre: 16, verset: 6, texte: `Tu fixes mon destin, tu m’assures un sort favorable: Tu tiens mon avenir en mains. La part que j’ai reçue est un enclos plein de délices, Mon héritage est le plus beau.` },
  { livre: `Psaumes`, chapitre: 16, verset: 7, texte: `Je bénis le Seigneur qui me conseille et qui me guide, Qui m’avertit même la nuit.` },
  { livre: `Psaumes`, chapitre: 16, verset: 8, texte: `Je garde constamment les yeux fixés sur l’Éternel, Il est toujours à mes côtés. Puisqu’il est près de moi, Je ne serai pas ébranlé, je ne chancellerai jamais.` },
  { livre: `Psaumes`, chapitre: 16, verset: 9, texte: `Mon cœur est dans la joie, mon âme exulte d’allégresse, Et mon corps lui-même repose dans la paix et la sécurité.` },
  { livre: `Psaumes`, chapitre: 16, verset: 10, texte: `Car tu n’abandonneras pas mon âme dans le séjour des morts; Tu ne permettras pas que ton ami, ton serviteur, Doive subir la corruption.` },
  { livre: `Psaumes`, chapitre: 16, verset: 11, texte: `Mais tu me montreras le chemin qui mène à la vie, Là où l’âme est rassasiée de joies. Face à face avec toi, on goûte des joies sans mesure, Un bonheur qui ne finira jamais.` },
  { livre: `Psaumes`, chapitre: 17, verset: 1, texte: `Prière de David. Seigneur, mon Dieu, toi qui es juste, Entends mon cri! Prête l’oreille à mon appel Jailli de lèvres vraies et sincères!` },
  { livre: `Psaumes`, chapitre: 17, verset: 2, texte: `Qu’en ta présence soit révélé Que je suis juste et dans mon droit. Tes yeux discernent l’intégrité.` },
  { livre: `Psaumes`, chapitre: 17, verset: 3, texte: `Que tu me sondes cœur et pensées, Que tu me suives même la nuit, Que tu m’éprouves dans ton creuset, Rien de honteux n’apparaîtra, Jamais ma bouche n’a proféré Des propos autres que mes pensées.` },
  { livre: `Psaumes`, chapitre: 17, verset: 4, texte: `Et quoi que fassent les autres hommes, Ma seule règle, c’est ta parole. Oui, j’ai suivi la bonne route En évitant les fausses voies des violents.` },
  { livre: `Psaumes`, chapitre: 17, verset: 5, texte: `Mes pas sont fermes dans tes sentiers, Je suis tes traces sans chanceler.` },
  { livre: `Psaumes`, chapitre: 17, verset: 6, texte: `Dieu, je t’appelle car tu m’entends. Prête l’oreille, écoute-moi!` },
  { livre: `Psaumes`, chapitre: 17, verset: 7, texte: `Fais resplendir l’immensité de ta bonté. Toi qui délivres des assaillants ceux qui s’abritent sous ta droite.` },
  { livre: `Psaumes`, chapitre: 17, verset: 8, texte: `Veille sur moi comme tu veilles sur la prunelle de tes deux yeux, Et, sous tes ailes, abrite-moi` },
  { livre: `Psaumes`, chapitre: 17, verset: 9, texte: `Loin des coupables qui m’ont pillé, Des adversaires qui m’environnent et s’acharnent contre mon âme!` },
  { livre: `Psaumes`, chapitre: 17, verset: 10, texte: `Leur embonpoint les endurcit Et leurs richesses ferment leur cœur. Leur bouche parle avec hauteur.` },
  { livre: `Psaumes`, chapitre: 17, verset: 11, texte: `Ils me poursuivent; à chaque pas, ils se rapprochent et les voilà: Leurs yeux me fixent car ils voudraient me terrasser.` },
  { livre: `Psaumes`, chapitre: 17, verset: 12, texte: `Ils sont semblables à un lion, la gueule ouverte, prêt à tuer. Ou à des fauves en embuscade dans leur fourré.` },
  { livre: `Psaumes`, chapitre: 17, verset: 13, texte: `Oh! Viens, Seigneur, affronte-les! Courbe leur nuque, et, par ton glaive, délivre-moi! Sauve mon âme de ces méchants!` },
  { livre: `Psaumes`, chapitre: 17, verset: 14, texte: `Par ta puissance, ô, mon Seigneur, protège-moi contre ces hommes! Ils sont esclaves de cette vie, les joies du monde, voilà leur part, Car tu les combles de tous tes biens. Ils s’en repaissent, eux et leurs fils, Et ils les laissent aux descendants.` },
  { livre: `Psaumes`, chapitre: 17, verset: 15, texte: `Moi, par ta grâce, justifié, je vois ta face; À mon réveil, de ton visage, à satiété, je jouirai.` },
  { livre: `Psaumes`, chapitre: 18, verset: 0, texte: `Au chef de chœur; de David, serviteur du Seigneur. Il dédia au Seigneur les paroles de ce cantique le jour où le Seigneur l’a délivré du pouvoir de tous ses ennemis et de la main de Saül.` },
  { livre: `Psaumes`, chapitre: 18, verset: 1, texte: `Je t’aime, ô Éternel, ma force!` },
  { livre: `Psaumes`, chapitre: 18, verset: 2, texte: `Le Seigneur est ma forteresse, mon rocher, mon libérateur. Il est mon Dieu, le roc solide sur lequel je peux m’appuyer. Il est mon Sauveur tout-puissant, mon rempart et mon bouclier.` },
  { livre: `Psaumes`, chapitre: 18, verset: 3, texte: `Dès que j’ai loué le Seigneur, j’ai vaincu tous mes ennemis.` },
  { livre: `Psaumes`, chapitre: 18, verset: 4, texte: `Les flots de la mort et ses vagues m’enveloppaient de tous côtés, Les torrents sournois de l’abîme m’avaient surpris et terrifié,` },
  { livre: `Psaumes`, chapitre: 18, verset: 5, texte: `Le séjour des morts m’entourait de ses liens; J’avais devant moi, déjà, les filets de la mort.` },
  { livre: `Psaumes`, chapitre: 18, verset: 6, texte: `J’invoquai Dieu dans ma détresse, vers lui j’ai lancé mon appel. Mon cri parvint à ses oreilles, dans son temple, il m’a entendu.` },
  { livre: `Psaumes`, chapitre: 18, verset: 7, texte: `Soudain, la terre oscille et tremble, Ses fondements sont ébranlés et secoués par sa colère.` },
  { livre: `Psaumes`, chapitre: 18, verset: 8, texte: `Fumées et tourbillons de flammes jaillissent hors de ses narines, Sa bouche lance des éclairs et des charbons incandescents.` },
  { livre: `Psaumes`, chapitre: 18, verset: 9, texte: `Il descend, et les cieux s’inclinent, l’obscurité est à ses pieds.` },
  { livre: `Psaumes`, chapitre: 18, verset: 10, texte: `Un chérubin est sa monture, il vole sur l’aile du vent.` },
  { livre: `Psaumes`, chapitre: 18, verset: 11, texte: `Il s’enveloppe de ténèbres et se cache dans leurs replis, Dans l’obscurité de la pluie et dans des nuages opaques.` },
  { livre: `Psaumes`, chapitre: 18, verset: 12, texte: `Devant l’éclat de sa présence, s’allument de brillants éclairs, Ses nuées viennent et déferlent, lançant grêle et gerbes de feu.` },
  { livre: `Psaumes`, chapitre: 18, verset: 13, texte: `Au ciel, déchaînant la tempête, la foudre de Dieu retentit, La voix du Dieu très-haut résonne parmi la grêle et dans le feu.` },
  { livre: `Psaumes`, chapitre: 18, verset: 14, texte: `Soudain, il décoche ses flèches pour disperser mes ennemis. Au milieu d’un terrible orage, l’ennemi fuit de tous côtés.` },
  { livre: `Psaumes`, chapitre: 18, verset: 15, texte: `Alors, les fonds des eaux paraissent, ceux de la terre sont à nu, Seigneur, à ta voix menaçante, au souffle de ton ouragan.` },
  { livre: `Psaumes`, chapitre: 18, verset: 16, texte: `Du ciel, sa main vient pour me prendre, Me retirer des grandes eaux,` },
  { livre: `Psaumes`, chapitre: 18, verset: 17, texte: `M’arracher à mes adversaires, à mes rivaux plus forts que moi.` },
  { livre: `Psaumes`, chapitre: 18, verset: 18, texte: `Ils m’attendaient au jour néfaste, mais le Seigneur fut mon appui.` },
  { livre: `Psaumes`, chapitre: 18, verset: 19, texte: `Il m’a délivré de l’angoisse, il m’a sauvé car il m’aimait.` },
  { livre: `Psaumes`, chapitre: 18, verset: 20, texte: `Oui, le Seigneur a bien voulu me traiter selon sa justice, Il a vu que mes mains sont pures, le Seigneur m’a récompensé.` },
  { livre: `Psaumes`, chapitre: 18, verset: 21, texte: `Car, à ses voies, je suis fidèle, je ne délaisse pas mon Dieu.` },
  { livre: `Psaumes`, chapitre: 18, verset: 22, texte: `Ses lois sont toujours sous mes yeux, je n’écarte pas ses statuts.` },
  { livre: `Psaumes`, chapitre: 18, verset: 23, texte: `Envers lui, je suis sans reproche, je me suis gardé du péché.` },
  { livre: `Psaumes`, chapitre: 18, verset: 24, texte: `Le Seigneur a vu ma droiture, mes mains pures devant ses yeux.` },
  { livre: `Psaumes`, chapitre: 18, verset: 25, texte: `Au fidèle, à celui qui t’aime, tu témoignes tout ton amour. À tes amis droits et sincères, tu offres ta sincérité.` },
  { livre: `Psaumes`, chapitre: 18, verset: 26, texte: `Pour les cœurs aux intentions pures, tu es loyal et transparent. Mais à l’homme aux pensées perverses, tu lui rends sa perversité.` },
  { livre: `Psaumes`, chapitre: 18, verset: 27, texte: `Car tu sauves ceux qui sont humbles, Tu abaisses les yeux hautains.` },
  { livre: `Psaumes`, chapitre: 18, verset: 28, texte: `Celui qui fait briller ma lampe, C’est le Seigneur, c’est toi, mon Dieu. Tu fais resplendir mes ténèbres, scintiller mon obscurité.` },
  { livre: `Psaumes`, chapitre: 18, verset: 29, texte: `Avec toi, je me précipite sur une troupe bien armée, Par toi, je franchis des murailles.` },
  { livre: `Psaumes`, chapitre: 18, verset: 30, texte: `Les voies de Dieu sont sans reproche, Et sa parole est infaillible comme un métal passé au feu. Ceux qui le prennent pour refuge trouvent en lui un bouclier.` },
  { livre: `Psaumes`, chapitre: 18, verset: 31, texte: `Qui est Dieu, sinon le Seigneur? Qui est un Roc? C’est notre Dieu!` },
  { livre: `Psaumes`, chapitre: 18, verset: 32, texte: `Dieu me remplit de sa vaillance, il me trace un chemin parfait.` },
  { livre: `Psaumes`, chapitre: 18, verset: 33, texte: `Par lui, je cours comme une biche, j’accède à des lieux élevés.` },
  { livre: `Psaumes`, chapitre: 18, verset: 34, texte: `Il dresse mes mains pour combattre, Mes bras pour bander l’arc de bronze.` },
  { livre: `Psaumes`, chapitre: 18, verset: 35, texte: `Ton bouclier est ma victoire, ta droite est là qui me soutient. Je suis fort par ta bienveillance.` },
  { livre: `Psaumes`, chapitre: 18, verset: 36, texte: `Avec toi, sûrement, j’avance, mes jambes ne fléchissent pas.` },
  { livre: `Psaumes`, chapitre: 18, verset: 37, texte: `Je pourchasse mes adversaires, je les rattrape et les détruis.` },
  { livre: `Psaumes`, chapitre: 18, verset: 38, texte: `Je frappe: aucun ne se relève, ils sont étendus sous mes pieds.` },
  { livre: `Psaumes`, chapitre: 18, verset: 39, texte: `C’est toi qui me ceins de puissance, tu fais plier mes agresseurs.` },
  { livre: `Psaumes`, chapitre: 18, verset: 40, texte: `Tu mets mes ennemis en fuite, ceux qui m’en veulent sont perdus.` },
  { livre: `Psaumes`, chapitre: 18, verset: 41, texte: `Ils crient, mais n’ont point de Sauveur; Le Seigneur ne leur répond pas.` },
  { livre: `Psaumes`, chapitre: 18, verset: 42, texte: `Je les broie, les réduis en poudre, Je les balaie comme la boue.` },
  { livre: `Psaumes`, chapitre: 18, verset: 43, texte: `En face d’un peuple en révolte, C’est toi qui me fais triompher, Tu m’établis chef des nations, Des inconnus me sont soumis.` },
  { livre: `Psaumes`, chapitre: 18, verset: 44, texte: `Au premier mot, ils m’obéissent, Des étrangers forment ma cour;` },
  { livre: `Psaumes`, chapitre: 18, verset: 45, texte: `Les fils de l’étranger me flattent, Quittant tout tremblants leurs bastions.` },
  { livre: `Psaumes`, chapitre: 18, verset: 46, texte: `Dieu est vivant! À lui la gloire et que mon rocher soit béni! Que mon Sauveur soit exalté!` },
  { livre: `Psaumes`, chapitre: 18, verset: 47, texte: `Ce Dieu m’accorde ma revanche, Il soumet à mon joug des peuples.` },
  { livre: `Psaumes`, chapitre: 18, verset: 48, texte: `Des ennemis, tu me délivres, Tu me sauves des agresseurs, Tu m’arraches aux violents.` },
  { livre: `Psaumes`, chapitre: 18, verset: 49, texte: `Aussi je publie tes louanges, Ô Seigneur, parmi les nations, Et je veux célébrer ton nom.` },
  { livre: `Psaumes`, chapitre: 18, verset: 50, texte: `Tu multiplies les délivrances Et les victoires de ton roi. Tu témoignes ta bienveillance À celui qui t’est consacré, À David et sa descendance, Pour toujours, pour l’éternité.` },
  { livre: `Psaumes`, chapitre: 19, verset: 0, texte: `Au chef de chœur. Cantique de David.` },
  { livre: `Psaumes`, chapitre: 19, verset: 1, texte: `Les cieux magnifient la gloire du Dieu fort (du Créateur). L’œuvre de ses mains éclate partout dans le firmament.` },
  { livre: `Psaumes`, chapitre: 19, verset: 2, texte: `La connaissance en ruisselle d’un jour jusqu’à l’autre jour. La nuit à la nuit révèle ce qu’elle a appris (de lui).` },
  { livre: `Psaumes`, chapitre: 19, verset: 3, texte: `Ce ne sont pas des paroles, ce ne sont point des discours, Ni des voix qu’on puisse entendre.` },
  { livre: `Psaumes`, chapitre: 19, verset: 4, texte: `Pourtant, leur rythme est perçu jusqu’aux confins de la terre Et leurs accents harmonieux résonnent dans l’univers. Là où Dieu dresse une tente d’où s’élance le soleil` },
  { livre: `Psaumes`, chapitre: 19, verset: 5, texte: `Pareil à un jeune époux qui sort, joyeux, de sa chambre, À un champion qui s’avance, heureux de prendre la course.` },
  { livre: `Psaumes`, chapitre: 19, verset: 6, texte: `Tout à l’orient, il se lève, Et sa course se prolonge jusqu’au seuil de l’horizon. Il n’est rien qui se dérobe à l’ardeur de ses rayons.` },
  { livre: `Psaumes`, chapitre: 19, verset: 7, texte: `La loi de Dieu est parfaite, elle restaure notre âme. Son témoignage est certain, il instruit les ignorants.` },
  { livre: `Psaumes`, chapitre: 19, verset: 8, texte: `Ses ordonnances sont justes, elles font la joie du cœur; Et ses ordres sont limpides, ils font briller le regard.` },
  { livre: `Psaumes`, chapitre: 19, verset: 9, texte: `La crainte de Dieu est pure, elle subsiste à jamais. Les décrets de Dieu sont fermes, ils sont justes tous ensemble.` },
  { livre: `Psaumes`, chapitre: 19, verset: 10, texte: `Ils sont bien plus désirables que beaucoup de lingots d’or. Et beaucoup plus savoureux que le miel, le miel nouveau!` },
  { livre: `Psaumes`, chapitre: 19, verset: 11, texte: `Ton serviteur s’en pénètre, il en reçoit instruction. Il veut les mettre en pratique, il y trouve un grand profit.` },
  { livre: `Psaumes`, chapitre: 19, verset: 12, texte: `Qui reconnaît ses faux pas? De mes fautes inconscientes et cachées, acquitte-moi.` },
  { livre: `Psaumes`, chapitre: 19, verset: 13, texte: `Mets aussi ton serviteur à l’abri des orgueilleux, Qu’ils n’aient sur moi pas d’emprise. Alors, je serai intègre, innocent de grands péchés.` },
  { livre: `Psaumes`, chapitre: 19, verset: 14, texte: `Veuille agréer mes paroles, Reçois favorablement les sentiments de mon cœur, Ô Éternel, mon rocher, Seigneur, mon libérateur.` },
  { livre: `Psaumes`, chapitre: 20, verset: 0, texte: `Au chef de chœur. Cantique de David.` },
  { livre: `Psaumes`, chapitre: 20, verset: 1, texte: `Que l’Éternel t’exauce quand tu es en danger, Et que ta forteresse soit le nom de ton Dieu, Ce nom: Dieu de Jacob.` },
  { livre: `Psaumes`, chapitre: 20, verset: 2, texte: `Que, de son sanctuaire, il t’envoie du secours, Et que, depuis Sion, il t’offre son soutien.` },
  { livre: `Psaumes`, chapitre: 20, verset: 3, texte: `Qu’il garde en sa mémoire tes offrandes, tes dons, Et que tes holocaustes soient agréés par lui.` },
  { livre: `Psaumes`, chapitre: 20, verset: 4, texte: `Ce que ton cœur souhaite, puisse-t-il l’accorder! Et ce que tu projettes, qu’il veuille l’accomplir!` },
  { livre: `Psaumes`, chapitre: 20, verset: 5, texte: `Pour fêter ta victoire, nous chanterons de joie, Déployant nos bannières au nom de notre Dieu. Que le Seigneur exauce pleinement tous tes vœux!` },
  { livre: `Psaumes`, chapitre: 20, verset: 6, texte: `Je le sais, à cette heure: Dieu soutient son Messie,` },
  { livre: `Psaumes`, chapitre: 20, verset: 7, texte: `Il exauce ses vœux de sa sainte demeure Par le secours puissant de son bras qui délivre. Aux uns, les chars de guerre, aux autres, les chevaux. Nous, notre confiance est dans le nom de Dieu, Nous nous en souvenons.` },
  { livre: `Psaumes`, chapitre: 20, verset: 8, texte: `Ils fléchissent, ils tombent, Et nous restons debout.` },
  { livre: `Psaumes`, chapitre: 20, verset: 9, texte: `Oui, donne la victoire à notre roi, Seigneur, Et veuille le sauver! Réponds-nous et exauce lorsque nous t’invoquons!` },
  { livre: `Psaumes`, chapitre: 21, verset: 0, texte: `Au chef de chœur. Cantique de David.` },
  { livre: `Psaumes`, chapitre: 21, verset: 1, texte: `Seigneur, le roi se réjouit de ta (grande) puissance; Devant ton œuvre de salut, il exulte de joie.` },
  { livre: `Psaumes`, chapitre: 21, verset: 2, texte: `Tu as pleinement satisfait le désir de son cœur, Tu ne lui as pas refusé ce qu’il te demandait.` },
  { livre: `Psaumes`, chapitre: 21, verset: 3, texte: `Tu as prévenu ses souhaits par des bénédictions. Sur sa tête, tu as posé une couronne d’or.` },
  { livre: `Psaumes`, chapitre: 21, verset: 4, texte: `Il t’avait demandé la vie, tu la lui as donnée Et tu vas prolonger ses jours jusqu’en l’éternité.` },
  { livre: `Psaumes`, chapitre: 21, verset: 5, texte: `Par ta victoire et ton appui, sa gloire s’est accrue, Grâce à toi, il est revêtu de splendeur et d’honneur.` },
  { livre: `Psaumes`, chapitre: 21, verset: 6, texte: `Tu fais de lui la source de bénédictions éternelles. Tu combles son bonheur par la clarté de ta présence.` },
  { livre: `Psaumes`, chapitre: 21, verset: 7, texte: `Car le roi met sa confiance en l’Éternel, son Dieu, Protégé par sa bienveillance, il ne chancelle pas.` },
  { livre: `Psaumes`, chapitre: 21, verset: 8, texte: `Tu vas frapper tes ennemis, atteindre tes rivaux.` },
  { livre: `Psaumes`, chapitre: 21, verset: 9, texte: `Ils seront dans une fournaise quand tu apparaîtras. Dans sa colère, le Seigneur les consumera tous.` },
  { livre: `Psaumes`, chapitre: 21, verset: 10, texte: `Tu extirperas de la terre les fils de leurs enfants. Tu vas rayer leur descendance d’entre les fils d’Adam.` },
  { livre: `Psaumes`, chapitre: 21, verset: 11, texte: `Ils ont conçu des plans perfides, ils seront impuissants!` },
  { livre: `Psaumes`, chapitre: 21, verset: 12, texte: `Tu les réduis à la déroute, Et tu vises leur cœur, ton arc les atteindra.` },
  { livre: `Psaumes`, chapitre: 21, verset: 13, texte: `Triomphe, Seigneur, par ta force! Par nos chants et nos hymnes, Nous célébrerons ta vaillance, nous louerons tes hauts faits.` },
  { livre: `Psaumes`, chapitre: 22, verset: 0, texte: `Au chef de chœur. Psaume de David. Sur l’air de «Biche de l’aurore».` },
  { livre: `Psaumes`, chapitre: 22, verset: 1, texte: `Mon Dieu, mon Dieu, pourquoi m’as-tu abandonné? Que tu es loin! Sourd à tous mes gémissements, Pourquoi, mon Dieu, ne viens-tu pas me secourir?` },
  { livre: `Psaumes`, chapitre: 22, verset: 2, texte: `Pendant le jour, j’appelle: tu ne réponds pas. Je crie, la nuit, sans trouver le moindre répit.` },
  { livre: `Psaumes`, chapitre: 22, verset: 3, texte: `N’es-tu pas saint, toi qui règnes en ton sanctuaire Environné de la louange d’Israël?` },
  { livre: `Psaumes`, chapitre: 22, verset: 4, texte: `En toi aussi, nos pères ont mis leur confiance. Tu as été celui qui les a délivrés.` },
  { livre: `Psaumes`, chapitre: 22, verset: 5, texte: `Ils ont crié vers toi, ils ont été sauvés, Ils ont compté sur toi: aucun ne fut déçu.` },
  { livre: `Psaumes`, chapitre: 22, verset: 6, texte: `Cependant moi, je suis un ver et non un homme, La dérision, l’opprobre des humains, Le méprisé, rejeté par le peuple.` },
  { livre: `Psaumes`, chapitre: 22, verset: 7, texte: `Lorsqu’on me voit, on se moque de moi. On fait la moue en secouant la tête:` },
  { livre: `Psaumes`, chapitre: 22, verset: 8, texte: `«Fie-toi à Dieu, compte sur le Seigneur! Que celui-ci le libère et le sauve puisqu’il est son ami».` },
  { livre: `Psaumes`, chapitre: 22, verset: 9, texte: `Oui, c’est bien toi qui, depuis ma naissance, m’as protégé. Tu m’as mis en sécurité près de ma mère, tout contre sa poitrine.` },
  { livre: `Psaumes`, chapitre: 22, verset: 10, texte: `Dès mon jeune âge, j’ai été placé sous ta garde Et depuis ma naissance, tu es mon Dieu.` },
  { livre: `Psaumes`, chapitre: 22, verset: 11, texte: `Ne reste pas si loin de moi, car l’angoisse m’étreint, Et personne ne vient pour m’aider ou me secourir.` },
  { livre: `Psaumes`, chapitre: 22, verset: 12, texte: `De nombreux taureaux m’environnent. Les fortes bêtes de Basan sont tout autour de moi.` },
  { livre: `Psaumes`, chapitre: 22, verset: 13, texte: `Ils ouvrent largement leurs mufles contre moi, Ils sont comme un lion qui déchire et rugit.` },
  { livre: `Psaumes`, chapitre: 22, verset: 14, texte: `Je suis comme une eau qui s’écoule, tous mes os se sont disjoints. Mon cœur est pareil à la cire, on dirait qu’il se fond en moi.` },
  { livre: `Psaumes`, chapitre: 22, verset: 15, texte: `Ma force est desséchée comme un tesson d’argile, Ma langue colle à mon palais, Tu me fais retourner à la poussière de la mort.` },
  { livre: `Psaumes`, chapitre: 22, verset: 16, texte: `Des hordes de chiens m’environnent, La meute des méchants m’assaille. Ils ont percé mes mains, mes pieds,` },
  { livre: `Psaumes`, chapitre: 22, verset: 17, texte: `Je pourrais compter tous mes os; ils me regardent, ils me toisent,` },
  { livre: `Psaumes`, chapitre: 22, verset: 18, texte: `Ils se partagent mes habits et tirent au sort ma tunique.` },
  { livre: `Psaumes`, chapitre: 22, verset: 19, texte: `Mais toi, Seigneur, ne reste pas si loin! Viens vite à mon secours!` },
  { livre: `Psaumes`, chapitre: 22, verset: 20, texte: `Sauve ma vie, arrache-la au glaive! Protège-moi de la fureur des chiens!` },
  { livre: `Psaumes`, chapitre: 22, verset: 21, texte: `Délivre-moi du lion, de sa gueule! Préserve-moi des cornes des taureaux! Oui, tu m’as répondu!` },
  { livre: `Psaumes`, chapitre: 22, verset: 22, texte: `Je dirai à mes frères la gloire de ton nom, Je te célébrerai dans la grande assemblée.` },
  { livre: `Psaumes`, chapitre: 22, verset: 23, texte: `Vous tous qui craignez Dieu, célébrez-le! Descendants de Jacob, honorez-le! Descendants d’Israël, vénérez-le!` },
  { livre: `Psaumes`, chapitre: 22, verset: 24, texte: `Il n’a pas méprisé l’humiliation du pauvre, il n’a pas détourné devant lui son visage, mais il a écouté le cri lancé vers lui.` },
  { livre: `Psaumes`, chapitre: 22, verset: 25, texte: `À toi soit ma louange dans la grande assemblée, J’accomplirai mes vœux devant ceux qui t’adorent.` },
  { livre: `Psaumes`, chapitre: 22, verset: 26, texte: `Les malheureux, les humbles sont rassasiés de biens, Tous ceux qui cherchent Dieu chanteront ses louanges. Que votre cœur vive à toujours!` },
  { livre: `Psaumes`, chapitre: 22, verset: 27, texte: `Aux confins de la terre, on pensera à Dieu. Tous les peuples du monde se tourneront vers lui, Et toutes les nations viendront se prosterner un jour devant ta face.` },
  { livre: `Psaumes`, chapitre: 22, verset: 28, texte: `Car c’est à l’Éternel qu’appartiendra le règne, Lui seul dominera sur toutes les nations.` },
  { livre: `Psaumes`, chapitre: 22, verset: 29, texte: `Tous les grands de la terre, Après avoir mangé, ont dû se prosterner. Ceux qui vont vers la tombe Avec leur vie précaire se courbent devant lui.` },
  { livre: `Psaumes`, chapitre: 22, verset: 30, texte: `Mais la postérité servira le Seigneur Et parlera de lui à la génération qui viendra après elle.` },
  { livre: `Psaumes`, chapitre: 22, verset: 31, texte: `Cette postérité publiera sa justice Et elle annoncera au peuple qui naîtra les hauts faits du Seigneur.` },
  { livre: `Psaumes`, chapitre: 23, verset: 1, texte: `Psaume de David. L’Éternel est mon Berger! Je ne manquerai de rien.` },
  { livre: `Psaumes`, chapitre: 23, verset: 2, texte: `Il me laisse reposer sur des gazons verdoyants. Il me conduit avec soin tout au long des eaux tranquilles.` },
  { livre: `Psaumes`, chapitre: 23, verset: 3, texte: `Il restaure la santé et les forces de mon âme, Et, pour l’honneur de son nom, Il me mène pas à pas dans le bon chemin.` },
  { livre: `Psaumes`, chapitre: 23, verset: 4, texte: `Quand je devrai traverser La vallée obscure où plane l’ombre de la mort, Je ne craindrai aucun mal Car tu seras près de moi, ton bâton me guidera, Ta houlette de berger me rassurera!` },
  { livre: `Psaumes`, chapitre: 23, verset: 5, texte: `Pour moi, tu dresses une table au vu de mes ennemis, Tu oins de parfums ma tête et ma coupe est débordante.` },
  { livre: `Psaumes`, chapitre: 23, verset: 6, texte: `Oui, le bonheur et la grâce me suivront ma vie durant Et je pourrai demeurer dans la maison du Seigneur Jusqu’à la fin de mes jours.` },
  { livre: `Psaumes`, chapitre: 24, verset: 1, texte: `Psaume de David. La terre et ses richesses sont le bien du Seigneur. L’univers est à lui, avec ses habitants.` },
  { livre: `Psaumes`, chapitre: 24, verset: 2, texte: `Il a fondé la terre sur les rives des mers. Il l’a consolidée au-dessus des cours d’eaux.` },
  { livre: `Psaumes`, chapitre: 24, verset: 3, texte: `Qui pourra accéder au mont de l’Éternel? Qui pourra habiter dans sa sainte demeure?` },
  { livre: `Psaumes`, chapitre: 24, verset: 4, texte: `L’innocent aux mains nettes et dont le cœur est pur, Qui n’a pas l’âme encline au mal, aux vanités, Et qui ne jure pas pour tromper son prochain.` },
  { livre: `Psaumes`, chapitre: 24, verset: 5, texte: `Il aura l’avantage d’être béni par Dieu, D’être justifié par l’Éternel qui sauve.` },
  { livre: `Psaumes`, chapitre: 24, verset: 6, texte: `Seigneur, tel est le peuple de ceux qui te recherchent, Qui veulent contempler ta face, ô Seigneur, Ô toi, Dieu de Jacob.` },
  { livre: `Psaumes`, chapitre: 24, verset: 7, texte: `Ô portails, ouvrez-vous, relevez vos frontons! Ouvrez-vous toutes grandes, portes de l’univers Pour que le Roi de gloire y fasse son entrée!` },
  { livre: `Psaumes`, chapitre: 24, verset: 8, texte: `Qui est ce Roi de gloire? C’est Dieu, notre Seigneur, Le Dieu fort et vaillant, le héros des combats.` },
  { livre: `Psaumes`, chapitre: 24, verset: 9, texte: `Ô portails, ouvrez-vous, relevez vos frontons! Ouvrez-vous toutes grandes, portes de l’univers Pour que le Roi de gloire y fasse son entrée!` },
  { livre: `Psaumes`, chapitre: 24, verset: 10, texte: `Qui est ce Roi de gloire? C’est le Dieu des armées, Le Dieu de l’univers. C’est lui le Roi de gloire.` },
  { livre: `Psaumes`, chapitre: 25, verset: 1, texte: `De David. Vers toi, Seigneur, j’élève mes pensées.` },
  { livre: `Psaumes`, chapitre: 25, verset: 2, texte: `En toi, mon Dieu, j’ai mis ma confiance. Ne permets pas que je sois confondu, Et que mes ennemis puissent se réjouir à mon sujet.` },
  { livre: `Psaumes`, chapitre: 25, verset: 3, texte: `Jamais, jamais, ceux qui comptent sur toi Ne seront confondus. Tous ceux qui t’abandonnent et te sont infidèles Sans cause ni raison, Ceux-là seront déçus.` },
  { livre: `Psaumes`, chapitre: 25, verset: 4, texte: `Seigneur, mon Dieu, montre-moi ton chemin, Enseigne-moi quelle est ta volonté.` },
  { livre: `Psaumes`, chapitre: 25, verset: 5, texte: `Fais-moi marcher selon ta vérité et instruis-moi. Car c’est toi seul, le Dieu de mon salut, Et je m’attends à toi chaque jour, à chaque heure.` },
  { livre: `Psaumes`, chapitre: 25, verset: 6, texte: `Éternel, souviens-toi de ta miséricorde! Rappelle-toi ton amitié pour moi Que tu m’as témoignée depuis l’éternité.` },
  { livre: `Psaumes`, chapitre: 25, verset: 7, texte: `N’évoque plus mes péchés de jeunesse, mes révoltes passées. Mais souviens-toi de moi selon ta grâce. Au nom de ta bonté, ne m’oublie pas, Seigneur.` },
  { livre: `Psaumes`, chapitre: 25, verset: 8, texte: `Oui, l’Éternel est bon, C’est pourquoi il indique aux égarés la voie.` },
  { livre: `Psaumes`, chapitre: 25, verset: 9, texte: `Il sait guider les humbles dans la voie droite, Il montre aux malheureux le bon chemin.` },
  { livre: `Psaumes`, chapitre: 25, verset: 10, texte: `Tous les sentiers de Dieu sont grâce et vérité Pour ceux qui gardent son alliance et ses statuts.` },
  { livre: `Psaumes`, chapitre: 25, verset: 11, texte: `Pour l’amour de ton nom, Seigneur, Pardonne mon péché, car il est grand.` },
  { livre: `Psaumes`, chapitre: 25, verset: 12, texte: `À l’homme qui craint le Seigneur, Dieu montrera la voie qu’il doit choisir,` },
  { livre: `Psaumes`, chapitre: 25, verset: 13, texte: `Et il reposera dans le bonheur. Ses descendants prendront possession du pays.` },
  { livre: `Psaumes`, chapitre: 25, verset: 14, texte: `L’intimité de Dieu est pour ceux qui le craignent, Et son alliance est là pour les instruire.` },
  { livre: `Psaumes`, chapitre: 25, verset: 15, texte: `Mes yeux sont constamment tournés vers le Seigneur Car c’est lui qui dégage mes pieds pris au filet.` },
  { livre: `Psaumes`, chapitre: 25, verset: 16, texte: `Regarde-moi, Seigneur, et prends pitié de moi, Car je suis solitaire et malheureux.` },
  { livre: `Psaumes`, chapitre: 25, verset: 17, texte: `Mon cœur est angoissé, Délivre-moi de mes tourments.` },
  { livre: `Psaumes`, chapitre: 25, verset: 18, texte: `Vois ma misère et ma souffrance Et pardonne tous mes péchés.` },
  { livre: `Psaumes`, chapitre: 25, verset: 19, texte: `Oh! vois combien mes ennemis sont en grand nombre Et quelle haine violente ils ont pour moi!` },
  { livre: `Psaumes`, chapitre: 25, verset: 20, texte: `Garde mon âme, délivre-moi, Je cherche en toi un sûr refuge, Ne déçois pas ma confiance.` },
  { livre: `Psaumes`, chapitre: 25, verset: 21, texte: `Que l’innocence et la droiture me sauvegardent Puisque j’espère, Seigneur, en toi.` },
  { livre: `Psaumes`, chapitre: 25, verset: 22, texte: `Rachète, ô Dieu, (ton peuple d’) Israël de tous ses maux.` },
  { livre: `Psaumes`, chapitre: 26, verset: 1, texte: `De David. Fais-moi justice, ô Éternel, je marche dans l’intégrité. J’ai pris le Seigneur pour appui, je ne faiblirai pas.` },
  { livre: `Psaumes`, chapitre: 26, verset: 2, texte: `Soumets-moi à ton examen, Seigneur, éprouve-moi. Viens sonder mon cœur, mes pensées.` },
  { livre: `Psaumes`, chapitre: 26, verset: 3, texte: `J’ai ton amour devant les yeux, je marche dans ta vérité.` },
  { livre: `Psaumes`, chapitre: 26, verset: 4, texte: `Je ne vais pas m’asseoir avec les imposteurs. Je ne fréquente pas ceux qui sont hypocrites.` },
  { livre: `Psaumes`, chapitre: 26, verset: 5, texte: `Je hais la compagnie de ceux qui font le mal, Je ne m’arrête pas auprès des gens pervers.` },
  { livre: `Psaumes`, chapitre: 26, verset: 6, texte: `C’est dans une eau limpide, qu’en signe d’innocence, Je laverai mes mains avant de m’approcher de ton autel, Seigneur,` },
  { livre: `Psaumes`, chapitre: 26, verset: 7, texte: `Pour faire retentir des accents de louanges Et conter en détail tes œuvres merveilleuses.` },
  { livre: `Psaumes`, chapitre: 26, verset: 8, texte: `Combien j’aime, Seigneur, le lieu de ton séjour Où tu fais resplendir ta gloire.` },
  { livre: `Psaumes`, chapitre: 26, verset: 9, texte: `N’entraîne pas mon âme dans le sort des pécheurs, Ne m’ôte pas la vie avec les assassins!` },
  { livre: `Psaumes`, chapitre: 26, verset: 10, texte: `Leurs mains ont trempé dans le crime, ils se sont laissé acheter.` },
  { livre: `Psaumes`, chapitre: 26, verset: 11, texte: `Mais moi, je veux marcher avec intégrité. Délivre-moi dans ta pitié!` },
  { livre: `Psaumes`, chapitre: 26, verset: 12, texte: `D’un pas bien résolu, je marche sur le droit chemin. Oui, je veux te bénir, Seigneur, dans les lieux d’assemblée.` },
  { livre: `Psaumes`, chapitre: 27, verset: 1, texte: `De David. Le Seigneur Dieu est ma lumière et mon salut, Qui donc aurais-je à craindre? Il est le rempart de ma vie, Qui pourrait m’effrayer?` },
  { livre: `Psaumes`, chapitre: 27, verset: 2, texte: `Quand des méchants s’avancent contre moi, Voulant me déchirer, Ce seront eux, mes ennemis, mes oppresseurs, Qui perdront pied et tomberont.` },
  { livre: `Psaumes`, chapitre: 27, verset: 3, texte: `Quand une armée viendrait camper pour m’assiéger, Mon cœur ne craindrait rien. Quand un combat me serait imposé, Malgré cela, je resterais plein d’assurance.` },
  { livre: `Psaumes`, chapitre: 27, verset: 4, texte: `J’ai présenté à l’Éternel un seul souhait, Je le répète constamment: Je voudrais habiter dans la maison de l’Éternel Tous les jours de ma vie, Pour contempler la beauté du Seigneur, Pour l’admirer dans sa demeure.` },
  { livre: `Psaumes`, chapitre: 27, verset: 5, texte: `Car il me cache sous sa tente aux jours d’adversité. Au plus secret du tabernacle, il me tient abrité, Et, sur un rocher, il m’élève.` },
  { livre: `Psaumes`, chapitre: 27, verset: 6, texte: `Dès à présent, je relève la tête Au-dessus de mes ennemis qui sont autour de moi. J’offrirai, dans son tabernacle, des sacrifices de triomphe, Je chanterai des psaumes à l’Éternel (mon Dieu).` },
  { livre: `Psaumes`, chapitre: 27, verset: 7, texte: `Seigneur, écoute mon appel, car je t’invoque. Fais-moi grâce et réponds-moi.` },
  { livre: `Psaumes`, chapitre: 27, verset: 8, texte: `Mon cœur m’exhorte de ta part Et me dit: «Recherchez ma face». Je cherche ta face, ô Seigneur,` },
  { livre: `Psaumes`, chapitre: 27, verset: 9, texte: `Ne la détourne pas de moi! Ne sois pas irrité contre ton serviteur, ne le repousse pas! Toi qui m’as secouru, ne me délaisse pas! Ne m’abandonne pas, ô Dieu de mon salut!` },
  { livre: `Psaumes`, chapitre: 27, verset: 10, texte: `Car mon père et ma mère peuvent m’abandonner, Mais le Seigneur est là: il me recueillera.` },
  { livre: `Psaumes`, chapitre: 27, verset: 11, texte: `Enseigne-moi ta voie, Seigneur, et conduis-moi Par un sentier uni et droit, Puisque mes ennemis me guettent.` },
  { livre: `Psaumes`, chapitre: 27, verset: 12, texte: `Ne m’abandonne pas au désir de mes adversaires Car des témoins menteurs qui respirent la violence, Se dressent contre moi.` },
  { livre: `Psaumes`, chapitre: 27, verset: 13, texte: `Mais, j’en ai l’assurance, je verrai la bonté de l’Éternel Au pays des vivants.` },
  { livre: `Psaumes`, chapitre: 27, verset: 14, texte: `Attends-toi au Seigneur! Sois fort! Que ton cœur s’affermisse! Compte sur l’Éternel!` },
  { livre: `Psaumes`, chapitre: 28, verset: 1, texte: `De David. À toi, Seigneur, je fais appel; toi, mon rocher, Ne sois pas sourd à ma requête. Si tu t’éloignes sans me répondre, j’irai rejoindre ceux qui descendent dans le tombeau.` },
  { livre: `Psaumes`, chapitre: 28, verset: 2, texte: `Entends ma voix qui te supplie quand je t’invoque En élevant mes mains vers toi au lieu très-saint dans ton saint temple.` },
  { livre: `Psaumes`, chapitre: 28, verset: 3, texte: `Ne me joins pas à ces méchants, Qui font le mal, parlant de paix à leur prochain, Avec la haine au fond du cœur.` },
  { livre: `Psaumes`, chapitre: 28, verset: 4, texte: `Rends-leur, (Seigneur,) selon leurs actes et leurs méfaits. Oh! traite-les selon l’ouvrage fait par leurs mains. Retourne-leur ce qu’ils ont fait!` },
  { livre: `Psaumes`, chapitre: 28, verset: 5, texte: `Ils ne comprennent ni les actions de l’Éternel, Ni les ouvrages faits par ses mains. Ils méconnaissent ce que tu fais. Mais un jour, Dieu les brisera pour ne jamais les relever.` },
  { livre: `Psaumes`, chapitre: 28, verset: 6, texte: `Béni soit Dieu, car il exauce mes cris, mes pleurs.` },
  { livre: `Psaumes`, chapitre: 28, verset: 7, texte: `Oui, le Seigneur est mon rempart, mon bouclier. En lui, mon cœur a mis sa foi, et son secours m’est assuré. Aussi mon cœur se réjouit et il exulte. Je lui rends grâce par un cantique que je jouerai. Je le louerai par mon chant.` },
  { livre: `Psaumes`, chapitre: 28, verset: 8, texte: `Dieu est la force de tous les siens et le rempart des délivrances Pour son Messie.` },
  { livre: `Psaumes`, chapitre: 28, verset: 9, texte: `Sauve ton peuple et viens bénir ton héritage, Sois son Berger et son soutien dès à présent et pour toujours.` },
  { livre: `Psaumes`, chapitre: 29, verset: 1, texte: `Psaume de David. Célébrez l’Éternel, vous, fils de Dieu. Rendez à l’Éternel gloire et honneur.` },
  { livre: `Psaumes`, chapitre: 29, verset: 2, texte: `Rendez hommage au nom glorieux de l’Éternel. Prosternez-vous, revêtus de splendeur, adorez le Seigneur!` },
  { livre: `Psaumes`, chapitre: 29, verset: 3, texte: `La voix de l’Éternel retentit sur les eaux, Le Dieu de majesté fait gronder le tonnerre. La voix de Dieu domine le bruit des grandes eaux.` },
  { livre: `Psaumes`, chapitre: 29, verset: 4, texte: `La voix de l’Éternel est une voix puissante, La voix de l’Éternel, pleine de majesté.` },
  { livre: `Psaumes`, chapitre: 29, verset: 5, texte: `La voix de l’Éternel brise les plus grands cèdres, C’est l’Éternel qui brise les cèdres du Liban.` },
  { livre: `Psaumes`, chapitre: 29, verset: 6, texte: `Il fait bondir tout le Liban et le Sirion Comme bondissent de jeunes buffles.` },
  { livre: `Psaumes`, chapitre: 29, verset: 7, texte: `La voix de Dieu lance des flammes étincelantes.` },
  { livre: `Psaumes`, chapitre: 29, verset: 8, texte: `La voix du Seigneur fait trembler tout le désert, Le Seigneur fait trembler le désert de Kadès.` },
  { livre: `Psaumes`, chapitre: 29, verset: 9, texte: `La voix de l’Éternel fait enfanter les biches, Elle dépouille tous les grands arbres de la forêt. Dans son palais, chacun s’écrie: «Gloire au Seigneur!»` },
  { livre: `Psaumes`, chapitre: 29, verset: 10, texte: `Lors du déluge, Dieu dominait et il siégeait sur son saint trône. L’Éternel règne, Roi éternel.` },
  { livre: `Psaumes`, chapitre: 29, verset: 11, texte: `L’Éternel donne force et courage à tout son peuple. Il le bénit. L’Éternel donne à tout son peuple paix et bonheur.` },
  { livre: `Psaumes`, chapitre: 30, verset: 0, texte: `Cantique pour l’inauguration de la maison de Dieu. Un psaume de David.` },
  { livre: `Psaumes`, chapitre: 30, verset: 1, texte: `Je t’exalterai, Seigneur, car tu m’as sauvé en me tirant de la fosse. Tu n’as pas laissé tous mes adversaires se réjouir à mes dépens.` },
  { livre: `Psaumes`, chapitre: 30, verset: 2, texte: `Ô, Seigneur, mon Dieu, j’ai crié vers toi, et tu m’as guéri:` },
  { livre: `Psaumes`, chapitre: 30, verset: 3, texte: `Seigneur, du séjour des morts, tu fis remonter mon âme, Tu m’as rendu à la vie quand j’allais vers le tombeau.` },
  { livre: `Psaumes`, chapitre: 30, verset: 4, texte: `Chantez au Seigneur, vous ses bien-aimés! Que par vos louanges, son saint nom soit évoqué.` },
  { livre: `Psaumes`, chapitre: 30, verset: 5, texte: `Son courroux dure un instant, son amour est pour la vie. Le soir apporte des larmes, le matin des cris de joie.` },
  { livre: `Psaumes`, chapitre: 30, verset: 6, texte: `Pour moi, dans mon insouciance, je me disais: «Tout va bien, je ne tomberai jamais».` },
  { livre: `Psaumes`, chapitre: 30, verset: 7, texte: `Éternel, par ta faveur, j’étais en sécurité, Établi sur les hauteurs fortifiées de mes montagnes. Mais tu as caché ta face et je fus épouvanté,` },
  { livre: `Psaumes`, chapitre: 30, verset: 8, texte: `Vers toi, Seigneur, j’ai crié, j’ai demandé grâce à Dieu:` },
  { livre: `Psaumes`, chapitre: 30, verset: 9, texte: `«Que te rapporte ma mort? Si je descends dans la fosse, Ma poussière pourra-t-elle chanter ta louange, publier ta vérité?` },
  { livre: `Psaumes`, chapitre: 30, verset: 10, texte: `Éternel, exauce-moi, veuille m’accorder ta grâce, Seigneur, viens à mon secours».` },
  { livre: `Psaumes`, chapitre: 30, verset: 11, texte: `Et tu as changé mon deuil en une danse de joie. Tu as défait mes habits funèbres pour me draper d’allégresse, Tu m’as ceint de joie,` },
  { livre: `Psaumes`, chapitre: 30, verset: 12, texte: `Afin que mon cœur te chante et qu’il te loue sans relâche. Ô Seigneur, mon Dieu, je veux te louer toujours.` },
  { livre: `Psaumes`, chapitre: 31, verset: 0, texte: `Au chef de chœur. Psaume de David.` },
  { livre: `Psaumes`, chapitre: 31, verset: 1, texte: `Ô Éternel, j’ai mis en toi mon espérance, Que je ne sois jamais déçu! Délivre-moi dans ta justice,` },
  { livre: `Psaumes`, chapitre: 31, verset: 2, texte: `Incline vers moi ton oreille, hâte-toi de me délivrer! Sois pour moi le rocher solide où je pourrai me réfugier! Sois une forte citadelle où je trouverai le salut!` },
  { livre: `Psaumes`, chapitre: 31, verset: 3, texte: `Oui, tu es pour moi ce rocher, tu es la forte citadelle, Et, pour la gloire de ton nom, tu me conduis et tu me guides.` },
  { livre: `Psaumes`, chapitre: 31, verset: 4, texte: `Tu me fais échapper au piège que l’on a tendu sous mes pas, Puisque tu es mon protecteur.` },
  { livre: `Psaumes`, chapitre: 31, verset: 5, texte: `Oui, c’est entre tes mains, (Seigneur,) que je dépose mon esprit. Éternel, tu es mon Sauveur, tu es le Dieu de vérité.` },
  { livre: `Psaumes`, chapitre: 31, verset: 6, texte: `Je déteste ceux qui s’attachent à des idoles de néant, Et je m’en remets au Seigneur.` },
  { livre: `Psaumes`, chapitre: 31, verset: 7, texte: `Ton amour me fait jubiler, il me remplit de joie. Puisque tu as vu ma misère, Et que tu as pris connaissance des tourments de mon âme,` },
  { livre: `Psaumes`, chapitre: 31, verset: 8, texte: `Tu ne m’as pas abandonné au pouvoir de mes ennemis, Mais tu as mis mes pas au large.` },
  { livre: `Psaumes`, chapitre: 31, verset: 9, texte: `Prends pitié de moi, ô Seigneur, car l’angoisse m’étreint, La douleur a rongé mes yeux, mon âme et tout mon corps.` },
  { livre: `Psaumes`, chapitre: 31, verset: 10, texte: `Ma vie se consume en tourments, mes années dans les pleurs. Le péché épuise mes forces et mes os dépérissent.` },
  { livre: `Psaumes`, chapitre: 31, verset: 11, texte: `Mes ennemis ont fait de moi l’objet de leur risée. Je suis la honte des voisins et l’effroi de mes connaissances. Ceux qui me croisent en chemin s’écartent loin de moi.` },
  { livre: `Psaumes`, chapitre: 31, verset: 12, texte: `Je suis rayé du souvenir comme un mort inconnu. Je suis comme un objet perdu.` },
  { livre: `Psaumes`, chapitre: 31, verset: 13, texte: `J’entends toutes les médisances que l’on répand à mon sujet, La frayeur règne aux alentours: Ils se concertent contre moi, ils songent à m’ôter la vie.` },
  { livre: `Psaumes`, chapitre: 31, verset: 14, texte: `Mais j’ai confiance en toi, Seigneur, Je dis: «C’est toi qui es mon Dieu!»` },
  { livre: `Psaumes`, chapitre: 31, verset: 15, texte: `Mes destinées sont dans ta main, veuille me délivrer, Seigneur, De la main de mes ennemis et de (tous) ceux qui me poursuivent.` },
  { livre: `Psaumes`, chapitre: 31, verset: 16, texte: `Fais briller l’éclat de ta face sur moi, ton serviteur, Et sauve-moi dans ton amour!` },
  { livre: `Psaumes`, chapitre: 31, verset: 17, texte: `Que je ne sois pas confondu, Seigneur, de t’avoir appelé, Mais que les méchants soient confus et réduits au silence Dans le séjour des morts.` },
  { livre: `Psaumes`, chapitre: 31, verset: 18, texte: `Qu’ils soient muets tous ces menteurs qui médisent du juste Avec arrogance et dédain, pleins d’orgueil méprisant.` },
  { livre: `Psaumes`, chapitre: 31, verset: 19, texte: `Comme elle est grande, la bonté que tu tiens en réserve Pour ceux qui te respectent, Pour ceux qui trouvent refuge auprès de toi Au vu de tous les hommes!` },
  { livre: `Psaumes`, chapitre: 31, verset: 20, texte: `Sous la protection de ta face, tu les mets à l’abri Loin des machinations des hommes. Tu les préserves dans ta tente des langues de discorde.` },
  { livre: `Psaumes`, chapitre: 31, verset: 21, texte: `Béni soit le Seigneur! Car sa fidélité pour moi A été merveilleuse. (Il m’a placé) dans la ville forte.` },
  { livre: `Psaumes`, chapitre: 31, verset: 22, texte: `Dans mon effroi, je me disais: «Je suis loin de ses yeux». Pourtant tu écoutais mes pleurs quand j’ai crié vers toi.` },
  { livre: `Psaumes`, chapitre: 31, verset: 23, texte: `Vous tous qui servez le Seigneur, donnez-lui votre amour. Le Seigneur garde les croyants et il prend soin des siens. Mais il punit sévèrement ceux qui sont orgueilleux.` },
  { livre: `Psaumes`, chapitre: 31, verset: 24, texte: `Soyez forts et prenez courage, vous tous qui espérez en Dieu.` },
  { livre: `Psaumes`, chapitre: 32, verset: 1, texte: `Méditation de David. Heureux, bienheureux est l’homme dont la faute est enlevée, Dont le péché est couvert.` },
  { livre: `Psaumes`, chapitre: 32, verset: 2, texte: `Heureux, bienheureux est l’homme à qui le Seigneur fait grâce En oubliant son offense et dont l’esprit est sans fraude.` },
  { livre: `Psaumes`, chapitre: 32, verset: 3, texte: `Tant que je taisais ma faute, mes membres dépérissaient. Je me rongeais en moi-même, sans arrêt, je gémissais.` },
  { livre: `Psaumes`, chapitre: 32, verset: 4, texte: `Ta main s’appesantissait sur moi le jour et la nuit, Ma force se desséchait comme l’herbe en plein été.` },
  { livre: `Psaumes`, chapitre: 32, verset: 5, texte: `Je t’ai confessé ma faute, je n’ai plus caché mes torts, J’ai dit: «J’avouerai à Dieu les péchés que j’ai commis». Alors, tu as effacé la peine de mon péché.` },
  { livre: `Psaumes`, chapitre: 32, verset: 6, texte: `Ainsi, que chaque fidèle te prie au moment voulu. Si les grandes eaux déferlent, leurs flots ne l’atteindront pas.` },
  { livre: `Psaumes`, chapitre: 32, verset: 7, texte: `Seigneur, tu es mon refuge, tu me gardes de l’angoisse. Tu m’environnes de joie et de chants de délivrance.` },
  { livre: `Psaumes`, chapitre: 32, verset: 8, texte: `Tu as dit: «Je vais t’instruire et t’indiquer Le chemin que tu devras emprunter, Je serai ton conseiller, mes yeux veilleront sur toi».` },
  { livre: `Psaumes`, chapitre: 32, verset: 9, texte: `Ne soyez pas entêtés comme un cheval, Un mulet dépourvu d’intelligence dont il faut dompter la fougue Par la bride et par le mors pour qu’ils ne t’approchent pas.` },
  { livre: `Psaumes`, chapitre: 32, verset: 10, texte: `Nombreuses sont les souffrances qui attendent le méchant, Mais ceux qui comptent sur Dieu sont entourés de sa grâce.` },
  { livre: `Psaumes`, chapitre: 32, verset: 11, texte: `Justes, réjouissez-vous et chantez votre allégresse, Vous qui êtes droits de cœur: le Seigneur soit votre joie!` },
  { livre: `Psaumes`, chapitre: 33, verset: 1, texte: `Vous tous qui êtes justes, acclamez le Seigneur! Il sied aux hommes droits de louer l’Éternel.` },
  { livre: `Psaumes`, chapitre: 33, verset: 2, texte: `Célébrez le Seigneur, louez-le sur la harpe! Jouez-lui sur le luth!` },
  { livre: `Psaumes`, chapitre: 33, verset: 3, texte: `Chantez en son honneur un cantique nouveau! Jouez de tout votre art! Sonnez de vos trompettes!` },
  { livre: `Psaumes`, chapitre: 33, verset: 4, texte: `Car la parole du Seigneur repose sur la vérité, Son œuvre entière est authentique, empreinte de fidélité;` },
  { livre: `Psaumes`, chapitre: 33, verset: 5, texte: `Dieu aime la justice, ainsi que la droiture. La bonté du Seigneur remplit la terre entière.` },
  { livre: `Psaumes`, chapitre: 33, verset: 6, texte: `À la parole du Seigneur les cieux sont apparus, Et toute l’armée des étoiles est née du souffle de sa bouche.` },
  { livre: `Psaumes`, chapitre: 33, verset: 7, texte: `Il endigue les eaux des mers, il emprisonne l’océan.` },
  { livre: `Psaumes`, chapitre: 33, verset: 8, texte: `Que l’univers entier révère le Seigneur! Qu’ils tremblent devant lui, les habitants du monde!` },
  { livre: `Psaumes`, chapitre: 33, verset: 9, texte: `Car, dès qu’il a parlé, la chose a existé. Dès qu’il a commandé, ce fut réalisé.` },
  { livre: `Psaumes`, chapitre: 33, verset: 10, texte: `Le Seigneur fait échec aux desseins des nations. Il réduit à néant les vains projets des peuples.` },
  { livre: `Psaumes`, chapitre: 33, verset: 11, texte: `Le dessein du Seigneur demeure pour toujours. Les projets de son cœur subsistent d’âge en âge.` },
  { livre: `Psaumes`, chapitre: 33, verset: 12, texte: `Heureuse est la nation dont l’Éternel est Dieu, Le peuple qu’il choisit comme son héritage.` },
  { livre: `Psaumes`, chapitre: 33, verset: 13, texte: `Du haut de sa demeure, Dieu voit tous les humains.` },
  { livre: `Psaumes`, chapitre: 33, verset: 14, texte: `De son séjour céleste, Il observe et surveille les habitants du monde.` },
  { livre: `Psaumes`, chapitre: 33, verset: 15, texte: `Il a formé leur cœur sur un modèle unique, Et il reste attentif à chacun de leurs actes.` },
  { livre: `Psaumes`, chapitre: 33, verset: 16, texte: `Le roi n’est pas sauvé par une armée puissante, La force ne saurait délivrer le guerrier.` },
  { livre: `Psaumes`, chapitre: 33, verset: 17, texte: `Trompeur est le secours du cheval pour sauver, Et toute sa vigueur ne nous délivre pas.` },
  { livre: `Psaumes`, chapitre: 33, verset: 18, texte: `Mais le Seigneur se penche sur tous ceux qui le craignent, Qui comptent sur sa grâce,` },
  { livre: `Psaumes`, chapitre: 33, verset: 19, texte: `Pour délivrer leur âme, l’arracher à la mort Et pour les faire vivre aux jours de la famine.` },
  { livre: `Psaumes`, chapitre: 33, verset: 20, texte: `Notre âme espère en Dieu, il est notre secours et notre bouclier.` },
  { livre: `Psaumes`, chapitre: 33, verset: 21, texte: `Notre cœur est en joie, car il nous réjouit, Et notre confiance est dans son nom très saint.` },
  { livre: `Psaumes`, chapitre: 33, verset: 22, texte: `Que ta grâce, ô Seigneur, repose sur nous (tous), Car nous comptons sur toi.` },
  { livre: `Psaumes`, chapitre: 34, verset: 0, texte: `Un psaume de David lorsqu’il simula la folie en présence d’Abimélec qui le chassa.` },
  { livre: `Psaumes`, chapitre: 34, verset: 1, texte: `Je bénirai sans cesse l’Éternel, le Seigneur, Et j’aurai sa louange pour toujours dans la bouche.` },
  { livre: `Psaumes`, chapitre: 34, verset: 2, texte: `Dans le Seigneur, mon âme mettra toute sa gloire. Qu’ils écoutent, les humbles, et soient remplis de joie,` },
  { livre: `Psaumes`, chapitre: 34, verset: 3, texte: `Avec moi qu’ils acclament l’Éternel, le Seigneur. Exaltons tous ensemble la gloire de son nom!` },
  { livre: `Psaumes`, chapitre: 34, verset: 4, texte: `J’ai cherché le Seigneur, et il m’a répondu. Oui, il m’a délivré de toutes mes frayeurs.` },
  { livre: `Psaumes`, chapitre: 34, verset: 5, texte: `Ceux qui, vers lui, regardent sont rayonnants de joie, Et jamais leur visage ne rougira de honte.` },
  { livre: `Psaumes`, chapitre: 34, verset: 6, texte: `Qu’un malheureux appelle, le Seigneur l’entendra; De toutes ses détresses, il le délivrera.` },
  { livre: `Psaumes`, chapitre: 34, verset: 7, texte: `L’ange du Seigneur veille autour de ses fidèles, prêt à les dégager.` },
  { livre: `Psaumes`, chapitre: 34, verset: 8, texte: `Voyez et constatez que le Seigneur est bon. Oui, bienheureux est l’homme qui s’abandonne à lui.` },
  { livre: `Psaumes`, chapitre: 34, verset: 9, texte: `Vous qu’il a consacrés, craignez donc le Seigneur! Car aucun bien ne manque à tous ceux qui le craignent.` },
  { livre: `Psaumes`, chapitre: 34, verset: 10, texte: `Le lion peut connaître la disette et la faim, Mais ceux qui cherchent Dieu ne manquent d’aucun bien.` },
  { livre: `Psaumes`, chapitre: 34, verset: 11, texte: `Mes fils, écoutez-moi, et je vous apprendrai à craindre le Seigneur.` },
  { livre: `Psaumes`, chapitre: 34, verset: 12, texte: `Qui a plaisir à vivre? Qui voudrait être heureux?` },
  { livre: `Psaumes`, chapitre: 34, verset: 13, texte: `Qu’il surveille sa langue pour ne dire aucun mal, Qu’il préserve ses lèvres des paroles rusées.` },
  { livre: `Psaumes`, chapitre: 34, verset: 14, texte: `Détourne-toi du mal, et pratique le bien, Cherche et poursuis la paix.` },
  { livre: `Psaumes`, chapitre: 34, verset: 15, texte: `Les yeux de l’Éternel se tournent vers les justes, Son oreille est tendue pour écouter leurs cris.` },
  { livre: `Psaumes`, chapitre: 34, verset: 16, texte: `Mais le Seigneur fait front à ceux qui font le mal, Pour rayer de la terre même leur souvenir.` },
  { livre: `Psaumes`, chapitre: 34, verset: 17, texte: `Lorsque ceux qui sont justes font monter leur appel, Le Seigneur les entend; aussi, il les arrache à toutes leurs angoisses.` },
  { livre: `Psaumes`, chapitre: 34, verset: 18, texte: `Car le Seigneur est proche des cœurs découragés. Il sauve ceux qui ont un esprit déprimé.` },
  { livre: `Psaumes`, chapitre: 34, verset: 19, texte: `Des épreuves nombreuses sont dans le lot du juste, Mais, toujours, le Seigneur vient pour le délivrer.` },
  { livre: `Psaumes`, chapitre: 34, verset: 20, texte: `Sur chacun de ses membres et de ses os, Dieu veille: Il ne s’en brise aucun.` },
  { livre: `Psaumes`, chapitre: 34, verset: 21, texte: `Le mal tue le méchant, les ennemis du juste Auront leur châtiment,` },
  { livre: `Psaumes`, chapitre: 34, verset: 22, texte: `Mais le Seigneur rachète l’âme de tous ses serviteurs, Et ceux qui se confient en lui ne seront jamais condamnés.` },
  { livre: `Psaumes`, chapitre: 35, verset: 1, texte: `De David. Prends à partie, Seigneur, ceux qui font mon procès, Combats mes assaillants!` },
  { livre: `Psaumes`, chapitre: 35, verset: 2, texte: `Saisis le bouclier et revêts ton armure pour venir à mon aide!` },
  { livre: `Psaumes`, chapitre: 35, verset: 3, texte: `Brandis sur eux ta lance avec le javelot Et barre le chemin à mes persécuteurs! Parle à mon âme et dis: «C’est moi, moi ton Sauveur»,` },
  { livre: `Psaumes`, chapitre: 35, verset: 4, texte: `Pour qu’ils soient confondus dans la honte et la crainte, Ceux qui veulent ma mort! Qu’ils reculent bien loin et rougissent de honte,` },
  { livre: `Psaumes`, chapitre: 35, verset: 5, texte: `Qu’ils soient comme la balle emportée par le vent Quand l’ange du Seigneur les mettra en déroute!` },
  { livre: `Psaumes`, chapitre: 35, verset: 6, texte: `Que leur chemin soit sombre et leur route glissante Quand l’ange du Seigneur viendra les pourchasser!` },
  { livre: `Psaumes`, chapitre: 35, verset: 7, texte: `Ils ont caché sans cause des pièges sous mes pas Et, sans raison, ils creusent des fosses pour me perdre.` },
  { livre: `Psaumes`, chapitre: 35, verset: 8, texte: `Que le malheur s’abatte sur eux à l’improviste! Que, dans leurs propres pièges, ils puissent s’empêtrer! Qu’ils tombent dans la fosse qu’ils ont voulu creuser!` },
  { livre: `Psaumes`, chapitre: 35, verset: 9, texte: `Et moi, plein d’allégresse, en Dieu, j’exulterai parce qu’il m’a sauvé.` },
  { livre: `Psaumes`, chapitre: 35, verset: 10, texte: `Tout mon être dira: «Qui est semblable à toi, ô Seigneur Éternel? Tu délivres le faible d’un plus puissant que lui, Le pauvre et l’opprimé de ceux qui les exploitent».` },
  { livre: `Psaumes`, chapitre: 35, verset: 11, texte: `De faux témoins se lèvent, Ils me demandent compte de fautes que j’ignore.` },
  { livre: `Psaumes`, chapitre: 35, verset: 12, texte: `Ils me rendent le mal pour le bien que j’ai fait. Je suis abandonné.` },
  { livre: `Psaumes`, chapitre: 35, verset: 13, texte: `Moi, dans leurs maladies, je me couvrais d’un sac Et j’humiliais mon âme pour jeûner et prier. Sans fin, j’intercédais` },
  { livre: `Psaumes`, chapitre: 35, verset: 14, texte: `Comme pour un ami ou pour mon propre frère. Je marchais lentement, courbé sous la tristesse, Comme en menant le deuil pour la mort d’une mère.` },
  { livre: `Psaumes`, chapitre: 35, verset: 15, texte: `Quand je viens à tomber, tout joyeux, ils s’attroupent. Oui, des gens violents s’attroupent contre moi, Venant à l’improviste me déchirer sans cesse.` },
  { livre: `Psaumes`, chapitre: 35, verset: 16, texte: `Avec des hypocrites, des moqueurs parasites, Ils sont prêts à me mordre.` },
  { livre: `Psaumes`, chapitre: 35, verset: 17, texte: `Seigneur, jusques à quand pourras-tu voir cela? Protège donc mon âme contre leurs violences! Viens arracher ma vie à ces bêtes féroces!` },
  { livre: `Psaumes`, chapitre: 35, verset: 18, texte: `Je te rendrai hommage dans la grande assemblée. Je te célébrerai avec la foule immense.` },
  { livre: `Psaumes`, chapitre: 35, verset: 19, texte: `Que mes ennemis fourbes n’aient plus à se réjouir! Que ceux qui me détestent, sans motif ni raison, Ne lancent plus entre eux des regards triomphants!` },
  { livre: `Psaumes`, chapitre: 35, verset: 20, texte: `Car ce n’est pas la paix qu’apporte leur parole, Ils ont des propos fourbes et des desseins retors Contre les gens tranquilles.` },
  { livre: `Psaumes`, chapitre: 35, verset: 21, texte: `Sur un ton insolent, ils déclarent: «C’est bien! Nos yeux le voient».` },
  { livre: `Psaumes`, chapitre: 35, verset: 22, texte: `Éternel, tu le vois! Ne reste pas muet! Seigneur, ne te tiens pas si éloigné de moi!` },
  { livre: `Psaumes`, chapitre: 35, verset: 23, texte: `Réveille-toi, ô Dieu! Mets-toi en mouvement! Viens me rendre justice! Prends mon procès en mains! Ô, mon Dieu et mon maître,` },
  { livre: `Psaumes`, chapitre: 35, verset: 24, texte: `Viens défendre mon droit! Ô mon Seigneur, mon Dieu, Qu’ils ne puissent plus rire ni se moquer de moi!` },
  { livre: `Psaumes`, chapitre: 35, verset: 25, texte: `Qu’ils ne puissent plus dire: «Nos désirs sont comblés!» Qu’ils ne puissent plus dire: «Nous l’avons avalé!»` },
  { livre: `Psaumes`, chapitre: 35, verset: 26, texte: `Qu’ils soient déshonorés et confus tous ensemble, Ceux qui se réjouissaient de me voir malheureux! Qu’ils soient couverts de honte et revêtus d’opprobre, Ceux qui s’enflaient d’orgueil en triomphant de moi!` },
  { livre: `Psaumes`, chapitre: 35, verset: 27, texte: `Ceux qui prennent plaisir à voir mon innocence Se réjouiront alors, et ils crieront de joie En répétant sans cesse: «Qu’il est grand le Seigneur, Lui qui veut le bonheur de son (bon) serviteur!»` },
  { livre: `Psaumes`, chapitre: 35, verset: 28, texte: `Ma langue chantera ta justice, et tous les jours, ta gloire.` },
  { livre: `Psaumes`, chapitre: 36, verset: 0, texte: `Au chef de chœur, de David, serviteur du Seigneur.` },
  { livre: `Psaumes`, chapitre: 36, verset: 1, texte: `La parole criminelle de l’impie m’atteint au cœur,` },
  { livre: `Psaumes`, chapitre: 36, verset: 2, texte: `Car il n’envisage pas qu’il lui faille craindre Dieu. L’impie a l’œil indulgent pour se regarder lui-même, Il ne veut pas reconnaître sa faute et la détester.` },
  { livre: `Psaumes`, chapitre: 36, verset: 3, texte: `Les paroles de sa bouche sont méfait et tromperie, Il repousse la sagesse et renonce à bien agir.` },
  { livre: `Psaumes`, chapitre: 36, verset: 4, texte: `Dans le secret, sur sa couche, il médite un mauvais coup. Il s’engage et puis s’obstine dans une voie sans issue: Il n’a pas l’horreur du mal.` },
  { livre: `Psaumes`, chapitre: 36, verset: 5, texte: `Seigneur, ta bonté, ta grâce vont jusqu’au-delà des cieux, Ta fidélité surpasse les nuages dans les airs.` },
  { livre: `Psaumes`, chapitre: 36, verset: 6, texte: `Ta justice est aussi ferme que les montagnes de Dieu. Tes sentences sont profondes comme l’immense océan. Seigneur, tu es secourable à l’homme et à l’animal.` },
  { livre: `Psaumes`, chapitre: 36, verset: 7, texte: `Ô Dieu, qu’elle est précieuse (pour moi) ta fidélité! C’est à l’ombre de tes ailes que l’homme trouve un refuge.` },
  { livre: `Psaumes`, chapitre: 36, verset: 8, texte: `Il savoure les richesses des festins de ta maison. Au torrent de tes délices, toi, tu étanches sa soif.` },
  { livre: `Psaumes`, chapitre: 36, verset: 9, texte: `Car la source de la vie, (Seigneur,) c’est (d’être) avec toi. Lorsque tu nous illumines, nous percevons la lumière.` },
  { livre: `Psaumes`, chapitre: 36, verset: 10, texte: `À (tous) ceux qui te connaissent, veuille garder ton amour Et ta justice (divine) à ceux qui sont droits de cœur!` },
  { livre: `Psaumes`, chapitre: 36, verset: 11, texte: `Que les pieds des orgueilleux ne viennent pas m’écraser, Que la main des infidèles ne puisse pas m’ébranler.` },
  { livre: `Psaumes`, chapitre: 36, verset: 12, texte: `Voici, déjà ils succombent, ceux qui pratiquent le mal: Ils sont renversés, ils tombent, sans pouvoir se relever.` },
  { livre: `Psaumes`, chapitre: 37, verset: 1, texte: `De David. Ne te fâche pas contre les méchants! Ne jalouse pas ceux qui font le mal!` },
  { livre: `Psaumes`, chapitre: 37, verset: 2, texte: `Car, rapidement, comme l’herbe aux champs, Ils seront fauchés et se faneront comme le gazon.` },
  { livre: `Psaumes`, chapitre: 37, verset: 3, texte: `Mets ta confiance en Dieu, le Seigneur! Fais ce qui est bien, demeure au pays Et gagne ta vie en sécurité.` },
  { livre: `Psaumes`, chapitre: 37, verset: 4, texte: `En Dieu, mets ta joie Et il comblera les vœux de ton cœur.` },
  { livre: `Psaumes`, chapitre: 37, verset: 5, texte: `Remets ton destin aux mains du Seigneur, Aie confiance en lui et il agira.` },
  { livre: `Psaumes`, chapitre: 37, verset: 6, texte: `Il fera briller ton droit, ta justice, comme la lumière, Et ta loyauté, comme le soleil à son plein midi.` },
  { livre: `Psaumes`, chapitre: 37, verset: 7, texte: `Sois calme et confiant devant le Seigneur. Appuie-toi sur lui, Ne t’indigne pas contre ton voisin Quand il réussit dans ses entreprises, Contre l’intrigant qui mène à leur fin ses mauvais desseins!` },
  { livre: `Psaumes`, chapitre: 37, verset: 8, texte: `Laisse la colère, calme ton courroux, ne t’irrite pas, À quoi bon? Cela t’entraînerait au mal.` },
  { livre: `Psaumes`, chapitre: 37, verset: 9, texte: `Car les malfaiteurs seront retranchés: Mais ceux qui s’attendent au Seigneur, ceux-là Auront le pays comme possession.` },
  { livre: `Psaumes`, chapitre: 37, verset: 10, texte: `Encore peu de temps et l’impie n’est plus. Tu cherches sa place: il a disparu.` },
  { livre: `Psaumes`, chapitre: 37, verset: 11, texte: `Mais les débonnaires héritent la terre Et ils jouiront d’une paix profonde.` },
  { livre: `Psaumes`, chapitre: 37, verset: 12, texte: `Le méchant complote pour ruiner le juste, Il cherche à le mordre.` },
  { livre: `Psaumes`, chapitre: 37, verset: 13, texte: `Le Seigneur s’en moque, Car il voit venir son jour (fatidique).` },
  { livre: `Psaumes`, chapitre: 37, verset: 14, texte: `Ceux qui sont rebelles ont tiré l’épée, Ils ont tendu l’arc pour frapper le pauvre et le malheureux Et pour égorger ceux qui marchent droit.` },
  { livre: `Psaumes`, chapitre: 37, verset: 15, texte: `Leur épée pénètre dans leur propre cœur; Leurs arcs sont brisés.` },
  { livre: `Psaumes`, chapitre: 37, verset: 16, texte: `L’avoir bien modeste de ceux qui sont justes Est bien préférable aux grandes richesses de nombreux méchants.` },
  { livre: `Psaumes`, chapitre: 37, verset: 17, texte: `Car, si leur puissance, un jour, est brisée, Le Seigneur demeure le soutien des justes.` },
  { livre: `Psaumes`, chapitre: 37, verset: 18, texte: `Il connaît la vie des hommes de bien, Et leur héritage demeure à jamais.` },
  { livre: `Psaumes`, chapitre: 37, verset: 19, texte: `Ils ne seront pas pris au dépourvu au temps du malheur. Ils sont rassasiés aux jours de famine.` },
  { livre: `Psaumes`, chapitre: 37, verset: 20, texte: `Les méchants périssent et les adversaires de (notre) Seigneur, Tel l’éclat des prés, s’évanouiront, Comme une fumée, ils disparaîtront.` },
  { livre: `Psaumes`, chapitre: 37, verset: 21, texte: `Le méchant emprunte, mais il ne rend pas; Le juste a pitié, il partage et donne.` },
  { livre: `Psaumes`, chapitre: 37, verset: 22, texte: `Ceux que Dieu bénit héritent la terre, Mais ceux qu’il maudit seront retranchés.` },
  { livre: `Psaumes`, chapitre: 37, verset: 23, texte: `C’est par l’Éternel que les pas d’un homme seront affermis, Dieu lui montrera la voie qui lui plaît.` },
  { livre: `Psaumes`, chapitre: 37, verset: 24, texte: `S’il vient à tomber, il n’est pas question qu’il soit rejeté Car Dieu le soutient et lui prend la main.` },
  { livre: `Psaumes`, chapitre: 37, verset: 25, texte: `J’étais un enfant et me voilà vieux, Jamais je n’ai vu un homme de bien être abandonné, Ni ses descendants mendier leur pain.` },
  { livre: `Psaumes`, chapitre: 37, verset: 26, texte: `Tout au long des jours, il use de grâce, et il prête (aux autres). Ses enfants seront en bénédiction.` },
  { livre: `Psaumes`, chapitre: 37, verset: 27, texte: `Évite le mal, accomplis le bien, Ainsi ta demeure sera permanente.` },
  { livre: `Psaumes`, chapitre: 37, verset: 28, texte: `Car le Seigneur aime tout ce qui est droit, Et ceux qui le servent ne seront jamais délaissés par lui. Il les gardera éternellement, Mais la descendance de gens malfaisants sera retranchée;` },
  { livre: `Psaumes`, chapitre: 37, verset: 29, texte: `Tandis que les justes auront le pays comme possession. Ils l’habiteront éternellement.` },
  { livre: `Psaumes`, chapitre: 37, verset: 30, texte: `La bouche des justes parle de sagesse Et leur langue énonce des sentences vraies.` },
  { livre: `Psaumes`, chapitre: 37, verset: 31, texte: `La loi de leur Dieu, gravée dans leur cœur, Rendra leurs pas fermes.` },
  { livre: `Psaumes`, chapitre: 37, verset: 32, texte: `L’impie fait le guet, il épie le juste pour le mettre à mort.` },
  { livre: `Psaumes`, chapitre: 37, verset: 33, texte: `Jamais, le Seigneur ne le livrera aux mains des méchants. Il ne permet pas qu’il soit condamné quand il est jugé.` },
  { livre: `Psaumes`, chapitre: 37, verset: 34, texte: `Attends le Seigneur et suis son chemin: Il t’élèvera à la possession de tout le pays. Tu verras comment tous les malfaisants seront retranchés.` },
  { livre: `Psaumes`, chapitre: 37, verset: 35, texte: `J’ai vu le méchant, terrible et puissant, Croître comme un cèdre large et verdoyant.` },
  { livre: `Psaumes`, chapitre: 37, verset: 36, texte: `Mais il a passé: voici qu’il n’est plus. Partout j’ai cherché sans le retrouver.` },
  { livre: `Psaumes`, chapitre: 37, verset: 37, texte: `Garde l’innocence, observe le juste, Car l’homme de paix a un avenir.` },
  { livre: `Psaumes`, chapitre: 37, verset: 38, texte: `Mais les transgresseurs, Ceux qui se révoltent, sont détruits ensemble, Leur postérité sera retranchée.` },
  { livre: `Psaumes`, chapitre: 37, verset: 39, texte: `Le salut des justes vient de l’Éternel Car il est leur force et leur forteresse. Au temps de l’angoisse, l’Éternel les aide` },
  { livre: `Psaumes`, chapitre: 37, verset: 40, texte: `Et il les délivre de tous les méchants. Il les sauvera, car ils ont cherché leur refuge en lui.` },
  { livre: `Psaumes`, chapitre: 38, verset: 0, texte: `Un psaume de David pour se souvenir.` },
  { livre: `Psaumes`, chapitre: 38, verset: 1, texte: `Seigneur, ne me punis pas malgré ta colère. Seigneur, ne me châtie pas malgré ton courroux!` },
  { livre: `Psaumes`, chapitre: 38, verset: 2, texte: `Car tes flèches m’ont atteint, ta main s’est posée sur moi:` },
  { livre: `Psaumes`, chapitre: 38, verset: 3, texte: `Je souffre dans tout mon corps par l’effet de ta colère. Rien n’est sain dans tous mes membres à cause de mon péché.` },
  { livre: `Psaumes`, chapitre: 38, verset: 4, texte: `Mes iniquités s’élèvent bien au-dessus de ma tête, Elles sont un lourd fardeau qui m’accable et qui m’écrase.` },
  { livre: `Psaumes`, chapitre: 38, verset: 5, texte: `Mes plaies infectées suppurent par l’effet de ma folie.` },
  { livre: `Psaumes`, chapitre: 38, verset: 6, texte: `Courbé, triste et abattu, je me traîne tout le jour,` },
  { livre: `Psaumes`, chapitre: 38, verset: 7, texte: `J’ai les reins tout enflammés, rien n’est plus intact en moi.` },
  { livre: `Psaumes`, chapitre: 38, verset: 8, texte: `Je suis à bout, tout brisé, J’ai le cœur en désarroi, je hurle ma plainte.` },
  { livre: `Psaumes`, chapitre: 38, verset: 9, texte: `Ô Seigneur, tous mes désirs sont étalés sous tes yeux, Pas un seul de mes soupirs n’est caché pour toi.` },
  { livre: `Psaumes`, chapitre: 38, verset: 10, texte: `Mon cœur bat violemment et ma vigueur m’abandonne, Et la clarté de mes yeux n’est même plus avec moi.` },
  { livre: `Psaumes`, chapitre: 38, verset: 11, texte: `Ma plaie éloigne de moi mes amis, mes compagnons, Ceux qui me sont les plus proches restent à l’écart.` },
  { livre: `Psaumes`, chapitre: 38, verset: 12, texte: `Tous ceux qui traquent mon âme m’ont tendu des pièges, Ils s’acharnent à ma perte. Ils me menacent de mort. Ils méditent tout le jour leurs machinations perfides.` },
  { livre: `Psaumes`, chapitre: 38, verset: 13, texte: `Pourtant, moi je fais le sourd et je n’entends rien; Je reste comme un muet, sans ouvrir la bouche.` },
  { livre: `Psaumes`, chapitre: 38, verset: 14, texte: `Je suis pareil à celui qui ne comprend pas Et ne peut rien répliquer.` },
  { livre: `Psaumes`, chapitre: 38, verset: 15, texte: `Car c’est en toi seul, Seigneur, que j’ai mis ma confiance. C’est toi seul qui répondras, ô Seigneur, mon Dieu.` },
  { livre: `Psaumes`, chapitre: 38, verset: 16, texte: `Je dis: «Qu’ils ne puissent pas rire Ou triompher de moi en me voyant chanceler».` },
  { livre: `Psaumes`, chapitre: 38, verset: 17, texte: `Oui, je suis près de tomber, ma douleur est toujours là,` },
  { livre: `Psaumes`, chapitre: 38, verset: 18, texte: `Car je reconnais ma faute, je m’effraie de mon péché.` },
  { livre: `Psaumes`, chapitre: 38, verset: 19, texte: `Ceux qui sont mes ennemis sont pleins de vie, pleins de force. Nombreux sont mes adversaires qui me haïssent sans cause.` },
  { livre: `Psaumes`, chapitre: 38, verset: 20, texte: `Pour le bien que j’accomplis, ils me font du mal. Ils se font mes ennemis puisque je poursuis le bien.` },
  { livre: `Psaumes`, chapitre: 38, verset: 21, texte: `Seigneur, ne me laisse pas! Mon Dieu, ne t’éloigne pas!` },
  { livre: `Psaumes`, chapitre: 38, verset: 22, texte: `Viens en hâte à mon secours, toi mon maître et mon Sauveur!` },
  { livre: `Psaumes`, chapitre: 39, verset: 0, texte: `Au chef de chœur, à Jéduthun. Psaume de David.` },
  { livre: `Psaumes`, chapitre: 39, verset: 1, texte: `Je m’étais dit: «Je garderai le bon chemin Sans laisser s’égarer ma langue. Je mettrai un frein à ma bouche Tant que des méchants seront là».` },
  { livre: `Psaumes`, chapitre: 39, verset: 2, texte: `Je me suis imposé silence, je me suis tu tant que j’ai pu, Mais je n’étais pas plus heureux, ma douleur s’est exaspérée.` },
  { livre: `Psaumes`, chapitre: 39, verset: 3, texte: `Mon cœur brûlait dans ma poitrine, ma pensée s’embrasait en moi. Obsédé par ce feu ardent, les mots sont venus sur ma langue:` },
  { livre: `Psaumes`, chapitre: 39, verset: 4, texte: `«Seigneur, fais-moi savoir ma fin et la mesure de mes jours, Afin que je me rende compte à quel point ma vie est éphémère.` },
  { livre: `Psaumes`, chapitre: 39, verset: 5, texte: `Voici, mes jours sont limités, leur longueur n’est que d’une main. En comparaison avec toi, ma vie est pareille au néant. Tout homme debout n’est qu’un souffle».` },
  { livre: `Psaumes`, chapitre: 39, verset: 6, texte: `Oui, chacun passe comme une ombre. C’est bien en vain que l’on s’agite. Et les richesses qu’on entasse, Sait-on qui les recueillera?` },
  { livre: `Psaumes`, chapitre: 39, verset: 7, texte: `Dès lors, Seigneur, que dois-je attendre? Mon espérance est toute en toi,` },
  { livre: `Psaumes`, chapitre: 39, verset: 8, texte: `De tous mes péchés, sauve-moi! (Seigneur,) ne m’abandonne pas aux outrages des insensés!` },
  { livre: `Psaumes`, chapitre: 39, verset: 9, texte: `Voici que je reste muet et que je n’ouvre plus la bouche, Parce que c’est toi qui agis.` },
  { livre: `Psaumes`, chapitre: 39, verset: 10, texte: `Ah! détourne de moi tes coups, Autrement je succomberai sous les attaques de ta main.` },
  { livre: `Psaumes`, chapitre: 39, verset: 11, texte: `Lorsque tu punis les péchés, (Seigneur,) tu corriges les hommes, Et tu détruis comme la teigne Leurs désirs les plus précieux. Tous les hommes ne sont qu’un souffle.` },
  { livre: `Psaumes`, chapitre: 39, verset: 12, texte: `Seigneur, écoute ma prière et prête l’oreille à mon cri! Ne reste pas sourd à mes larmes, Car je suis, chez toi, comme un hôte, Un étranger, un voyageur, comme l’ont été mes ancêtres.` },
  { livre: `Psaumes`, chapitre: 39, verset: 13, texte: `Détourne de moi ton regard! Laisse-moi un peu de répit! Pour que je puisse respirer avant de partir pour jamais.` },
  { livre: `Psaumes`, chapitre: 40, verset: 0, texte: `Au chef de chœur. Psaume de David.` },
  { livre: `Psaumes`, chapitre: 40, verset: 1, texte: `J’ai mis tout mon espoir dans le Seigneur, mon Dieu. Il s’est penché vers moi, il a prêté l’oreille à ma supplication.` },
  { livre: `Psaumes`, chapitre: 40, verset: 2, texte: `Il m’a fait remonter Du puits de perdition plein de boue et de fange. Il m’a remis debout sur un rocher solide: mes pas sont affermis.` },
  { livre: `Psaumes`, chapitre: 40, verset: 3, texte: `Il a mis dans ma bouche un cantique nouveau, Un hymne de louanges en l’honneur du Seigneur. Beaucoup s’en aperçoivent Et, pénétrés de crainte, ils se confient en Dieu.` },
  { livre: `Psaumes`, chapitre: 40, verset: 4, texte: `Heureux, oui, heureux l’homme, qui fait confiance à Dieu Et ne se tourne pas vers les gens orgueilleux Qui prônent le mensonge.` },
  { livre: `Psaumes`, chapitre: 40, verset: 5, texte: `Ô Éternel, mon Dieu, tu accomplis pour nous Des œuvres merveilleuses, Tu as multiplié tes desseins bienveillants. Qui est semblable à toi? Je voudrais publier, annoncer tes merveilles, Elles sont trop nombreuses pour être énumérées.` },
  { livre: `Psaumes`, chapitre: 40, verset: 6, texte: `Tu ne prends nul plaisir à l’offrande, aux victimes, Tu m’as ouvert l’oreille, Tu n’as pas exigé (de nous) des holocaustes Ou bien des sacrifices expiant le péché.` },
  { livre: `Psaumes`, chapitre: 40, verset: 7, texte: `Alors, j’ai dit: «Voici, je viens, je me présente – Dans le rouleau du livre, il est question de moi –` },
  { livre: `Psaumes`, chapitre: 40, verset: 8, texte: `Je prends plaisir à faire ta volonté, mon Dieu, Et ta loi est gravée tout au fond de mon cœur».` },
  { livre: `Psaumes`, chapitre: 40, verset: 9, texte: `À la grande assemblée, j’annonce ta justice: C’est la bonne nouvelle que mes lèvres proclament; Je ne les ferme pas, Seigneur, tu le sais bien;` },
  { livre: `Psaumes`, chapitre: 40, verset: 10, texte: `Je n’ai pas fait silence En secret dans mon cœur sur ta justice. J’ai proclamé bien haut que tu étais fidèle et que tu m’as sauvé, Sans rien dissimuler de ta miséricorde et de ta vérité Dans la grande assemblée.` },
  { livre: `Psaumes`, chapitre: 40, verset: 11, texte: `Et toi, Seigneur, mon Dieu, Tu ne retiendras pas loin de moi ta tendresse. C’est ta miséricorde et ta fidélité qui veilleront sur moi.` },
  { livre: `Psaumes`, chapitre: 40, verset: 12, texte: `Car des maux innombrables m’environnent partout, Mes péchés m’ont atteint, je ne peux plus les voir, Ils surpassent en nombre les cheveux de ma tête, Le courage me manque.` },
  { livre: `Psaumes`, chapitre: 40, verset: 13, texte: `Ô Seigneur, s’il te plaît, viens donc me délivrer! Viens vite à mon secours!` },
  { livre: `Psaumes`, chapitre: 40, verset: 14, texte: `Qu’ils soient tous confondus, qu’ils soient couverts de honte Ceux qui cherchent ma mort! Qu’ils soient déshonorés et battent en retraite, Ceux qui veulent ma perte!` },
  { livre: `Psaumes`, chapitre: 40, verset: 15, texte: `Qu’ils soient dans la stupeur sous l’effet de la honte, Ceux qui disent de moi: «Ah ah! Bien fait pour lui!»` },
  { livre: `Psaumes`, chapitre: 40, verset: 16, texte: `Qu’ils soient dans l’allégresse, Qu’en toi ils se réjouissent, tous ceux qui te recherchent! S’ils aiment ton salut, qu’ils redisent sans cesse: «Qu’il est grand, le Seigneur!»` },
  { livre: `Psaumes`, chapitre: 40, verset: 17, texte: `Moi, pauvre et misérable, Je sais que le Seigneur s’occupera de moi. C’est toi qui es mon aide et mon libérateur! Mon Dieu, ne tarde pas!` },
  { livre: `Psaumes`, chapitre: 41, verset: 0, texte: `Au chef de chœur. Psaume de David.` },
  { livre: `Psaumes`, chapitre: 41, verset: 1, texte: `Bienheureux est celui qui s’intéresse au pauvre. Quand survient un malheur, le Seigneur le délivre,` },
  { livre: `Psaumes`, chapitre: 41, verset: 2, texte: `Le Seigneur le protège, il l’aidera à vivre Et le rendra heureux ici-bas sur la terre, Tu ne le livres pas aux désirs insatiables de tous ses ennemis.` },
  { livre: `Psaumes`, chapitre: 41, verset: 3, texte: `Le Seigneur le soutient sur son lit de souffrances. Quand il est malade, tu lui refais sa couche.` },
  { livre: `Psaumes`, chapitre: 41, verset: 4, texte: `J’ai dit: «Pitié, Seigneur! Par grâce, guéris-moi! J’ai péché contre toi».` },
  { livre: `Psaumes`, chapitre: 41, verset: 5, texte: `Mes adversaires parlent méchamment contre moi: «Quand donc va-t-il mourir? Quand périra son nom?»` },
  { livre: `Psaumes`, chapitre: 41, verset: 6, texte: `L’un d’eux vient-il me voir, il se met à mentir: Son cœur emmagasine des sujets de médire, Et, dès qu’il est dehors, il parle pour me nuire.` },
  { livre: `Psaumes`, chapitre: 41, verset: 7, texte: `Tous unis contre moi, Mes ennemis chuchotent, ne pensant qu’à ma perte:` },
  { livre: `Psaumes`, chapitre: 41, verset: 8, texte: `«C’est un mal incurable qui s’acharne après lui, Celui qui est couché ne se relève plus».` },
  { livre: `Psaumes`, chapitre: 41, verset: 9, texte: `Oui, mon ami intime À qui je me fiais, qui partageait mon pain, Lui aussi me trahit, me donne un coup de pied.` },
  { livre: `Psaumes`, chapitre: 41, verset: 10, texte: `Mais toi, du moins, Seigneur, dans ta grâce, aide-moi Et viens me relever, pour que j’aie ma revanche.` },
  { livre: `Psaumes`, chapitre: 41, verset: 11, texte: `À ceci, je saurai que tu veux bien de moi: Si tu ne laisses pas l’ennemi triompher.` },
  { livre: `Psaumes`, chapitre: 41, verset: 12, texte: `Car je suis innocent, aussi tu me soutiens, Tu me fais subsister devant toi pour toujours.` },
  { livre: `Psaumes`, chapitre: 41, verset: 13, texte: `Béni soit le Seigneur, le (grand) Dieu d’Israël, Depuis l’éternité jusqu’à l’éternité, Ainsi soit-il! Amen!` },
  { livre: `Psaumes`, chapitre: 42, verset: 0, texte: `Au chef de chœur. Poème didactique des fils de Koré.` },
  { livre: `Psaumes`, chapitre: 42, verset: 1, texte: `Comme un cerf qui languit après les courants d’eau, Ainsi languit mon âme après toi, ô (mon) Dieu.` },
  { livre: `Psaumes`, chapitre: 42, verset: 2, texte: `Mon âme a soif de Dieu, du Dieu fort et vivant. Quand donc pourrai-je entrer, paraître devant Dieu?` },
  { livre: `Psaumes`, chapitre: 42, verset: 3, texte: `Mes larmes sont le pain de mes jours et mes nuits. Sans cesse, on me répète: «Où donc est-il, ton Dieu?»` },
  { livre: `Psaumes`, chapitre: 42, verset: 4, texte: `Je suis ému aux larmes, lorsque je me souviens Du temps où je marchais, entouré de la foule, Vers la maison de Dieu, avec des cris de joie Et des actions de grâces de tout un peuple en fête.` },
  { livre: `Psaumes`, chapitre: 42, verset: 5, texte: `Pourquoi donc, ô mon âme, es-tu si abattue? Pourquoi te replier sur toi-même et gémir? Mets ton espoir en Dieu: Je le louerai encore, car il est mon Sauveur.` },
  { livre: `Psaumes`, chapitre: 42, verset: 6, texte: `Mon âme est abattue. Ô mon Dieu, c’est pourquoi Du pays du Jourdain, des cimes de l’Hermon, Et du mont de Misar, je me souviens de toi.` },
  { livre: `Psaumes`, chapitre: 42, verset: 7, texte: `S’appelant l’une l’autre, Les vagues se répondent quand mugit la tempête. Au bruit de tes cascades, tous tes flots et tes lames Ont déferlé sur moi.` },
  { livre: `Psaumes`, chapitre: 42, verset: 8, texte: `(Pourtant,) pendant le jour, Dieu m’accordait sa grâce, Et je passais la nuit à chanter ses louanges. J’adressais ma prière au Dieu qui est ma vie.` },
  { livre: `Psaumes`, chapitre: 42, verset: 9, texte: `Je veux dire à ce Dieu qui seul est mon rocher: «Pourquoi donc m’oublies-tu? Pourquoi dois-je marcher sombre et dans la tristesse, Pressé par l’ennemi?»` },
  { livre: `Psaumes`, chapitre: 42, verset: 10, texte: `Mes membres sont meurtris, mes ennemis m’insultent, Sans cesse, ils me demandent: «Où donc est-il, ton Dieu?»` },
  { livre: `Psaumes`, chapitre: 42, verset: 11, texte: `Pourquoi donc, ô mon âme, es-tu si abattue,? Pourquoi te replier sur toi-même et gémir? Mets ton espoir en Dieu! Je le louerai encore, car il est mon Sauveur, (Mon secours) et mon Dieu.` },
  { livre: `Psaumes`, chapitre: 43, verset: 1, texte: `Fais moi justice, ô Dieu, Et prends en main ma cause Contre un peuple sans foi. Délivre-moi de ceux qui sont méchants et faux!` },
  { livre: `Psaumes`, chapitre: 43, verset: 2, texte: `Toi qui es mon refuge, Pourquoi m’as-tu banni? Pourquoi dois-je marcher Sombre et dans la tristesse, Pressé par l’ennemi?` },
  { livre: `Psaumes`, chapitre: 43, verset: 3, texte: `Envoie donc ta lumière, Fais voir ta vérité, Pour qu’elles soient mes guides Et qu’elles me conduisent Vers ta sainte montagne, Jusqu’à tes tabernacles.` },
  { livre: `Psaumes`, chapitre: 43, verset: 4, texte: `Je voudrais revenir jusqu’à l’autel de Dieu, Vers le Dieu de ma joie et de mon allégresse. Je voudrais te louer aux accents des cithares, Ô Dieu: tu es mon Dieu!` },
  { livre: `Psaumes`, chapitre: 43, verset: 5, texte: `Pourquoi donc, ô mon âme, es-tu si abattue? Pourquoi te replier sur toi-même et gémir? Mets ton espoir en Dieu: je le louerai encore, Car il est mon Sauveur, (mon secours) et mon Dieu.` },
  { livre: `Psaumes`, chapitre: 44, verset: 0, texte: `Au chef de chœur. Un poème didactique des fils de Koré.` },
  { livre: `Psaumes`, chapitre: 44, verset: 1, texte: `Ô Dieu, nous avons entendu, nos pères nous ont raconté Quels exploits tu as accomplis autrefois, de leur temps:` },
  { livre: `Psaumes`, chapitre: 44, verset: 2, texte: `Ta main a chassé des nations et tu as implanté nos pères; Pour qu’ils aient l’espace voulu, tu as dépossédé des peuples.` },
  { livre: `Psaumes`, chapitre: 44, verset: 3, texte: `Ce n’est pas grâce à leur épée qu’ils ont occupé cette terre Ni par la force de leurs bras qu’ils ont remporté la victoire. C’est ta main droite, c’est ton bras, c’est la lumière de ta face (Qui leur a donné tout cela), c’est parce que tu les aimais.` },
  { livre: `Psaumes`, chapitre: 44, verset: 4, texte: `C’est toi, ô Dieu, qui es mon roi et qui fais triompher Jacob.` },
  { livre: `Psaumes`, chapitre: 44, verset: 5, texte: `Par toi, nous chassons l’ennemi, par ton nom, nous foulons aux pieds ceux qui s’élèvent contre nous.` },
  { livre: `Psaumes`, chapitre: 44, verset: 6, texte: `Je n’ai pas compté sur mon arc, mon glaive ne me sauve pas,` },
  { livre: `Psaumes`, chapitre: 44, verset: 7, texte: `C’est toi qui nous fais remporter la victoire sur l’adversaire, C’est toi qui as couvert de honte ceux qui nous haïssaient.` },
  { livre: `Psaumes`, chapitre: 44, verset: 8, texte: `Tous les jours, nous avons chanté les louanges de notre Dieu, Nous voulons célébrer son nom pendant toute l’éternité.` },
  { livre: `Psaumes`, chapitre: 44, verset: 9, texte: `Pourtant, tu nous as rejetés et tu nous as couverts de honte. Tu as cessé d’accompagner nos armées au combat!` },
  { livre: `Psaumes`, chapitre: 44, verset: 10, texte: `Tu nous as fait tourner le dos devant ceux qui nous attaquaient. L’ennemi nous a dépouillés, il a pillé nos biens.` },
  { livre: `Psaumes`, chapitre: 44, verset: 11, texte: `Tu as fait de nous une troupe destinée à la boucherie, Et tu nous as disséminés parmi les étrangers.` },
  { livre: `Psaumes`, chapitre: 44, verset: 12, texte: `Oui, tu vends ton peuple aux enchères pour une somme dérisoire, Tu n’as pas majoré son prix, tu ne l’estimes pas.` },
  { livre: `Psaumes`, chapitre: 44, verset: 13, texte: `Tu nous as livrés à l’opprobre parmi tous nos voisins. Notre entourage nous accable de sarcasme et de raillerie.` },
  { livre: `Psaumes`, chapitre: 44, verset: 14, texte: `Tu as fait de nous la risée, la fable des païens! En nous voyant, les étrangers hochent la tête en ricanant.` },
  { livre: `Psaumes`, chapitre: 44, verset: 15, texte: `Tout le jour, je suis humilié, ma honte est toujours devant moi, La confusion couvre mon front` },
  { livre: `Psaumes`, chapitre: 44, verset: 16, texte: `Quand j’entends les propos blessants, Les blasphèmes de l’ennemi, de celui qui veut se venger.` },
  { livre: `Psaumes`, chapitre: 44, verset: 17, texte: `Tout cela nous est arrivé sans que nous t’ayons oublié Et sans que nous ayons violé ton alliance avec nous.` },
  { livre: `Psaumes`, chapitre: 44, verset: 18, texte: `Notre cœur ne s’est pas repris, Nous n’avons pas rétrogradé, nos pas n’ont pas quitté ta voie.` },
  { livre: `Psaumes`, chapitre: 44, verset: 19, texte: `Pourtant, tu nous as refoulés là où demeurent les chacals, Tu nous couvres d’obscurité, de ténèbres mortelles.` },
  { livre: `Psaumes`, chapitre: 44, verset: 20, texte: `Si nous avions mis en oubli le nom de notre Dieu, Si nous avions tendu nos mains vers un dieu étranger,` },
  { livre: `Psaumes`, chapitre: 44, verset: 21, texte: `Dieu ne l’aurait-il pas appris, lui qui connaît le fond des cœurs?` },
  { livre: `Psaumes`, chapitre: 44, verset: 22, texte: `À cause de toi, chaque jour, nous sommes massacrés Et l’on nous traite sans arrêt comme des brebis d’abattoir.` },
  { livre: `Psaumes`, chapitre: 44, verset: 23, texte: `Réveille-toi donc, ô Seigneur! Pourquoi dormirais-tu? Sors de ton sommeil, (lève-toi,) ne nous renie pas pour toujours!` },
  { livre: `Psaumes`, chapitre: 44, verset: 24, texte: `Pourquoi caches-tu ton visage? Pourquoi oublies-tu nos malheurs et nos tribulations?` },
  { livre: `Psaumes`, chapitre: 44, verset: 25, texte: `Notre âme est abattue à terre, notre corps est cloué au sol,` },
  { livre: `Psaumes`, chapitre: 44, verset: 26, texte: `Lève-toi, Seigneur, viens à l’aide! Rachète-nous dans ton amour!` },
  { livre: `Psaumes`, chapitre: 45, verset: 0, texte: `Au chef de chœur, sur l’air «Les lis». Un poème didactique et un chant d’amour des fils de Koré.` },
  { livre: `Psaumes`, chapitre: 45, verset: 1, texte: `Des paroles charmantes bouillonnent dans mon cœur. Je dirai mon poème, je le dédie au Roi. Que ma langue s’anime Comme la plume agile d’un écrivain habile.` },
  { livre: `Psaumes`, chapitre: 45, verset: 2, texte: `Parmi les fils des hommes, c’est bien toi le plus beau! La grâce est sur tes lèvres; C’est pourquoi l’Éternel t’a béni à jamais.` },
  { livre: `Psaumes`, chapitre: 45, verset: 3, texte: `Guerrier plein de vaillance, ceins ton épée au flanc! Dans ta magnificence,` },
  { livre: `Psaumes`, chapitre: 45, verset: 4, texte: `Dans l’éclat de ta gloire, remporte des succès! Mène ton char de guerre, Défends la vérité, la douceur, la justice! Que ta main se signale par des actions d’éclat!` },
  { livre: `Psaumes`, chapitre: 45, verset: 5, texte: `Tes flèches sont mordantes, Et des peuples soumis tomberont devant toi. Ils perdent leur courage, les ennemis du roi.` },
  { livre: `Psaumes`, chapitre: 45, verset: 6, texte: `Ton trône, ô Dieu, subsiste pour toute éternité, Le sceptre de ton règne est sceptre d’équité.` },
  { livre: `Psaumes`, chapitre: 45, verset: 7, texte: `Tu aimes la justice, tu hais l’iniquité. Aussi, ô Dieu, ton Dieu t’a marqué de l’onction Avec l’huile de joie, plus que tes compagnons.` },
  { livre: `Psaumes`, chapitre: 45, verset: 8, texte: `Tes vêtements exhalent la myrrhe et l’aloès, La casse les embaume. Dans le palais d’ivoire où tu seras fêté, les harpes te ravissent.` },
  { livre: `Psaumes`, chapitre: 45, verset: 9, texte: `Et voici des princesses qui s’avancent vers toi, La reine est à ta droite, parée de l’or d’Ophir.` },
  { livre: `Psaumes`, chapitre: 45, verset: 10, texte: `Entends, ma fille, et vois! Viens et prête l’oreille, Mets en oubli ton peuple, la maison de ton père.` },
  { livre: `Psaumes`, chapitre: 45, verset: 11, texte: `Et que le Roi s’éprenne de toi, de ta beauté! Puisque c’est lui ton maître, courbe-toi devant lui!` },
  { livre: `Psaumes`, chapitre: 45, verset: 12, texte: `En te rendant hommage, Les habitants de Tyr, les peuples les plus riches Viendront chargés d’offrandes pour gagner ta faveur.` },
  { livre: `Psaumes`, chapitre: 45, verset: 13, texte: `Toute resplendissante est la fille du roi, Cachée en sa demeure au milieu du palais. D’étoffes précieuses et d’or, elle est parée.` },
  { livre: `Psaumes`, chapitre: 45, verset: 14, texte: `En vêtements brodés, on la présente au roi. De jeunes demoiselles la suivent en cortège et te sont amenées.` },
  { livre: `Psaumes`, chapitre: 45, verset: 15, texte: `Avec des chants de fête, au milieu de la joie, Elles sont introduites dans le palais du roi.` },
  { livre: `Psaumes`, chapitre: 45, verset: 16, texte: `Au trône de tes pères, succéderont tes fils, Tu en feras des princes sur le pays entier.` },
  { livre: `Psaumes`, chapitre: 45, verset: 17, texte: `Je publierai ton nom à travers tous les siècles. C’est pourquoi tous les peuples te loueront à jamais, Ils te rendront hommage durant l’éternité.` },
  { livre: `Psaumes`, chapitre: 46, verset: 0, texte: `Au chef de chœur. Cantique des fils de Koré pour voix de soprano.` },
  { livre: `Psaumes`, chapitre: 46, verset: 1, texte: `Dieu est pour nous un rempart, un refuge et un appui, Un secours toujours offert lorsque survient le danger.` },
  { livre: `Psaumes`, chapitre: 46, verset: 2, texte: `Aussi, nous ne craignons rien si la terre est secouée, Si les montagnes s’effondrent et basculent au fond des mers.` },
  { livre: `Psaumes`, chapitre: 46, verset: 3, texte: `Que les eaux des océans grondent et bouillonnent, Que les montagnes frémissent devant son emportement!` },
  { livre: `Psaumes`, chapitre: 46, verset: 4, texte: `Il y a un fleuve, ses eaux sont paisibles, Elles réjouissent la cité de Dieu, Les saintes demeures qui sont habitées par le Dieu très-haut.` },
  { livre: `Psaumes`, chapitre: 46, verset: 5, texte: `Dieu réside au milieu d’elle, elle ne chancelle pas. Le Seigneur lui vient en aide dès qu’apparaît le matin.` },
  { livre: `Psaumes`, chapitre: 46, verset: 6, texte: `Des peuples s’agitent, des règnes s’effondrent, Sa voix retentit, et la terre tremble.` },
  { livre: `Psaumes`, chapitre: 46, verset: 7, texte: `Le Seigneur de l’univers, l’Éternel est avec nous: Nous avons pour citadelle le Dieu de Jacob.` },
  { livre: `Psaumes`, chapitre: 46, verset: 8, texte: `Venez contempler les œuvres, les hauts faits de l’Éternel: Il déchaîne sur la terre des ravages effrayants.` },
  { livre: `Psaumes`, chapitre: 46, verset: 9, texte: `Il fait cesser les combats jusqu’aux confins de la terre, Il a brisé l’arc et rompu la lance, Il consume au feu tous les chars de guerre.` },
  { livre: `Psaumes`, chapitre: 46, verset: 10, texte: `«Arrêtez! dit-il, reconnaissez-moi pour Dieu. Je triomphe des nations, je domine sur la terre.»` },
  { livre: `Psaumes`, chapitre: 46, verset: 11, texte: `Le Seigneur de l’univers, l’Éternel est avec nous, Nous avons pour citadelle le Dieu de Jacob.` },
  { livre: `Psaumes`, chapitre: 47, verset: 0, texte: `Au chef de chœur. Un psaume des fils de Koré.` },
  { livre: `Psaumes`, chapitre: 47, verset: 1, texte: `Vous, tous les peuples, battez des mains! Poussez vers Dieu des cris de joie!` },
  { livre: `Psaumes`, chapitre: 47, verset: 2, texte: `Car le Seigneur est le Très-Haut, Le redoutable et le grand Roi de l’univers.` },
  { livre: `Psaumes`, chapitre: 47, verset: 3, texte: `Il a soumis à notre empire des nations, Il met des peuples dessous nos pieds.` },
  { livre: `Psaumes`, chapitre: 47, verset: 4, texte: `Il a choisi notre héritage Qui fait la gloire propre à Jacob son bien-aimé.` },
  { livre: `Psaumes`, chapitre: 47, verset: 5, texte: `Dieu est monté parmi les cris de la victoire. (Il est monté) au son du cor, lui, le Seigneur.` },
  { livre: `Psaumes`, chapitre: 47, verset: 6, texte: `Chantez à Dieu! Chantez, chantez pour notre roi! Chantez sa gloire,` },
  { livre: `Psaumes`, chapitre: 47, verset: 7, texte: `Car il est Roi de l’univers. Sonnez pour Dieu de tout votre art!` },
  { livre: `Psaumes`, chapitre: 47, verset: 8, texte: `L’Éternel règne sur les nations. Il a pris place sur son saint trône.` },
  { livre: `Psaumes`, chapitre: 47, verset: 9, texte: `Les chefs des peuple se réunissent Avec ton peuple, Dieu d’Abraham! Car Dieu soumet tous les puissants de cette terre. Oui, sa puissance est sans limites.` },
  { livre: `Psaumes`, chapitre: 48, verset: 0, texte: `Cantique. Un psaume des fils de Koré.` },
  { livre: `Psaumes`, chapitre: 48, verset: 1, texte: `Le Seigneur est grand, Infiniment digne de toutes louanges. Sa montagne sainte est dans la cité de notre Seigneur.` },
  { livre: `Psaumes`, chapitre: 48, verset: 2, texte: `Élancée et fière, la sainte colline de Sion, la belle, Est source de joie pour la terre entière. Au septentrion, voici la cité, celle du grand Roi.` },
  { livre: `Psaumes`, chapitre: 48, verset: 3, texte: `Dieu, dans ses palais, se révèle à nous comme un vrai rempart.` },
  { livre: `Psaumes`, chapitre: 48, verset: 4, texte: `Car voici, contre la ville, les rois s’étaient concertés. Ensemble, ils ont avancé.` },
  { livre: `Psaumes`, chapitre: 48, verset: 5, texte: `Mais dès qu’ils l’ont aperçue, la stupeur les a saisis, L’épouvante les a pris, et ils se sont tous enfuis.` },
  { livre: `Psaumes`, chapitre: 48, verset: 6, texte: `Ils se sont mis à trembler, Comme une femme en travail quand la douleur la saisit.` },
  { livre: `Psaumes`, chapitre: 48, verset: 7, texte: `Ils ont été dispersés comme des bateaux au vent Lorsque le vent d’Orient brise les navires de Tarsis.` },
  { livre: `Psaumes`, chapitre: 48, verset: 8, texte: `Ce que nous avions appris, nous l’avons vu de nos yeux Dans la ville du Seigneur, de l’Éternel des armées, La cité de notre Dieu. Dieu l’affermit à jamais.` },
  { livre: `Psaumes`, chapitre: 48, verset: 9, texte: `Nous pensons à ta bonté, ô Dieu, dans ton sanctuaire,` },
  { livre: `Psaumes`, chapitre: 48, verset: 10, texte: `Ainsi que ton nom, ô Dieu, Ta louange retentit jusqu’aux confins de la terre. Tu répands, à pleines mains, la justice, le salut.` },
  { livre: `Psaumes`, chapitre: 48, verset: 11, texte: `Que le mont Sion jubile, que les filles de Juda Soient transportées d’allégresse, car tes jugements sont justes!` },
  { livre: `Psaumes`, chapitre: 48, verset: 12, texte: `Parcourez Sion, longez son enceinte, comptez-en les tours.` },
  { livre: `Psaumes`, chapitre: 48, verset: 13, texte: `Considérez bien ses murs fortifiés! Passez en revue chacun des palais, Pour le raconter aux générations qui viendront un jour.` },
  { livre: `Psaumes`, chapitre: 48, verset: 14, texte: `Car c’est ce Dieu-là qui est notre Dieu, Éternellement et à tout jamais, C’est lui qui nous guide jusqu’à notre mort.` },
  { livre: `Psaumes`, chapitre: 49, verset: 0, texte: `Au chef de chœur. Un psaume des fils de Koré.` },
  { livre: `Psaumes`, chapitre: 49, verset: 1, texte: `Ô vous, tous les peuples, écoutez ceci! Habitants du monde, ouvrez vos oreilles,` },
  { livre: `Psaumes`, chapitre: 49, verset: 2, texte: `Vous, les gens illustres et les gens obscurs, Vous, les hommes riches comme vous les pauvres!` },
  { livre: `Psaumes`, chapitre: 49, verset: 3, texte: `Ma bouche dira des paroles sages, La raison m’inspire les pensées du cœur.` },
  { livre: `Psaumes`, chapitre: 49, verset: 4, texte: `Je prête l’oreille à quelque proverbe. Au son de la harpe, je dis mes pensées.` },
  { livre: `Psaumes`, chapitre: 49, verset: 5, texte: `Pourquoi donc craindrais-je Ce qui adviendra aux jours du malheur, Quand l’iniquité de mes ennemis m’environnera?` },
  { livre: `Psaumes`, chapitre: 49, verset: 6, texte: `Ils ont foi dans leur fortune Et ils tirent vanité de leurs immenses richesses.` },
  { livre: `Psaumes`, chapitre: 49, verset: 7, texte: `Et cependant, aucun d’eux ne peut racheter son frère. Aucun ne saurait payer à Dieu sa propre rançon.` },
  { livre: `Psaumes`, chapitre: 49, verset: 8, texte: `Trop coûteux est le rachat de leur âme, de leur vie. Ils n’y parviendraient jamais même dans l’éternité.` },
  { livre: `Psaumes`, chapitre: 49, verset: 9, texte: `Ils ne vivront pas toujours: Ils ne pourront éviter de descendre dans la tombe.` },
  { livre: `Psaumes`, chapitre: 49, verset: 10, texte: `On voit que les sages, l’imbécile et l’insensé, Périssent également, laissant à d’autres leurs biens.` },
  { livre: `Psaumes`, chapitre: 49, verset: 11, texte: `Cependant, ils s’imaginent Que leurs maisons vont durer jusque dans l’éternité. Ils pensent que leurs demeures Seront à l’abri du temps pendant des générations, Qu’ils peuvent donner leur nom à leurs terres pour toujours.` },
  { livre: `Psaumes`, chapitre: 49, verset: 12, texte: `L’homme le plus opulent ne demeure pas longtemps: Il est semblable au bétail que l’on réduit au silence.` },
  { livre: `Psaumes`, chapitre: 49, verset: 13, texte: `Telle est leur voie, leur folie Et le sort final de ceux qui approuvent leurs discours.` },
  { livre: `Psaumes`, chapitre: 49, verset: 14, texte: `Vers le séjour des ténèbres, Ils s’avancent tous ensemble Comme un troupeau de moutons Que la mort mènerait paître. Quand se lèvera l’aurore, Seuls les justes prévaudront sur eux et triompheront. Alors que, dans leur demeure, dans le séjour de la mort, Leur beauté s’évanouira,` },
  { livre: `Psaumes`, chapitre: 49, verset: 15, texte: `Dieu rachètera mon âme, Il arrachera ma vie des mains du séjour des morts, Sous sa garde il me prendra.` },
  { livre: `Psaumes`, chapitre: 49, verset: 16, texte: `Ne sois donc pas alarmé quand un homme s’enrichit Et lorsque tu vois s’accroître la gloire de sa maison.` },
  { livre: `Psaumes`, chapitre: 49, verset: 17, texte: `Car, lorsqu’un jour il mourra, il ne pourra emporter Aucun trésor amassé: ses biens ne le suivront pas.` },
  { livre: `Psaumes`, chapitre: 49, verset: 18, texte: `Il a beau se dire heureux pendant sa vie d’ici-bas Et s’attirer des louanges d’avoir trouvé le bien-être,` },
  { livre: `Psaumes`, chapitre: 49, verset: 19, texte: `Il rejoindra ses ancêtres qui, jamais, Ne reverront plus la lumière du jour.` },
  { livre: `Psaumes`, chapitre: 49, verset: 20, texte: `L’homme qui est en honneur, s’il n’a pas d’intelligence, Est semblable aux animaux que l’on réduit au silence.` },
  { livre: `Psaumes`, chapitre: 50, verset: 1, texte: `Psaume d’Asaph. Le Dieu très-haut et tout-puissant, l’Éternel va parler. Il appelle la terre entière, du levant au couchant.` },
  { livre: `Psaumes`, chapitre: 50, verset: 2, texte: `De Sion, parfaite en beauté, l’Éternel resplendit.` },
  { livre: `Psaumes`, chapitre: 50, verset: 3, texte: `Qu’il vienne notre Dieu! Qu’il sorte donc de son silence! Devant lui brûle un feu; autour de lui, c’est la tempête.` },
  { livre: `Psaumes`, chapitre: 50, verset: 4, texte: `Il convoque les plus hauts cieux, Il convoque la terre, il vient juger son peuple:` },
  { livre: `Psaumes`, chapitre: 50, verset: 5, texte: `«Rassemblez devant moi les miens, Ceux qui ont conclu avec moi l’alliance par le sacrifice.»` },
  { livre: `Psaumes`, chapitre: 50, verset: 6, texte: `Les cieux publieront sa justice; le juge, oui, c’est Dieu!` },
  { livre: `Psaumes`, chapitre: 50, verset: 7, texte: `«Mon peuple, écoute, je te parle, Israël, j’ouvre ton procès: ton Seigneur Dieu, c’est moi.` },
  { livre: `Psaumes`, chapitre: 50, verset: 8, texte: `Ce n’est pas pour tes sacrifices que je t’accuserai, Tes holocaustes, constamment, sont présents à mes yeux.` },
  { livre: `Psaumes`, chapitre: 50, verset: 9, texte: `Je n’ai que faire des taureaux, je me garderai bien de prendre Un bœuf de ton étable, un bélier de tes fermes,` },
  { livre: `Psaumes`, chapitre: 50, verset: 10, texte: `Car tout le gibier des forêts est en ma possession. Toutes les bêtes des montagnes, par milliers, m’appartiennent:` },
  { livre: `Psaumes`, chapitre: 50, verset: 11, texte: `Je connais l’oiseau des collines et la faune des champs.` },
  { livre: `Psaumes`, chapitre: 50, verset: 12, texte: `Si j’avais faim, te le dirais-je? L’univers est à moi, et tout ce qu’il renferme.` },
  { livre: `Psaumes`, chapitre: 50, verset: 13, texte: `Vais-je manger des taureaux gras, boire du sang de bouc?` },
  { livre: `Psaumes`, chapitre: 50, verset: 14, texte: `Offre au Seigneur, en sacrifice, la louange et l’action de grâces! Accomplis envers le Très-Haut les vœux que tu as faits.` },
  { livre: `Psaumes`, chapitre: 50, verset: 15, texte: `Alors, tu pourras m’invoquer au jour de la détresse, Je te tirerai du danger, et tu me rendras gloire.»` },
  { livre: `Psaumes`, chapitre: 50, verset: 16, texte: `Au pécheur aussi, Dieu s’adresse: «Pourquoi rabâches-tu mes lois? Tu as mon alliance à la bouche,` },
  { livre: `Psaumes`, chapitre: 50, verset: 17, texte: `Mais tu détestes l’instruction Et tu rejettes mes paroles derrière toi, au loin.` },
  { livre: `Psaumes`, chapitre: 50, verset: 18, texte: `À peine as-tu vu un voleur, tu te fais son complice, Et tu fais bien cause commune avec les adultères.` },
  { livre: `Psaumes`, chapitre: 50, verset: 19, texte: `Ta bouche forge la malice et la méchanceté! Ta langue est mariée à la fraude.` },
  { livre: `Psaumes`, chapitre: 50, verset: 20, texte: `Lorsque tu t’assieds avec d’autres, tu calomnies ton frère, Tu vas jeter le déshonneur sur le fils de ta mère.` },
  { livre: `Psaumes`, chapitre: 50, verset: 21, texte: `Lorsque tu agissais ainsi et que je n’ai rien dit, Tu as vraiment imaginé que je te ressemblais? Aussi vais-je te corriger, tout mettre sous tes yeux.` },
  { livre: `Psaumes`, chapitre: 50, verset: 22, texte: `Prenez donc garde et comprenez, vous qui oubliez Dieu, Sinon je vous déchirerai et nul ne vous délivrera.` },
  { livre: `Psaumes`, chapitre: 50, verset: 23, texte: `Celui qui offre la louange, celui-là me rend gloire. À celui qui veille avec soin sur la voie où il marche, Je ferai contempler le salut du Seigneur».` },
  { livre: `Psaumes`, chapitre: 51, verset: 0, texte: `Au chef de chœur. Un psaume de David, qu’il composa lorsque le prophète Nathan vint chez lui après qu’il eut péché avec Bath-Schéba.` },
  { livre: `Psaumes`, chapitre: 51, verset: 1, texte: `Aie pitié de moi, ô Dieu! Dans ton amour, fais-moi grâce! Dans tes grandes compassions, efface mes transgressions!` },
  { livre: `Psaumes`, chapitre: 51, verset: 2, texte: `Lave-moi de toute faute, nettoie-moi de mon péché!` },
  { livre: `Psaumes`, chapitre: 51, verset: 3, texte: `Car je reconnais mes torts Et la vue de mon péché reste toujours devant moi.` },
  { livre: `Psaumes`, chapitre: 51, verset: 4, texte: `Envers toi seul, j’ai péché, j’ai fait le mal à tes yeux. Tu es juste quand tu parles, tu as raison quand tu juges.` },
  { livre: `Psaumes`, chapitre: 51, verset: 5, texte: `Je suis né chargé de fautes, Et j’étais déjà pécheur quand ma mère m’a porté.` },
  { livre: `Psaumes`, chapitre: 51, verset: 6, texte: `Mais tu veux que la droiture soit en moi, au fond du cœur, Tu m’enseignes la sagesse au plus profond de moi-même.` },
  { livre: `Psaumes`, chapitre: 51, verset: 7, texte: `Purifie-moi du péché avec un rameau d’hysope, Et je serai purifié! Lave-moi et je serai plus blanc même que la neige.` },
  { livre: `Psaumes`, chapitre: 51, verset: 8, texte: `Rends-moi le son de la joie! Fais-moi vibrer d’allégresse! Les os que tu as broyés retrouveront le bonheur.` },
  { livre: `Psaumes`, chapitre: 51, verset: 9, texte: `Veuille te voiler la face pour ne plus voir mes péchés! Efface toutes mes fautes,` },
  { livre: `Psaumes`, chapitre: 51, verset: 10, texte: `Recrée en moi un cœur pur! Ô Seigneur, (rénove-moi)! Fais renaître dans mon sein un esprit bien disposé!` },
  { livre: `Psaumes`, chapitre: 51, verset: 11, texte: `Ne me repousse jamais loin de toi, de ta présence, Et ne me retire pas ton esprit de sainteté!` },
  { livre: `Psaumes`, chapitre: 51, verset: 12, texte: `Rends-moi la joie du salut Et donne-moi le soutien d’un esprit prompt à bien faire!` },
  { livre: `Psaumes`, chapitre: 51, verset: 13, texte: `Alors, je pourrai montrer ton chemin aux transgresseurs Pour que les pécheurs retrouvent le sentier menant vers toi.` },
  { livre: `Psaumes`, chapitre: 51, verset: 14, texte: `Délivre-moi, ô Seigneur, du sang que j’ai répandu, Et ma langue chantera ta justice, ô Dieu sauveur.` },
  { livre: `Psaumes`, chapitre: 51, verset: 15, texte: `Seigneur, veuille ouvrir mes lèvres, Et ma bouche annoncera (et chantera) ta louange.` },
  { livre: `Psaumes`, chapitre: 51, verset: 16, texte: `Car tu ne veux pas de moi n’importe quel sacrifice. J’offrirais des holocaustes, mais tu n’y prends point plaisir.` },
  { livre: `Psaumes`, chapitre: 51, verset: 17, texte: `Le sacrifice agréable qui convient à notre Dieu, C’est un esprit repentant. Ô Dieu, tu n’écartes pas un cœur humble et abattu.` },
  { livre: `Psaumes`, chapitre: 51, verset: 18, texte: `Veuille accorder le bonheur à la ville de Sion! (Seigneur,) veuille rebâtir les murs de Jérusalem!` },
  { livre: `Psaumes`, chapitre: 51, verset: 19, texte: `Alors, tu prendras plaisir à de justes sacrifices: Holocaustes, dons parfaits. Alors, de jeunes taureaux monteront sur ton autel.` },
  { livre: `Psaumes`, chapitre: 52, verset: 0, texte: `Au chef de chœur: un poème didactique de David, qu’il composa lorsque Doëg l’Édomite vint informer Saül que David était entré dans la maison d’Achimélek.` },
  { livre: `Psaumes`, chapitre: 52, verset: 1, texte: `Qu’as-tu à te vanter, ô tyran, de ta cruauté? La bonté du Seigneur dure éternellement.` },
  { livre: `Psaumes`, chapitre: 52, verset: 2, texte: `Ta langue fomente des crimes, C’est un couteau bien affilé, et qui manie la tromperie.` },
  { livre: `Psaumes`, chapitre: 52, verset: 3, texte: `Tu préfères le mal au bien, le mensonge à la vérité!` },
  { livre: `Psaumes`, chapitre: 52, verset: 4, texte: `Tu n’aimes que les mots qui tuent, Ta langue est pleine d’imposture.` },
  { livre: `Psaumes`, chapitre: 52, verset: 5, texte: `Aussi Dieu te renversera, pour toujours, il te saisira. Il te chassera de ta tente, Il arrachera tes racines du pays des vivants.` },
  { livre: `Psaumes`, chapitre: 52, verset: 6, texte: `Alors, les justes le verront et ils seront saisis de crainte, Ils se riront de lui:` },
  { livre: `Psaumes`, chapitre: 52, verset: 7, texte: `«Le voici, l’homme fort qui ne prenait pas Dieu pour rempart et appui! Celui qui se fiait en ses grandes richesses Et qui se croyait fort par sa méchanceté!»` },
  { livre: `Psaumes`, chapitre: 52, verset: 8, texte: `Tandis que moi, je suis toujours Comme un olivier verdoyant dans la maison de Dieu. Je mets toute ma confiance dans l’amour du Seigneur, Pour le temps et l’éternité.` },
  { livre: `Psaumes`, chapitre: 52, verset: 9, texte: `Je te célébrerai toujours car tu es un Dieu qui agit. Je veux espérer en ton nom car tu es bon, Seigneur, Pour tous tes bien-aimés.` },
  { livre: `Psaumes`, chapitre: 53, verset: 0, texte: `Au chef de chœur. Poème didactique de David, à chanter avec accompagnement de flûtes.` },
  { livre: `Psaumes`, chapitre: 53, verset: 1, texte: `Ils sont fous tous ceux qui pensent: «Dieu n’existe pas». Leur conduite est dégradante, ils sont corrompus. Il n’y a plus d’honnête homme, aucun n’agit bien.` },
  { livre: `Psaumes`, chapitre: 53, verset: 2, texte: `Du haut du ciel, Dieu observe tout le genre humain: Reste-t-il un homme sage et qui cherche Dieu?` },
  { livre: `Psaumes`, chapitre: 53, verset: 3, texte: `Tous sont égarés ensemble, tous sont avilis. Il n’en reste plus d’honnête, même pas un seul.` },
  { livre: `Psaumes`, chapitre: 53, verset: 4, texte: `Ceux qui s’adonnent au vice et qui font le mal Sont-ils sans intelligence? N’ont-ils pas compris? Car ils dévorent mon peuple et mangent mon pain Mais sans jamais reconnaître ni invoquer Dieu.` },
  { livre: `Psaumes`, chapitre: 53, verset: 5, texte: `Les voilà pris d’épouvante, ils sont tout tremblants Sans aucun sujet de crainte ni rien d’effrayant, Car Dieu disperse les membres de tes assiégeants, Tu les couvriras de honte, tous les agresseurs, Puisque c’est par Dieu lui-même qu’ils sont rejetés.` },
  { livre: `Psaumes`, chapitre: 53, verset: 6, texte: `Il vient de Sion pour apporter le salut à (tout) Israël! Lorsque Dieu ramènera son peuple captif, Jacob criera d’allégresse, Israël de joie.` },
  { livre: `Psaumes`, chapitre: 54, verset: 0, texte: `Au chef de chœur. Un poème didactique de David, à chanter avec accompagnement d’instruments à cordes. Il le composa lorsque les Ziphites vinrent dire à Saül: «David est caché parmi nous».` },
  { livre: `Psaumes`, chapitre: 54, verset: 1, texte: `Seigneur, mon Dieu, que, par ton nom, je sois sauvé! Par ta vaillance, rends-moi juste!` },
  { livre: `Psaumes`, chapitre: 54, verset: 2, texte: `Seigneur, mon Dieu, écoute-moi quand je te prie! Prête l’oreille à mes paroles!` },
  { livre: `Psaumes`, chapitre: 54, verset: 3, texte: `Des étrangers m’ont attaqué, Des gens violents veulent me perdre. Ils n’ont pas Dieu dans leurs pensées!` },
  { livre: `Psaumes`, chapitre: 54, verset: 4, texte: `Oui, Dieu est mon secours! Le Seigneur est de ceux qui soutiennent ma vie!` },
  { livre: `Psaumes`, chapitre: 54, verset: 5, texte: `Il fera retomber sur mes ennemis mêmes Le mal qu’ils me voulaient. Dans ta fidélité, réduis-les au silence!` },
  { livre: `Psaumes`, chapitre: 54, verset: 6, texte: `Je t’offrirai de tout mon cœur des sacrifices volontaires. Je chanterai ton nom, Seigneur, car il est favorable,` },
  { livre: `Psaumes`, chapitre: 54, verset: 7, texte: `Car il m’a délivré de toutes mes détresses, Je peux braver mes ennemis.` },
  { livre: `Psaumes`, chapitre: 55, verset: 0, texte: `Au chef de chœur. Un poème didactique de David à chanter avec accompagnement d’instruments à cordes.` },
  { livre: `Psaumes`, chapitre: 55, verset: 1, texte: `Ô Dieu, prête l’oreille à ma prière et ne fuis pas quand je supplie!` },
  { livre: `Psaumes`, chapitre: 55, verset: 2, texte: `Sois attentif et réponds-moi! Car, dans ma peine, je me démène en me plaignant.` },
  { livre: `Psaumes`, chapitre: 55, verset: 3, texte: `Je suis troublé, car l’ennemi crie après moi Et le méchant vient m’opprimer. Les gens m’accablent de leurs méfaits, Avec colère, ils me pourchassent.` },
  { livre: `Psaumes`, chapitre: 55, verset: 4, texte: `Mon cœur se crispe dans ma poitrine, Et la frayeur devant la mort vient m’assaillir.` },
  { livre: `Psaumes`, chapitre: 55, verset: 5, texte: `Crainte et frisson m’ont envahi, et c’est l’horreur qui m’environne.` },
  { livre: `Psaumes`, chapitre: 55, verset: 6, texte: `Alors, je dis: «Je voudrais bien avoir des ailes! Comme la colombe je volerais vers un abri paisible et sûr.` },
  { livre: `Psaumes`, chapitre: 55, verset: 7, texte: `Bien loin d’ici, je m’enfuirais; j’habiterais dans le désert.` },
  { livre: `Psaumes`, chapitre: 55, verset: 8, texte: `J’aurais bientôt trouvé l’asile Contre le vent impétueux et la tempête qui se déchaîne».` },
  { livre: `Psaumes`, chapitre: 55, verset: 9, texte: `Frappe, Seigneur, confonds leurs langues, Car je ne vois que violences et dissensions dans la cité.` },
  { livre: `Psaumes`, chapitre: 55, verset: 10, texte: `De nuit, de jour, ils font le tour de ses remparts, Peine et misère sont dans son sein, au milieu d’elle, c’est l’injustice,` },
  { livre: `Psaumes`, chapitre: 55, verset: 11, texte: `Fraude et mensonge ne quittent plus ses grandes places.` },
  { livre: `Psaumes`, chapitre: 55, verset: 12, texte: `Si c’était l’ennemi qui venait m’outrager, je le supporterais. Si celui qui me hait s’élevait contre moi, je pourrais me cacher, Me dérober à lui.` },
  { livre: `Psaumes`, chapitre: 55, verset: 13, texte: `Cependant, toi que je considérais comme un autre moi-même, Toi mon ami, qui me connais intimement,` },
  { livre: `Psaumes`, chapitre: 55, verset: 14, texte: `Avec qui je goûtais une amitié si douce, Nous marchions de concert vers la maison de Dieu.` },
  { livre: `Psaumes`, chapitre: 55, verset: 15, texte: `Que la mort les surprenne! Que, vivants, ils descendent dans le séjour des morts! Car la méchanceté habite leur demeure, le mal est dans leur cœur!` },
  { livre: `Psaumes`, chapitre: 55, verset: 16, texte: `Moi, j’en appelle à Dieu; oui, l’Éternel sauve.` },
  { livre: `Psaumes`, chapitre: 55, verset: 17, texte: `Le soir et le matin et au milieu du jour, Je me répands en plaintes: il entendra ma voix,` },
  { livre: `Psaumes`, chapitre: 55, verset: 18, texte: `Il me délivrera, et me rendra la paix, En arrachant mon âme au combat qu’on me livre. Car ils sont très nombreux, ceux à qui j’ai affaire.` },
  { livre: `Psaumes`, chapitre: 55, verset: 19, texte: `Le Seigneur m’entendra et les humiliera. Il règne au long des siècles. Eux ne s’amendent pas; ils ne craignent pas Dieu.` },
  { livre: `Psaumes`, chapitre: 55, verset: 20, texte: `Cet homme étend ses mains Contre ses partenaires qui lui voulaient du bien, Il profane l’alliance qui le liait à eux.` },
  { livre: `Psaumes`, chapitre: 55, verset: 21, texte: `Sa bouche était suave, plus douce que la crème, Mais la guerre est tapie tout au fond de son cœur! Ses paroles sont tendres, glissantes comme l’huile, Mais ce sont des poignards, des épées dégainées!` },
  { livre: `Psaumes`, chapitre: 55, verset: 22, texte: `Rejette ton fardeau, remets-le au Seigneur: Il prendra soin de toi, il ne permettra pas que le juste chancelle, (Qu’il tombe) pour toujours.` },
  { livre: `Psaumes`, chapitre: 55, verset: 23, texte: `Et toi, ô Dieu, tu les feras descendre dans le gouffre mortel, Ces hommes sanguinaires, perfides, violents, Et ils n’atteindront pas la moitié de leurs jours! Tandis que moi, je me confie en toi.` },
  { livre: `Psaumes`, chapitre: 56, verset: 0, texte: `Au maître du chant. Sur la mélodie de «Colombe muette des pays lointains». Composé par David lorsqu’il fut retenu par les Philistins à Gath.` },
  { livre: `Psaumes`, chapitre: 56, verset: 1, texte: `Fais-moi grâce, ô Dieu, car on me piétine; les hommes s’acharnent contre moi sans cesse, ils me font la guerre.` },
  { livre: `Psaumes`, chapitre: 56, verset: 2, texte: `Ils fondent sur moi, voulant me frapper. Oui, mes adversaires, toujours, me piétinent, car ils sont nombreux, ceux qui me combattent avec arrogance!` },
  { livre: `Psaumes`, chapitre: 56, verset: 3, texte: `Le jour où j’ai peur, à toi, je me fie.` },
  { livre: `Psaumes`, chapitre: 56, verset: 4, texte: `Je veux louer Dieu, louer sa parole, je me fie à lui Et je n’ai plus peur. Que pourraient me faire des êtres mortels?` },
  { livre: `Psaumes`, chapitre: 56, verset: 5, texte: `Tout au long des jours, ils me font souffrir, Tordant mes paroles, toutes leurs pensées ne visent qu’à nuire.` },
  { livre: `Psaumes`, chapitre: 56, verset: 6, texte: `Ils se réunissent pour me tendre un piège. Postés à l’affût, ils épient mes traces. On dirait qu’ils guettent ma vie pour me perdre.` },
  { livre: `Psaumes`, chapitre: 56, verset: 7, texte: `Est-ce par le crime qu’ils vont échapper? Dieu, dans ta colère, renverse les peuples!` },
  { livre: `Psaumes`, chapitre: 56, verset: 8, texte: `Tu comptes mes pas dans ma vie d’exil Et, dans ton calice, tu reçois mes larmes; Elles sont inscrites toutes dans ton livre.` },
  { livre: `Psaumes`, chapitre: 56, verset: 9, texte: `Je t’invoquerai, et mes ennemis battront en retraite, Car je suis certain que Dieu est pour moi.` },
  { livre: `Psaumes`, chapitre: 56, verset: 10, texte: `Je veux louer Dieu, louer sa parole,` },
  { livre: `Psaumes`, chapitre: 56, verset: 11, texte: `Je me fie à lui, et je n’ai plus peur des êtres mortels.` },
  { livre: `Psaumes`, chapitre: 56, verset: 12, texte: `Je veux accomplir les vœux que j’ai faits, Et je veux t’offrir des actions de grâces.` },
  { livre: `Psaumes`, chapitre: 56, verset: 13, texte: `Car tu as sauvé ma vie de la mort, Tu as préservé mes pieds de la chute Afin que je marche devant le Seigneur Éclairé par toi, lumière de vie.` },
  { livre: `Psaumes`, chapitre: 57, verset: 0, texte: `Au maître du chant. De David. Lorsqu’il s’enfuit, poursuivi par Saül, et se réfugia dans la caverne.` },
  { livre: `Psaumes`, chapitre: 57, verset: 1, texte: `Fais-moi grâce, ô Dieu! Fais-moi grâce! C’est auprès de toi que mon âme cherche son refuge, son abri. Je me réfugie sous tes ailes tant que durera le malheur.` },
  { livre: `Psaumes`, chapitre: 57, verset: 2, texte: `J’en appelle à Dieu, le Très-Haut, au Dieu qui fera tout pour moi.` },
  { livre: `Psaumes`, chapitre: 57, verset: 3, texte: `Qu’il m’envoie du ciel son salut en dépit de ceux qui m’écrasent. Oui, Dieu enverra son amour, sa fidélité et sa grâce!` },
  { livre: `Psaumes`, chapitre: 57, verset: 4, texte: `Je suis entouré de lions, Couché au milieu d’ennemis Qui crachent des flammes dévorantes. Leurs dents acérées sont des lames, Semblables à des flèches, Comme un glaive aigu est leur langue.` },
  { livre: `Psaumes`, chapitre: 57, verset: 5, texte: `Ô Dieu, lève-toi sur les cieux! Que le monde entier voie ta gloire!` },
  { livre: `Psaumes`, chapitre: 57, verset: 6, texte: `Ils ont préparé un filet Et ils l’ont tendu sous mes pas. Ils m’ont fait plier pour me perdre. Ils avaient creusé une trappe; Dans la fosse, eux-mêmes sont tombés.` },
  { livre: `Psaumes`, chapitre: 57, verset: 7, texte: `Mon cœur est tranquille, ô mon Dieu! Mon cœur est tranquille. Oui, je chante et je psalmodie sur la harpe,` },
  { livre: `Psaumes`, chapitre: 57, verset: 8, texte: `C’est là mon bonheur et ma gloire. Vite, éveillez-vous, harpe et luth! Je veux m’éveiller dès l’aurore,` },
  { livre: `Psaumes`, chapitre: 57, verset: 9, texte: `Je veux te louer, ô Seigneur, parmi tous les peuples Psalmodier parmi les nations à ta gloire.` },
  { livre: `Psaumes`, chapitre: 57, verset: 10, texte: `Car ta grâce atteint jusqu’aux cieux, Ta fidélité jusqu’aux nues.` },
  { livre: `Psaumes`, chapitre: 57, verset: 11, texte: `Ô Dieu, lève-toi sur les cieux, Que le monde entier voie ta gloire!` },
  { livre: `Psaumes`, chapitre: 58, verset: 0, texte: `Au maître du chant. Sur (la mélodie): «Ne détruis pas». Psaume composé par David.` },
  { livre: `Psaumes`, chapitre: 58, verset: 1, texte: `Rendez-vous vraiment justice en fermant la bouche? Jugez-vous avec droiture, vous, les fils des hommes?` },
  { livre: `Psaumes`, chapitre: 58, verset: 2, texte: `Sciemment, vous commettez des iniquités! Vous jetez dans la balance la violence de vos mains Pour dominer le pays.` },
  { livre: `Psaumes`, chapitre: 58, verset: 3, texte: `Les pécheurs sont fourvoyés depuis leur naissance, Les menteurs sont égarés depuis tout petits.` },
  { livre: `Psaumes`, chapitre: 58, verset: 4, texte: `Les impies sont venimeux comme des serpents, Ils se bouchent les oreilles comme l’aspic sourd` },
  { livre: `Psaumes`, chapitre: 58, verset: 5, texte: `Qui refuse d’écouter la voix des charmeurs Et celle de l’enchanteur habile dans l’art.` },
  { livre: `Psaumes`, chapitre: 58, verset: 6, texte: `Ô Dieu, brise-leur les dents au fond de la bouche: Seigneur, arrache les crocs de ces lionceaux!` },
  { livre: `Psaumes`, chapitre: 58, verset: 7, texte: `Comme les eaux qui s’en vont, qu’ils s’évanouissent: Comme l’herbe qu’on piétine, qu’ils soient desséchés,` },
  { livre: `Psaumes`, chapitre: 58, verset: 8, texte: `Qu’ils périssent et se fondent comme un limaçon, Qu’ils soient comme un avorton, sans voir le soleil!` },
  { livre: `Psaumes`, chapitre: 58, verset: 9, texte: `Avant qu’ils s’en aperçoivent, aussi vite qu’un feu d’épines Lèche vos marmites, viande crue ou viande cuite, Qu’ils soient emportés!` },
  { livre: `Psaumes`, chapitre: 58, verset: 10, texte: `Le juste se réjouira voyant la vengeance. Dans le sang des réprouvés, il baigne ses pas.` },
  { livre: `Psaumes`, chapitre: 58, verset: 11, texte: `Et les hommes pourront dire: «Oui, ceux qui sont justes trouvent une récompense. Il y a un Dieu qui exerce la justice ici-bas sur terre».` },
  { livre: `Psaumes`, chapitre: 59, verset: 0, texte: `Au chef de chœur. Psaume composé par David, lorsque Saül envoya cerner sa maison pour le faire mourir.` },
  { livre: `Psaumes`, chapitre: 59, verset: 1, texte: `Ô mon Dieu! délivre-moi de mes ennemis! Contre tous mes agresseurs, mets-moi à l’abri!` },
  { livre: `Psaumes`, chapitre: 59, verset: 2, texte: `Sauve-moi des malfaisants et des meurtriers,` },
  { livre: `Psaumes`, chapitre: 59, verset: 3, texte: `Car les voici qui me guettent, pour m’ôter la vie! Des gens violents me poursuivent, ils vont m’attaquer, Sans que j’aie commis ni faute ni péché, Seigneur.` },
  { livre: `Psaumes`, chapitre: 59, verset: 4, texte: `Sans que j’aie fait aucun mal, ils courent, s’apprêtent! Réveille-toi et regarde, viens à ma rencontre!` },
  { livre: `Psaumes`, chapitre: 59, verset: 5, texte: `Toi, Seigneur, Dieu d’Israël, Dieu de l’univers, Sors du sommeil, viens et vois! Seigneur, lève-toi pour punir tous ces païens! N’use pas de grâce pour ces traîtres malfaisants.` },
  { livre: `Psaumes`, chapitre: 59, verset: 6, texte: `Le soir, ils sont là; en grondant comme des chiens, Ils rôdent partout, ils font le tour de la ville.` },
  { livre: `Psaumes`, chapitre: 59, verset: 7, texte: `Les voici déjà! Ils ont l’injure à la bouche, Leurs paroles sont des glaives: qui peut les entendre?` },
  { livre: `Psaumes`, chapitre: 59, verset: 8, texte: `Toi, Seigneur, tu t’en amuses, Tu te moqueras, Seigneur, de tous ces païens.` },
  { livre: `Psaumes`, chapitre: 59, verset: 9, texte: `C’est vers toi que je regarde, toi qui es ma force. Mon Dieu est ma forteresse, il est mon rempart.` },
  { livre: `Psaumes`, chapitre: 59, verset: 10, texte: `Mon Dieu viendra, plein de grâce, au-devant de moi. Il me permet de défier tous mes ennemis.` },
  { livre: `Psaumes`, chapitre: 59, verset: 11, texte: `Ne les extermine pas, De peur que mon peuple ne vienne à les oublier, Mais par ta puissance, disperse et renverse-les, Puisque toi tu es notre bouclier, Seigneur.` },
  { livre: `Psaumes`, chapitre: 59, verset: 12, texte: `Toutes leurs paroles ne sont jamais que péché. Qu’ils soient pris au piège dressé par leur propre orgueil, Par tous les outrages et mensonges qu’ils profèrent!` },
  { livre: `Psaumes`, chapitre: 59, verset: 13, texte: `Pour qu’ils disparaissent, détruis-les dans ta colère Afin que l’on sache que Dieu règne sur Jacob, Qu’il est souverain jusqu’aux confins de la terre!` },
  { livre: `Psaumes`, chapitre: 59, verset: 14, texte: `Le soir, ils sont là; en hurlant comme des chiens, Ils rôdent partout, ils font le tour de la ville.` },
  { livre: `Psaumes`, chapitre: 59, verset: 15, texte: `Errant ça et là, pour découvrir une proie, S’ils n’en trouvent pas, ils restent la nuit entière.` },
  { livre: `Psaumes`, chapitre: 59, verset: 16, texte: `Mais, pendant ce temps, je veux chanter ta puissance Et, dès le matin, je veux célébrer ta grâce, Car tu es pour moi une forte citadelle, Tu es mon refuge quand je suis dans la détresse!` },
  { livre: `Psaumes`, chapitre: 59, verset: 17, texte: `Ô toi, ma puissance, pour toi je veux psalmodier, Car Dieu est pour moi une forte citadelle, Dieu plein de bonté.` },
  { livre: `Psaumes`, chapitre: 60, verset: 0, texte: `Au chef de chœur, sur (la mélodie): «La loi est comme les lis». Poème didactique composé par David 1259 à l’occasion de sa guerre contre la Syrie mésopotamienne et contre la Syrie de Tsoba, quand Joab revint et vainquit les Édomites de la vallée du Sel, au nombre de douze mille hommes.` },
  { livre: `Psaumes`, chapitre: 60, verset: 1, texte: `Ô Dieu, tu nous as abandonnés! Tu as brisé nos armées! Tu as montré ton courroux, viens, rétablis-nous!` },
  { livre: `Psaumes`, chapitre: 60, verset: 2, texte: `Tu as fait trembler la terre, tu l’as déchirée, Guéris ses blessures, car elle vacille.` },
  { livre: `Psaumes`, chapitre: 60, verset: 3, texte: `Tu as fait passer ton peuple par des épreuves bien dures! Tu nous as donné à boire un vin d’étourdissement!` },
  { livre: `Psaumes`, chapitre: 60, verset: 4, texte: `Mais tu as donné à ceux qui t’adorent Un signal de ralliement au nom de la vérité!` },
  { livre: `Psaumes`, chapitre: 60, verset: 5, texte: `Que tes bien-aimés vivent en sécurité! Que ta droite nous assiste! Ô Dieu, réponds-nous!` },
  { livre: `Psaumes`, chapitre: 60, verset: 6, texte: `Dieu l’a déclaré dans son sanctuaire: «Je triompherai! Je veux partager Sichem Et mesurer au cordeau le val de Souccoth.` },
  { livre: `Psaumes`, chapitre: 60, verset: 7, texte: `À moi, Galaad, à moi, Manassé! Éphraïm est mon rempart, C’est un casque pour ma tête, Juda, mon sceptre royal,` },
  { livre: `Psaumes`, chapitre: 60, verset: 8, texte: `Moab sera le bassin où je pourrai me baigner. Je vais lancer ma sandale sur Édom (et la soumettre). Philistie, pousse des cris de victoire en mon honneur!»` },
  { livre: `Psaumes`, chapitre: 60, verset: 9, texte: `Qui me mènera dans la cité fortifiée? Qui me conduit à Édom?` },
  { livre: `Psaumes`, chapitre: 60, verset: 10, texte: `Sinon toi, mon Dieu, qui nous avais rejetés, Qui ne sortais plus, ô Dieu, avec nos armées.` },
  { livre: `Psaumes`, chapitre: 60, verset: 11, texte: `Viens nous secourir contre l’adversaire! Car trompeur est le secours qui nous vient des hommes.` },
  { livre: `Psaumes`, chapitre: 60, verset: 12, texte: `En Dieu, nous serons vaillants, C’est lui qui écrasera tous nos adversaires!` },
  { livre: `Psaumes`, chapitre: 61, verset: 0, texte: `Au chef de chœur. Un psaume de David. À chanter avec accompagnement d’instruments à cordes. Entends mes cris, ô Dieu! Écoute ma prière!` },
  { livre: `Psaumes`, chapitre: 61, verset: 1, texte: `Des confins de la terre, je fais appel à toi! Mon cœur est abattu, Conduis-moi au rocher qui est trop haut pour moi!` },
  { livre: `Psaumes`, chapitre: 61, verset: 2, texte: `Car tu es mon refuge, mon bastion fortifié face à mes ennemis!` },
  { livre: `Psaumes`, chapitre: 61, verset: 3, texte: `Je voudrais demeurer pour toujours dans ta tente, M’abriter sous tes ailes.` },
  { livre: `Psaumes`, chapitre: 61, verset: 4, texte: `Car, ô Dieu, tu exauces mes vœux et tu accordes Un héritage à ceux qui respectent ton nom.` },
  { livre: `Psaumes`, chapitre: 61, verset: 5, texte: `Prolonge de longs jours la vie de notre roi, Qu’il vive d’âge en âge!` },
  { livre: `Psaumes`, chapitre: 61, verset: 6, texte: `Qu’il siège pour toujours en présence de Dieu!` },
  { livre: `Psaumes`, chapitre: 61, verset: 7, texte: `Ordonne que l’amour et que la vérité Toujours veillent sur lui` },
  { livre: `Psaumes`, chapitre: 61, verset: 8, texte: `Et je psalmodierai toujours en ton honneur. J’accomplirai ainsi mes vœux jour après jour.` },
  { livre: `Psaumes`, chapitre: 62, verset: 0, texte: `Au chef de chœur, sur Jéduthun. Un psaume de David.` },
  { livre: `Psaumes`, chapitre: 62, verset: 1, texte: `C’est vrai! C’est en Dieu seul que mon âme est tranquille. Mon salut vient de lui.` },
  { livre: `Psaumes`, chapitre: 62, verset: 2, texte: `C’est vrai! Il est mon roc, mon salut, ma retraite. Je ne serai jamais fortement ébranlé.` },
  { livre: `Psaumes`, chapitre: 62, verset: 3, texte: `Combien de temps encore allez-vous, tous ensemble, Vous ruer sur un homme pour chercher à l’abattre Comme un mur lézardé, une paroi branlante?` },
  { livre: `Psaumes`, chapitre: 62, verset: 4, texte: `C’est vrai! Ils se consultent pour le précipiter de son poste élevé. Ils aiment le mensonge: bénissant de la bouche, maudissant du cœur.` },
  { livre: `Psaumes`, chapitre: 62, verset: 5, texte: `C’est vrai! Tu peux rester dans la paix, ô mon âme, En te confiant à Dieu, car il est mon espoir.` },
  { livre: `Psaumes`, chapitre: 62, verset: 6, texte: `C’est vrai! Il est mon roc, mon salut, ma retraite: Je ne serai jamais, non jamais ébranlé.` },
  { livre: `Psaumes`, chapitre: 62, verset: 7, texte: `Auprès de Dieu se trouvent mon salut et ma gloire Car mon roc fortifié, mon refuge est en Dieu.` },
  { livre: `Psaumes`, chapitre: 62, verset: 8, texte: `Ô vous, gens de mon peuple, Ayez confiance en lui instant après instant: Ouvrez-lui votre cœur! Dieu est notre refuge.` },
  { livre: `Psaumes`, chapitre: 62, verset: 9, texte: `C’est vrai! Les fils d’Adam ne sont que vanité Et tous les fils d’un homme ne sont qu’une illusion. Placés dans la balance, ils pèsent moins que rien.` },
  { livre: `Psaumes`, chapitre: 62, verset: 10, texte: `N’ayez pas confiance dans l’injuste oppression! Ne placez pas d’espoir dans les biens mal acquis! Si la fortune afflue, ne vous y attachez pas.` },
  { livre: `Psaumes`, chapitre: 62, verset: 11, texte: `Je le sais, Dieu l’a dit, et il l’a répété, J’ai entendu ceci: «Tout pouvoir est à Dieu».` },
  { livre: `Psaumes`, chapitre: 62, verset: 12, texte: `À toi, Seigneur, la grâce Car tu rends à chacun selon ce qu’il a fait.` },
  { livre: `Psaumes`, chapitre: 63, verset: 0, texte: `Psaume de David, lorsqu’il était dans le désert de Juda.` },
  { livre: `Psaumes`, chapitre: 63, verset: 1, texte: `Ô Dieu, tu es mon Dieu! C’est toi que je recherche comme on attend l’aurore. Mon âme a soif de toi. Mon être entier soupire Et languit après toi comme une terre aride, épuisée et sans eau.` },
  { livre: `Psaumes`, chapitre: 63, verset: 2, texte: `Oh! Je voudrais te voir, toi, dans ton sanctuaire, Afin que m’apparaissent ta puissance et ta gloire.` },
  { livre: `Psaumes`, chapitre: 63, verset: 3, texte: `Car ton amour fidèle vaut bien mieux que la vie, Aussi mes lèvres chantent sans cesse tes louanges.` },
  { livre: `Psaumes`, chapitre: 63, verset: 4, texte: `Je pourrai te bénir tout au long de ma vie, J’élèverai les mains en invoquant ton nom.` },
  { livre: `Psaumes`, chapitre: 63, verset: 5, texte: `Lorsque, la joie aux lèvres, je chante tes louanges, mon âme est rassasiée comme si je goûtais des mets gras succulents.` },
  { livre: `Psaumes`, chapitre: 63, verset: 6, texte: `Dès que je suis couché, je me souviens de toi, Je médite sur toi tout au long de la nuit.` },
  { livre: `Psaumes`, chapitre: 63, verset: 7, texte: `Oui, tu es mon appui, je suis dans l’allégresse à l’ombre de tes ailes!` },
  { livre: `Psaumes`, chapitre: 63, verset: 8, texte: `Je te suis attaché avec toute mon âme et ton bras me soutient.` },
  { livre: `Psaumes`, chapitre: 63, verset: 9, texte: `Ceux qui veulent me perdre vont à leur propre perte. Ils seront entraînés aux tréfonds de l’abîme.` },
  { livre: `Psaumes`, chapitre: 63, verset: 10, texte: `Oui, ils seront livrés au tranchant de l’épée. Ils seront réservés en pâture aux chacals.` },
  { livre: `Psaumes`, chapitre: 63, verset: 11, texte: `Mais alors (notre) roi se réjouira en Dieu. Tous ceux qui jureront (fidélité) à Dieu par lui triompheront, Tandis que les menteurs auront la bouche close.` },
  { livre: `Psaumes`, chapitre: 64, verset: 0, texte: `Au chef de chœur. Psaume de David.` },
  { livre: `Psaumes`, chapitre: 64, verset: 1, texte: `Écoute, ô Dieu, lorsque, dans la détresse, Ma voix plaintive s’élève jusqu’à toi! Garde mon âme de la peur que m’inspirent mes ennemis!` },
  { livre: `Psaumes`, chapitre: 64, verset: 2, texte: `Protège-moi des complots des méchants Et du tumulte des artisans du mal!` },
  { livre: `Psaumes`, chapitre: 64, verset: 3, texte: `Comme une épée, ils affûtent leurs langues, Et ils décochent leurs paroles amères comme des flèches!` },
  { livre: `Psaumes`, chapitre: 64, verset: 4, texte: `Ils tirent en secret sur l’innocent, Ils le visent soudain, sans avoir peur.` },
  { livre: `Psaumes`, chapitre: 64, verset: 5, texte: `Ils s’enhardissent dans leurs mauvais propos, Ils se concertent pour bien cacher leurs pièges, En se disant: «Qui donc les trouvera?»` },
  { livre: `Psaumes`, chapitre: 64, verset: 6, texte: `Chacun combine un complot bien ourdi: «Nous voilà prêts! Notre plan est parfait!» Le cœur de l’homme est un gouffre profond.` },
  { livre: `Psaumes`, chapitre: 64, verset: 7, texte: `Mais le Seigneur lance soudainement Sur eux ses flèches, et les voilà frappés.` },
  { livre: `Psaumes`, chapitre: 64, verset: 8, texte: `Leur propre langue les a fait trébucher. Ceux qui les voient hochent contre eux la tête,` },
  { livre: `Psaumes`, chapitre: 64, verset: 9, texte: `Et tous les hommes se mettent à trembler. Les gens proclament: «C’est là l’œuvre de Dieu!» Et ils méditent sur tout ce qu’il a fait.` },
  { livre: `Psaumes`, chapitre: 64, verset: 10, texte: `Le juste met sa joie dans le Seigneur. Il se confie en lui: c’est son abri, Tous les cœurs droits (en lui) se glorifient.` },
  { livre: `Psaumes`, chapitre: 65, verset: 0, texte: `Au chef de chœur. Un psaume de David.` },
  { livre: `Psaumes`, chapitre: 65, verset: 1, texte: `Dans le silence, monte vers toi notre louange, Dieu de Sion! À toi nos vœux! Qu’ils s’accomplissent en ton honneur!` },
  { livre: `Psaumes`, chapitre: 65, verset: 2, texte: `Car tu écoutes notre prière. Tous les mortels viendront vers toi.` },
  { livre: `Psaumes`, chapitre: 65, verset: 3, texte: `Le poids des fautes pèse sur moi: il est trop lourd, Mais tu pardonnes nos transgressions.` },
  { livre: `Psaumes`, chapitre: 65, verset: 4, texte: `Heureux l’élu que tu invites en ta présence Pour qu’il habite dans tes parvis! Nous y goûtons tous les bienfaits de ta maison, Les dons sacrés de ton palais.` },
  { livre: `Psaumes`, chapitre: 65, verset: 5, texte: `Dans ta justice, tu nous réponds par des merveilles, Ô Dieu Sauveur, espoir des hommes jusqu’aux confins De notre terre et de la mer.` },
  { livre: `Psaumes`, chapitre: 65, verset: 6, texte: `Il établit fermement les montagnes par sa force. Il se revêt de puissance,` },
  { livre: `Psaumes`, chapitre: 65, verset: 7, texte: `Il calme le bruit des vagues et l’agitation des peuples.` },
  { livre: `Psaumes`, chapitre: 65, verset: 8, texte: `Aux extrémités du monde, Les peuples sont angoissés à la vue de tes prodiges. Tu fais tressaillir de joie le levant et le couchant.` },
  { livre: `Psaumes`, chapitre: 65, verset: 9, texte: `Tu as visité la terre, pour lui donner l’abondance, Tu la combles de richesses! Les ruisseaux de Dieu débordent, Tu fais pousser nos moissons, en fertilisant la terre.` },
  { livre: `Psaumes`, chapitre: 65, verset: 10, texte: `Tu inondes ses sillons; tu en aplanis les mottes, Tes averses l’amollissent, et tu bénis ce qui germe.` },
  { livre: `Psaumes`, chapitre: 65, verset: 11, texte: `Tu as couronné l’année de tes bienfaits généreux, Tes pas versent l’abondance.` },
  { livre: `Psaumes`, chapitre: 65, verset: 12, texte: `Les prés et les pâturages sont largement arrosés, Les collines se revêtent d’une ceinture de joie.` },
  { livre: `Psaumes`, chapitre: 65, verset: 13, texte: `Les prés couverts de brebis, les vallées drapées de blé, Tout chante et clame sa joie.` },
  { livre: `Psaumes`, chapitre: 66, verset: 1, texte: `Au chef de chœur. Cantique, psaume. Poussez vers Dieu des cris de joie, vous tous, habitants de la terre!` },
  { livre: `Psaumes`, chapitre: 66, verset: 2, texte: `Chantez la gloire de son nom! Glorifiez-le par la louange!` },
  { livre: `Psaumes`, chapitre: 66, verset: 3, texte: `Dites à Dieu: «Que tes œuvres sont imposantes!» Devant ta puissance infinie, tes ennemis rendent hommage.` },
  { livre: `Psaumes`, chapitre: 66, verset: 4, texte: `La terre entière est à tes pieds, Elle entonne un chant de louanges pour célébrer ton nom glorieux.` },
  { livre: `Psaumes`, chapitre: 66, verset: 5, texte: `Venez voir les œuvres de Dieu, Car son action est merveilleuse En faveur des enfants des hommes.` },
  { livre: `Psaumes`, chapitre: 66, verset: 6, texte: `Il a transformé la mer Rouge et l’a changée en terre ferme, On a passé le fleuve à pied. Aussi nous exultons en lui` },
  { livre: `Psaumes`, chapitre: 66, verset: 7, texte: `Car il gouverne pour toujours, Sa force domine le monde, ses yeux surveillent les nations De peur que les impies ne puissent s’élever avec arrogance.` },
  { livre: `Psaumes`, chapitre: 66, verset: 8, texte: `Bénissez notre Dieu, ô peuples! Faites résonner sa louange!` },
  { livre: `Psaumes`, chapitre: 66, verset: 9, texte: `C’est grâce à lui que nous vivons: il nous a gardés de la chute.` },
  { livre: `Psaumes`, chapitre: 66, verset: 10, texte: `Tu nous as éprouvés, ô Dieu, Tu nous as jetés au creuset comme on affine le métal,` },
  { livre: `Psaumes`, chapitre: 66, verset: 11, texte: `Tu nous as saisis au filet, tu nous as chargés d’un fardeau,` },
  { livre: `Psaumes`, chapitre: 66, verset: 12, texte: `Tu as permis à l’ennemi de nous réduire sous son joug. Nous avons traversé le feu, nous avons dû passer par l’eau, Mais tu nous en as fait sortir pour nous conduire à l’abondance.` },
  { livre: `Psaumes`, chapitre: 66, verset: 13, texte: `Je veux entrer dans ta maison avec des holocaustes, Je veux m’acquitter envers toi des vœux que je t’ai faits.` },
  { livre: `Psaumes`, chapitre: 66, verset: 14, texte: `Je veux accomplir les promesses exprimées par mes lèvres Au temps de ma détresse.` },
  { livre: `Psaumes`, chapitre: 66, verset: 15, texte: `Je veux t’offrir en holocauste Les moutons les plus gras, des béliers avec de l’encens. J’immolerai (sur ton autel) des taureaux et des boucs.` },
  { livre: `Psaumes`, chapitre: 66, verset: 16, texte: `Venez, vous tous qui craignez Dieu, Je vous raconterai (tout) ce qu’il a fait pour mon âme.` },
  { livre: `Psaumes`, chapitre: 66, verset: 17, texte: `J’ai crié vers lui de ma bouche, sa louange était sur ma langue.` },
  { livre: `Psaumes`, chapitre: 66, verset: 18, texte: `Si j’avais gardé dans mon cœur ou nourri des pensées coupables, Dieu ne m’aurait pas écouté.` },
  { livre: `Psaumes`, chapitre: 66, verset: 19, texte: `Mais voyez: Dieu m’a entendu, Et il a été attentif à ma voix suppliante.` },
  { livre: `Psaumes`, chapitre: 66, verset: 20, texte: `Béni soit Dieu! Car il n’est pas inaccessible à ma prière, Il me conserve son amour.` },
  { livre: `Psaumes`, chapitre: 67, verset: 0, texte: `Au chef de chœur. Un psaume à chanter avec accompagnement d’instruments à cordes.` },
  { livre: `Psaumes`, chapitre: 67, verset: 1, texte: `Que Dieu nous fasse grâce! Qu’il veuille nous bénir! Que l’éclat de sa face resplendisse sur nous` },
  { livre: `Psaumes`, chapitre: 67, verset: 2, texte: `Afin qu’on reconnaisse tes voies dans le pays, Ainsi que ton salut dans toutes les nations!` },
  { livre: `Psaumes`, chapitre: 67, verset: 3, texte: `Que les peuples te louent, ô Dieu, oui, qu’ils te louent, Et qu’ils te rendent grâces, les peuples tous ensemble!` },
  { livre: `Psaumes`, chapitre: 67, verset: 4, texte: `Que les nations jubilent et soient dans l’allégresse Car, avec équité, tu gouvernes les peuples, Tu conduis les nations, les États de ce monde!` },
  { livre: `Psaumes`, chapitre: 67, verset: 5, texte: `Que les peuples te louent, ô Dieu, oui, qu’ils te louent, Les peuples tous ensemble!` },
  { livre: `Psaumes`, chapitre: 67, verset: 6, texte: `Notre terre a produit ses récoltes, ses fruits, Notre Dieu nous bénit.` },
  { livre: `Psaumes`, chapitre: 67, verset: 7, texte: `Oui, que Dieu nous bénisse et que les gens le craignent. Jusqu’au bout de la terre!` },
  { livre: `Psaumes`, chapitre: 68, verset: 0, texte: `Au chef de chœur. Un psaume de David. À chanter.` },
  { livre: `Psaumes`, chapitre: 68, verset: 1, texte: `Que Dieu se lève! Et que tous ses adversaires soient dispersés! Que tous ceux qui le haïssent s’enfuient de devant sa face!` },
  { livre: `Psaumes`, chapitre: 68, verset: 2, texte: `Qu’ils disparaissent comme une fumée légère qui se dissipe, Comme la cire qui fond au feu! Que les méchants ainsi périssent loin de la face de (notre Dieu)!` },
  { livre: `Psaumes`, chapitre: 68, verset: 3, texte: `Alors, les justes se réjouiront, Et ils seront dans l’allégresse. Devant leur Dieu, ils pousseront des cris de joie!` },
  { livre: `Psaumes`, chapitre: 68, verset: 4, texte: `Chantez à Dieu! Chantez un psaume pour célébrer son (grand) nom! Frayez la voie du cavalier qui chevauche Venant des hauteurs du ciel! Son (vrai) nom, c’est «l’Éternel». Sautez de joie devant lui!` },
  { livre: `Psaumes`, chapitre: 68, verset: 5, texte: `Il est le père des orphelins Et le défenseur des veuves. Oui, tel est Dieu dans sa sainte habitation.` },
  { livre: `Psaumes`, chapitre: 68, verset: 6, texte: `Aux isolés, Dieu accorde une maison, Il fait sortir ceux qui étaient enchaînés, Il les fait vivre dans le bonheur. Seuls les rebelles sont confinés dans le désert. Sortie d’Égypte` },
  { livre: `Psaumes`, chapitre: 68, verset: 7, texte: `Ô notre Dieu, quand tu sortis devant ton peuple, Quand tu marchas dans le désert,` },
  { livre: `Psaumes`, chapitre: 68, verset: 8, texte: `La terre fut ébranlée, les cieux se fondaient en eau. Devant ta face, le mont Sinaï trembla; devant ta face, Dieu d’Israël! Entrée en Canaan` },
  { livre: `Psaumes`, chapitre: 68, verset: 9, texte: `Tu fis pleuvoir tes bienfaits sur ton héritage, ô Dieu, Ton héritage épuisé. Et tu restauras ses forces.` },
  { livre: `Psaumes`, chapitre: 68, verset: 10, texte: `Ton peuple s’est établi en ces lieux par ta bonté, Et tu affermis, ô Dieu, les malheureux, dans ta bonté.` },
  { livre: `Psaumes`, chapitre: 68, verset: 11, texte: `Le Seigneur a dit un mot, Aussitôt les messagères forment une armée nombreuse.` },
  { livre: `Psaumes`, chapitre: 68, verset: 12, texte: `Les rois ennemis ont fui, leurs armées sont en déroute. Les habitants du pays se partagent le butin.` },
  { livre: `Psaumes`, chapitre: 68, verset: 13, texte: `Resterez-vous au repos bien couchés entre vos murs Quand les ailes des colombes sont recouvertes d’argent, Quand les plumes de leur dos, ont la couleur de l’or fin?` },
  { livre: `Psaumes`, chapitre: 68, verset: 14, texte: `Quand le Tout-Puissant, là-bas, a pulvérisé les rois, Il a neigé sur la montagne Salmon.` },
  { livre: `Psaumes`, chapitre: 68, verset: 15, texte: `Ô vous, montagnes de Dieu, Ô vous, montagnes sublimes, monts de Basan,` },
  { livre: `Psaumes`, chapitre: 68, verset: 16, texte: `Pourquoi donc jalousez-vous, ô vous, montagnes sublimes, Le mont que Dieu s’est choisi pour y faire sa demeure? Le Seigneur l’habitera jusqu’à la fin.` },
  { livre: `Psaumes`, chapitre: 68, verset: 17, texte: `Les chars de Dieu sont innombrables, Ils sont vingt mille milliers Et le Seigneur est parmi eux au sanctuaire du Sinaï. Dieu et ses ennemis` },
  { livre: `Psaumes`, chapitre: 68, verset: 18, texte: `Tu montas sur la hauteur en emmenant des captifs. Tu as fait des prisonniers. Tu as reçu en tribut des hommes – oui des rebelles – Seigneur Dieu, pour qu’ils habitent là où tu as ta demeure.` },
  { livre: `Psaumes`, chapitre: 68, verset: 19, texte: `Béni soit le Seigneur Dieu, c’est lui qui, jour après jour, Nous porte et nous prend en charge, il est notre délivrance.` },
  { livre: `Psaumes`, chapitre: 68, verset: 20, texte: `Le Tout-Puissant est pour nous. C’est le Dieu des délivrances. Il nous arrache à la mort, car il est Dieu, le Seigneur.` },
  { livre: `Psaumes`, chapitre: 68, verset: 21, texte: `Oui, Dieu brisera la tête de ses (puissants) ennemis, Les chefs aux cheveux flottants dont la conduite est coupable.` },
  { livre: `Psaumes`, chapitre: 68, verset: 22, texte: `Le Seigneur a déclaré: «Je ramènerai mon peuple Des montagnes de Basan, je les ferai revenir des abîmes de la mer` },
  { livre: `Psaumes`, chapitre: 68, verset: 23, texte: `Pour que tu baignes ton pied dans le sang des ennemis, Que la langue de tes chiens ait sa part de la curée». Procession dans le temple` },
  { livre: `Psaumes`, chapitre: 68, verset: 24, texte: `On voit ton cortège, ô Dieu, le cortège triomphal De mon Dieu et de mon Roi pour se rendre au sanctuaire.` },
  { livre: `Psaumes`, chapitre: 68, verset: 25, texte: `D’abord viennent les chanteurs; derrière eux, les musiciens, Au milieu, les jeunes filles qui frappent leur tambourin.` },
  { livre: `Psaumes`, chapitre: 68, verset: 26, texte: `Bénissez le Seigneur Dieu dans vos grandes assemblées: «À la source d’Israël, il y avait le Seigneur».` },
  { livre: `Psaumes`, chapitre: 68, verset: 27, texte: `Voici Benjamin, le plus petit, mais il marche en tête et les conduit, Les chefs de Juda en habits brodés, ceux de Zabulon et de Nephtali. Perspectives` },
  { livre: `Psaumes`, chapitre: 68, verset: 28, texte: `Ton Dieu veut que tu sois fort. Montre ta puissance, ô Dieu, Consolide par ta force ce que tu as fait pour nous.` },
  { livre: `Psaumes`, chapitre: 68, verset: 29, texte: `Du haut de ton sanctuaire dominant Jérusalem, Tu recevras les présents que t’apporteront les rois.` },
  { livre: `Psaumes`, chapitre: 68, verset: 30, texte: `Menace le crocodile qui se tapit dans les joncs, Et la bande de taureaux, avec tous les veaux des peuples. Ils viennent se prosterner avec leurs pièces d’argent. Ô Dieu, disperse ces peuples, tous ceux qui aiment la guerre!` },
  { livre: `Psaumes`, chapitre: 68, verset: 31, texte: `De l’Égypte, des puissants viendront avec leurs offrandes, L’Éthiopie viendra vers Dieu, les mains étendues vers lui. Finale` },
  { livre: `Psaumes`, chapitre: 68, verset: 32, texte: `Ô royaumes de la terre, chantez en l’honneur de Dieu! Célébrez tous le Seigneur!` },
  { livre: `Psaumes`, chapitre: 68, verset: 33, texte: `Chantez celui qui s’avance, Qui chevauche dans les cieux, oui, dans les cieux éternels! Voici qu’il fait retentir sa voix, sa voix éclatante.` },
  { livre: `Psaumes`, chapitre: 68, verset: 34, texte: `Rendez hommage au Seigneur, Reconnaissez sa puissance: Sa puissance est dans les nues, Sa splendeur sur Israël.` },
  { livre: `Psaumes`, chapitre: 68, verset: 35, texte: `Tu es redoutable, ô Dieu, du fond de ton sanctuaire: Oui, c’est le Dieu d’Israël qui donne force et vigueur. Béni soit Dieu, le Seigneur!` },
  { livre: `Psaumes`, chapitre: 69, verset: 0, texte: `Au chef de chœur. Un psaume de David (à chanter sur) «Les lis».` },
  { livre: `Psaumes`, chapitre: 69, verset: 1, texte: `Ô mon Dieu, sauve-moi: les flots me submergent et menacent ma vie.` },
  { livre: `Psaumes`, chapitre: 69, verset: 2, texte: `Je m’enlise et j’enfonce dans un bourbier sans fond, Sans aucun point d’appui. Me voici descendu Au plus profond des eaux; le torrent me submerge.` },
  { livre: `Psaumes`, chapitre: 69, verset: 3, texte: `Je m’épuise à crier, mon gosier est brûlant, Mes yeux se sont usés à force de guetter le secours de mon Dieu.` },
  { livre: `Psaumes`, chapitre: 69, verset: 4, texte: `Car ceux qui me haïssent sans cause ni raison Ont dépassé le nombre des cheveux de ma tête. Ils sont plus forts que moi, ils veulent me détruire, Mes ennemis menteurs. Je dois restituer ce que je n’ai pas pris.` },
  { livre: `Psaumes`, chapitre: 69, verset: 5, texte: `Ô Dieu, toi, tu connais tous mes égarements Et mes actes coupables ne te sont pas cachés.` },
  { livre: `Psaumes`, chapitre: 69, verset: 6, texte: `Qu’ils n’aient pas à rougir de moi, Ceux qui ont mis tout leur espoir en toi! Éternel des armées, qu’ils ne soient pas confus par moi Ceux qui te cherchent, ô toi, Dieu d’Israël!` },
  { livre: `Psaumes`, chapitre: 69, verset: 7, texte: `Car c’est à ton service que je souffre l’insulte Et que la confusion me couvre le visage.` },
  { livre: `Psaumes`, chapitre: 69, verset: 8, texte: `Me voilà devenu étranger pour mes frères Et comme un inconnu pour les fils de ma mère!` },
  { livre: `Psaumes`, chapitre: 69, verset: 9, texte: `Car je suis dévoré d’ardeur pour ta maison, L’insulte qu’on t’adresse est retombée sur moi.` },
  { livre: `Psaumes`, chapitre: 69, verset: 10, texte: `J’ai mortifié mon âme, j’ai pleuré, j’ai jeûné, Mais cela ne m’attire, hélas, que des insultes!` },
  { livre: `Psaumes`, chapitre: 69, verset: 11, texte: `Si je me revêtais d’un vêtement de deuil, Je devenais, pour eux, la risée du quartier.` },
  { livre: `Psaumes`, chapitre: 69, verset: 12, texte: `Les badauds de la ville jasent à mon sujet, Et les buveurs de bière font de moi leur chanson.` },
  { livre: `Psaumes`, chapitre: 69, verset: 13, texte: `Mais moi, dans ma prière, je me tourne vers toi, Ô Éternel, mon Dieu! C’est le moment propice, Ô Dieu, exauce-moi dans ton immense amour, Que ta fidélité m’accorde le salut!` },
  { livre: `Psaumes`, chapitre: 69, verset: 14, texte: `Tire-moi du bourbier: que je ne sombre pas! Que je sois arraché à ceux qui me haïssent et du tréfonds des eaux!` },
  { livre: `Psaumes`, chapitre: 69, verset: 15, texte: `Que l’eau tumultueuse ne me submerge pas! Que l’abîme sans fond ne m’engloutisse pas! Que le gouffre béant ne me dévore pas!` },
  { livre: `Psaumes`, chapitre: 69, verset: 16, texte: `Réponds-moi, ô Seigneur, toi dont la grâce est douce! Dans ta grande tendresse, tourne vers moi ta face!` },
  { livre: `Psaumes`, chapitre: 69, verset: 17, texte: `Ne cache plus ta face loin de ton serviteur! Réponds-moi sans tarder, car je suis dans l’angoisse!` },
  { livre: `Psaumes`, chapitre: 69, verset: 18, texte: `Approche-toi de moi, viens racheter mon âme Car j’ai des ennemis. Viens donc me libérer!` },
  { livre: `Psaumes`, chapitre: 69, verset: 19, texte: `Tu connais mon opprobre: je suis couvert de honte, insulté, bafoué, tous mes persécuteurs se tiennent devant moi,` },
  { livre: `Psaumes`, chapitre: 69, verset: 20, texte: `Leurs outrages m’atteignent et me brisent le cœur, Le mal est sans remède. J’attends de la pitié, Mais mon attente est vaine; quelqu’un qui me console, Mais je n’en trouve point.` },
  { livre: `Psaumes`, chapitre: 69, verset: 21, texte: `Ils mêlent du poison et du fiel à mon pain. Pour étancher ma soif, on m’offre du vinaigre.` },
  { livre: `Psaumes`, chapitre: 69, verset: 22, texte: `Que leur table devienne un piège devant eux, Que leur prospérité leur tende un traquenard!` },
  { livre: `Psaumes`, chapitre: 69, verset: 23, texte: `Que leurs yeux s’obscurcissent au point de ne plus voir, Et que leurs pas chancellent! Rabats leur assurance!` },
  { livre: `Psaumes`, chapitre: 69, verset: 24, texte: `Que ton indignation se déverse sur eux! Que ta colère ardente (à la fin) les atteigne!` },
  { livre: `Psaumes`, chapitre: 69, verset: 25, texte: `Que les lieux où ils campent deviennent des déserts, Que toutes leurs demeures soient privées d’habitants!` },
  { livre: `Psaumes`, chapitre: 69, verset: 26, texte: `Car ils ont poursuivi celui que tu frappais, Ils commentent les malheurs de ceux que tu avais blessés.` },
  { livre: `Psaumes`, chapitre: 69, verset: 27, texte: `Rends le crime à leur crime, Et qu’ils n’aient plus accès à ta miséricorde!` },
  { livre: `Psaumes`, chapitre: 69, verset: 28, texte: `Que leurs noms soient rayés du livre des vivants! Qu’ils ne soient pas inscrits, (Seigneur,) parmi les justes!` },
  { livre: `Psaumes`, chapitre: 69, verset: 29, texte: `Moi, je suis humilié, blessé, endolori. Ô Dieu, que ton salut soit ma haute retraite!` },
  { livre: `Psaumes`, chapitre: 69, verset: 30, texte: `Je chanterai ton nom, ô Dieu, dans mes cantiques, Et je t’exalterai par des actions de grâces.` },
  { livre: `Psaumes`, chapitre: 69, verset: 31, texte: `Cela peut plaire à Dieu plus que le sacrifice D’un troupeau de taureaux ayant corne et sabot.` },
  { livre: `Psaumes`, chapitre: 69, verset: 32, texte: `Ô vous, les malheureux, voyez, réjouissez-vous! Et vous qui cherchez Dieu, que votre cœur revive!` },
  { livre: `Psaumes`, chapitre: 69, verset: 33, texte: `Car le Seigneur entend les cris des malheureux, Il ne méprise pas ceux qui sont prisonniers.` },
  { livre: `Psaumes`, chapitre: 69, verset: 34, texte: `Que les cieux et la terre entonnent ses louanges Et que les mers l’acclament avec leur peuplement!` },
  { livre: `Psaumes`, chapitre: 69, verset: 35, texte: `Car Dieu viendra sauver la ville de Sion Et rebâtira les cités de Juda. On y habitera, on les possédera.` },
  { livre: `Psaumes`, chapitre: 69, verset: 36, texte: `Les fils de tes esclaves l’auront pour héritage, Ceux qui aiment ton nom y feront leur demeure.` },
  { livre: `Psaumes`, chapitre: 70, verset: 0, texte: `Au chef de chœur. Évocation de David.` },
  { livre: `Psaumes`, chapitre: 70, verset: 1, texte: `Ô Dieu, viens à mon aide, Seigneur, à mon secours! Hâte-toi, vite, accours!` },
  { livre: `Psaumes`, chapitre: 70, verset: 2, texte: `Qu’ils soient couverts de honte, qu’ils aillent se cacher, Ceux qui guettent mon âme! Qu’ils reculent de honte, Ceux qui se réjouissent en voyant mon malheur!` },
  { livre: `Psaumes`, chapitre: 70, verset: 3, texte: `Qu’ils tournent les talons, honteux, ceux qui disaient: «Ah! Ah!» à mon sujet!` },
  { livre: `Psaumes`, chapitre: 70, verset: 4, texte: `Mais tous ceux qui te cherchent seront dans l’allégresse, Ils trouveront en toi leur bonheur et leur joie. Que tous ceux qui aspirent à ton salut, ô Dieu, Puissent dire sans cesse: «Que le Seigneur est grand!»` },
  { livre: `Psaumes`, chapitre: 70, verset: 5, texte: `Moi je suis humilié, indigent, misérable; Ô mon Dieu, hâte-toi, viens vite à mon secours! Car tu es mon Sauveur et mon libérateur. Seigneur, ne tarde plus!` },
  { livre: `Psaumes`, chapitre: 71, verset: 1, texte: `En toi, Seigneur, j’ai cherché mon refuge. Que mon espoir ne soit jamais déçu!` },
  { livre: `Psaumes`, chapitre: 71, verset: 2, texte: `Dans ta justice, tu vas me délivrer. Viens, secours-moi et fais-moi échapper! Écoute-moi, tends vers moi ton oreille et sauve-moi!` },
  { livre: `Psaumes`, chapitre: 71, verset: 3, texte: `Sois mon abri, le roc de mon refuge, La place forte où je trouve un asile à tout moment! Oui, tu as résolu de me sauver, Car tu es mon rocher, ma forteresse.` },
  { livre: `Psaumes`, chapitre: 71, verset: 4, texte: `Ô mon Dieu, secours-moi! Délivre-moi de la main de l’impie! Arrache-moi au poing du scélérat et du tyran!` },
  { livre: `Psaumes`, chapitre: 71, verset: 5, texte: `Car tu es mon espoir, Seigneur, mon Dieu, Tu es ma sauvegarde et mon appui depuis ma tendre enfance!` },
  { livre: `Psaumes`, chapitre: 71, verset: 6, texte: `Tu me soutiens depuis que je suis né. Tu m’as choisi dès le sein maternel. Tu es sans cesse l’objet de mes louanges.` },
  { livre: `Psaumes`, chapitre: 71, verset: 7, texte: `Je suis un signe pour beaucoup, un prodige, Car mon refuge, mon sûr abri, c’est toi.` },
  { livre: `Psaumes`, chapitre: 71, verset: 8, texte: `Ma bouche est pleine du chant de tes louanges Et, chaque jour, elle publie ta gloire.` },
  { livre: `Psaumes`, chapitre: 71, verset: 9, texte: `En ma vieillesse, ne me rejette pas; Quand je faiblis, ne m’abandonne pas!` },
  { livre: `Psaumes`, chapitre: 71, verset: 10, texte: `Mes ennemis discourent contre moi, Ceux qui m’épient se concertent ensemble.` },
  { livre: `Psaumes`, chapitre: 71, verset: 11, texte: `Ils se murmurent: «Dieu l’a abandonné! Poursuivez-le! Saisissez-vous de lui! Il n’est personne qui pourrait le sauver».` },
  { livre: `Psaumes`, chapitre: 71, verset: 12, texte: `Mais toi, ô Dieu, ne reste pas si loin! Mon Dieu, à l’aide! Viens vite à mon secours!` },
  { livre: `Psaumes`, chapitre: 71, verset: 13, texte: `Qu’ils soient confus, tous mes accusateurs! Qu’ils disparaissent, qu’ils soient couverts de honte et d’infamie, Ceux qui cherchent ma perte!` },
  { livre: `Psaumes`, chapitre: 71, verset: 14, texte: `Mais moi, sans cesse, je serai plein d’espoir. De plus en plus, je veux chanter ta gloire.` },
  { livre: `Psaumes`, chapitre: 71, verset: 15, texte: `Oui, tout le jour, ma bouche annoncera ton équité, Tes bienfaits sans mesure, sans parvenir à les énumérer.` },
  { livre: `Psaumes`, chapitre: 71, verset: 16, texte: `Je parlerai des hauts faits du Seigneur, J’évoquerai ta justice, ô mon Dieu.` },
  { livre: `Psaumes`, chapitre: 71, verset: 17, texte: `Tu m’as instruit, ô Dieu, dès ma jeunesse, Jusqu’à ce jour, je publie tes merveilles.` },
  { livre: `Psaumes`, chapitre: 71, verset: 18, texte: `Reste avec moi à la blanche vieillesse! Seigneur, mon Dieu, ne m’abandonne pas! Et je pourrai révéler ta puissance dès aujourd’hui Aux hommes de mon temps, Et ta vaillance à tous ceux qui viendront.` },
  { livre: `Psaumes`, chapitre: 71, verset: 19, texte: `Car ta justice, ô Dieu, est infinie, Car tu as fait des choses admirables! Qui donc, ô Dieu, serait semblable à toi?` },
  { livre: `Psaumes`, chapitre: 71, verset: 20, texte: `Tu nous as fait passer par des détresses Et des malheurs graves et innombrables. Fais-moi revivre et, du fond des abîmes, rappelle-moi!` },
  { livre: `Psaumes`, chapitre: 71, verset: 21, texte: `Tu accroîtras mon prestige et ma gloire. Tu reviendras, tu me consoleras.` },
  { livre: `Psaumes`, chapitre: 71, verset: 22, texte: `Moi, en retour, je te célébrerai avec le luth. Pour ta fidélité, je te louerai, Je jouerai sur la harpe, Seigneur, mon Dieu. Je te glorifierai, Saint d’Israël!` },
  { livre: `Psaumes`, chapitre: 71, verset: 23, texte: `Mes lèvres, de joie, exulteront. Je veux psalmodier en ton honneur, Car tu as racheté mon âme, (ô Dieu).` },
  { livre: `Psaumes`, chapitre: 71, verset: 24, texte: `Ma langue redira, de jour en jour, tes œuvres de salut et ta justice, Car ils sont confondus, tout honteux, ceux qui cherchaient ma perte.` },
  { livre: `Psaumes`, chapitre: 72, verset: 1, texte: `De Salomon. Ô Dieu, accorde au roi des jugements divins, Et donne au fils du roi ton esprit de justice!` },
  { livre: `Psaumes`, chapitre: 72, verset: 2, texte: `Qu’il gouverne ton peuple avec de justes lois, Les pauvres que tu aimes en appliquant le droit!` },
  { livre: `Psaumes`, chapitre: 72, verset: 3, texte: `Que par l’effet de ta justice, la paix descende des montagnes Et des collines du pays pour tout le peuple!` },
  { livre: `Psaumes`, chapitre: 72, verset: 4, texte: `Qu’il fasse droit aux opprimés et aux malheureux de son peuple! Qu’il sauve les enfants des pauvres, mais qu’il écrase l’oppresseur!` },
  { livre: `Psaumes`, chapitre: 72, verset: 5, texte: `Alors, ils te vénéreront tant que durera le soleil, Tant que la lune apparaîtra, à travers tous les âges.` },
  { livre: `Psaumes`, chapitre: 72, verset: 6, texte: `Le roi sera comme une pluie qui descend sur un pré fauché, Et comme une averse féconde qui abreuve la terre.` },
  { livre: `Psaumes`, chapitre: 72, verset: 7, texte: `Que le juste soit florissant tant que dure son règne, Dans la paix et dans l’opulence tant que brille la lune!` },
  { livre: `Psaumes`, chapitre: 72, verset: 8, texte: `Qu’il règne d’une mer à l’autre, Qu’il domine depuis le fleuve jusqu’aux confins du monde!` },
  { livre: `Psaumes`, chapitre: 72, verset: 9, texte: `Devant lui se prosterneront ceux qui habitent le désert, Et tous ses adversaires lécheront la poussière.` },
  { livre: `Psaumes`, chapitre: 72, verset: 10, texte: `Les rois de Tarsis et des îles lui apporteront des présents. Les souverains de l’Arabie lui présenteront leurs offrandes.` },
  { livre: `Psaumes`, chapitre: 72, verset: 11, texte: `Tous les rois lui rendront hommage en se prosternant devant lui. Tous les pays le serviront.` },
  { livre: `Psaumes`, chapitre: 72, verset: 12, texte: `Car il délivrera le pauvre qui implorera son secours, Et l’affligé qui n’a point d’aide.` },
  { livre: `Psaumes`, chapitre: 72, verset: 13, texte: `Il aura compassion des faibles, des humbles et des malheureux, Il protège la vie des pauvres.` },
  { livre: `Psaumes`, chapitre: 72, verset: 14, texte: `Il saura racheter leur âme de la fraude et de l’oppression, Leur vie est précieuse à ses yeux.` },
  { livre: `Psaumes`, chapitre: 72, verset: 15, texte: `Tout le temps que le roi vivra, il recevra l’or de Saba. Que l’on prie pour lui sans relâche! Qu’on le bénisse tous les jours!` },
  { livre: `Psaumes`, chapitre: 72, verset: 16, texte: `Les champs de blé abonderont, Ils couvriront tout le pays jusqu’à la crête des montagnes. Les épis lourds onduleront comme des cèdres du Liban Et, dans les villes florissantes, Les hommes se multiplieront autant que l’herbe dans les prés.` },
  { livre: `Psaumes`, chapitre: 72, verset: 17, texte: `Que son nom subsiste à jamais! Que sa renommée se propage autant que l’éclat du soleil! Pour être béni, qu’on l’invoque, Que toutes les nations du monde proclament sa félicité!` },
  { livre: `Psaumes`, chapitre: 72, verset: 18, texte: `Oui, béni soit le Seigneur Dieu, Le grand Dieu d’Israël, qui, seul, accomplit des miracles!` },
  { livre: `Psaumes`, chapitre: 72, verset: 19, texte: `Béni soit, pour l’éternité, son nom glorieux, et que la terre Soit toute remplie de sa gloire! Amen, Amen! Ainsi soit-il!` },
  { livre: `Psaumes`, chapitre: 72, verset: 20, texte: `Fin des prières de David, fils d’Isaï.` },
  { livre: `Psaumes`, chapitre: 73, verset: 1, texte: `Psaume d’Asaph. Oui, Dieu est bon pour Israël, pour tous ceux qui ont le cœur pur.` },
  { livre: `Psaumes`, chapitre: 73, verset: 2, texte: `Pourtant il s’en fallut de peu et mes pieds allaient trébucher, Un rien de plus et je glissais.` },
  { livre: `Psaumes`, chapitre: 73, verset: 3, texte: `Car j’étais jaloux des vantards en voyant la paix des méchants.` },
  { livre: `Psaumes`, chapitre: 73, verset: 4, texte: `Car ils sont exempts de souffrance, Ils ne pensent pas à la mort, leur corps est en bonne santé.` },
  { livre: `Psaumes`, chapitre: 73, verset: 5, texte: `Ils échappent à la misère que connaissent tous les humains. Ils ne subissent pas les maux qui atteignent les autres hommes.` },
  { livre: `Psaumes`, chapitre: 73, verset: 6, texte: `Aussi sont-ils pleins d’arrogance, Ils prennent l’orgueil pour collier Et la violence est leur parure,` },
  { livre: `Psaumes`, chapitre: 73, verset: 7, texte: `Leurs yeux pétillent de bien-être, Les convoitises de leur cœur Débordent sans frein, sans mesure.` },
  { livre: `Psaumes`, chapitre: 73, verset: 8, texte: `Ils sont railleurs et insolents Et ils se vantent méchamment de leurs méfaits, De leurs violences. Ils parlent sur un ton hautain,` },
  { livre: `Psaumes`, chapitre: 73, verset: 9, texte: `Leur bouche s’attaque au ciel même, Leur langue sévit sur la terre.` },
  { livre: `Psaumes`, chapitre: 73, verset: 10, texte: `C’est pourquoi le peuple de Dieu Se détourne de leur côté, Buvant à longs traits leurs paroles,` },
  { livre: `Psaumes`, chapitre: 73, verset: 11, texte: `Tout en disant: «Dieu? Que sait-il? Le Très-Haut en a-t-il conscience?»` },
  { livre: `Psaumes`, chapitre: 73, verset: 12, texte: `Voilà comment sont les méchants: Toujours heureux, jamais troublés, ils accumulent leurs richesses.` },
  { livre: `Psaumes`, chapitre: 73, verset: 13, texte: `En vérité, c’est donc en vain Que j’ai conservé mon cœur pur et gardé mes mains innocentes!` },
  { livre: `Psaumes`, chapitre: 73, verset: 14, texte: `Tous les jours, je suis maltraité, je suis châtié chaque matin!` },
  { livre: `Psaumes`, chapitre: 73, verset: 15, texte: `Si je disais: «Parlons comme eux», je trahirais tous tes enfants.` },
  { livre: `Psaumes`, chapitre: 73, verset: 16, texte: `Je me suis mis à réfléchir: longtemps, j’ai cherché à comprendre, C’était un tourment à mes yeux,` },
  { livre: `Psaumes`, chapitre: 73, verset: 17, texte: `Jusqu’au jour où je suis entré dans le dessein secret de Dieu Et où j’ai fini par comprendre le sort final qui les attend.` },
  { livre: `Psaumes`, chapitre: 73, verset: 18, texte: `Car tu les mets, certainement, sur un terrain qui est glissant, Tu les entraînes vers la ruine.` },
  { livre: `Psaumes`, chapitre: 73, verset: 19, texte: `Et soudain, c’est la catastrophe: En un instant, ils sont détruits et finissent dans l’épouvante.` },
  { livre: `Psaumes`, chapitre: 73, verset: 20, texte: `Comme un songe après le réveil, Seigneur, quand tu te lèveras, tu chasseras leur vaine image.` },
  { livre: `Psaumes`, chapitre: 73, verset: 21, texte: `Oui, quand j’avais le cœur amer et tout mon être déchiré,` },
  { livre: `Psaumes`, chapitre: 73, verset: 22, texte: `J’étais un sot, un ignorant, comme un animal sans raison.` },
  { livre: `Psaumes`, chapitre: 73, verset: 23, texte: `Car je suis toujours avec toi, tu m’as saisi par la main droite,` },
  { livre: `Psaumes`, chapitre: 73, verset: 24, texte: `Selon ton plan, tu me conduis, Puis tu me prendras dans la gloire.` },
  { livre: `Psaumes`, chapitre: 73, verset: 25, texte: `Qui ai-je au ciel, si ce n’est toi? Et, quand je suis auprès de toi, rien ne m’attire plus sur terre.` },
  { livre: `Psaumes`, chapitre: 73, verset: 26, texte: `Si ma chair et mon cœur défaillent, Dieu reste mon rocher, ma part, mon héritage pour toujours.` },
  { livre: `Psaumes`, chapitre: 73, verset: 27, texte: `Qui t’abandonne périra, Et tu réduiras au silence tous ceux qui te sont infidèles.` },
  { livre: `Psaumes`, chapitre: 73, verset: 28, texte: `Tandis que mon bonheur à moi, c’est de vivre tout près de Dieu, Oui, j’ai trouvé un sûr abri auprès du Seigneur Éternel, Afin de raconter ses œuvres.` },
  { livre: `Psaumes`, chapitre: 74, verset: 1, texte: `Poème didactique d’Asaph. Pourquoi, ô Dieu, nous délaisser obstinément? Pourquoi ce courroux fulminant contre le troupeau que tu pais?` },
  { livre: `Psaumes`, chapitre: 74, verset: 2, texte: `Souviens-toi de ton assemblée que tu fondas dans le passé: Tu avais racheté ce peuple afin qu’il t’appartienne en propre. Souviens-toi du mont de Sion où tu as fixé ton séjour!` },
  { livre: `Psaumes`, chapitre: 74, verset: 3, texte: `Viens voir ces lieux toujours en ruines: L’ennemi a tout dévasté, tout saccagé au sanctuaire.` },
  { livre: `Psaumes`, chapitre: 74, verset: 4, texte: `Ses cris emplissent le lieu saint. À l’endroit où l’on te fêtait, Ils ont planté leurs étendards comme des signes de victoire.` },
  { livre: `Psaumes`, chapitre: 74, verset: 5, texte: `Ils sont venus avec leurs haches, Cognant comme des bûcherons dans les halliers de la forêt,` },
  { livre: `Psaumes`, chapitre: 74, verset: 6, texte: `Mettant en pièces les sculptures avec la masse et la cognée.` },
  { livre: `Psaumes`, chapitre: 74, verset: 7, texte: `Ils ont mis le feu à ton temple, Ils ont rasé et profané la résidence de ton nom.` },
  { livre: `Psaumes`, chapitre: 74, verset: 8, texte: `Ils avaient pensé dans leur cœur: «Nous les détruirons d’un seul coup!» Ils ont brûlé, dans le pays, tous les lieux consacrés à Dieu.` },
  { livre: `Psaumes`, chapitre: 74, verset: 9, texte: `Nous ne voyons plus nos emblèmes, Nous n’entendons plus de prophètes. Personne d’entre nous ne sait combien de temps? Jusques à quand?` },
  { livre: `Psaumes`, chapitre: 74, verset: 10, texte: `Jusques à quand, ô (Seigneur) Dieu, l’adversaire insultera-t-il? Les ennemis pourront-ils donc sans cesse outrager ton saint nom?` },
  { livre: `Psaumes`, chapitre: 74, verset: 11, texte: `Pourquoi retires-tu ta main? Sors donc ta droite de ton sein!` },
  { livre: `Psaumes`, chapitre: 74, verset: 12, texte: `Pourtant, ô Dieu, tu es mon Roi, tu l’es depuis les temps antiques! Tu opères des délivrances au milieu du pays!` },
  { livre: `Psaumes`, chapitre: 74, verset: 13, texte: `C’est toi qui as fendu la mer par ta grande puissance! C’est toi qui as brisé la tête des monstres sur les eaux!` },
  { livre: `Psaumes`, chapitre: 74, verset: 14, texte: `Toi qui as fracassé l’échine du grand dragon marin, Et qui l’as donné en pâture aux requins de la mer!` },
  { livre: `Psaumes`, chapitre: 74, verset: 15, texte: `Toi qui as fait jaillir des sources et les eaux en torrent! Toi qui as desséché le lit des flots intarissables!` },
  { livre: `Psaumes`, chapitre: 74, verset: 16, texte: `À toi le jour, à toi la nuit! Toi qui créas l’astre nocturne ainsi que le soleil.` },
  { livre: `Psaumes`, chapitre: 74, verset: 17, texte: `Toi qui as fixé les frontières, dressé les bornes de la terre, Tu as créé l’été, l’hiver!` },
  { livre: `Psaumes`, chapitre: 74, verset: 18, texte: `Souviens-toi, Éternel, que l’ennemi t’a insulté, Qu’un peuple fou a blasphémé ton saint nom, ô Seigneur!` },
  { livre: `Psaumes`, chapitre: 74, verset: 19, texte: `Ne livre pas aux bêtes fauves la vie de ta colombe, N’oublie pas indéfiniment le troupeau de tes affligés!` },
  { livre: `Psaumes`, chapitre: 74, verset: 20, texte: `Sois attentif à ton alliance, car la mesure est comble! Les lieux retirés du pays sont des repaires de brigands.` },
  { livre: `Psaumes`, chapitre: 74, verset: 21, texte: `Que l’opprimé ne reste pas sous l’insulte et la honte! Que les malheureux et les pauvres puissent louer ton nom!` },
  { livre: `Psaumes`, chapitre: 74, verset: 22, texte: `Debout, ô Dieu! défends ta cause! Rappelle-toi l’insulte que, tout le jour, t’adresse un fou! N’oublie pas les clameurs de tous tes adversaires, Ni le tumulte grandissant que font monter sans cesse Ceux qui se dressent contre toi.` },
  { livre: `Psaumes`, chapitre: 75, verset: 1, texte: `Au chef de chœur. Psaume d’Asaph. (À chanter sur la mélodie: «Ne détruis pas».)` },
  { livre: `Psaumes`, chapitre: 75, verset: 2, texte: `Ô Dieu, nous te célébrons, nous louons ton nom, Tu es près de nous. Qu’on raconte tes merveilles!` },
  { livre: `Psaumes`, chapitre: 75, verset: 3, texte: `«Quand viendra le temps que j’ai décidé, (a dit le Seigneur,) Je rendrai justice avec équité.` },
  { livre: `Psaumes`, chapitre: 75, verset: 4, texte: `Que la terre tremble avec tous ses habitants! Moi seul, j’affermis ses bases.` },
  { livre: `Psaumes`, chapitre: 75, verset: 5, texte: `J’avertis ceux qui se vantent: “Plus de vantardises!” Je dis aux impies: “Ne levez pas votre front ”».` },
  { livre: `Psaumes`, chapitre: 75, verset: 6, texte: `Ne le levez pas contre le Très-Haut! Cessez de parler en raidissant votre nuque!` },
  { livre: `Psaumes`, chapitre: 75, verset: 7, texte: `Ce n’est pas de l’est, non plus de l’ouest, Et ce n’est pas du désert que viendra votre salut!` },
  { livre: `Psaumes`, chapitre: 75, verset: 8, texte: `C’est Dieu seul qui juge: il abaisse l’un et relève l’autre.` },
  { livre: `Psaumes`, chapitre: 75, verset: 9, texte: `Le Seigneur tient dans sa main une coupe Emplie de vin âpre et fermenté. Il en verse, et les méchants Devront vider cette coupe en buvant jusqu’à la lie.` },
  { livre: `Psaumes`, chapitre: 75, verset: 10, texte: `Moi, je chanterai sans cesse En l’honneur de Dieu, du Dieu de Jacob, Et j’abattrai l’arrogance de tous les impies Tandis que le juste pourra marcher le front haut.` },
  { livre: `Psaumes`, chapitre: 76, verset: 0, texte: `Au chef de chœur. Un psaume d’Asaph. À chanter avec accompagnement d’instruments à cordes.` },
  { livre: `Psaumes`, chapitre: 76, verset: 1, texte: `Dieu s’est fait connaître en Juda, son nom est grand en Israël.` },
  { livre: `Psaumes`, chapitre: 76, verset: 2, texte: `Son tabernacle est à Salem, et sa demeure est en Sion.` },
  { livre: `Psaumes`, chapitre: 76, verset: 3, texte: `C’est là qu’il a brisé les flèches fulgurantes, Les boucliers, les glaives et les engins de guerre.` },
  { livre: `Psaumes`, chapitre: 76, verset: 4, texte: `Tu es, ô Tout-puissant, éclatant de lumière, Plus que les monts des ravisseurs.` },
  { livre: `Psaumes`, chapitre: 76, verset: 5, texte: `Tous les vaillants guerriers ont été dépouillés, Ils se sont endormis de leur dernier sommeil. Tous les héros de guerre N’ont pas su retrouver la vigueur de leurs mains.` },
  { livre: `Psaumes`, chapitre: 76, verset: 6, texte: `À ta seule menace, ô Dieu, Dieu de Jacob, Cavaliers et chevaux se sont paralysés.` },
  { livre: `Psaumes`, chapitre: 76, verset: 7, texte: `Que tu es redoutable! Qui tiendrait devant toi quand ta colère éclate?` },
  { livre: `Psaumes`, chapitre: 76, verset: 8, texte: `Au ciel tu fais entendre quel sera ton verdict Et la terre, effrayée, se tient dans le silence,` },
  { livre: `Psaumes`, chapitre: 76, verset: 9, texte: `Quand tu te lèveras, ô Dieu, Pour prononcer le jugement Et pour sauver tous les affligés de la terre.` },
  { livre: `Psaumes`, chapitre: 76, verset: 10, texte: `Car même la fureur des homme tournera à ta gloire Et tu t’attacheras les rescapés de la colère.` },
  { livre: `Psaumes`, chapitre: 76, verset: 11, texte: `Accomplissez vos vœux au Seigneur, votre Dieu, Vous tous qui l’entourez: Apportez vos présents à ce Dieu redoutable.` },
  { livre: `Psaumes`, chapitre: 76, verset: 12, texte: `Il rabat le courage des princes tyranniques, Il se rend redoutable pour les rois de la terre.` },
  { livre: `Psaumes`, chapitre: 77, verset: 0, texte: `Au chef de chœur, à Jéduthun. Un psaume d’Asaph.` },
  { livre: `Psaumes`, chapitre: 77, verset: 1, texte: `Je crie vers Dieu à pleine voix, Oui, ma voix s’élève vers Dieu et il tend l’oreille vers moi.` },
  { livre: `Psaumes`, chapitre: 77, verset: 2, texte: `Au jour de ma détresse, tout au long de la nuit, Sans relâche et sans cesse: Je tends les mains vers lui, mais mon âme est inconsolable.` },
  { livre: `Psaumes`, chapitre: 77, verset: 3, texte: `Je me souviens de Dieu, mais c’est en gémissant. Quand je veux méditer, l’esprit se brouille en moi.` },
  { livre: `Psaumes`, chapitre: 77, verset: 4, texte: `Quand je veux m’endormir, tu me tiens en éveil. Je m’agite et me trouble et ne sais plus que dire.` },
  { livre: `Psaumes`, chapitre: 77, verset: 5, texte: `Je songe aux jours passés, aux années d’autrefois,` },
  { livre: `Psaumes`, chapitre: 77, verset: 6, texte: `J’évoque mes cantiques, au milieu de la nuit, Fredonnant dans mon cœur. Mon esprit s’interroge:` },
  { livre: `Psaumes`, chapitre: 77, verset: 7, texte: `L’abandon du Seigneur est-il définitif? Ne redeviendra-t-il plus jamais favorable?` },
  { livre: `Psaumes`, chapitre: 77, verset: 8, texte: `Sa grâce et sa bonté sont-elles épuisées? Sa parole aurait-elle cessé pour tous les siècles?` },
  { livre: `Psaumes`, chapitre: 77, verset: 9, texte: `Dieu a-t-il oublié d’avoir de la pitié? A-t-il, dans sa colère, retiré son amour?` },
  { livre: `Psaumes`, chapitre: 77, verset: 10, texte: `Alors, je me suis dit: «Ce qui fait ma souffrance, C’est que Dieu a changé: sa main n’est plus la même».` },
  { livre: `Psaumes`, chapitre: 77, verset: 11, texte: `Pourtant je me souviens des exploits du Seigneur. Oui, je veux évoquer tes miracles passés,` },
  { livre: `Psaumes`, chapitre: 77, verset: 12, texte: `Je veux considérer tout ce que tu as fait, réfléchir à tes œuvres.` },
  { livre: `Psaumes`, chapitre: 77, verset: 13, texte: `Ô Dieu, ta voie est sainte! Quel Dieu pourrait prétendre être aussi grand que Dieu?` },
  { livre: `Psaumes`, chapitre: 77, verset: 14, texte: `Tu es le Tout-Puissant et tu fais des miracles! Tu as manifesté ta puissance aux nations.` },
  { livre: `Psaumes`, chapitre: 77, verset: 15, texte: `Par ton bras triomphant, tu rachetas ton peuple, Les enfants de Jacob et les fils de Joseph.` },
  { livre: `Psaumes`, chapitre: 77, verset: 16, texte: `Les eaux t’ont vu, ô Dieu, et, quand elles t’ont vu, Elles ont bouillonné! Les abîmes frémirent.` },
  { livre: `Psaumes`, chapitre: 77, verset: 17, texte: `Les nuages versèrent de la pluie en torrents, Et les cieux retentirent de leur voix de tonnerre, Tes flèches sillonnèrent l’espace çà et là.` },
  { livre: `Psaumes`, chapitre: 77, verset: 18, texte: `Au fracas de ta foudre, au sein de la tornade, L’éclat de tes éclairs illuminait le monde. La terre s’effraya et se mit à trembler.` },
  { livre: `Psaumes`, chapitre: 77, verset: 19, texte: `Au milieu de la mer, tu as frayé ta route Et tracé ton sentier dans les eaux bouillonnantes, Et nul n’a discerné la trace de tes pas.` },
  { livre: `Psaumes`, chapitre: 77, verset: 20, texte: `Tu as conduit ton peuple par Moïse et Aaron Comme un berger conduit son troupeau de brebis.` },
  { livre: `Psaumes`, chapitre: 78, verset: 1, texte: `Poème didactique d’Asaph. Mon peuple, écoute mon enseignement, Sois attentif à ce que je vais dire.` },
  { livre: `Psaumes`, chapitre: 78, verset: 2, texte: `Je vais énoncer des pensées profondes Et dégager les leçons du passé:` },
  { livre: `Psaumes`, chapitre: 78, verset: 3, texte: `Nous avons entendu et nous savons Ce que nos pères nous ont raconté, Nous n’allons pas le cacher à nos fils.` },
  { livre: `Psaumes`, chapitre: 78, verset: 4, texte: `Nous redirons à tous ceux qui vont naître Que le Seigneur est digne de louanges Par sa puissance et ses nombreux miracles.` },
  { livre: `Psaumes`, chapitre: 78, verset: 5, texte: `Il a donné des ordres à Jacob et institué des lois pour Israël. Ce qu’il avait confié à nos ancêtres, Ils devaient le transmettre à leurs enfants,` },
  { livre: `Psaumes`, chapitre: 78, verset: 6, texte: `Pour que la nouvelle génération L’apprenne et puisse à son tour le transmettre À tous leurs enfants qui viendront à naître Et qui le rediront à leurs enfants,` },
  { livre: `Psaumes`, chapitre: 78, verset: 7, texte: `Afin qu’ils placent leur confiance en Dieu, Qu’ils n’oublient pas les hauts faits du Seigneur Et qu’ils observent ses commandements,` },
  { livre: `Psaumes`, chapitre: 78, verset: 8, texte: `Qu’ils ne soient pas semblables à leurs pères, Génération rebelle et révoltée, Génération dont le cœur vacillait, Dont l’esprit n’était pas fidèle à Dieu.` },
  { livre: `Psaumes`, chapitre: 78, verset: 9, texte: `Les enfants d’Éphraïm, archers habiles, Ont tourné le dos, au jour du combat.` },
  { livre: `Psaumes`, chapitre: 78, verset: 10, texte: `Ils n’ont pas gardé l’alliance de Dieu, Ils ont refusé de suivre sa loi.` },
  { livre: `Psaumes`, chapitre: 78, verset: 11, texte: `Ils avaient mis en oubli ses exploits Et les hauts faits opérés sous leurs yeux.` },
  { livre: `Psaumes`, chapitre: 78, verset: 12, texte: `Devant leurs pères, Dieu fit des prodiges Aux champs de Tsoar, au pays d’Égypte.` },
  { livre: `Psaumes`, chapitre: 78, verset: 13, texte: `Il a fendu la mer et ils passèrent, Il a dressé les eaux comme une digue.` },
  { livre: `Psaumes`, chapitre: 78, verset: 14, texte: `Il les guidait, le jour par la nuée et la nuit, par la lumière d’un feu.` },
  { livre: `Psaumes`, chapitre: 78, verset: 15, texte: `Il a fendu des rochers au désert, il les désaltéra de torrents d’eau.` },
  { livre: `Psaumes`, chapitre: 78, verset: 16, texte: `Il fit jaillir des ruisseaux de la pierre, Il en fit sortir les eaux comme un fleuve.` },
  { livre: `Psaumes`, chapitre: 78, verset: 17, texte: `Mais, sans arrêt, ils péchaient contre lui, Irritant le Très-Haut dans le désert.` },
  { livre: `Psaumes`, chapitre: 78, verset: 18, texte: `Dans leur cœur, ils ont mis Dieu à l’épreuve En réclamant de manger à leur faim.` },
  { livre: `Psaumes`, chapitre: 78, verset: 19, texte: `Ils ont tenu des propos contre Dieu: «Dieu peut-il dresser la table au désert?»` },
  { livre: `Psaumes`, chapitre: 78, verset: 20, texte: `Oui, car voici il a frappé le roc, L’eau a coulé, des torrents ont jailli. «Pourrait-il aussi nous donner du pain Ou préparer de la viande à son peuple?»` },
  { livre: `Psaumes`, chapitre: 78, verset: 21, texte: `Voyant cela, le Seigneur s’emporta, il alluma un feu contre Jacob, Contre Israël s’éleva sa colère,` },
  { livre: `Psaumes`, chapitre: 78, verset: 22, texte: `Car ils n’avaient pas fait confiance à Dieu, Et ils n’étaient pas sûrs de son salut.` },
  { livre: `Psaumes`, chapitre: 78, verset: 23, texte: `Il donna l’ordre aux nuages d’en haut Et il ouvrit les écluses du ciel.` },
  { livre: `Psaumes`, chapitre: 78, verset: 24, texte: `Pour les nourrir, il fit pleuvoir la manne Et il leur donna le froment des cieux.` },
  { livre: `Psaumes`, chapitre: 78, verset: 25, texte: `Chacun mangea de ce pain des puissants, Dieu leur fournit des vivres abondants.` },
  { livre: `Psaumes`, chapitre: 78, verset: 26, texte: `Il fit souffler le vent d’est dans les cieux Et fit lever un puissant vent du sud.` },
  { livre: `Psaumes`, chapitre: 78, verset: 27, texte: `Il fit pleuvoir de la viande sur eux, Elle était drue comme de la poussière. Il fit tomber une nuée d’oiseaux Aussi nombreux que le sable des mers.` },
  { livre: `Psaumes`, chapitre: 78, verset: 28, texte: `Ils sont tombés au milieu de leur camp Tout à l’entour du lieu de leur passage.` },
  { livre: `Psaumes`, chapitre: 78, verset: 29, texte: `Ils en mangèrent jusqu’à satiété. Dieu avait satisfait tous leurs désirs.` },
  { livre: `Psaumes`, chapitre: 78, verset: 30, texte: `Mais leur envie n’était pas assouvie, Ils avaient encore la viande à la bouche,` },
  { livre: `Psaumes`, chapitre: 78, verset: 31, texte: `Quand s’éleva la colère de Dieu. Il tua les plus vigoureux d’entre eux, Abattant les jeunes gens d’Israël.` },
  { livre: `Psaumes`, chapitre: 78, verset: 32, texte: `Malgré cela, ils péchèrent encore Et ils ne crurent pas en ses miracles.` },
  { livre: `Psaumes`, chapitre: 78, verset: 33, texte: `Il réduisit leurs jours à peu de chose Et, d’un seul coup, abrégea leurs années.` },
  { livre: `Psaumes`, chapitre: 78, verset: 34, texte: `Quand ils étaient frappés, ils cherchaient Dieu, Ils revenaient et se tournaient vers lui,` },
  { livre: `Psaumes`, chapitre: 78, verset: 35, texte: `Se souvenant que Dieu était leur roc, Que le Très-Haut était leur rédempteur.` },
  { livre: `Psaumes`, chapitre: 78, verset: 36, texte: `Mais s’ils priaient, c’était pour le tromper: Ils lui offraient des hommages menteurs.` },
  { livre: `Psaumes`, chapitre: 78, verset: 37, texte: `Leur cœur ne lui était pas attaché, À son alliance, ils n’étaient pas fidèles.` },
  { livre: `Psaumes`, chapitre: 78, verset: 38, texte: `Lui, cependant, rempli de compassion, Couvrait leur faute au lieu de les détruire. Bien souvent, il détourna sa colère Au lieu de déchaîner tout son courroux.` },
  { livre: `Psaumes`, chapitre: 78, verset: 39, texte: `Il se souvenait que l’homme est fragile: Un souffle qui passe et ne revient plus.` },
  { livre: `Psaumes`, chapitre: 78, verset: 40, texte: `Que de fois ils l’ont bravé au désert Et l’ont offensé dans les solitudes!` },
  { livre: `Psaumes`, chapitre: 78, verset: 41, texte: `De nouveau, ils ont mis Dieu à l’épreuve Et ont attristé le Saint d’Israël.` },
  { livre: `Psaumes`, chapitre: 78, verset: 42, texte: `Ils ont oublié l’œuvre de ses mains, Le jour qu’il les sauva de l’ennemi,` },
  { livre: `Psaumes`, chapitre: 78, verset: 43, texte: `Lorsqu’en Égypte, Dieu fit des miracles Et, au pays de Tsoan, des prodiges.` },
  { livre: `Psaumes`, chapitre: 78, verset: 44, texte: `Il fit tourner en sang les bras du Nil, Nul ne pouvait plus se désaltérer.` },
  { livre: `Psaumes`, chapitre: 78, verset: 45, texte: `Il envoya des insectes qui rongent Et des grenouilles qui les infestèrent.` },
  { livre: `Psaumes`, chapitre: 78, verset: 46, texte: `Il livra leur récolte aux sauterelles Et le fruit de leur labeur aux criquets.` },
  { livre: `Psaumes`, chapitre: 78, verset: 47, texte: `Par les grêlons, il fit périr leurs vignes Et leurs mûriers par les effets du gel.` },
  { livre: `Psaumes`, chapitre: 78, verset: 48, texte: `Il exposa leur bétail à la grêle Et leurs troupeaux périrent foudroyés.` },
  { livre: `Psaumes`, chapitre: 78, verset: 49, texte: `Il lança contre eux sa colère ardente, Son courroux, sa fureur et la détresse, Une armée de messagers de malheur.` },
  { livre: `Psaumes`, chapitre: 78, verset: 50, texte: `Il donna libre cours à sa colère, Il n’épargna pas la mort à leur âme, Il livra leur vie à l’épidémie,` },
  { livre: `Psaumes`, chapitre: 78, verset: 51, texte: `Il frappa tous les premiers-nés d’Égypte, La jeune vigueur au pays de Cham.` },
  { livre: `Psaumes`, chapitre: 78, verset: 52, texte: `Comme un troupeau, il fit sortir son peuple Et il lui fit traverser le désert.` },
  { livre: `Psaumes`, chapitre: 78, verset: 53, texte: `Il le conduisit, confiant et sans crainte, Et la mer engloutit ses ennemis.` },
  { livre: `Psaumes`, chapitre: 78, verset: 54, texte: `Il le fit pénétrer en terre sainte, À ce mont que sa droite avait conquis.` },
  { livre: `Psaumes`, chapitre: 78, verset: 55, texte: `Puis il chassa devant lui des nations, Et lui donna le pays en partage. Il installa les tribus d’Israël, Les établit sous les tentes des autres.` },
  { livre: `Psaumes`, chapitre: 78, verset: 56, texte: `Mais elles ont provoqué le Dieu très-haut Et elles se sont rebellées contre lui. Elles n’ont pas gardé ses commandements.` },
  { livre: `Psaumes`, chapitre: 78, verset: 57, texte: `Elles se sont dévoyées comme leurs pères. Elles ont été des traîtres infidèles, Elles ont dévié comme un arc mal tendu.` },
  { livre: `Psaumes`, chapitre: 78, verset: 58, texte: `Leurs hauts lieux ont excité sa colère Et leurs idoles l’ont rendu jaloux.` },
  { livre: `Psaumes`, chapitre: 78, verset: 59, texte: `Dieu l’entendit, et se mit en fureur, Il eut un grand mépris pour Israël.` },
  { livre: `Psaumes`, chapitre: 78, verset: 60, texte: `Il délaissa sa demeure à Silo, Le tabernacle établi chez les hommes.` },
  { livre: `Psaumes`, chapitre: 78, verset: 61, texte: `Il laissa partir en captivité (L’arche qui témoignait de) sa puissance. Il livra sa gloire aux mains ennemies.` },
  { livre: `Psaumes`, chapitre: 78, verset: 62, texte: `Il abandonna son peuple à l’épée Et s’emporta contre son héritage.` },
  { livre: `Psaumes`, chapitre: 78, verset: 63, texte: `Le feu dévora ses adolescents, Les vierges furent privées de louanges,` },
  { livre: `Psaumes`, chapitre: 78, verset: 64, texte: `Ses prêtres ont péri à coups d’épée, Ses veuves n’ont pas pu verser de larmes.` },
  { livre: `Psaumes`, chapitre: 78, verset: 65, texte: `Mais, comme un dormeur qui sort de ses rêves, Tout à coup, le Seigneur se réveilla Comme un guerrier exalté par le vin.` },
  { livre: `Psaumes`, chapitre: 78, verset: 66, texte: `Ses coups ont mis l’ennemi en déroute, Il les couvrit d’un opprobre éternel.` },
  { livre: `Psaumes`, chapitre: 78, verset: 67, texte: `Il dédaigna la maison de Joseph, Il répudia la tribu d’Éphraïm.` },
  { livre: `Psaumes`, chapitre: 78, verset: 68, texte: `Mais il choisit la tribu de Juda, Ce mont Sion qu’il prit en affection.` },
  { livre: `Psaumes`, chapitre: 78, verset: 69, texte: `C’est là qu’il édifia son sanctuaire Bâti pour toujours comme ciel et terre.` },
  { livre: `Psaumes`, chapitre: 78, verset: 70, texte: `Il a choisi son serviteur David Et il l’a tiré de ses bergeries.` },
  { livre: `Psaumes`, chapitre: 78, verset: 71, texte: `Il l’a cherché derrière ses brebis Pour qu’il soit berger de Jacob, son peuple Et d’Israël qui est son héritage.` },
  { livre: `Psaumes`, chapitre: 78, verset: 72, texte: `Il fut pour eux un berger au cœur droit Et il les conduisit avec sagesse.` },
  { livre: `Psaumes`, chapitre: 79, verset: 1, texte: `Psaume d’Asaph. Ô Dieu! des païens sont venus, ils ont envahi ton domaine, Ils ont souillé ton temple saint et ils ont pris Jérusalem, Ils en ont fait un tas de ruines.` },
  { livre: `Psaumes`, chapitre: 79, verset: 2, texte: `Ils ont tué tes serviteurs Et jeté leurs corps en pâture aux oiseaux rapaces des cieux. La chair de tes adorateurs est donnée aux bêtes sauvages.` },
  { livre: `Psaumes`, chapitre: 79, verset: 3, texte: `Ils ont versé des flots de sang tout autour de Jérusalem. Ils ont laissé les morts dehors sans leur donner de sépulture.` },
  { livre: `Psaumes`, chapitre: 79, verset: 4, texte: `Nous sommes devenus la honte et la risée de nos voisins, Nous sommes sans cesse exposés aux moqueries de l’entourage.` },
  { livre: `Psaumes`, chapitre: 79, verset: 5, texte: `Jusques à quand, ô Éternel, seras-tu sans cesse irrité? Et ton ardente indignation brûlera-t-elle comme un feu?` },
  { livre: `Psaumes`, chapitre: 79, verset: 6, texte: `Répands ta fureur sur les peuples, ceux qui ne te connaissent pas, De même que sur les royaumes qui n’invoquent jamais ton nom!` },
  { livre: `Psaumes`, chapitre: 79, verset: 7, texte: `Car ils ont dévoré Jacob, ils ont dévasté sa demeure.` },
  { livre: `Psaumes`, chapitre: 79, verset: 8, texte: `Ne te souviens plus, contre nous, Des transgressions de nos ancêtres! Hâte-toi! Que tes compassions viennent vite au-devant de nous! Car nous sommes bien malheureux.` },
  { livre: `Psaumes`, chapitre: 79, verset: 9, texte: `Aide-nous, Dieu, notre Sauveur, pour l’honneur de ton nom! Délivre-nous, pardonne-nous pour l’amour de ton nom!` },
  { livre: `Psaumes`, chapitre: 79, verset: 10, texte: `Pourquoi ces nations diraient-elles: «Où est leur Dieu?» Montre à ces païens, sous nos yeux, Que tu es le vengeur du meurtre de tes serviteurs!` },
  { livre: `Psaumes`, chapitre: 79, verset: 11, texte: `Puissent les soupirs des captifs parvenir jusqu’à toi! Et sauve par ton bras puissant les condamnés à mort.` },
  { livre: `Psaumes`, chapitre: 79, verset: 12, texte: `Fais retomber sur nos voisins, au septuple, en leur sein, Le mépris qu’ils ont témoigné à toi, notre Seigneur!` },
  { livre: `Psaumes`, chapitre: 79, verset: 13, texte: `Et nous, ton peuple, ton troupeau dont tu es le berger, Nous te célébrerons toujours, au cours de tous les âges, Et nous publierons tes louanges.` },
  { livre: `Psaumes`, chapitre: 80, verset: 0, texte: `Au chef de chœur. Témoignage d’Asaph. Psaume.` },
  { livre: `Psaumes`, chapitre: 80, verset: 1, texte: `Ô Berger d’Israël, prête l’oreille, Toi qui mènes Joseph comme un troupeau. Ô toi qui es assis entre les chérubins, Parais dans ta splendeur` },
  { livre: `Psaumes`, chapitre: 80, verset: 2, texte: `Aux regards d’Éphraïm, de Benjamin, de Manassé! Relève ta puissance, viens nous sauver!` },
  { livre: `Psaumes`, chapitre: 80, verset: 3, texte: `Ô Dieu, rétablis-nous, Fais resplendir ta face et nous serons sauvés!` },
  { livre: `Psaumes`, chapitre: 80, verset: 4, texte: `Seigneur, Dieu des armées, Jusques à quand seras-tu en colère Contre ton peuple t’adressant ses prières?` },
  { livre: `Psaumes`, chapitre: 80, verset: 5, texte: `Tu le nourris d’un pain trempé de pleurs. Tu lui fais boire des larmes sans mesure.` },
  { livre: `Psaumes`, chapitre: 80, verset: 6, texte: `Tu fais de nous un objet de querelle pour nos voisins! Nos ennemis ont lieu de se moquer.` },
  { livre: `Psaumes`, chapitre: 80, verset: 7, texte: `Dieu des armées, rends-nous la vie, Fais resplendir ta face, et nous serons sauvés!` },
  { livre: `Psaumes`, chapitre: 80, verset: 8, texte: `Tu arrachas de l’Égypte une vigne, Tu chassas des nations et tu la transplantas.` },
  { livre: `Psaumes`, chapitre: 80, verset: 9, texte: `Tu déblayas le terrain devant elle. Elle a jeté des racines profondes et couvert le pays.` },
  { livre: `Psaumes`, chapitre: 80, verset: 10, texte: `Voici, son ombre a couvert les montagnes, Et ses sarments étaient semblables à des cèdres de Dieu.` },
  { livre: `Psaumes`, chapitre: 80, verset: 11, texte: `Elle étendait ses vrilles vers la mer, Et ses rejets jusqu’au fleuve d’Euphrate.` },
  { livre: `Psaumes`, chapitre: 80, verset: 12, texte: `Pourquoi as-tu renversé ses clôtures? Tous les passants viennent y grappiller.` },
  { livre: `Psaumes`, chapitre: 80, verset: 13, texte: `Le sanglier qui sort de la forêt la retourne en tous sens, Les animaux des champs viennent y pâturer.` },
  { livre: `Psaumes`, chapitre: 80, verset: 14, texte: `Dieu des armées, reviens enfin! Jette un regard du haut du ciel et vois! Visite cette vigne!` },
  { livre: `Psaumes`, chapitre: 80, verset: 15, texte: `Protège le jardin que ta droite a planté, Le rejeton que tu as fortifié!` },
  { livre: `Psaumes`, chapitre: 80, verset: 16, texte: `Tout est brûlé et saccagé comme des balayures. Sous ta colère, tout va périr.` },
  { livre: `Psaumes`, chapitre: 80, verset: 17, texte: `Étends ta protection sur l’homme élu que ta droite a choisi, Le fils de l’homme que tu as affermi pour ton service!` },
  { livre: `Psaumes`, chapitre: 80, verset: 18, texte: `Et, jamais plus, nous n’irons loin de toi. Fais-nous revivre et invoquer ton nom!` },
  { livre: `Psaumes`, chapitre: 80, verset: 19, texte: `Seigneur, Dieu des armées, rends-nous la vie, Fais resplendir ta face, et nous serons sauvés!` },
  { livre: `Psaumes`, chapitre: 81, verset: 0, texte: `Au chef de chœur. Sur la guiterne. Psaume d’Asaph.` },
  { livre: `Psaumes`, chapitre: 81, verset: 1, texte: `Chantez avec allégresse à Dieu notre force! Acclamez joyeusement le Dieu de Jacob!` },
  { livre: `Psaumes`, chapitre: 81, verset: 2, texte: `Ouvrez le concert, Entonnez un chant, frappez sur le tambourin, Pincez la lyre harmonieuse, jouez de la harpe!` },
  { livre: `Psaumes`, chapitre: 81, verset: 3, texte: `Embouchez le cor au début du mois, À la pleine lune, le grand jour de fête!` },
  { livre: `Psaumes`, chapitre: 81, verset: 4, texte: `Car telle est la règle, la loi d’Israël, C’est une ordonnance du Dieu de Jacob.` },
  { livre: `Psaumes`, chapitre: 81, verset: 5, texte: `C’est un témoignage Qu’il établit pour Joseph quand il sortit de l’Égypte. J’entends un langage que je ne connaissais pas:` },
  { livre: `Psaumes`, chapitre: 81, verset: 6, texte: `«J’ai déchargé ses épaules, j’ai retiré son fardeau, Et ses mains sont affranchies du poids des corbeilles.` },
  { livre: `Psaumes`, chapitre: 81, verset: 7, texte: `Au sein de l’angoisse, tu m’as appelé, Et je suis venu pour te délivrer, Je t’ai répondu du sein de l’orage, Je t’ai éprouvé près des eaux de Mériba.` },
  { livre: `Psaumes`, chapitre: 81, verset: 8, texte: `Écoute, ô mon peuple, et je t’instruirai. Si tu voulais m’écouter, ô mon peuple d’Israël!` },
  { livre: `Psaumes`, chapitre: 81, verset: 9, texte: `Tu n’auras chez toi aucun autre dieu, Tu n’adoreras aucun des dieux étrangers!` },
  { livre: `Psaumes`, chapitre: 81, verset: 10, texte: `Je suis l’Éternel, le Seigneur ton Dieu, qui t’ai fait sortir d’Égypte. Ouvre largement ta bouche, je la remplirai.»` },
  { livre: `Psaumes`, chapitre: 81, verset: 11, texte: `«Mais mon peuple d’Israël n’a pas écouté ma voix, Il n’a pas voulu de moi.` },
  { livre: `Psaumes`, chapitre: 81, verset: 12, texte: `Je l’ai abandonnés à son cœur si endurci, Il n’a fait que suivre ses propres conseils.` },
  { livre: `Psaumes`, chapitre: 81, verset: 13, texte: `Si mon peuple m’écoutait, Et si Israël marchait dans mes voies,` },
  { livre: `Psaumes`, chapitre: 81, verset: 14, texte: `J’aurais bien vite humilié tous ses adversaires, Et ma main se tournerait contre ceux qui l’oppriment.` },
  { livre: `Psaumes`, chapitre: 81, verset: 15, texte: `Les ennemis du Seigneur lui rendraient hommage Et le temps de son bonheur durerait toujours.` },
  { livre: `Psaumes`, chapitre: 81, verset: 16, texte: `Je le nourrirais de fleur de froment, Je le rassasierais de miel du rocher».` },
  { livre: `Psaumes`, chapitre: 82, verset: 1, texte: `Psaume d’Asaph. Dieu se tient debout dans la Cour divine, la Cour de justice. Entouré des juges aux pouvoirs divins, il rend son arrêt:` },
  { livre: `Psaumes`, chapitre: 82, verset: 2, texte: `«Jusqu’à quand jugerez-vous faussement En favorisant la partie coupable?` },
  { livre: `Psaumes`, chapitre: 82, verset: 3, texte: `Faites droit au faible et à l’orphelin, Acquittez le pauvre et le malheureux,` },
  { livre: `Psaumes`, chapitre: 82, verset: 4, texte: `Venez en aide aux petits, délivrez les opprimés Et, de la main des méchants, venez donc les arracher!` },
  { livre: `Psaumes`, chapitre: 82, verset: 5, texte: `Mais ils sont sans connaissance Et ils ne comprennent rien; ils marchent dans les ténèbres. Tous les fondements du pays sont ébranlés.` },
  { livre: `Psaumes`, chapitre: 82, verset: 6, texte: `«J’avais dit: “Vous êtes dieux, Oui, vous tous vous êtes des fils du Très-Haut!”` },
  { livre: `Psaumes`, chapitre: 82, verset: 7, texte: `Cependant vous périrez comme tous les hommes, Et vous tomberez tous ensemble, ô princes!»` },
  { livre: `Psaumes`, chapitre: 82, verset: 8, texte: `Ô Dieu, lève-toi pour juger la terre, Car tu as pour héritage toutes les nations!` },
  { livre: `Psaumes`, chapitre: 83, verset: 0, texte: `Psaume d’Asaph (à chanter).` },
  { livre: `Psaumes`, chapitre: 83, verset: 1, texte: `Ô Dieu, ne reste pas dans le silence et ne demeure pas muet! Cesse, ô Dieu, d’être indifférent!` },
  { livre: `Psaumes`, chapitre: 83, verset: 2, texte: `Voici, tes ennemis s’agitent, Et ceux qui te haïssent portent la tête haute,` },
  { livre: `Psaumes`, chapitre: 83, verset: 3, texte: `Ils sont ligués contre ton peuple, Ils trament des complots perfides, ils intriguent contre les tiens.` },
  { livre: `Psaumes`, chapitre: 83, verset: 4, texte: `Ils ont dit: «Exterminons-les, rayons-les d’entre les nations Afin que le nom d’Israël ne soit plus jamais évoqué!»` },
  { livre: `Psaumes`, chapitre: 83, verset: 5, texte: `D’un seul cœur, ils ont conspiré, se coalisant contre toi:` },
  { livre: `Psaumes`, chapitre: 83, verset: 6, texte: `Enfants d’Édom, Ismaélites, enfants d’Hagar et Moabites,` },
  { livre: `Psaumes`, chapitre: 83, verset: 7, texte: `Guébal, Ammon et Amalek, les Philistins et les Tyriens,` },
  { livre: `Psaumes`, chapitre: 83, verset: 8, texte: `L’Assyrie même est leur alliée, prêtant main-forte aux fils de Lot.` },
  { livre: `Psaumes`, chapitre: 83, verset: 9, texte: `Traite-les donc comme à Madian, Comme à Sisera ou Jabbin auprès du torrent de Kison.` },
  { livre: `Psaumes`, chapitre: 83, verset: 10, texte: `Ils furent détruits à En-Dor, comme du fumier sur le sol.` },
  { livre: `Psaumes`, chapitre: 83, verset: 11, texte: `Que tous leurs nobles soient pareils à Oreb et à Zeeb, Et que leurs princes soient comme Zébach et Tsalmunna!` },
  { livre: `Psaumes`, chapitre: 83, verset: 12, texte: `Ils s’étaient dit: «Emparons-nous des demeures où Dieu habite!»` },
  { livre: `Psaumes`, chapitre: 83, verset: 13, texte: `Mon Dieu, fais-les tourbillonner comme une paille dans le vent,` },
  { livre: `Psaumes`, chapitre: 83, verset: 14, texte: `Comme un feu brûlant la forêt, et la flamme embrasant les monts!` },
  { livre: `Psaumes`, chapitre: 83, verset: 15, texte: `Pourchasse-les par ta tempête! Qu’ils aient peur de ton ouragan!` },
  { livre: `Psaumes`, chapitre: 83, verset: 16, texte: `Couvre leur visage de honte, qu’ils cherchent ton nom, Seigneur!` },
  { livre: `Psaumes`, chapitre: 83, verset: 17, texte: `Qu’ils soient confondus à jamais, qu’ils périssent déshonorés!` },
  { livre: `Psaumes`, chapitre: 83, verset: 18, texte: `Qu’ils reconnaissent que toi seul tu portes le nom de Seigneur, Que tu es le Dieu souverain, le maître de toute la terre!` },
  { livre: `Psaumes`, chapitre: 84, verset: 0, texte: `Au chef de chœur. Un psaume des fils de Koré.` },
  { livre: `Psaumes`, chapitre: 84, verset: 1, texte: `Combien j’aime tes demeures, ô Éternel des armées!` },
  { livre: `Psaumes`, chapitre: 84, verset: 2, texte: `Je languis et je soupire après tes parvis, Seigneur! Mon cœur et mon corps tressaillent Et poussent des cris vers le Dieu vivant.` },
  { livre: `Psaumes`, chapitre: 84, verset: 3, texte: `Le moineau découvre un gîte, L’hirondelle trouve un nid où déposer ses petits. (Pour moi,) ce sont tes autels, ô Éternel des armées, Mon roi et mon Dieu!` },
  { livre: `Psaumes`, chapitre: 84, verset: 4, texte: `Bienheureux ceux qui habitent ta maison, (Seigneur)! Ils peuvent encore chanter tes louanges.` },
  { livre: `Psaumes`, chapitre: 84, verset: 5, texte: `Bienheureux les hommes dont tu es la force, Dans leur cœur, ils trouvent des chemins frayés.` },
  { livre: `Psaumes`, chapitre: 84, verset: 6, texte: `Car lorsqu’ils traversent la vallée des pleurs, Ils en font une oasis, et la pluie d’automne Vient la recouvrir de bénédictions.` },
  { livre: `Psaumes`, chapitre: 84, verset: 7, texte: `D’étape en étape, ils ont plus de force Pour se présenter à Dieu en Sion,` },
  { livre: `Psaumes`, chapitre: 84, verset: 8, texte: `Éternel, Dieu des armées, entends ma prière Et prête l’oreille, ô Dieu de Jacob!` },
  { livre: `Psaumes`, chapitre: 84, verset: 9, texte: `Ô toi, notre bouclier, vois ô Dieu! Regarde le visage de ton Oint!` },
  { livre: `Psaumes`, chapitre: 84, verset: 10, texte: `Car un jour dans tes parvis vaut bien mieux que mille ailleurs. Je préfère me tenir sur le seuil de ta maison, maison de mon Dieu, Plutôt que de demeurer dans le palais des méchants.` },
  { livre: `Psaumes`, chapitre: 84, verset: 11, texte: `Car le Seigneur Dieu est notre soleil et un bouclier. Il donne la grâce, il donne la gloire, Il ne refuse aucun bien à ceux qui cheminent dans l’intégrité.` },
  { livre: `Psaumes`, chapitre: 84, verset: 12, texte: `Éternel, Dieu des armées, Bienheureux est l’homme qui compte sur toi.` },
  { livre: `Psaumes`, chapitre: 85, verset: 0, texte: `Au chef de chœur. Un psaume des fils de Koré.` },
  { livre: `Psaumes`, chapitre: 85, verset: 1, texte: `Ô Seigneur, tu as montré ta faveur à ton pays. Tu as ramené les déportés de Jacob.` },
  { livre: `Psaumes`, chapitre: 85, verset: 2, texte: `Tu as pardonné les torts de ton peuple Et tu as couvert son péché d’un voile.` },
  { livre: `Psaumes`, chapitre: 85, verset: 3, texte: `Tu as retiré toute ta colère, tu as réfréné ton indignation.` },
  { livre: `Psaumes`, chapitre: 85, verset: 4, texte: `Fais-nous revenir, Dieu, notre Sauveur! Mets, de grâce, un terme à ta colère envers nous!` },
  { livre: `Psaumes`, chapitre: 85, verset: 5, texte: `Veux-tu, éternellement, être irrité contre nous? Maintiendras-tu d’âge en âge ton ressentiment?` },
  { livre: `Psaumes`, chapitre: 85, verset: 6, texte: `Ne voudrais-tu pas nous rendre à la vie Afin que ton peuple se réjouisse en toi?` },
  { livre: `Psaumes`, chapitre: 85, verset: 7, texte: `Fais-nous contempler ton amour, Seigneur! Accorde-nous ton salut!` },
  { livre: `Psaumes`, chapitre: 85, verset: 8, texte: `Je veux écouter ce que dit le Seigneur Dieu: C’est de paix qu’il parle à son peuple, à ceux qui l’aiment. Mais qu’ils abandonnent leurs égarements!` },
  { livre: `Psaumes`, chapitre: 85, verset: 9, texte: `Oui, certainement, son salut est près de ceux qui l’honorent, Sa gloire rayonnera bientôt sur notre pays.` },
  { livre: `Psaumes`, chapitre: 85, verset: 10, texte: `L’Amour et la Vérité vont se rencontrer, Et la Justice et la Paix s’y embrasseront.` },
  { livre: `Psaumes`, chapitre: 85, verset: 11, texte: `La Vérité germera du sein de la terre, La Justice veillera des hauteurs célestes.` },
  { livre: `Psaumes`, chapitre: 85, verset: 12, texte: `Le Seigneur lui-même nous enverra le bonheur, Et notre pays produira ses fruits.` },
  { livre: `Psaumes`, chapitre: 85, verset: 13, texte: `La Justice le précède et prépare son chemin.` },
  { livre: `Psaumes`, chapitre: 86, verset: 1, texte: `Prière de David. Incline ton oreille, Éternel, réponds-moi, Car je suis humilié, et je me sens bien pauvre.` },
  { livre: `Psaumes`, chapitre: 86, verset: 2, texte: `Conserve-moi la vie, car je suis ton ami. Sauve ton serviteur qui se confie en toi.` },
  { livre: `Psaumes`, chapitre: 86, verset: 3, texte: `Pitié pour moi, Seigneur! Je crie vers toi sans cesse:` },
  { livre: `Psaumes`, chapitre: 86, verset: 4, texte: `Rends la vie et la joie à celui qui te sert, Car c’est vers toi, Seigneur, que s’élève mon âme.` },
  { livre: `Psaumes`, chapitre: 86, verset: 5, texte: `Car tu es bon, Seigneur, et prompt à pardonner, Tu es riche d’amour pour tous ceux qui t’appellent.` },
  { livre: `Psaumes`, chapitre: 86, verset: 6, texte: `Exauce ma prière, Seigneur, écoute-moi! Entends ma voix plaintive, mes accents suppliants!` },
  { livre: `Psaumes`, chapitre: 86, verset: 7, texte: `Au jour de ma détresse, c’est vers toi que je crie, Car tu sais me répondre, tu m’exauces, ô mon Maître.` },
  { livre: `Psaumes`, chapitre: 86, verset: 8, texte: `Parmi les dieux, Seigneur, nul n’est semblable à toi! Il n’est rien qui approche les œuvres de tes mains.` },
  { livre: `Psaumes`, chapitre: 86, verset: 9, texte: `Tous les peuples païens viendront se prosterner Devant toi, ô Seigneur, pour honorer ton nom.` },
  { livre: `Psaumes`, chapitre: 86, verset: 10, texte: `Car tu es grand, Seigneur, et tu fais des merveilles! Tu es le seul vrai Dieu!` },
  { livre: `Psaumes`, chapitre: 86, verset: 11, texte: `Enseigne-moi, Seigneur, à marcher dans tes voies Et je me conduirai selon ta vérité. Communique à mon cœur le respect de ton nom!` },
  { livre: `Psaumes`, chapitre: 86, verset: 12, texte: `Je veux te célébrer, ô toi, Seigneur mon Dieu, De tout cœur et toujours honorer ton (saint) nom.` },
  { livre: `Psaumes`, chapitre: 86, verset: 13, texte: `Car ton amour est grand, (Seigneur,) en ma faveur Et tu as délivré mon âme de l’abîme.` },
  { livre: `Psaumes`, chapitre: 86, verset: 14, texte: `Ô Dieu, des orgueilleux s’élèvent contre moi, Des hommes violents veulent m’ôter la vie. Ils ne pensent jamais que tu les vois, Seigneur!` },
  { livre: `Psaumes`, chapitre: 86, verset: 15, texte: `Mais toi, ô mon Seigneur, tu es un Dieu clément, Plein de miséricorde et lent à la colère. Oui, tu es riche en grâce et en fidélité.` },
  { livre: `Psaumes`, chapitre: 86, verset: 16, texte: `Tourne vers moi, (Seigneur,) tes regards, fais-moi grâce. Accorde ton appui à celui qui te sert Et envoie ton salut au fils de ta servante.` },
  { livre: `Psaumes`, chapitre: 86, verset: 17, texte: `Accorde-moi un signe de ta faveur, (Seigneur,) Pour que mes ennemis le voient et soient confus! Ils sauront que c’est toi, Seigneur, qui es mon aide Et mon consolateur.` },
  { livre: `Psaumes`, chapitre: 87, verset: 1, texte: `Psaume des fils de Koré. Cantique. Le Seigneur a fondé Sion Sur les montagnes saintes,` },
  { livre: `Psaumes`, chapitre: 87, verset: 2, texte: `Le Seigneur en aime les portes` },
  { livre: `Psaumes`, chapitre: 87, verset: 3, texte: `Plus que les villes de Jacob. On publie ce qui fait ta gloire, Toi qui es la cité de Dieu.` },
  { livre: `Psaumes`, chapitre: 87, verset: 4, texte: `Je ferai mention de l’Égypte Aussi bien que de Babylone Parmi tous ceux qui me connaissent. Philistie, Tyr et Éthiopie Disent aussi: «Je suis né là».` },
  { livre: `Psaumes`, chapitre: 87, verset: 5, texte: `Mais, de Sion, on dit: «Ma mère», Car chaque homme est chez soi en elle, Et le Tout-Puissant l’affermit.` },
  { livre: `Psaumes`, chapitre: 87, verset: 6, texte: `Le Seigneur en comptant les hommes Mentionnera pour l’un ou l’autre: C’est aussi un fils de Sion.` },
  { livre: `Psaumes`, chapitre: 87, verset: 7, texte: `Et chanteurs et danseurs diront: «Toutes mes sources sont en toi».` },
  { livre: `Psaumes`, chapitre: 88, verset: 0, texte: `Un psaume des fils de Koré. Au chef de chœur. Cantique à chanter avec accompagnement de flûtes. Un poème didactique d’Héman l’Ezrachite.` },
  { livre: `Psaumes`, chapitre: 88, verset: 1, texte: `Seigneur, mon Dieu, toi qui me sauves, Je crie à toi pendant le jour, pendant la nuit, en ta présence.` },
  { livre: `Psaumes`, chapitre: 88, verset: 2, texte: `Que ma prière monte vers toi, devant ta face! Prête l’oreille à mes sanglots!` },
  { livre: `Psaumes`, chapitre: 88, verset: 3, texte: `Car je suis rassasié de maux et de malheurs, Et ma vie est au bord de l’abîme des morts.` },
  { livre: `Psaumes`, chapitre: 88, verset: 4, texte: `Déjà je suis compté parmi ceux Qui s’en vont sombrer dans le tombeau. Je ressemble à un homme qui a perdu ses forces.` },
  { livre: `Psaumes`, chapitre: 88, verset: 5, texte: `C’est au milieu des morts que se trouve ma couche, Comme ceux qui, déjà, sont couchés dans la tombe, Que tu as oubliés et qui sont retranchés de ta sollicitude.` },
  { livre: `Psaumes`, chapitre: 88, verset: 6, texte: `Tu m’as abandonné dans un gouffre sans fond Et tu m’as relégué dans les lieux ténébreux.` },
  { livre: `Psaumes`, chapitre: 88, verset: 7, texte: `Ta fureur me tenaille, les flots de ta colère ont déferlé sur moi.` },
  { livre: `Psaumes`, chapitre: 88, verset: 8, texte: `Tu as chassé de moi mes amis, mes intimes. Tu m’as rendu, pour eux, comme un objet d’horreur. Je suis emprisonné sans pouvoir m’évader.` },
  { livre: `Psaumes`, chapitre: 88, verset: 9, texte: `Mes yeux sont épuisés à force de souffrir. Je t’appelle, Seigneur, tous les jours (de ma vie), J’étends les mains vers toi.` },
  { livre: `Psaumes`, chapitre: 88, verset: 10, texte: `Feras-tu des miracles pour ceux qui ne sont plus? Verra-t-on se lever les morts pour te louer?` },
  { livre: `Psaumes`, chapitre: 88, verset: 11, texte: `Parle-t-on dans la tombe de ta fidélité? Ou de ton grand amour dans le séjour des morts?` },
  { livre: `Psaumes`, chapitre: 88, verset: 12, texte: `Est-ce que l’on publie Tes œuvres merveilleuses au pays des ténèbres? Connaît-on ta justice en la terre d’oubli?` },
  { livre: `Psaumes`, chapitre: 88, verset: 13, texte: `Pour moi, Seigneur, je crie à toi! Dès le matin, ma prière te cherche.` },
  { livre: `Psaumes`, chapitre: 88, verset: 14, texte: `Pourquoi, Seigneur, délaisses-tu mon âme? Pourquoi dérobes-tu ta face loin de moi?` },
  { livre: `Psaumes`, chapitre: 88, verset: 15, texte: `Car je suis pauvre et malheureux Depuis l’enfance, j’ai enduré tes coups terribles. J’en suis glacé, je suis à bout.` },
  { livre: `Psaumes`, chapitre: 88, verset: 16, texte: `Les flots de ton courroux ont déferlé sur moi, L’effroi que tu m’inspires m’a réduit au silence.` },
  { livre: `Psaumes`, chapitre: 88, verset: 17, texte: `Chaque jour ils m’entourent, comme des flots, Ils me menacent de tous côtés.` },
  { livre: `Psaumes`, chapitre: 88, verset: 18, texte: `Mes familiers et mes amis, tu les as éloignés de moi! Je n’ai pour compagnie que les ténèbres.` },
  { livre: `Psaumes`, chapitre: 89, verset: 0, texte: `Méditation poétique d’Ethan l’Ezrachite.` },
  { livre: `Psaumes`, chapitre: 89, verset: 1, texte: `Je veux chanter à jamais l’amour du Seigneur Et proclamer d’âge en âge sa fidélité.` },
  { livre: `Psaumes`, chapitre: 89, verset: 2, texte: `En effet, je peux le dire, car tu l’as promis: L’amour est inébranlable pour l’éternité. Dans les cieux est établie ta fidélité.` },
  { livre: `Psaumes`, chapitre: 89, verset: 3, texte: `«J’ai contracté une alliance avec mon élu; À David, mon serviteur, j’ai fait un serment:` },
  { livre: `Psaumes`, chapitre: 89, verset: 4, texte: `J’affermis ta dynastie pour l’éternité Et j’établirai ton trône aux siècles des siècles.»` },
  { livre: `Psaumes`, chapitre: 89, verset: 5, texte: `Les cieux chantent tes merveilles, ô Seigneur (mon Dieu)! L’assemblée des saints célèbre ta fidélité.` },
  { livre: `Psaumes`, chapitre: 89, verset: 6, texte: `Qui est égal au Seigneur là-haut dans le ciel? Qui donc est semblable à lui, qui, parmi les dieux?` },
  { livre: `Psaumes`, chapitre: 89, verset: 7, texte: `C’est un Dieu de majesté au conseil des saints. Il est grand et redoutable pour son entourage.` },
  { livre: `Psaumes`, chapitre: 89, verset: 8, texte: `Seigneur, Dieu de l’univers, qui est comme toi? Que tu es puissant, Seigneur! Que tu es puissant! Ta fidélité rayonne tout autour de toi.` },
  { livre: `Psaumes`, chapitre: 89, verset: 9, texte: `C’est toi, (Seigneur,) qui domines l’orgueil de la mer. Quand ses vagues se déchaînent, toi, tu les apaises.` },
  { livre: `Psaumes`, chapitre: 89, verset: 10, texte: `C’est toi qui as écrasé l’orgueilleuse Égypte Après l’avoir transpercée par ton bras puissant. C’est toi qui as dispersé tous tes ennemis.` },
  { livre: `Psaumes`, chapitre: 89, verset: 11, texte: `À toi appartient le ciel et à toi la terre, Le monde et son contenu, tu les as fondés;` },
  { livre: `Psaumes`, chapitre: 89, verset: 12, texte: `Et le Nord et le Midi, tu les as créés. Le mont Thabor et l’Hermon célèbrent ton nom.` },
  { livre: `Psaumes`, chapitre: 89, verset: 13, texte: `Ton bras est armé de force, ta main est puissante, Et ta droite est élevée, c’est toi qui commandes.` },
  { livre: `Psaumes`, chapitre: 89, verset: 14, texte: `Les assises de ton trône sont Justice et Droit. L’Amour et la Vérité marchent devant toi.` },
  { livre: `Psaumes`, chapitre: 89, verset: 15, texte: `Oh! qu’il est heureux, le peuple qui sait t’exalter. À la clarté de ta face, il marche, Seigneur.` },
  { livre: `Psaumes`, chapitre: 89, verset: 16, texte: `Il se réjouira sans cesse en ton nom, Seigneur! Et, de ton juste pouvoir, il se glorifie!` },
  { livre: `Psaumes`, chapitre: 89, verset: 17, texte: `Tu es la magnificence, l’éclat de sa force, Et c’est par ta bienveillance que nous triomphons.` },
  { livre: `Psaumes`, chapitre: 89, verset: 18, texte: `Entre les mains du Seigneur est notre défense, Et notre roi appartient au Saint d’Israël.` },
  { livre: `Psaumes`, chapitre: 89, verset: 19, texte: `Autrefois, tu as parlé au cours de visions, Tu as dit à tes fidèles: «J’ai prêté secours À un homme valeureux, un héros puissant, J’ai exalté un jeune homme du milieu du peuple.` },
  { livre: `Psaumes`, chapitre: 89, verset: 20, texte: `J’ai découvert en David un (bon) serviteur; C’est lui que j’ai consacré de mon huile sainte.` },
  { livre: `Psaumes`, chapitre: 89, verset: 21, texte: `Ma main le tient fermement, elle est son soutien, Et mon bras l’affermira, il sera sa force.` },
  { livre: `Psaumes`, chapitre: 89, verset: 22, texte: `L’ennemi ne pourra pas triompher de lui, Ni le méchant l’humilier ou le maltraiter.` },
  { livre: `Psaumes`, chapitre: 89, verset: 23, texte: `J’écraserai devant lui tous ses ennemis. Je frapperai d’une plaie ceux qui le haïssent.` },
  { livre: `Psaumes`, chapitre: 89, verset: 24, texte: `Ma grâce et ma vérité seront avec lui, Il relèvera le front par la force de mon nom.` },
  { livre: `Psaumes`, chapitre: 89, verset: 25, texte: `J’étendrai jusqu’à la mer sa domination. J’établirai son empire jusque sur les fleuves.` },
  { livre: `Psaumes`, chapitre: 89, verset: 26, texte: `En m’invoquant, il dira: “Mon Père, c’est toi: Tu es le roc qui me sauve, et tu es mon Dieu!”` },
  { livre: `Psaumes`, chapitre: 89, verset: 27, texte: `Et moi, je ferai de lui mon fils premier-né, Le plus élevé des rois, des rois de la terre.` },
  { livre: `Psaumes`, chapitre: 89, verset: 28, texte: `Je lui garderai toujours mon amour, ma grâce, Et mon alliance fidèle lui est assurée.` },
  { livre: `Psaumes`, chapitre: 89, verset: 29, texte: `Je ferai durer toujours sa postérité, Et son trône aussi longtemps que durent les cieux.` },
  { livre: `Psaumes`, chapitre: 89, verset: 30, texte: `Toutefois si ses enfants délaissent ma loi, S’ils ne se conduisent plus selon mes décrets,` },
  { livre: `Psaumes`, chapitre: 89, verset: 31, texte: `S’ils venaient à profaner mes commandements, Et s’ils n’obéissaient plus à ma volonté,` },
  { livre: `Psaumes`, chapitre: 89, verset: 32, texte: `Je châtierais leur péché avec le bâton, Je sévirais par des coups contre leur révolte.` },
  { livre: `Psaumes`, chapitre: 89, verset: 33, texte: `Mais je ne renierai pas mon amour pour lui. Je ne démentirai pas ma fidélité,` },
  { livre: `Psaumes`, chapitre: 89, verset: 34, texte: `Car je ne profanerai jamais mon alliance Et je ne changerai rien à ce que j’ai dit.` },
  { livre: `Psaumes`, chapitre: 89, verset: 35, texte: `Un jour j’ai fait le serment sur ma sainteté: Non, je ne pourrai jamais mentir à David,` },
  { livre: `Psaumes`, chapitre: 89, verset: 36, texte: `Sa lignée subsistera éternellement, Et son trône durera comme le soleil.` },
  { livre: `Psaumes`, chapitre: 89, verset: 37, texte: `Comme la lune, à toujours, il se maintiendra. Là-haut, le témoin céleste restera fidèle».` },
  { livre: `Psaumes`, chapitre: 89, verset: 38, texte: `Pourtant, tu as délaissé, tu as rejeté, Dans ta colère, celui qui t’est consacré.` },
  { livre: `Psaumes`, chapitre: 89, verset: 39, texte: `Tu as dédaigné l’alliance de ton serviteur, Tu as traîné sa couronne jusque dans la terre.` },
  { livre: `Psaumes`, chapitre: 89, verset: 40, texte: `Tu as fait de larges brèches dans tous ses remparts; Et ses fortifications, tu les as détruites.` },
  { livre: `Psaumes`, chapitre: 89, verset: 41, texte: `Tous les passants de la route l’ont mis au pillage, Il est un objet d’opprobre pour (tous) ses voisins.` },
  { livre: `Psaumes`, chapitre: 89, verset: 42, texte: `Tu as soutenu la force de ses oppresseurs Et tu as rempli de joie tous ses ennemis.` },
  { livre: `Psaumes`, chapitre: 89, verset: 43, texte: `Tu as même fait dévier les coups de son glaive Et tu ne le soutiens pas pendant le combat.` },
  { livre: `Psaumes`, chapitre: 89, verset: 44, texte: `Tu as terni sa splendeur, jeté bas son trône.` },
  { livre: `Psaumes`, chapitre: 89, verset: 45, texte: `Tu as abrégé ses jours en pleine jeunesse, Et tu l’as couvert de honte et de confusion.` },
  { livre: `Psaumes`, chapitre: 89, verset: 46, texte: `Jusques à quand, Éternel, te cacheras-tu Et laisseras-tu flamber ton indignation?` },
  { livre: `Psaumes`, chapitre: 89, verset: 47, texte: `Qu’est la durée de ma vie? Seigneur, souviens-toi Combien elle est éphémère, et pour quel néant Tu as créé tous les hommes, tous les fils d’Adam.` },
  { livre: `Psaumes`, chapitre: 89, verset: 48, texte: `Quel est l’homme qui vivra sans voir le trépas? Qui peut arracher son âme au séjour des morts?` },
  { livre: `Psaumes`, chapitre: 89, verset: 49, texte: `Seigneur, où donc est resté ton premier amour Que, dans ta fidélité, tu avais juré à David (ton serviteur)?` },
  { livre: `Psaumes`, chapitre: 89, verset: 50, texte: `Pense à l’opprobre, Seigneur, de tes serviteurs, Pense à ces peuples nombreux que j’ai sur le cœur,` },
  { livre: `Psaumes`, chapitre: 89, verset: 51, texte: `(Pense) aux outrages, Seigneur, de tes ennemis Qui insultent sans pudeur les pas de ton Oint.` },
  { livre: `Psaumes`, chapitre: 89, verset: 52, texte: `Béni soit le Seigneur Dieu Pour l’éternité, Amen et amen.` },
  { livre: `Psaumes`, chapitre: 90, verset: 1, texte: `Prière de Moïse, l’homme de Dieu. Seigneur, tu fus pour nous, d’âge en âge, un refuge.` },
  { livre: `Psaumes`, chapitre: 90, verset: 2, texte: `Avant que les montagnes n’aient été enfantées, Et que tu n’aies créé la terre et l’univers, De toute éternité et pour l’éternité, toi, tu es Dieu.` },
  { livre: `Psaumes`, chapitre: 90, verset: 3, texte: `Tu fais rentrer les hommes jusque dans la poussière, Tu leur dis: «Revenez, (revenez,) fils d’Adam!»` },
  { livre: `Psaumes`, chapitre: 90, verset: 4, texte: `Mille ans sont à tes yeux comme la journée d’hier Qui déjà est passée, comme une heure de veille au milieu de la nuit.` },
  { livre: `Psaumes`, chapitre: 90, verset: 5, texte: `C’est toi qui les emportes comme un peu de sommeil Qui s’efface au matin. Ils sont pareils à l’herbe` },
  { livre: `Psaumes`, chapitre: 90, verset: 6, texte: `Qui fleurit le matin, qui passe et qui, le soir, se sèche et se flétrit.` },
  { livre: `Psaumes`, chapitre: 90, verset: 7, texte: `Nous sommes épuisés, (Seigneur,) par ta colère, Ta fureur nous effraie:` },
  { livre: `Psaumes`, chapitre: 90, verset: 8, texte: `Tu as mis devant toi, (Seigneur, tous) nos péchés, Et nos fautes cachées, tu les mets en lumière.` },
  { livre: `Psaumes`, chapitre: 90, verset: 9, texte: `Tous nos jours disparaissent par ton indignation. Nous voyons nos années s’effacer comme un souffle…` },
  { livre: `Psaumes`, chapitre: 90, verset: 10, texte: `Le temps de nos années? C’est soixante-dix ans, Au mieux quatre-vingts ans pour les plus vigoureux; Et leur agitation n’est que peine et misère. Car le temps passe vite et nous nous envolons.` },
  { livre: `Psaumes`, chapitre: 90, verset: 11, texte: `(Seigneur,) qui peut connaître le poids de ta colère? Qui te révère assez pour craindre ton courroux?` },
  { livre: `Psaumes`, chapitre: 90, verset: 12, texte: `(Seigneur,) apprends-nous donc à bien compter nos jours, Afin que notre cœur découvre la sagesse!` },
  { livre: `Psaumes`, chapitre: 90, verset: 13, texte: `Reviens, ô Éternel! Reviens! Jusques à quand Tarderas-tu encore? Exerce ta pitié envers tes serviteurs!` },
  { livre: `Psaumes`, chapitre: 90, verset: 14, texte: `Comble-nous chaque aurore de ta fidélité, Et nous crierons de joie tout au long de nos jours.` },
  { livre: `Psaumes`, chapitre: 90, verset: 15, texte: `Rends-nous en jours de joie les jours de nos épreuves, Change en années de joie nos années de malheur!` },
  { livre: `Psaumes`, chapitre: 90, verset: 16, texte: `Que ton œuvre apparaisse envers tes serviteurs, Ta gloire envers leurs fils!` },
  { livre: `Psaumes`, chapitre: 90, verset: 17, texte: `Et que la bienveillance du Seigneur, notre Dieu, Repose sur nous tous! Fais prospérer pour nous l’ouvrage de nos mains! Oh oui! fais prospérer l’ouvrage de nos mains!` },
  { livre: `Psaumes`, chapitre: 91, verset: 1, texte: `Celui qui se tient caché tout près du Très-Haut Repose en sécurité à l’ombre du Tout-Puissant.` },
  { livre: `Psaumes`, chapitre: 91, verset: 2, texte: `Je dis au Seigneur: «Tu es mon refuge et ma citadelle, Oui, tu es mon Dieu en qui j’ai confiance».` },
  { livre: `Psaumes`, chapitre: 91, verset: 3, texte: `Car c’est lui qui te délivre du filet de l’oiseleur, De la peste et de ses maux.` },
  { livre: `Psaumes`, chapitre: 91, verset: 4, texte: `Il t’abrite de son aile Et, caché sous son plumage, tu trouves un refuge sûr, Sa fidélité est un bouclier et une cuirasse.` },
  { livre: `Psaumes`, chapitre: 91, verset: 5, texte: `Tu n’as plus à craindre Ni les terreurs de la nuit, ni la flèche ailée, le jour,` },
  { livre: `Psaumes`, chapitre: 91, verset: 6, texte: `Ni le mal rôdant dans l’ombre, Ni l’épidémie qui sévit en plein midi.` },
  { livre: `Psaumes`, chapitre: 91, verset: 7, texte: `Qu’un millier tombe à ta gauche et dix milliers à ta droite, Cela ne t’atteindra pas.` },
  { livre: `Psaumes`, chapitre: 91, verset: 8, texte: `Ouvre seulement les yeux, Et tu pourras contempler la punition des méchants.` },
  { livre: `Psaumes`, chapitre: 91, verset: 9, texte: `Seigneur, tu es mon refuge; le Très-Haut est ton rempart:` },
  { livre: `Psaumes`, chapitre: 91, verset: 10, texte: `Aucun mal ne t’atteindra, Nul fléau n’approchera de la tente où tu demeures,` },
  { livre: `Psaumes`, chapitre: 91, verset: 11, texte: `Car il chargera ses anges de veiller sur toi dans toutes tes voies.` },
  { livre: `Psaumes`, chapitre: 91, verset: 12, texte: `Ils te soutiendront, te porteront sur leurs mains, De peur que ton pied ne heurte contre quelque pierre.` },
  { livre: `Psaumes`, chapitre: 91, verset: 13, texte: `Tu pourras marcher sur le lion et l’aspic Et tu fouleras aux pieds le lionceau, le serpent.` },
  { livre: `Psaumes`, chapitre: 91, verset: 14, texte: `«Parce qu’il m’est attaché, (a dit le Seigneur,) Je vais le sauver et le protéger parce qu’il connaît mon nom.` },
  { livre: `Psaumes`, chapitre: 91, verset: 15, texte: `Il m’invoquera, je lui répondrai, Oui, je serai avec lui au moment de la détresse, Et je le délivrerai, je le couvrirai de gloire.` },
  { livre: `Psaumes`, chapitre: 91, verset: 16, texte: `Il sera comblé de jours et il verra mon salut».` },
  { livre: `Psaumes`, chapitre: 92, verset: 0, texte: `Psaume pour le jour du sabbat, à chanter.` },
  { livre: `Psaumes`, chapitre: 92, verset: 1, texte: `Quel bonheur de pouvoir louer le Seigneur, De chanter en l’honneur de ton nom, Très-Haut!` },
  { livre: `Psaumes`, chapitre: 92, verset: 2, texte: `D’annoncer ton amour dès le point du jour, Ta fidélité tout au long des nuits,` },
  { livre: `Psaumes`, chapitre: 92, verset: 3, texte: `Sur la cithare à dix cordes, Aux accords du luth, au son de la harpe,` },
  { livre: `Psaumes`, chapitre: 92, verset: 4, texte: `Car tu me combles de joie, par ce que tu fais, Seigneur. Je veux célébrer les ouvrages de tes mains.` },
  { livre: `Psaumes`, chapitre: 92, verset: 5, texte: `Combien tes œuvres sont grandes ô Seigneur, (mon Dieu)! Que tes pensées sont profondes!` },
  { livre: `Psaumes`, chapitre: 92, verset: 6, texte: `L’insensé n’y connaît rien, le sot ne peut les comprendre.` },
  { livre: `Psaumes`, chapitre: 92, verset: 7, texte: `Si les infidèles croissent comme l’herbe, Et si tous les malfaisants sont si florissants, C’est pour périr à toujours.` },
  { livre: `Psaumes`, chapitre: 92, verset: 8, texte: `Mais toi, ô Seigneur, tu es le Très-Haut, pour l’éternité.` },
  { livre: `Psaumes`, chapitre: 92, verset: 9, texte: `Car voici, Seigneur, tous tes ennemis: ils vont succomber, Tous les malfaisants vont se disperser.` },
  { livre: `Psaumes`, chapitre: 92, verset: 10, texte: `Mais tu relèves ma force, Je suis comme un buffle, tu m’arroses d’huile fraîche.` },
  { livre: `Psaumes`, chapitre: 92, verset: 11, texte: `Mon œil aime à regarder ceux qui m’espionnent Mon oreille entend sans crainte ceux qui viennent m’attaquer.` },
  { livre: `Psaumes`, chapitre: 92, verset: 12, texte: `Les justes croîtront comme le palmier, Ils s’élèveront comme un cèdre du Liban,` },
  { livre: `Psaumes`, chapitre: 92, verset: 13, texte: `Bien plantés dans la maison du Seigneur, Ils se couvriront de fleurs dans les cours du temple de notre Dieu.` },
  { livre: `Psaumes`, chapitre: 92, verset: 14, texte: `Ils seront encore féconds jusqu’en leur blanche vieillesse, Ils resteront vigoureux pleins de sève et de verdeur,` },
  { livre: `Psaumes`, chapitre: 92, verset: 15, texte: `Prêts à proclamer la droiture du Seigneur: Il est mon rocher, on ne trouve pas de faille en lui.` },
  { livre: `Psaumes`, chapitre: 93, verset: 1, texte: `L’Éternel règne vêtu de gloire, ceint de puissance, de majesté. Le monde est ferme: il ne chancelle jamais.` },
  { livre: `Psaumes`, chapitre: 93, verset: 2, texte: `Dès l’origine, ton trône est ferme. Depuis toujours, toi, tu existes.` },
  { livre: `Psaumes`, chapitre: 93, verset: 3, texte: `Les eaux élèvent, Seigneur, les eaux élèvent leur voix. Les eaux élèvent leur grondement.` },
  { livre: `Psaumes`, chapitre: 93, verset: 4, texte: `Mais, plus puissant que les eaux mugissantes, Plus imposant que les flots de la mer, Est le Seigneur dans les hauteurs célestes.` },
  { livre: `Psaumes`, chapitre: 93, verset: 5, texte: `Tes témoignages sont la vérité, la sainteté convient à ta maison, Ô Éternel, pour la durée des temps.` },
  { livre: `Psaumes`, chapitre: 94, verset: 1, texte: `Dieu qui fais justice, ô Seigneur, Dieu qui fais justice, apparais dans ton éclat!` },
  { livre: `Psaumes`, chapitre: 94, verset: 2, texte: `Dresse-toi! Viens juger la terre! Rends aux orgueilleux le salaire qu’ils méritent!` },
  { livre: `Psaumes`, chapitre: 94, verset: 3, texte: `Combien de temps, ô Seigneur, Combien de temps les méchants vont-ils triompher?` },
  { livre: `Psaumes`, chapitre: 94, verset: 4, texte: `Ce sont des bavards, ils parlent insolemment, Tous les artisans du mal palabrent entre eux.` },
  { livre: `Psaumes`, chapitre: 94, verset: 5, texte: `Ô Seigneur, ils tyrannisent ton peuple Et ils humilient ceux qui t’appartiennent.` },
  { livre: `Psaumes`, chapitre: 94, verset: 6, texte: `Ils tuent l’étranger, ainsi que la veuve, et ils assassinent l’orphelin` },
  { livre: `Psaumes`, chapitre: 94, verset: 7, texte: `Tout en se disant: «Le Seigneur ne le voit pas, Le Dieu de Jacob n’y fera pas attention!»` },
  { livre: `Psaumes`, chapitre: 94, verset: 8, texte: `Comprenez donc, insensés! Gens bornés, quand serez-vous sages?` },
  { livre: `Psaumes`, chapitre: 94, verset: 9, texte: `Celui qui a fait l’oreille, n’entendrait-il pas? Celui qui a formé l’œil, ne verrait-il pas?` },
  { livre: `Psaumes`, chapitre: 94, verset: 10, texte: `Celui qui instruit les peuples et donne aux humains la science, Ne peut-il punir?` },
  { livre: `Psaumes`, chapitre: 94, verset: 11, texte: `Le Seigneur connaît les pensées de l’homme: Elles ne sont que du vent.` },
  { livre: `Psaumes`, chapitre: 94, verset: 12, texte: `Bienheureux est l’homme que tu corriges, Seigneur, Et que tu instruis en lui expliquant ta loi,` },
  { livre: `Psaumes`, chapitre: 94, verset: 13, texte: `Pour lui donner du repos aux jours du malheur, Tandis que se creuse une fosse pour l’impie.` },
  { livre: `Psaumes`, chapitre: 94, verset: 14, texte: `Jamais le Seigneur ne délaissera son peuple. Il n’abandonnera pas la nation qu’il a choisie.` },
  { livre: `Psaumes`, chapitre: 94, verset: 15, texte: `Car, un jour, ses jugements apparaîtront équitables, Et tous les cœurs droits voudront se rallier à lui.` },
  { livre: `Psaumes`, chapitre: 94, verset: 16, texte: `Qui m’assistera contre les méchants? Qui me soutiendra contre ceux qui font le mal?` },
  { livre: `Psaumes`, chapitre: 94, verset: 17, texte: `Ah! si le Seigneur ne m’avait pas secouru, Bien vite mon âme aurait habité la demeure du silence.` },
  { livre: `Psaumes`, chapitre: 94, verset: 18, texte: `À peine ai-je dit: «Je vais perdre pied», Que ton amour, ô Seigneur, est venu me soutenir.` },
  { livre: `Psaumes`, chapitre: 94, verset: 19, texte: `Lorsque des pensées en foule s’agitaient en moi, Tes consolations m’ont rendu la joie.` },
  { livre: `Psaumes`, chapitre: 94, verset: 20, texte: `Serais-tu l’allié d’un pouvoir inique Qui commet des crimes au mépris des lois?` },
  { livre: `Psaumes`, chapitre: 94, verset: 21, texte: `Ils se coalisent afin d’attenter à la vie du juste Et ils font couler le sang innocent.` },
  { livre: `Psaumes`, chapitre: 94, verset: 22, texte: `Mais le Seigneur est pour moi une forteresse, Oui, mon Dieu est le rocher où je peux me réfugier.` },
  { livre: `Psaumes`, chapitre: 94, verset: 23, texte: `Il fait retomber sur eux leur iniquité, Il les réduit au silence par leur méchanceté même. Oui, le Seigneur, notre Dieu, les réduira au silence.` },
  { livre: `Psaumes`, chapitre: 95, verset: 1, texte: `Venez, crions notre joie en l’honneur de l’Éternel! Louons le Seigneur! Acclamons notre rocher et notre Sauveur!` },
  { livre: `Psaumes`, chapitre: 95, verset: 2, texte: `Allons au-devant de lui avec des louanges. Acclamons-le par des psaumes.` },
  { livre: `Psaumes`, chapitre: 95, verset: 3, texte: `Car c’est un Dieu de grandeur que notre Seigneur. Il est un grand Roi au-dessus de tous les dieux.` },
  { livre: `Psaumes`, chapitre: 95, verset: 4, texte: `C’est lui qui tient dans sa main les profondeurs de la terre, Et les plus hautes montagnes, toutes sont à lui.` },
  { livre: `Psaumes`, chapitre: 95, verset: 5, texte: `À lui appartient la mer, c’est lui qui l’a faite Et les continents que ses mains ont façonnés.` },
  { livre: `Psaumes`, chapitre: 95, verset: 6, texte: `Venez, prosternons-nous et humilions-nous, Ployons les genoux devant le Seigneur qui nous a créés.` },
  { livre: `Psaumes`, chapitre: 95, verset: 7, texte: `Il est notre Dieu, nous sommes son peuple Qu’il conduit comme un berger, Le menu troupeau guidé par sa main. Aujourd’hui, si vous entendez sa voix,` },
  { livre: `Psaumes`, chapitre: 95, verset: 8, texte: `N’endurcissez pas vos cœurs Comme lors de la révolte près de Mériba, Comme au jour de tentation à Massa dans le désert:` },
  { livre: `Psaumes`, chapitre: 95, verset: 9, texte: `«Vos pères m’ont provoqué et ils m’ont mis à l’épreuve Bien qu’ils aient vu mes exploits,` },
  { livre: `Psaumes`, chapitre: 95, verset: 10, texte: `Pendant quarante ans. J’ai été déçu par cette génération, et j’ai dit alors: “C’est un peuple au cœur errant, ils n’ont pas connu mes voies”.` },
  { livre: `Psaumes`, chapitre: 95, verset: 11, texte: `Et dans ma colère, j’ai fait ce serment: “Ils n’entreront pas au pays de mon repos ”».` },
  { livre: `Psaumes`, chapitre: 96, verset: 0, texte: `Chantez à l’Éternel un cantique nouveau! Chantez à l’Éternel, habitants de la terre!` },
  { livre: `Psaumes`, chapitre: 96, verset: 1, texte: `Chantez à l’Éternel en bénissant son nom! Annoncez chaque jour la joie de son salut!` },
  { livre: `Psaumes`, chapitre: 96, verset: 2, texte: `Oui, publiez sa gloire chez les peuples païens! Racontez ses merveilles à toutes les nations!` },
  { livre: `Psaumes`, chapitre: 96, verset: 3, texte: `Car l’Éternel est grand et comblé de louanges Et il est redoutable par-dessus tous les dieux.` },
  { livre: `Psaumes`, chapitre: 96, verset: 4, texte: `Tous les dieux des nations ne sont que des idoles, Lui, il a fait les cieux.` },
  { livre: `Psaumes`, chapitre: 96, verset: 5, texte: `Splendeur et majesté forment son avant-garde, Et puissance et beauté sont dans son sanctuaire:` },
  { livre: `Psaumes`, chapitre: 96, verset: 6, texte: `Rendez à l’Éternel, vous, familles des peuples, Rendez à l’Éternel la gloire et la puissance!` },
  { livre: `Psaumes`, chapitre: 96, verset: 7, texte: `Rendez à l’Éternel la gloire de son nom! Apportez vos offrandes, entrez dans ses parvis` },
  { livre: `Psaumes`, chapitre: 96, verset: 8, texte: `Et, là, prosternez-vous, adorez l’Éternel, parés de sainteté! Habitants de la terre, tremblez devant sa face!` },
  { livre: `Psaumes`, chapitre: 96, verset: 9, texte: `Proclamez aux nations que l’Éternel est roi! Aussi le monde est ferme, il ne chancelle pas. Dieu gouverne les peuples. Il juge avec droiture.` },
  { livre: `Psaumes`, chapitre: 96, verset: 10, texte: `Que les cieux soient en joie et que la terre exulte, Que la mer se déchaîne jusqu’en ses profondeurs!` },
  { livre: `Psaumes`, chapitre: 96, verset: 11, texte: `Que tressaillent les champs et tout ce qui s’y trouve! Que les arbres des bois poussent des cris de joie` },
  { livre: `Psaumes`, chapitre: 96, verset: 12, texte: `Devant Dieu, car il vient, il vient juger la terre.` },
  { livre: `Psaumes`, chapitre: 96, verset: 13, texte: `Il jugera le monde selon des arrêts justes, (Il jugera) les peuples selon la vérité.` },
  { livre: `Psaumes`, chapitre: 97, verset: 1, texte: `L’Éternel règne! Ô terre exulte! Îles sans nombre, réjouissez-vous!` },
  { livre: `Psaumes`, chapitre: 97, verset: 2, texte: `Autour de lui, des nuées sombres Et des ténèbres montent la garde. Justice et droit fondent son trône` },
  { livre: `Psaumes`, chapitre: 97, verset: 3, texte: `Et, devant lui, un feu s’avance: Il flambe et cerne tout à l’entour ses ennemis.` },
  { livre: `Psaumes`, chapitre: 97, verset: 4, texte: `Par ses éclairs, il illumine tout l’univers. En les voyant, la terre tremble,` },
  { livre: `Psaumes`, chapitre: 97, verset: 5, texte: `Les monts se fondent comme la cire face au Seigneur, Face à celui qui est le Maître de l’univers.` },
  { livre: `Psaumes`, chapitre: 97, verset: 6, texte: `Les cieux proclament son équité Et tous les peuples voient sa splendeur.` },
  { livre: `Psaumes`, chapitre: 97, verset: 7, texte: `Qu’ils soient confus tous ceux qui servent des vanités Et qui se vantent de leurs idoles Car devant Dieu, tous les faux dieux s’inclineront.` },
  { livre: `Psaumes`, chapitre: 97, verset: 8, texte: `Sion l’apprend et s’en réjouit. Toutes les villes de la Judée vont exulter À la pensée de tes sentences, ô Éternel!` },
  { livre: `Psaumes`, chapitre: 97, verset: 9, texte: `Car, ô Seigneur, c’est toi qui es le (Dieu) Très-Haut Sur tout le monde, bien au-dessus de tous les dieux!` },
  { livre: `Psaumes`, chapitre: 97, verset: 10, texte: `Vous, les amis de l’Éternel, ayez le mal en abjection! Il garde l’âme de ses fidèles Et, de la main des réprouvés, il les délivre.` },
  { livre: `Psaumes`, chapitre: 97, verset: 11, texte: `Une lumière se manifeste à l’homme juste Et de la joie pour les cœurs droits.` },
  { livre: `Psaumes`, chapitre: 97, verset: 12, texte: `Ô, vous les justes, réjouissez-vous dans le Seigneur Et rendez grâces à son saint nom.` },
  { livre: `Psaumes`, chapitre: 98, verset: 1, texte: `Chantez à l’Éternel un cantique nouveau Car il fait des merveilles, Sa droite et son bras saint lui sont venus en aide.` },
  { livre: `Psaumes`, chapitre: 98, verset: 2, texte: `L’Éternel fait connaître son salut (son secours), Révélant sa justice aux regards des païens.` },
  { livre: `Psaumes`, chapitre: 98, verset: 3, texte: `(L’Éternel) se souvient de sa fidélité Et de sa bienveillance Et il les manifeste au peuple d’Israël. Jusqu’au bout de la terre, On a vu le salut qui vient de notre Dieu.` },
  { livre: `Psaumes`, chapitre: 98, verset: 4, texte: `Acclamez l’Éternel, habitants de la terre! Éclatez d’allégresse, jouez de la musique,` },
  { livre: `Psaumes`, chapitre: 98, verset: 5, texte: `Jouez sur la cithare en l’honneur du Seigneur, Sur la cithare, au son de tous les instruments!` },
  { livre: `Psaumes`, chapitre: 98, verset: 6, texte: `Au son de la trompette et aux accents du cor, Acclamez la présence de l’Éternel, du Roi!` },
  { livre: `Psaumes`, chapitre: 98, verset: 7, texte: `Que la mer se déchaîne jusqu’en ses profondeurs! Que l’univers résonne avec ses habitants!` },
  { livre: `Psaumes`, chapitre: 98, verset: 8, texte: `Que les fleuves l’acclament! Qu’ensemble les montagnes poussent des cris de joie` },
  { livre: `Psaumes`, chapitre: 98, verset: 9, texte: `Devant Dieu, car il vient, il vient juger la terre! Il jugera le monde selon des arrêts justes, (Il jugera) les peuples selon la vérité.` },
  { livre: `Psaumes`, chapitre: 99, verset: 1, texte: `L’Éternel est roi. Que les peuples tremblent! Il siège (sur son trône) sur les chérubins. Que la terre tremble!` },
  { livre: `Psaumes`, chapitre: 99, verset: 2, texte: `L’Éternel est grand, (il règne) à Sion. Il est exalté au-dessus des peuples.` },
  { livre: `Psaumes`, chapitre: 99, verset: 3, texte: `Célébrez son nom grand et redoutable, Car il est le Saint` },
  { livre: `Psaumes`, chapitre: 99, verset: 4, texte: `Et il est un roi aimant la justice. C’est toi qui fondas l’ordre et l’équité, C’est toi qui exerces le droit en Jacob!` },
  { livre: `Psaumes`, chapitre: 99, verset: 5, texte: `Louez l’Éternel, c’est lui, notre Dieu, Et prosternez-vous aux pieds de son trône, Car il est le Saint!` },
  { livre: `Psaumes`, chapitre: 99, verset: 6, texte: `Moïse et Aaron étaient de ses prêtres, Eux et Samuel invoquaient son nom. Ils faisaient appel au Seigneur, Et lui, il les exauçait.` },
  { livre: `Psaumes`, chapitre: 99, verset: 7, texte: `Dieu, dans la nuée, s’adressait à eux. Ils ont observé ses commandements Et les prescriptions qu’il avait données.` },
  { livre: `Psaumes`, chapitre: 99, verset: 8, texte: `Seigneur, notre Dieu, tu les exauças Et tu fus pour eux un Dieu de pardon, Tout en punissant le mal qu’ils faisaient.` },
  { livre: `Psaumes`, chapitre: 99, verset: 9, texte: `Louez le Seigneur, C’est lui, notre Dieu, Et prosternez-vous Devant la montagne de sa sainteté! Il est le Seigneur, Il est notre Dieu.` },
  { livre: `Psaumes`, chapitre: 100, verset: 1, texte: `Psaume pour remercier Dieu. Acclame le Seigneur, Ô terre toute entière!` },
  { livre: `Psaumes`, chapitre: 100, verset: 2, texte: `Servez-le dans la joie! Entrez en sa présence Avec des chants joyeux!` },
  { livre: `Psaumes`, chapitre: 100, verset: 3, texte: `Sachez que c’est lui seul, Le Seigneur, qui est Dieu! C’est lui qui nous a faits, Nous lui appartenons: Oui, nous sommes son peuple, Le troupeau qu’il conduit.` },
  { livre: `Psaumes`, chapitre: 100, verset: 4, texte: `Entrez sous ses portiques Dans la reconnaissance! (Entrez) dans ses parvis En chantant vos louanges, Rendez-lui votre hommage Et bénissez son nom` },
  { livre: `Psaumes`, chapitre: 100, verset: 5, texte: `Car le Seigneur est bon, Son amour qui fait grâce Dure éternellement Et sa fidélité S’étendra d’âge en âge.` },
  { livre: `Psaumes`, chapitre: 101, verset: 1, texte: `Psaume de David. Je veux chanter l’amour et la justice Et composer un psaume pour toi, Seigneur.` },
  { livre: `Psaumes`, chapitre: 101, verset: 2, texte: `J’irai par le chemin des gens intègres. Quand viendras-tu vers moi? Je veux marcher avec un cœur intègre dans ma maison,` },
  { livre: `Psaumes`, chapitre: 101, verset: 3, texte: `Chasser de mes regards les actions viles. Je déteste les œuvres des apostats; Elles n’auront jamais d’attrait pour moi.` },
  { livre: `Psaumes`, chapitre: 101, verset: 4, texte: `Le cœur faux restera bien loin de moi, Je ne veux rien savoir des malfaisants.` },
  { livre: `Psaumes`, chapitre: 101, verset: 5, texte: `Qui dénigre en secret son compagnon, Je lui ferme la bouche (et le fais taire). Je ne supporte pas les yeux hautains Ni le cœur arrogant (et ambitieux).` },
  { livre: `Psaumes`, chapitre: 101, verset: 6, texte: `Mes yeux se porteront sur les fidèles (les gens de bonne foi), Dans le pays, pour les faire habiter auprès de moi, Et ceux qui sont intègres me serviront.` },
  { livre: `Psaumes`, chapitre: 101, verset: 7, texte: `Il n’y a pas de place dans ma maison pour qui use de fraude, Et le menteur ne subsistera pas devant mes yeux.` },
  { livre: `Psaumes`, chapitre: 101, verset: 8, texte: `Je fermerai la bouche chaque matin aux impies du pays, Pour retrancher de la cité de Dieu tous ceux qui font le mal.` },
  { livre: `Psaumes`, chapitre: 102, verset: 0, texte: `Prière d’un malheureux qui se sent défaillir et qui épanche sa plainte en présence du Seigneur.` },
  { livre: `Psaumes`, chapitre: 102, verset: 1, texte: `Seigneur, écoute ma prière, et que mon cri parvienne à toi!` },
  { livre: `Psaumes`, chapitre: 102, verset: 2, texte: `Ne me cache pas ton visage au jour où l’angoisse me tient! Incline vers moi ton oreille à l’instant même où je t’invoque, Ne tarde pas à me répondre!` },
  { livre: `Psaumes`, chapitre: 102, verset: 3, texte: `Mes jours en fumée se dissipent, J’ai comme un brasier dans mes os.` },
  { livre: `Psaumes`, chapitre: 102, verset: 4, texte: `Mon cœur est durement frappé, il se dessèche comme l’herbe, J’en oublie de manger mon pain.` },
  { livre: `Psaumes`, chapitre: 102, verset: 5, texte: `À force de crier ma plainte, je n’ai que la peau sur les os,` },
  { livre: `Psaumes`, chapitre: 102, verset: 6, texte: `Je suis devenu comparable au pélican dans le désert Je suis comme le chat-huant qui hante les lieux désolés.` },
  { livre: `Psaumes`, chapitre: 102, verset: 7, texte: `Je reste privé de sommeil, Je ressemble à un oisillon oublié tout seul sur un toit.` },
  { livre: `Psaumes`, chapitre: 102, verset: 8, texte: `Toujours mes ennemis m’insultent, Ceux qui sont furieux contre moi profèrent sur moi des jurons.` },
  { livre: `Psaumes`, chapitre: 102, verset: 9, texte: `La cendre est le pain que je mange, Ma boisson est mêlée de pleurs.` },
  { livre: `Psaumes`, chapitre: 102, verset: 10, texte: `Dans ta colère et ton courroux, tu m’as saisi et rejeté.` },
  { livre: `Psaumes`, chapitre: 102, verset: 11, texte: `Mes jours déclinent comme une ombre, Je me dessèche comme l’herbe.` },
  { livre: `Psaumes`, chapitre: 102, verset: 12, texte: `Mais toi, tu sièges pour toujours Et l’on se souviendra de toi tout au long des générations.` },
  { livre: `Psaumes`, chapitre: 102, verset: 13, texte: `Éternel, tu te lèveras, tu auras pitié de Sion! L’heure est là de lui faire grâce, le temps fixé est à son terme.` },
  { livre: `Psaumes`, chapitre: 102, verset: 14, texte: `Tes serviteurs aiment ses pierres, ils ont pitié de sa poussière.` },
  { livre: `Psaumes`, chapitre: 102, verset: 15, texte: `Tous les pays craindront ton nom, Seigneur, tous les rois de la terre s’inclineront devant ta gloire.` },
  { livre: `Psaumes`, chapitre: 102, verset: 16, texte: `Le Seigneur rebâtit Sion et sa gloire s’y manifeste.` },
  { livre: `Psaumes`, chapitre: 102, verset: 17, texte: `Il a égard à la prière du malheureux. Non, il n’a pas, pour sa prière, du mépris.` },
  { livre: `Psaumes`, chapitre: 102, verset: 18, texte: `Que cette chose soit écrite pour la génération future Où le peuple régénéré glorifiera notre Seigneur:` },
  { livre: `Psaumes`, chapitre: 102, verset: 19, texte: `Du haut de sa demeure sainte, Le Seigneur s’est penché (vers nous). Du ciel, il regarde la terre,` },
  { livre: `Psaumes`, chapitre: 102, verset: 20, texte: `Afin d’écouter les soupirs du prisonnier, Pour libérer ceux qui allaient mourir (sans lui),` },
  { livre: `Psaumes`, chapitre: 102, verset: 21, texte: `Pour que l’on publie en Sion le nom du Seigneur, (notre Dieu,) Sa louange à Jérusalem,` },
  { livre: `Psaumes`, chapitre: 102, verset: 22, texte: `Quand se rassembleront les peuples Et les royaumes (de la terre) afin de servir l’Éternel.` },
  { livre: `Psaumes`, chapitre: 102, verset: 23, texte: `Le Seigneur a brisé ma force en plein milieu de mon chemin. Et il a abrégé mes jours.` },
  { livre: `Psaumes`, chapitre: 102, verset: 24, texte: `Je dirai: «Ne m’enlève pas, mon Dieu, au milieu de mes jours, Toi qui subsistes d’âge en âge!»` },
  { livre: `Psaumes`, chapitre: 102, verset: 25, texte: `Tu as jadis fondé la terre, les cieux sont l’œuvre de tes mains.` },
  { livre: `Psaumes`, chapitre: 102, verset: 26, texte: `Ils périront, mais tu subsistes; ils s’useront comme un habit; Comme on change de vêtement, tu les écarteras de toi.` },
  { livre: `Psaumes`, chapitre: 102, verset: 27, texte: `Mais toi, tu es toujours le même, tes années ne finiront pas.` },
  { livre: `Psaumes`, chapitre: 102, verset: 28, texte: `Les enfants de tes serviteurs auront toujours une demeure Et, devant toi, leur descendance s’affermira solidement.` },
  { livre: `Psaumes`, chapitre: 103, verset: 1, texte: `De David. Mon âme, bénis l’Éternel! Et que tout ce qui est en moi bénisse son saint nom!` },
  { livre: `Psaumes`, chapitre: 103, verset: 2, texte: `Mon âme, bénis l’Éternel, n’oublie aucun de ses bienfaits.` },
  { livre: `Psaumes`, chapitre: 103, verset: 3, texte: `Car c’est lui qui pardonne entièrement tes fautes, C’est lui qui te guérit de toute maladie` },
  { livre: `Psaumes`, chapitre: 103, verset: 4, texte: `Et, du séjour des morts, il rachète ta vie. C’est lui qui te couronne de tendresse et d’amour,` },
  { livre: `Psaumes`, chapitre: 103, verset: 5, texte: `Qui rassasie de biens ton âge prolongé, Qui te fait rajeunir à la façon d’un aigle.` },
  { livre: `Psaumes`, chapitre: 103, verset: 6, texte: `Le Seigneur fait justice Et il défend les droits de tous les opprimés.` },
  { livre: `Psaumes`, chapitre: 103, verset: 7, texte: `Il a manifesté ses desseins à Moïse Et montré sa puissance aux enfants d’Israël.` },
  { livre: `Psaumes`, chapitre: 103, verset: 8, texte: `Le Seigneur est clément et miséricordieux. Il est plein de patience et débordant d’amour.` },
  { livre: `Psaumes`, chapitre: 103, verset: 9, texte: `Il ne conteste pas sans fin et sans arrêt, Et son ressentiment n’est jamais éternel.` },
  { livre: `Psaumes`, chapitre: 103, verset: 10, texte: `Il ne nous traite pas selon nos transgressions, Il ne nous châtie pas comme le méritaient nos actes d’injustice.` },
  { livre: `Psaumes`, chapitre: 103, verset: 11, texte: `Car autant les cieux sont distants de la terre, Autant sa grâce est grande pour ceux qui le révèrent.` },
  { livre: `Psaumes`, chapitre: 103, verset: 12, texte: `Et autant l’Orient est loin de l’Occident, Autant il éloigne de nous nos transgressions.` },
  { livre: `Psaumes`, chapitre: 103, verset: 13, texte: `Et, comme un père aimant Est plein de compassion pour ses propres enfants, Le Seigneur a pitié de ceux qui le révèrent:` },
  { livre: `Psaumes`, chapitre: 103, verset: 14, texte: `Il sait de quelle pâte nous sommes façonnés, Il se rappelle bien que nous sommes poussière.` },
  { livre: `Psaumes`, chapitre: 103, verset: 15, texte: `L’homme: faible mortel! Ses jours sont comme l’herbe; Comme une fleur des champs, le voici qui fleurit!` },
  { livre: `Psaumes`, chapitre: 103, verset: 16, texte: `Mais dès que le vent passe, il n’en est plus question, Le lieu qu’elle occupait ne la reconnaît plus.` },
  { livre: `Psaumes`, chapitre: 103, verset: 17, texte: `Mais l’amour du Seigneur va d’une éternité À l’autre éternité pour ceux qui le révèrent. Sa justice s’étend à leurs petits-enfants.` },
  { livre: `Psaumes`, chapitre: 103, verset: 18, texte: `Elle est pour ceux qui gardent, fidèles, son alliance, Pour ceux qui se souviennent de ses commandements Pour les exécuter.` },
  { livre: `Psaumes`, chapitre: 103, verset: 19, texte: `Dans les cieux, l’Éternel a établi son trône: Il est le Roi, le Maître de l’univers entier.` },
  { livre: `Psaumes`, chapitre: 103, verset: 20, texte: `Bénissez l’Éternel, vous tous, anges puissants, Qui faites ce qu’il dit dès que vous entendez l’accent de son appel!` },
  { livre: `Psaumes`, chapitre: 103, verset: 21, texte: `Bénissez l’Éternel, vous toutes ses armées, Vous qui, à son service, faites sa volonté.` },
  { livre: `Psaumes`, chapitre: 103, verset: 22, texte: `Bénissez l’Éternel, toutes ses créatures, partout où il gouverne! Et toi, mon âme aussi, bénis donc (l’Éternel)!` },
  { livre: `Psaumes`, chapitre: 104, verset: 1, texte: `Bénis l’Éternel, ô mon âme! Seigneur, mon Dieu, que tu es grand! Tu es revêtu de splendeur, d’éclat et de magnificence,` },
  { livre: `Psaumes`, chapitre: 104, verset: 2, texte: `Tu as pour manteau la lumière, Tu étends les cieux comme un voile,` },
  { livre: `Psaumes`, chapitre: 104, verset: 3, texte: `Tu construis au-dessus des eaux tes hauts palais inaccessibles. Des nuées, tu te fais un char glissant sur les ailes du vent,` },
  { livre: `Psaumes`, chapitre: 104, verset: 4, texte: `Tu fais des vents tes messagers, les éclairs sont tes serviteurs.` },
  { livre: `Psaumes`, chapitre: 104, verset: 5, texte: `Tu as établi notre terre sur de solides fondements Pour qu’elle reste inébranlable à tout jamais au cours des temps.` },
  { livre: `Psaumes`, chapitre: 104, verset: 6, texte: `Tu l’avais vêtue d’océans, les eaux recouvraient les montagnes.` },
  { livre: `Psaumes`, chapitre: 104, verset: 7, texte: `À ta menace, elles ont fui, au bruit de ta voix de tonnerre, Elles se sont précipitées,` },
  { livre: `Psaumes`, chapitre: 104, verset: 8, texte: `Laissant émerger des montagnes et des vallées qui se creusaient, Chacune d’elles à l’endroit que tu lui avais assigné.` },
  { livre: `Psaumes`, chapitre: 104, verset: 9, texte: `Tu as fixé une frontière que les eaux ne franchiront plus, Elles ne viendront plus jamais submerger à nouveau la terre.` },
  { livre: `Psaumes`, chapitre: 104, verset: 10, texte: `C’est toi qui fais jaillir des sources dans les ravins. Et les torrents s’écoulent entre les montagnes` },
  { livre: `Psaumes`, chapitre: 104, verset: 11, texte: `Abreuvant les bêtes sauvages. Les onagres s’y désaltèrent.` },
  { livre: `Psaumes`, chapitre: 104, verset: 12, texte: `Les oiseaux nichent sur leurs rives, Chantant parmi les frondaisons.` },
  { livre: `Psaumes`, chapitre: 104, verset: 13, texte: `De ses palais inaccessibles, il verse la pluie sur les monts, Ses bienfaits fécondent la terre.` },
  { livre: `Psaumes`, chapitre: 104, verset: 14, texte: `Il fait germer et croître l’herbe pour le bétail et les cultures, Pour servir les besoins de l’homme, pour tirer le pain de la terre.` },
  { livre: `Psaumes`, chapitre: 104, verset: 15, texte: `Le vin réjouit le cœur de l’homme Et fait resplendir son visage, le rendant plus brillant que l’huile. Le pain soutient le cœur de l’homme.` },
  { livre: `Psaumes`, chapitre: 104, verset: 16, texte: `Les arbres, (œuvres) du Seigneur, sont pleins de sève et pleins de vie Comme les cèdres du Liban que la main de Dieu a plantés.` },
  { livre: `Psaumes`, chapitre: 104, verset: 17, texte: `C’est là que nichent les oiseaux Et la cigogne a sa demeure là, sur les branches des cyprès.` },
  { livre: `Psaumes`, chapitre: 104, verset: 18, texte: `Les sommets des hautes montagnes servent d’asile aux bouquetins Et les rochers sont le refuge où les petits rongeurs se cachent.` },
  { livre: `Psaumes`, chapitre: 104, verset: 19, texte: `C’est lui qui a formé la lune pour marquer les cycles des temps. Le soleil sait où il se couche.` },
  { livre: `Psaumes`, chapitre: 104, verset: 20, texte: `Tu fais descendre les ténèbres et la nuit vient, et c’est alors Que se mettent en mouvement tous les animaux des forêts:` },
  { livre: `Psaumes`, chapitre: 104, verset: 21, texte: `Les lions chassent, rugissants, demandant à Dieu leur pâture.` },
  { livre: `Psaumes`, chapitre: 104, verset: 22, texte: `Mais dès que paraît le soleil, ils se replient dans leurs tanières.` },
  { livre: `Psaumes`, chapitre: 104, verset: 23, texte: `L’homme se rend à son ouvrage, il travaillera jusqu’au soir.` },
  { livre: `Psaumes`, chapitre: 104, verset: 24, texte: `Que tes œuvres sont en grand nombre! Tu as tout fait avec sagesse, Ô Éternel, la terre est pleine des biens que ta main a créés:` },
  { livre: `Psaumes`, chapitre: 104, verset: 25, texte: `Voici la mer aux bras immenses Peuplée d’animaux innombrables, Du plus petit jusqu’au plus grand,` },
  { livre: `Psaumes`, chapitre: 104, verset: 26, texte: `Avec ses bateaux en voyage Et avec ce monstre marin que tu créas pour s’y ébattre.` },
  { livre: `Psaumes`, chapitre: 104, verset: 27, texte: `Ces êtres espèrent en toi pour recevoir la nourriture, Chacun au moment opportun.` },
  { livre: `Psaumes`, chapitre: 104, verset: 28, texte: `Tu la leur donnes: ils la recueillent, Ils sont comblés quand ta main s’ouvre.` },
  { livre: `Psaumes`, chapitre: 104, verset: 29, texte: `Mais si tu détournes ta face, ils sont éperdus et tremblants. Sitôt que tu reprends leur souffle, Ils expirent et s’en retournent à la poussière d’où ils viennent.` },
  { livre: `Psaumes`, chapitre: 104, verset: 30, texte: `Rends-leur ton souffle et ils renaissent. L’aspect du sol se renouvelle.` },
  { livre: `Psaumes`, chapitre: 104, verset: 31, texte: `Gloire au Seigneur à tout jamais! Qu’il trouve la joie dans ses œuvres!` },
  { livre: `Psaumes`, chapitre: 104, verset: 32, texte: `Son regard fait trembler la terre, à son contact, les volcans fument.` },
  { livre: `Psaumes`, chapitre: 104, verset: 33, texte: `Je veux chanter à l’Éternel ma vie durant et, en l’honneur De mon Dieu, je veux psalmodier tout le temps que j’existerai.` },
  { livre: `Psaumes`, chapitre: 104, verset: 34, texte: `Que mon chant lui soit agréable! Je mets ma joie dans le Seigneur.` },
  { livre: `Psaumes`, chapitre: 104, verset: 35, texte: `Que les pécheurs soient retranchés! Que les méchants n’existent plus! Bénis l’Éternel, ô mon âme, Louange à Dieu: Alléluia!` },
  { livre: `Psaumes`, chapitre: 105, verset: 1, texte: `Louez l’Éternel! Invoquez son nom! Publiez ses œuvres parmi les nations!` },
  { livre: `Psaumes`, chapitre: 105, verset: 2, texte: `Chantez à sa gloire, psalmodiez pour lui! Entretenez-vous de tous ses miracles!` },
  { livre: `Psaumes`, chapitre: 105, verset: 3, texte: `Soyez fiers de lui, de son nom très saint! Que le cœur de ceux qui recherchent Dieu soit rempli de joie!` },
  { livre: `Psaumes`, chapitre: 105, verset: 4, texte: `Cherchez l’Éternel! Cherchez sa puissance! Aspirez à vivre constamment en sa présence!` },
  { livre: `Psaumes`, chapitre: 105, verset: 5, texte: `Souvenez-vous des miracles qu’il a opérés! Rappelez-vous ses prodiges Et les jugements que sa bouche a prononcés!` },
  { livre: `Psaumes`, chapitre: 105, verset: 6, texte: `Vous, les descendants d’Abraham, son serviteur Vous, fils de Jacob, vous qu’il a choisis!` },
  { livre: `Psaumes`, chapitre: 105, verset: 7, texte: `Notre Dieu, c’est l’Éternel, C’est lui qui gouverne l’univers entier.` },
  { livre: `Psaumes`, chapitre: 105, verset: 8, texte: `Il se souvient à jamais de son alliance, De la parole engagée pour mille générations,` },
  { livre: `Psaumes`, chapitre: 105, verset: 9, texte: `Du traité qu’il a conclu avec Abraham, De son serment à Isaac.` },
  { livre: `Psaumes`, chapitre: 105, verset: 10, texte: `Il l’a érigé en loi pour Jacob Et, pour Israël, en alliance perpétuelle.` },
  { livre: `Psaumes`, chapitre: 105, verset: 11, texte: `Il dit en effet: «Je te donnerai le pays de Canaan, Ce sera le lot de votre héritage.»` },
  { livre: `Psaumes`, chapitre: 105, verset: 12, texte: `Ils n’étaient qu’un petit nombre, une poignée d’immigrants` },
  { livre: `Psaumes`, chapitre: 105, verset: 13, texte: `Errant çà et là parmi les nations, d’un royaume à l’autre.` },
  { livre: `Psaumes`, chapitre: 105, verset: 14, texte: `(Dieu) ne permit à personne de les opprimer Et, pour défendre leur cause, il punit des rois:` },
  { livre: `Psaumes`, chapitre: 105, verset: 15, texte: `«Ne maltraitez pas ceux qui me sont consacrés Et ne touchez pas à ceux qui sont mes prophètes!»` },
  { livre: `Psaumes`, chapitre: 105, verset: 16, texte: `Il fit venir la famine sur tout le pays, il leur coupa tous les vivres.` },
  { livre: `Psaumes`, chapitre: 105, verset: 17, texte: `Il envoya, devant eux, Joseph, vendu comme esclave.` },
  { livre: `Psaumes`, chapitre: 105, verset: 18, texte: `On chargea ses pieds de liens, son cou d’un carcan de fer` },
  { livre: `Psaumes`, chapitre: 105, verset: 19, texte: `Jusqu’au jour où s’accomplit la parole du Seigneur qui le justifia.` },
  { livre: `Psaumes`, chapitre: 105, verset: 20, texte: `Le roi ordonna de le délier, le maître des peuples le fit relâcher.` },
  { livre: `Psaumes`, chapitre: 105, verset: 21, texte: `Il l’établit maître, chef de sa maison, et le nomma gouverneur De tous ses domaines` },
  { livre: `Psaumes`, chapitre: 105, verset: 22, texte: `Pour enseigner ses ministres, selon ses désirs, Pour apprendre la sagesse à ses anciens conseillers.` },
  { livre: `Psaumes`, chapitre: 105, verset: 23, texte: `Ensuite Israël entra en Égypte, Jacob émigra au pays de Cham.` },
  { livre: `Psaumes`, chapitre: 105, verset: 24, texte: `Dieu multiplia prodigieusement son peuple Et le rendit plus puissant que ses oppresseurs.` },
  { livre: `Psaumes`, chapitre: 105, verset: 25, texte: `Il changea leur attitude: ils se mirent à haïr le peuple (de Dieu), Et à comploter contre ceux qui le servaient.` },
  { livre: `Psaumes`, chapitre: 105, verset: 26, texte: `Alors, il leur envoya Moïse, son serviteur, Aaron qu’il avait choisi.` },
  { livre: `Psaumes`, chapitre: 105, verset: 27, texte: `Parmi eux, ils accomplirent sur son ordre des miracles Et de grands prodiges au pays de Cham.` },
  { livre: `Psaumes`, chapitre: 105, verset: 28, texte: `Il envoya les ténèbres qu’il rendit impénétrables. Et les Égyptiens ne purent résister à sa parole.` },
  { livre: `Psaumes`, chapitre: 105, verset: 29, texte: `Il changea leur eau en sang et fit mourir leurs poissons.` },
  { livre: `Psaumes`, chapitre: 105, verset: 30, texte: `Il fit pulluler les grenouilles sur la terre jusqu’aux alcôves royales.` },
  { livre: `Psaumes`, chapitre: 105, verset: 31, texte: `Sur un ordre de sa part, La vermine et les moustiques envahirent le pays.` },
  { livre: `Psaumes`, chapitre: 105, verset: 32, texte: `Il changea la pluie en grêle et un feu ardent brûla leur pays.` },
  { livre: `Psaumes`, chapitre: 105, verset: 33, texte: `Il frappa vigne et figuier et brisa les arbres dans leur territoire.` },
  { livre: `Psaumes`, chapitre: 105, verset: 34, texte: `Sur un ordre de sa part, D’innombrables sauterelles et des criquets arrivèrent` },
  { livre: `Psaumes`, chapitre: 105, verset: 35, texte: `Pour dévorer toute plante et tout fruit dans le pays.` },
  { livre: `Psaumes`, chapitre: 105, verset: 36, texte: `Ensuite il frappa tous les aînés de leur peuple, Toute la fleur de leur race,` },
  { livre: `Psaumes`, chapitre: 105, verset: 37, texte: `Et il fit sortir les siens avec de l’argent, de l’or. Et, dans ses tribus, nul ne chancela.` },
  { livre: `Psaumes`, chapitre: 105, verset: 38, texte: `Leur départ réjouit l’Égypte que la peur avait saisie.` },
  { livre: `Psaumes`, chapitre: 105, verset: 39, texte: `Il étendit la nuée comme un voile protecteur. Une colonne de flammes les illuminait la nuit.` },
  { livre: `Psaumes`, chapitre: 105, verset: 40, texte: `Parce qu’ils le demandèrent il leur envoya des cailles Et les rassasia du pain qui venait du ciel.` },
  { livre: `Psaumes`, chapitre: 105, verset: 41, texte: `Il fendit la roche et l’eau en jaillit. À travers la steppe aride, elle coula comme un fleuve,` },
  { livre: `Psaumes`, chapitre: 105, verset: 42, texte: `Car il s’était souvenu de la promesse sacrée Faite à Abraham qui était son serviteur.` },
  { livre: `Psaumes`, chapitre: 105, verset: 43, texte: `Il fit sortir du pays son peuple dans l’allégresse Et il guida ses élus avec des chants de triomphe.` },
  { livre: `Psaumes`, chapitre: 105, verset: 44, texte: `Il leur octroya des terres occupées par des nations Et ils héritèrent du travail des autres peuples` },
  { livre: `Psaumes`, chapitre: 105, verset: 45, texte: `Pour qu’ils gardent ses décrets et qu’ils observent ses lois. Louez l’Éternel!` },
  { livre: `Psaumes`, chapitre: 106, verset: 1, texte: `Loué soit Dieu! Célébrez l’Éternel car il est bon Et son amour dure éternellement!` },
  { livre: `Psaumes`, chapitre: 106, verset: 2, texte: `Qui saura dire toutes les victoires de l’Éternel? Qui publiera toute sa louange et toute sa gloire?` },
  { livre: `Psaumes`, chapitre: 106, verset: 3, texte: `Bienheureux ceux qui respectent le droit Et qui font en tout temps ce qui est juste.` },
  { livre: `Psaumes`, chapitre: 106, verset: 4, texte: `Ne m’oublie pas, Seigneur, dans ton amour, Toi qui es bienveillant envers ton peuple! Visite-nous et sois notre salut!` },
  { livre: `Psaumes`, chapitre: 106, verset: 5, texte: `Fais-moi voir le bonheur de tes élus! Viens, réjouis-moi de la joie de ton peuple Pour que je puisse éclater en louanges, De concert avec ceux qui t’appartiennent!` },
  { livre: `Psaumes`, chapitre: 106, verset: 6, texte: `Comme nos pères, Nous avons péché, nous avons dévié, Nous avons commis des iniquités!` },
  { livre: `Psaumes`, chapitre: 106, verset: 7, texte: `Car, en Égypte, nos pères n’ont pas compris tes miracles, Ils ont oublié tes grandes bontés; Ils se sont révoltés près de la mer, de la mer Rouge.` },
  { livre: `Psaumes`, chapitre: 106, verset: 8, texte: `Il les sauva pour l’honneur de son nom Afin de manifester sa puissance.` },
  { livre: `Psaumes`, chapitre: 106, verset: 9, texte: `Il menaça les flots de la mer Rouge: elle sécha; Il les conduisit à travers les flots, Comme à travers une rase campagne.` },
  { livre: `Psaumes`, chapitre: 106, verset: 10, texte: `Il les délivra des persécuteurs Et les sauva du pouvoir ennemi.` },
  { livre: `Psaumes`, chapitre: 106, verset: 11, texte: `Les flots ont recouvert leurs oppresseurs Et pas un seul d’entre eux n’en réchappa.` },
  { livre: `Psaumes`, chapitre: 106, verset: 12, texte: `Alors, (son peuple) eut foi en ses paroles Et il se mit à chanter sa louange.` },
  { livre: `Psaumes`, chapitre: 106, verset: 13, texte: `Mais il eut tôt fait d’oublier ses œuvres, Il n’avait pas confiance en ses desseins.` },
  { livre: `Psaumes`, chapitre: 106, verset: 14, texte: `Dans le désert, ils s’est livré à la convoitise, Il a tenté Dieu dans la solitude.` },
  { livre: `Psaumes`, chapitre: 106, verset: 15, texte: `Dieu lui a donné ce qu’il demandait. Pourtant, jamais il n’en avait assez.` },
  { livre: `Psaumes`, chapitre: 106, verset: 16, texte: `Dans le camp, il a jalousé Moïse Ainsi qu’Aaron, l’élu de l’Éternel.` },
  { livre: `Psaumes`, chapitre: 106, verset: 17, texte: `La terre s’ouvrit, dévorant Dathan Et recouvrant la troupe d’Abiram.` },
  { livre: `Psaumes`, chapitre: 106, verset: 18, texte: `Un feu s’alluma contre cette troupe, La flamme dévora ces réprouvés.` },
  { livre: `Psaumes`, chapitre: 106, verset: 19, texte: `À Horeb, ils ont façonné un veau Pour se prosterner devant du métal,` },
  { livre: `Psaumes`, chapitre: 106, verset: 20, texte: `Ils ont échangé leur sujet de gloire Contre un ruminant qui broute de l’herbe!` },
  { livre: `Psaumes`, chapitre: 106, verset: 21, texte: `Ils ont oublié leur Dieu, leur Sauveur, Et ses hauts faits accomplis en Égypte,` },
  { livre: `Psaumes`, chapitre: 106, verset: 22, texte: `Ses grands prodiges au pays de Cham, Ses actions terribles sur la mer Rouge.` },
  { livre: `Psaumes`, chapitre: 106, verset: 23, texte: `Aussi Dieu décida de les détruire. C’est alors que Moïse, son élu, S’est jeté devant lui, intercédant Pour détourner son courroux destructeur.` },
  { livre: `Psaumes`, chapitre: 106, verset: 24, texte: `Ils méprisèrent un pays enviable Car ils ne crurent pas à sa parole.` },
  { livre: `Psaumes`, chapitre: 106, verset: 25, texte: `Ils murmurèrent au fond de leurs tentes, N’écoutant plus la voix de l’Éternel.` },
  { livre: `Psaumes`, chapitre: 106, verset: 26, texte: `Alors, il jura en levant la main Qu’il les ferait tomber dans le désert,` },
  { livre: `Psaumes`, chapitre: 106, verset: 27, texte: `Et qu’il disperserait leurs descendants Dans tous les pays parmi les païens.` },
  { livre: `Psaumes`, chapitre: 106, verset: 28, texte: `Ils s’attachèrent à Baal Phégor Mangeant ce qu’on offrait à des (dieux) morts.` },
  { livre: `Psaumes`, chapitre: 106, verset: 29, texte: `Ils ont irrité Dieu par leurs pratiques Et un fléau éclata parmi eux.` },
  { livre: `Psaumes`, chapitre: 106, verset: 30, texte: `Mais Phinées intervint et fit justice, Et le fléau s’arrêta (aussitôt).` },
  { livre: `Psaumes`, chapitre: 106, verset: 31, texte: `Cela lui fut compté comme acte juste Pour tous les âges, pour l’éternité.` },
  { livre: `Psaumes`, chapitre: 106, verset: 32, texte: `Ils ont irrité Dieu à Mériba Et ils ont fait le malheur de Moïse:` },
  { livre: `Psaumes`, chapitre: 106, verset: 33, texte: `À cause d’eux, il perdit patience Et se mit à parler sans réfléchir.` },
  { livre: `Psaumes`, chapitre: 106, verset: 34, texte: `Ils ne détruisirent pas les nations Que le Seigneur leur avait désignées.` },
  { livre: `Psaumes`, chapitre: 106, verset: 35, texte: `Ils se mêlèrent aux peuples païens Et imitèrent leur façon de faire.` },
  { livre: `Psaumes`, chapitre: 106, verset: 36, texte: `Ils adorèrent leurs divinités, Elles devinrent un piège pour eux.` },
  { livre: `Psaumes`, chapitre: 106, verset: 37, texte: `Ils sacrifièrent leurs fils et leur filles à des démons` },
  { livre: `Psaumes`, chapitre: 106, verset: 38, texte: `Et répandirent le sang innocent, Versant le sang de leurs fils, de leurs filles, Immolés aux faux dieux de Canaan. Et le pays fut souillé par des meurtres.` },
  { livre: `Psaumes`, chapitre: 106, verset: 39, texte: `Ils se profanèrent par leurs pratiques, Par leur conduite, ils se prostituèrent.` },
  { livre: `Psaumes`, chapitre: 106, verset: 40, texte: `Alors, Dieu s’irrita contre son peuple Et il prit en horreur son héritage.` },
  { livre: `Psaumes`, chapitre: 106, verset: 41, texte: `Il le livra au pouvoir des nations, Ceux qui le haïssaient le dominèrent.` },
  { livre: `Psaumes`, chapitre: 106, verset: 42, texte: `Il fut frappé par ses adversaires Et fut humilié sous leur puissance.` },
  { livre: `Psaumes`, chapitre: 106, verset: 43, texte: `Plusieurs fois, Dieu le sauva de nouveau, Mais il se révoltait dans ses pensées Et s’obstinait à lui désobéir, De nouveau, il tombait dans le malheur.` },
  { livre: `Psaumes`, chapitre: 106, verset: 44, texte: `Pourtant, il prenait garde à sa détresse En écoutant ses cris et ses prières.` },
  { livre: `Psaumes`, chapitre: 106, verset: 45, texte: `Il pensait à son alliance avec lui, Il eut pitié et changea son dessein.` },
  { livre: `Psaumes`, chapitre: 106, verset: 46, texte: `Il excita pour lui la compassion De tous ceux qui le retenaient captifs.` },
  { livre: `Psaumes`, chapitre: 106, verset: 47, texte: `Délivre-nous, Éternel, notre Dieu! Rassemble-nous du milieu des nations Pour que nous puissions fêter ton saint nom Et mettre notre gloire à te louer.` },
  { livre: `Psaumes`, chapitre: 106, verset: 48, texte: `Béni soit l’Éternel, Dieu d’Israël, D’éternité jusqu’en éternité Et que le peuple entier réponde: Amen, Alléluia! Oui, louez l’Éternel!` },
  { livre: `Psaumes`, chapitre: 107, verset: 1, texte: `Célébrez l’Éternel, Car il est bon et son amour dure éternellement.` },
  { livre: `Psaumes`, chapitre: 107, verset: 2, texte: `Proclamez-le, vous qu’il a rachetés, Qu’il a sauvés des mains de l’oppresseur,` },
  { livre: `Psaumes`, chapitre: 107, verset: 3, texte: `Et qu’il a rassemblés de tous pays, De l’est à l’ouest et du nord au midi.` },
  { livre: `Psaumes`, chapitre: 107, verset: 4, texte: `Les uns erraient perdus dans le désert, Ils marchaient par des chemins désolés Sans trouver une ville où s’établir.` },
  { livre: `Psaumes`, chapitre: 107, verset: 5, texte: `Ils étaient affamés, ils avaient soif, Et ils étaient tout près de défaillir.` },
  { livre: `Psaumes`, chapitre: 107, verset: 6, texte: `Dans leur détresse, ils crièrent à Dieu Qui les délivra de tous leurs malheurs.` },
  { livre: `Psaumes`, chapitre: 107, verset: 7, texte: `Il les conduisit par le droit chemin, Ils ont atteint une ville habitable.` },
  { livre: `Psaumes`, chapitre: 107, verset: 8, texte: `Qu’ils louent donc l’Éternel pour son amour. Pour ses merveilles en faveur des hommes!` },
  { livre: `Psaumes`, chapitre: 107, verset: 9, texte: `Car il a satisfait l’âme altérée, il a comblé de biens l’âme affamée.` },
  { livre: `Psaumes`, chapitre: 107, verset: 10, texte: `D’autres vivaient dans une ombre mortelle, Enchaînés dans les fers et la misère` },
  { livre: `Psaumes`, chapitre: 107, verset: 11, texte: `Pour avoir bravé les ordres de Dieu Et méprisé les conseils du Très-Haut.` },
  { livre: `Psaumes`, chapitre: 107, verset: 12, texte: `Il humilia leur cœur par la souffrance, Ils succombaient, privés de tout secours.` },
  { livre: `Psaumes`, chapitre: 107, verset: 13, texte: `Dans leur détresse, ils crièrent à Dieu Qui les délivra de tous leurs malheurs.` },
  { livre: `Psaumes`, chapitre: 107, verset: 14, texte: `Il les fit sortir de l’ombre mortelle, Il rompit les liens qui les retenaient.` },
  { livre: `Psaumes`, chapitre: 107, verset: 15, texte: `Qu’ils louent donc l’Éternel pour son amour, Pour ses merveilles en faveur des hommes!` },
  { livre: `Psaumes`, chapitre: 107, verset: 16, texte: `Car il a brisé les portes de bronze et il a rompu les verrous de fer.` },
  { livre: `Psaumes`, chapitre: 107, verset: 17, texte: `Des insensés, par leur conduite indigne, S’étaient rendus malheureux par leurs fautes.` },
  { livre: `Psaumes`, chapitre: 107, verset: 18, texte: `Tout aliment répugnait à leur bouche Et ils touchaient aux confins de la mort.` },
  { livre: `Psaumes`, chapitre: 107, verset: 19, texte: `Dans leur détresse, ils crièrent à Dieu Qui les délivra de tous leurs malheurs.` },
  { livre: `Psaumes`, chapitre: 107, verset: 20, texte: `Envoyant sa parole, il les guérit Et fit échapper leur vie de la fosse.` },
  { livre: `Psaumes`, chapitre: 107, verset: 21, texte: `Qu’ils louent donc l’Éternel pour son amour, Pour ses merveilles en faveur des hommes!` },
  { livre: `Psaumes`, chapitre: 107, verset: 22, texte: `Qu’ils offrent (sans cesse à Dieu) leurs louanges En sacrifice de reconnaissance, Et qu’avec joie ils proclament ses œuvres.` },
  { livre: `Psaumes`, chapitre: 107, verset: 23, texte: `D’autres s’étaient embarqués sur la mer Pour travailler sur le vaste océan.` },
  { livre: `Psaumes`, chapitre: 107, verset: 24, texte: `Ils furent témoins des œuvres de Dieu, De ses merveilles dans les profondeurs.` },
  { livre: `Psaumes`, chapitre: 107, verset: 25, texte: `D’un mot, il fit lever une tempête Et les flots de la mer se soulevèrent.` },
  { livre: `Psaumes`, chapitre: 107, verset: 26, texte: `Tantôt ils étaient portés jusqu’aux cieux, Tantôt ils retombaient dans les abîmes. Leur âme défaillait dans le malheur.` },
  { livre: `Psaumes`, chapitre: 107, verset: 27, texte: `Pris de vertige, ils titubaient comme ivres, Toute leur sagesse avait disparu.` },
  { livre: `Psaumes`, chapitre: 107, verset: 28, texte: `Dans leur détresse, ils crièrent à Dieu Qui les délivra de tous leurs malheurs.` },
  { livre: `Psaumes`, chapitre: 107, verset: 29, texte: `Il réduisit la tempête au silence, Il apaisa les vagues en furie.` },
  { livre: `Psaumes`, chapitre: 107, verset: 30, texte: `La joie leur revint avec l’accalmie Et Dieu les guida au port désiré.` },
  { livre: `Psaumes`, chapitre: 107, verset: 31, texte: `Qu’ils louent donc l’Éternel pour son amour, Pour ses merveilles en faveur des hommes,` },
  { livre: `Psaumes`, chapitre: 107, verset: 32, texte: `Le glorifiant dans l’assemblée du peuple, Le célébrant au conseil des anciens.` },
  { livre: `Psaumes`, chapitre: 107, verset: 33, texte: `Il peut changer les fleuves en désert Les sources d’eau en pays de la soif;` },
  { livre: `Psaumes`, chapitre: 107, verset: 34, texte: `Un sol fertile, il le change en saline Quand ses habitants se sont pervertis.` },
  { livre: `Psaumes`, chapitre: 107, verset: 35, texte: `Mais il change aussi le désert en lac Et la terre aride en sources d’eau vive.` },
  { livre: `Psaumes`, chapitre: 107, verset: 36, texte: `C’est là qu’il établit ceux qui ont faim, Pour y fonder une ville habitable,` },
  { livre: `Psaumes`, chapitre: 107, verset: 37, texte: `Ensemencer des champs, planter des vignes Qui porteront des fruits en abondance.` },
  { livre: `Psaumes`, chapitre: 107, verset: 38, texte: `Dieu les bénit et ils se multiplient Et leur bétail jamais ne dépérit.` },
  { livre: `Psaumes`, chapitre: 107, verset: 39, texte: `D’autres sont décimés et humiliés Sous le poids du malheur et du chagrin.` },
  { livre: `Psaumes`, chapitre: 107, verset: 40, texte: `Dieu répand le mépris sur les puissants, Les fait errer dans un désert sans route.` },
  { livre: `Psaumes`, chapitre: 107, verset: 41, texte: `C’est aussi lui qui relève le pauvre De la misère et qui rend les familles (Fécondes) comme le menu bétail.` },
  { livre: `Psaumes`, chapitre: 107, verset: 42, texte: `Les hommes droits le voient et sont heureux, Mais l’injustice est réduite au silence.` },
  { livre: `Psaumes`, chapitre: 107, verset: 43, texte: `Que le sage ait donc égard à ces choses Et qu’il comprenne l’amour du Seigneur.` },
  { livre: `Psaumes`, chapitre: 108, verset: 0, texte: `Psaume de David. À chanter.` },
  { livre: `Psaumes`, chapitre: 108, verset: 1, texte: `Mon cœur est tranquille, ô mon Dieu! Mon cœur est tranquille. Oui, je chante et je psalmodie sur la harpe, C’est là mon bonheur et ma gloire.` },
  { livre: `Psaumes`, chapitre: 108, verset: 2, texte: `Vite, éveillez-vous, luth et harpe! Je veux m’éveiller dès l’aurore.` },
  { livre: `Psaumes`, chapitre: 108, verset: 3, texte: `Je veux te louer, ô Seigneur, parmi (tous) les peuples, Psalmodier parmi les nations à ta gloire.` },
  { livre: `Psaumes`, chapitre: 108, verset: 4, texte: `Car ta grâce atteint jusqu’aux cieux, ta fidélité jusqu’aux nues!` },
  { livre: `Psaumes`, chapitre: 108, verset: 5, texte: `Ô Dieu, lève-toi sur les cieux, que le monde entier voie ta gloire,` },
  { livre: `Psaumes`, chapitre: 108, verset: 6, texte: `Que tes bien-aimés libérés soient en sûreté! Ô (mon) Dieu, sauve par ta droite, réponds-nous!` },
  { livre: `Psaumes`, chapitre: 108, verset: 7, texte: `Dieu l’a déclaré dans son temple: «Je triompherai!» Dans la joie, je vais m’emparer de Sichem. Je vais mesurer au cordeau, arpenter le val de Souccoth.` },
  { livre: `Psaumes`, chapitre: 108, verset: 8, texte: `À moi Galaad, Manassé! À moi Éphraïm, mon rempart! Il sera un casque pour ma tête. Mon sceptre royal, c’est Juda,` },
  { livre: `Psaumes`, chapitre: 108, verset: 9, texte: `Et, pour me laver, j’ai Moab. Je tiendrai Édom sous mes pieds. De la Philistie, je triomphe.` },
  { livre: `Psaumes`, chapitre: 108, verset: 10, texte: `Qui me mènera au lieu fort, qui me conduira à Édom,` },
  { livre: `Psaumes`, chapitre: 108, verset: 11, texte: `Sinon toi, mon Dieu, (mon Seigneur)? Toi qui nous avais rejetés, qui ne sortais plus avec nous, Avec nos armées ô (mon) Dieu!` },
  { livre: `Psaumes`, chapitre: 108, verset: 12, texte: `Viens nous secourir dans l’épreuve, Contre l’adversaire, (aide-nous)! Le salut de l’homme est trompeur et sa délivrance est chimère.` },
  { livre: `Psaumes`, chapitre: 108, verset: 13, texte: `Nous accomplirons des exploits, Avec notre Dieu, nous serons vaillants et vainqueurs, Car c’est lui qui écrasera l’ennemi.` },
  { livre: `Psaumes`, chapitre: 109, verset: 1, texte: `Au chef de chœur. Psaume de David. Dieu de ma louange, sors de ton silence,` },
  { livre: `Psaumes`, chapitre: 109, verset: 2, texte: `Car la bouche des méchants, leur bouche rusée, S’ouvre contre moi. Leur langue est menteuse,` },
  { livre: `Psaumes`, chapitre: 109, verset: 3, texte: `Ils m’assaillent de paroles qu’inspire la haine. Sans cause, ils me font la guerre.` },
  { livre: `Psaumes`, chapitre: 109, verset: 4, texte: `En réponse à mon amour, ils m’ont accusé, Alors que je prie (pour eux).` },
  { livre: `Psaumes`, chapitre: 109, verset: 5, texte: `Ils me font du mal pour le bien que je leur fais, Et mon amitié est payée de haine.` },
  { livre: `Psaumes`, chapitre: 109, verset: 6, texte: `Établis sur lui l’autorité d’un méchant! Qu’un accusateur se lève à sa droite!` },
  { livre: `Psaumes`, chapitre: 109, verset: 7, texte: `Que, lors de son jugement, il sorte coupable, Et que sa prière reste sans effet!` },
  { livre: `Psaumes`, chapitre: 109, verset: 8, texte: `Que ses jours soient abrégés, qu’un autre prenne sa charge!` },
  { livre: `Psaumes`, chapitre: 109, verset: 9, texte: `Que ses fils soient orphelins, que sa femme reste veuve,` },
  { livre: `Psaumes`, chapitre: 109, verset: 10, texte: `Que ses enfants soient errants, qu’ils mendient leur pain, Loin de leur demeure en ruines!` },
  { livre: `Psaumes`, chapitre: 109, verset: 11, texte: `Que le créancier prenne tout son bien! Et que des étrangers pillent le produit de son labeur!` },
  { livre: `Psaumes`, chapitre: 109, verset: 12, texte: `Qu’il n’y ait personne qui lui fasse grâce Et qui ait pitié de ses orphelins!` },
  { livre: `Psaumes`, chapitre: 109, verset: 13, texte: `Que ses descendants soient exterminés! Que leur nom soit effacé dans les temps futurs!` },
  { livre: `Psaumes`, chapitre: 109, verset: 14, texte: `Que le péché de ses pères reste présent devant Dieu! Que la faute de sa mère ne soit jamais effacée!` },
  { livre: `Psaumes`, chapitre: 109, verset: 15, texte: `Que leurs crimes soient toujours devant les yeux du Seigneur! Que leur souvenir soit extirpé de la terre!` },
  { livre: `Psaumes`, chapitre: 109, verset: 16, texte: `Car il n’a jamais songé à user de charité Et il a persécuté le malheureux et le pauvre Jusqu’à mettre à mort l’homme au cœur brisé.` },
  { livre: `Psaumes`, chapitre: 109, verset: 17, texte: `Il aimait maudire: la malédiction viendra le frapper. Il refusait de bénir: la bénédiction fuira loin de lui.` },
  { livre: `Psaumes`, chapitre: 109, verset: 18, texte: `Puisqu’il endossait la malédiction comme une tunique, Comme l’eau, qu’elle pénètre au fond de lui-même Et se glisse comme l’huile jusque dans ses os!` },
  { livre: `Psaumes`, chapitre: 109, verset: 19, texte: `Qu’elle soit pour lui comme un vêtement pour l’envelopper, Comme une ceinture qui l’enserre constamment!` },
  { livre: `Psaumes`, chapitre: 109, verset: 20, texte: `C’est ainsi que le Seigneur paiera mes accusateurs Et ceux qui me calomnient.` },
  { livre: `Psaumes`, chapitre: 109, verset: 21, texte: `Mais toi, Seigneur, Éternel, Interviens en ma faveur Pour l’honneur de ton saint nom! Ton amour est si fidèle; oh, délivre-moi!` },
  { livre: `Psaumes`, chapitre: 109, verset: 22, texte: `Je suis malheureux et pauvre Et mon cœur est déchiré au-dedans de moi.` },
  { livre: `Psaumes`, chapitre: 109, verset: 23, texte: `Comme l’ombre à son déclin, je m’évanouis; Tout comme une sauterelle, je suis pourchassé.` },
  { livre: `Psaumes`, chapitre: 109, verset: 24, texte: `Mes genoux sont affaiblis à force de jeûner, Et mon corps est amaigri, il est épuisé.` },
  { livre: `Psaumes`, chapitre: 109, verset: 25, texte: `Je suis, pour (mes ennemis), un sujet de raillerie. Dès qu’ils m’aperçoivent, ils secouent la tête.` },
  { livre: `Psaumes`, chapitre: 109, verset: 26, texte: `Secours-moi, Seigneur mon Dieu! Sauve-moi selon ta grâce!` },
  { livre: `Psaumes`, chapitre: 109, verset: 27, texte: `Que mes ennemis comprennent que c’est ta main, Que c’est toi qui as fait cela.` },
  { livre: `Psaumes`, chapitre: 109, verset: 28, texte: `S’ils maudissent, tu bénis! Ils s’élèvent contre moi, Mais, toi, tu les confondras, et ton serviteur sera dans la joie.` },
  { livre: `Psaumes`, chapitre: 109, verset: 29, texte: `Que mes adversaires soient couverts de déshonneur! Que la honte les revête comme d’un manteau!` },
  { livre: `Psaumes`, chapitre: 109, verset: 30, texte: `Je rendrai grâce au Seigneur, le louant à pleine voix, Et je le célébrerai au milieu des foules,` },
  { livre: `Psaumes`, chapitre: 109, verset: 31, texte: `Car il s’est tenu aux côtés du pauvre Pour le délivrer de ceux qui le condamnaient.` },
  { livre: `Psaumes`, chapitre: 110, verset: 1, texte: `Psaume de David. Parole du Seigneur qui dit à mon Seigneur: «Assieds-toi à ma droite jusqu’à ce que j’aie fait De tous tes ennemis l’escabeau de tes pieds».` },
  { livre: `Psaumes`, chapitre: 110, verset: 2, texte: `L’Éternel étendra de Sion ton pouvoir Et tu domineras parmi tes ennemis.` },
  { livre: `Psaumes`, chapitre: 110, verset: 3, texte: `Au jour de ta puissance, ton peuple est plein d’ardeur Pour accourir vers toi dans leur sainte parure. Et, bien avant l’aurore, Te naîtra la rosée de tes jeunes guerriers.` },
  { livre: `Psaumes`, chapitre: 110, verset: 4, texte: `Le Seigneur l’a juré, il n’en reviendra pas: Tu seras pour toujours un sacrificateur comme Melkisédec.` },
  { livre: `Psaumes`, chapitre: 110, verset: 5, texte: `Le Seigneur, à ta droite, a écrasé des rois au jour de sa colère.` },
  { livre: `Psaumes`, chapitre: 110, verset: 6, texte: `Il juge les nations; les cadavres s’entassent, Il a brisé les chefs dans un vaste pays.` },
  { livre: `Psaumes`, chapitre: 110, verset: 7, texte: `Sur la voie du retour, il boit l’eau du torrent, Voilà pourquoi il marche en relevant la tête.` },
  { livre: `Psaumes`, chapitre: 111, verset: 1, texte: `Célébrez le Seigneur! Je mettrai tout mon cœur à louer le Seigneur Dans l’assemblée des justes et la communauté.` },
  { livre: `Psaumes`, chapitre: 111, verset: 2, texte: `Les œuvres du Seigneur sont pleines de grandeur, Elles font le bonheur de tous ceux qui les aiment.` },
  { livre: `Psaumes`, chapitre: 111, verset: 3, texte: `Ses actes manifestent sa splendeur, son éclat. Sa justice subsiste pour toute éternité.` },
  { livre: `Psaumes`, chapitre: 111, verset: 4, texte: `Il veut qu’on se souvienne de (toutes) ses merveilles. Le Seigneur a pitié, il est compatissant.` },
  { livre: `Psaumes`, chapitre: 111, verset: 5, texte: `Il pourvoit aux besoins de ceux qui le révèrent. Son alliance est toujours présente à sa mémoire.` },
  { livre: `Psaumes`, chapitre: 111, verset: 6, texte: `Il a montré aux siens la force de ses œuvres En léguant l’héritage des nations à son peuple.` },
  { livre: `Psaumes`, chapitre: 111, verset: 7, texte: `Tous ses actes témoignent qu’il est fidèle et juste Et ses commandements sont dignes de confiance,` },
  { livre: `Psaumes`, chapitre: 111, verset: 8, texte: `Ils sont inébranlables pour toute éternité, Fondés sur la justice et sur la vérité.` },
  { livre: `Psaumes`, chapitre: 111, verset: 9, texte: `Il envoie le salut: il délivre son peuple, Et conclut avec lui une alliance éternelle. Le nom de Dieu est saint et il est redoutable.` },
  { livre: `Psaumes`, chapitre: 111, verset: 10, texte: `La crainte du Seigneur Est le commencement de toute vraie sagesse. Qui pratique ses lois est plein d’intelligence. Sa louange subsiste pour toute éternité.` },
  { livre: `Psaumes`, chapitre: 112, verset: 1, texte: `Louez l’Éternel! Bienheureux est l’homme qui craint l’Éternel Et qui trouve son plaisir à mettre en pratique ses commandements.` },
  { livre: `Psaumes`, chapitre: 112, verset: 2, texte: `Sa postérité sera puissante sur terre Et la descendance du juste est bénie.` },
  { livre: `Psaumes`, chapitre: 112, verset: 3, texte: `L’abondance et la richesse régneront dans sa maison, Et sa justice subsiste pour l’éternité.` },
  { livre: `Psaumes`, chapitre: 112, verset: 4, texte: `Au cœur des ténèbres, la lumière s’est levée Pour les hommes droits, Pour l’homme compatissant qui est juste et bienveillant.` },
  { livre: `Psaumes`, chapitre: 112, verset: 5, texte: `Bienheureux est l’homme qui a compassion, Qui partage avec les autres et qui règle ses affaires avec équité,` },
  { livre: `Psaumes`, chapitre: 112, verset: 6, texte: `Car rien ne pourra jamais l’ébranler, Et le souvenir du juste durera toujours.` },
  { livre: `Psaumes`, chapitre: 112, verset: 7, texte: `Il n’a pas à craindre les bruits malveillants. Son cœur est confiant: il s’appuie sur le Seigneur.` },
  { livre: `Psaumes`, chapitre: 112, verset: 8, texte: `Son cœur est plein d’assurance: il n’a point de crainte, Il peut regarder en face (tous) ses adversaires.` },
  { livre: `Psaumes`, chapitre: 112, verset: 9, texte: `Il ouvre ses mains et il distribue largement aux indigents. Et sa justice subsiste pour l’éternité. Honoré de tous, il peut relever la tête.` },
  { livre: `Psaumes`, chapitre: 112, verset: 10, texte: `Le méchant en est témoin: il enrage et il s’aigrit, Il se ronge de dépit, mais les désirs des méchants Seront réduits à néant.` },
  { livre: `Psaumes`, chapitre: 113, verset: 1, texte: `Louez l’Éternel, serviteurs de l’Éternel, louez le nom du Seigneur!` },
  { livre: `Psaumes`, chapitre: 113, verset: 2, texte: `Que le nom de l’Éternel soit béni dès maintenant et à tout jamais!` },
  { livre: `Psaumes`, chapitre: 113, verset: 3, texte: `Du soleil levant jusqu’à son couchant, Que le nom de l’Éternel soit loué (par tous)!` },
  { livre: `Psaumes`, chapitre: 113, verset: 4, texte: `L’Éternel domine toutes les nations. Sa gloire est plus haute que les cieux (des cieux).` },
  { livre: `Psaumes`, chapitre: 113, verset: 5, texte: `Qui est comparable à l’Éternel notre Dieu? Il siège là-haut,` },
  { livre: `Psaumes`, chapitre: 113, verset: 6, texte: `Mais il s’abaisse pour voir le ciel et la terre,` },
  { livre: `Psaumes`, chapitre: 113, verset: 7, texte: `Il redresse l’humble et l’arrache à la poussière, Il relève l’indigent et le tire de la fange,` },
  { livre: `Psaumes`, chapitre: 113, verset: 8, texte: `Pour le faire asseoir avec les grands de son peuple.` },
  { livre: `Psaumes`, chapitre: 113, verset: 9, texte: `Il fait de la femme sans enfants et sans maison Une mère heureuse au milieu de nombreux fils. Louez l’Éternel!` },
  { livre: `Psaumes`, chapitre: 114, verset: 1, texte: `Quand Israël sortit d’Égypte Et quand la maison de Jacob s’éloigna d’un peuple étranger,` },
  { livre: `Psaumes`, chapitre: 114, verset: 2, texte: `Juda devint son sanctuaire et Israël fut son domaine.` },
  { livre: `Psaumes`, chapitre: 114, verset: 3, texte: `La mer le vit et prit la fuite, le Jourdain remonta son cours.` },
  { livre: `Psaumes`, chapitre: 114, verset: 4, texte: `Les montagnes bondirent, ainsi que des béliers. Les collines sautèrent, ainsi que des cabris.` },
  { livre: `Psaumes`, chapitre: 114, verset: 5, texte: `Qu’as-tu, ô mer, pour fuir ainsi? Et toi Jourdain pour refluer?` },
  { livre: `Psaumes`, chapitre: 114, verset: 6, texte: `Et vous, montagnes, à bondir comme des béliers? Et vous, collines, à sauter comme des cabris?` },
  { livre: `Psaumes`, chapitre: 114, verset: 7, texte: `Ô terre, tremble face au Seigneur, face au Dieu de Jacob!` },
  { livre: `Psaumes`, chapitre: 114, verset: 8, texte: `Lui qui change le roc en étang d’eau limpide, Qui transforme la pierre en fontaine d’eau vive.` },
  { livre: `Psaumes`, chapitre: 115, verset: 1, texte: `Non pas à nous, Seigneur, non pas à nous, Mais à ton nom rends gloire, À cause de ta grâce et de ta vérité!` },
  { livre: `Psaumes`, chapitre: 115, verset: 2, texte: `Pourquoi les païens diraient-ils: «Où est leur Dieu»?` },
  { livre: `Psaumes`, chapitre: 115, verset: 3, texte: `Notre Dieu est au ciel, il fait ce qui lui plaît.` },
  { livre: `Psaumes`, chapitre: 115, verset: 4, texte: `Les idoles des peuples, c’est de l’argent, de l’or, Ouvrages de mains d’hommes:` },
  { livre: `Psaumes`, chapitre: 115, verset: 5, texte: `Elles ont une bouche, oui, mais ne parlent pas! Elles ont bien deux yeux, mais elles ne voient pas!` },
  { livre: `Psaumes`, chapitre: 115, verset: 6, texte: `Elles ont deux oreilles, mais qui n’entendent pas! Elles ont bien un nez, oui, mais ne sentent rien!` },
  { livre: `Psaumes`, chapitre: 115, verset: 7, texte: `Elles ont bien deux mains, mais ne peuvent saisir! Elles ont bien deux pieds, mais ne peuvent marcher, Et leur gosier n’émet aucun murmure!` },
  { livre: `Psaumes`, chapitre: 115, verset: 8, texte: `Ils leur ressemblent bien ceux qui les confectionnent, Tous ceux qui se confient en elles.` },
  { livre: `Psaumes`, chapitre: 115, verset: 9, texte: `Toi, Israël, fais confiance au Seigneur! Il est pour toi secours et bouclier.` },
  { livre: `Psaumes`, chapitre: 115, verset: 10, texte: `Maison d’Aaron, fais confiance au Seigneur! Il est pour toi secours et bouclier.` },
  { livre: `Psaumes`, chapitre: 115, verset: 11, texte: `Vous tous qui l’adorez, comptez sur le Seigneur! Il est pour vous secours et bouclier.` },
  { livre: `Psaumes`, chapitre: 115, verset: 12, texte: `Le Seigneur se souvient de nous pour nous bénir. Oui, qu’il bénisse le peuple d’Israël! Et qu’il bénisse la famille d’Aaron!` },
  { livre: `Psaumes`, chapitre: 115, verset: 13, texte: `Et qu’il bénisse ceux qui adorent Dieu, Tous les petits aussi bien que les grands!` },
  { livre: `Psaumes`, chapitre: 115, verset: 14, texte: `Que le Seigneur vous multiplie ses dons pour vous et vos enfants!` },
  { livre: `Psaumes`, chapitre: 115, verset: 15, texte: `Soyez bénis par le Seigneur qui a fait les cieux et la terre!` },
  { livre: `Psaumes`, chapitre: 115, verset: 16, texte: `Les cieux sont les cieux du Seigneur, Il a donné la terre aux hommes.` },
  { livre: `Psaumes`, chapitre: 115, verset: 17, texte: `Les morts ne louent pas le Seigneur Ni aucun de ceux qui descendent au pays du silence.` },
  { livre: `Psaumes`, chapitre: 115, verset: 18, texte: `Mais nous, nous les vivants, bénissons le Seigneur, Dès maintenant et à jamais. Alléluia!` },
  { livre: `Psaumes`, chapitre: 116, verset: 1, texte: `Oui, j’aime le Seigneur, Car il entend ma voix et mes supplications,` },
  { livre: `Psaumes`, chapitre: 116, verset: 2, texte: `Car il a incliné son oreille vers moi, Et je l’invoquerai tous les jours de ma vie.` },
  { livre: `Psaumes`, chapitre: 116, verset: 3, texte: `Les lacets de la mort m’avaient enveloppé, Les filets de l’abîme m’avaient déjà saisi, Je n’avais en partage que chagrin et angoisse.` },
  { livre: `Psaumes`, chapitre: 116, verset: 4, texte: `Alors, j’ai appelé le Seigneur par son nom: «Ah! Seigneur, je te prie, viens délivrer mon âme!»` },
  { livre: `Psaumes`, chapitre: 116, verset: 5, texte: `Le Seigneur (nous) fait grâce et notre Dieu est juste. Il est compatissant.` },
  { livre: `Psaumes`, chapitre: 116, verset: 6, texte: `Il défend les petits, car j’étais misérable: le Seigneur m’a sauvé.` },
  { livre: `Psaumes`, chapitre: 116, verset: 7, texte: `Retourne à ton repos, mon âme, car l’Éternel t’a fait du bien.` },
  { livre: `Psaumes`, chapitre: 116, verset: 8, texte: `Oui, tu as délivré mon âme de la mort, Tu as séché mes pleurs et tu as préservé mes pieds de toute chute.` },
  { livre: `Psaumes`, chapitre: 116, verset: 9, texte: `Je marcherai encore en présence de Dieu au pays des vivants.` },
  { livre: `Psaumes`, chapitre: 116, verset: 10, texte: `J’ai gardé confiance, c’est pourquoi j’ai parlé, Quoique bien malheureux!` },
  { livre: `Psaumes`, chapitre: 116, verset: 11, texte: `Dans mon agitation, j’en venais à me dire: «Tout, dans l’homme, est trompeur!»` },
  { livre: `Psaumes`, chapitre: 116, verset: 12, texte: `Comment rendre au Seigneur tout ce qu’il m’a donné?` },
  { livre: `Psaumes`, chapitre: 116, verset: 13, texte: `J’élèverai la coupe du salut, J’invoquerai le nom de l’Éternel.` },
  { livre: `Psaumes`, chapitre: 116, verset: 14, texte: `J’accomplirai les vœux, que j’ai faits au Seigneur À la vue de son peuple.` },
  { livre: `Psaumes`, chapitre: 116, verset: 15, texte: `Il en coûte au Seigneur de voir mourir les siens.` },
  { livre: `Psaumes`, chapitre: 116, verset: 16, texte: `Écoute, ô Éternel, je suis ton serviteur. Je suis ton serviteur, le fils de ta servante, Tu as brisé mes chaînes.` },
  { livre: `Psaumes`, chapitre: 116, verset: 17, texte: `Aussi je veux t’offrir, Seigneur, le sacrifice de la reconnaissance, J’invoquerai ton nom,` },
  { livre: `Psaumes`, chapitre: 116, verset: 18, texte: `J’accomplirai les vœux, Que j’ai faits au Seigneur, à la vue de son peuple,` },
  { livre: `Psaumes`, chapitre: 116, verset: 19, texte: `Dans les parvis du temple de l’Éternel, Au cœur de ton enceinte, Jérusalem! Célébrez le Seigneur!` },
  { livre: `Psaumes`, chapitre: 117, verset: 1, texte: `Louez le Seigneur, toutes les nations! Et célébrez-le, ô vous, tous les peuples,` },
  { livre: `Psaumes`, chapitre: 117, verset: 2, texte: `Car sa bienveillance pour nous est puissante. Sa fidélité demeure à jamais. Louez le Seigneur!` },
  { livre: `Psaumes`, chapitre: 118, verset: 1, texte: `Célébrez l’Éternel, Car l’Éternel est bon, Car son amour est éternel!` },
  { livre: `Psaumes`, chapitre: 118, verset: 2, texte: `Oui, que la maison d’Israël proclame maintenant: Oui, son amour est éternel!` },
  { livre: `Psaumes`, chapitre: 118, verset: 3, texte: `Que la maison d’Aaron proclame maintenant: Oui, son amour est éternel!` },
  { livre: `Psaumes`, chapitre: 118, verset: 4, texte: `Que ceux qui craignent l’Éternel proclament maintenant: Oui, son amour est éternel!` },
  { livre: `Psaumes`, chapitre: 118, verset: 5, texte: `Du fond de ma détresse, j’invoquai l’Éternel, Et il m’a répondu en me mettant au large.` },
  { livre: `Psaumes`, chapitre: 118, verset: 6, texte: `L’Éternel est pour moi, Je n’ai donc rien à craindre, Que m’importent les hommes, Quel mal me feraient-ils?` },
  { livre: `Psaumes`, chapitre: 118, verset: 7, texte: `L’Éternel est mon aide, Aussi je peux braver tous ceux qui me haïssent.` },
  { livre: `Psaumes`, chapitre: 118, verset: 8, texte: `Mieux vaut se réfugier auprès de l’Éternel Que de se confier aux hommes d’ici-bas.` },
  { livre: `Psaumes`, chapitre: 118, verset: 9, texte: `Mieux vaut se réfugier auprès de l’Éternel Que de se confier aux grands de cette terre.` },
  { livre: `Psaumes`, chapitre: 118, verset: 10, texte: `Tous les peuples païens m’encerclaient de partout: Au nom de l’Éternel, je les repousserai.` },
  { livre: `Psaumes`, chapitre: 118, verset: 11, texte: `Ils m’avaient encerclé, m’enserrant de partout: Au nom de l’Éternel, je les repousserai.` },
  { livre: `Psaumes`, chapitre: 118, verset: 12, texte: `Ils m’avaient encerclé comme un essaim d’abeilles, Mais ils sont consumés comme un feu de broussailles: Au nom de l’Éternel, je les repousserai.` },
  { livre: `Psaumes`, chapitre: 118, verset: 13, texte: `On m’avait bousculé pour me faire tomber, L’Éternel m’a aidé.` },
  { livre: `Psaumes`, chapitre: 118, verset: 14, texte: `L’Éternel est ma force et l’objet de mes chants: C’est lui qui m’a sauvé.` },
  { livre: `Psaumes`, chapitre: 118, verset: 15, texte: `Des chants de délivrance et de triomphe Éclatent dans les tentes des justes: La droite du Seigneur accomplit des exploits,` },
  { livre: `Psaumes`, chapitre: 118, verset: 16, texte: `La droite du Seigneur remporte la victoire, La droite du Seigneur accomplit des exploits.` },
  { livre: `Psaumes`, chapitre: 118, verset: 17, texte: `Non, je ne mourrai pas, je resterai en vie Pour publier bien haut les œuvres du Seigneur!` },
  { livre: `Psaumes`, chapitre: 118, verset: 18, texte: `Le Seigneur m’a châtié avec sévérité, Mais il n’a pas voulu me livrer à la mort.` },
  { livre: `Psaumes`, chapitre: 118, verset: 19, texte: `Ouvrez-moi donc les portes, celles de la justice, Afin que j’y pénètre pour louer le Seigneur.` },
  { livre: `Psaumes`, chapitre: 118, verset: 20, texte: `C’est ici qu’est la porte du Seigneur Et, par elle, les justes passeront.` },
  { livre: `Psaumes`, chapitre: 118, verset: 21, texte: `Je viens te célébrer, Car tu m’as répondu et tu es mon salut.` },
  { livre: `Psaumes`, chapitre: 118, verset: 22, texte: `La pierre rejetée par ceux qui bâtissaient Est devenue la pierre principale de l’angle.` },
  { livre: `Psaumes`, chapitre: 118, verset: 23, texte: `C’est l’œuvre du Seigneur, un miracle à nos yeux.` },
  { livre: `Psaumes`, chapitre: 118, verset: 24, texte: `C’est ici la journée que l’Éternel a faite, Vivons-la dans la joie, Exultons d’allégresse!` },
  { livre: `Psaumes`, chapitre: 118, verset: 25, texte: `De grâce, ô Éternel, Délivre-nous toujours! De grâce, ô Éternel, Donne-nous le succès!` },
  { livre: `Psaumes`, chapitre: 118, verset: 26, texte: `Oui, béni soit qui vient au nom de l’Éternel! Oui, nous vous bénissons de la maison de Dieu!` },
  { livre: `Psaumes`, chapitre: 118, verset: 27, texte: `L’Éternel (seul) est Dieu, C’est lui qui nous éclaire. Attachez les branchages au cortège de fête, Jusqu’auprès de l’autel.` },
  { livre: `Psaumes`, chapitre: 118, verset: 28, texte: `Dieu fort, tu es mon Dieu, Je veux te célébrer, t’exalter, ô mon Dieu!` },
  { livre: `Psaumes`, chapitre: 118, verset: 29, texte: `Célébrez l’Éternel, Car l’Éternel est bon Et son amour est éternel!` },
  { livre: `Psaumes`, chapitre: 119, verset: 1, texte: `Heureux tous ceux qui marchent sans reproche En suivant la loi du Seigneur.` },
  { livre: `Psaumes`, chapitre: 119, verset: 2, texte: `Heureux tous ceux qui respectent ses règles En les cherchant de tout leur cœur.` },
  { livre: `Psaumes`, chapitre: 119, verset: 3, texte: `Ils ne commettent pas le mal, ils suivent ses chemins.` },
  { livre: `Psaumes`, chapitre: 119, verset: 4, texte: `Tu as toi-même commandé de respecter fidèlement Les ordres que tu as donnés.` },
  { livre: `Psaumes`, chapitre: 119, verset: 5, texte: `Que mes chemins soient assurés Pour que j’observe tes préceptes!` },
  { livre: `Psaumes`, chapitre: 119, verset: 6, texte: `Alors, je n’aurai pas de honte Lorsque je considérerai tous tes commandements.` },
  { livre: `Psaumes`, chapitre: 119, verset: 7, texte: `Je te célébrerai dans la droiture de mon cœur Lorsque j’aurai appris tes justes décisions.` },
  { livre: `Psaumes`, chapitre: 119, verset: 8, texte: `J’observerai fidèlement tes prescriptions. Ne m’abandonne pas entièrement!` },
  { livre: `Psaumes`, chapitre: 119, verset: 9, texte: `Comment avoir dès sa jeunesse une conduite pure? En prenant garde à ta parole.` },
  { livre: `Psaumes`, chapitre: 119, verset: 10, texte: `Je t’ai cherché de tout mon cœur, Ne permets pas que je m’égare en fuyant tes commandements!` },
  { livre: `Psaumes`, chapitre: 119, verset: 11, texte: `Je porte tes promesses cachées au fond du cœur Pour ne pas pécher contre toi.` },
  { livre: `Psaumes`, chapitre: 119, verset: 12, texte: `Béni sois-tu, Seigneur! Enseigne-moi tes volontés!` },
  { livre: `Psaumes`, chapitre: 119, verset: 13, texte: `Mes lèvres ont énuméré tous les décrets Prononcés par ta bouche.` },
  { livre: `Psaumes`, chapitre: 119, verset: 14, texte: `J’ai plus de joie à suivre tes préceptes Qu’à posséder tous les trésors.` },
  { livre: `Psaumes`, chapitre: 119, verset: 15, texte: `Je médite tes ordres, je contemple tes voies.` },
  { livre: `Psaumes`, chapitre: 119, verset: 16, texte: `Je trouve mon plaisir dans tes préceptes Et je ne veux jamais oublier ta parole.` },
  { livre: `Psaumes`, chapitre: 119, verset: 17, texte: `Fais du bien à ton serviteur, Accorde-lui de vivre en gardant ta parole!` },
  { livre: `Psaumes`, chapitre: 119, verset: 18, texte: `Ouvre mes yeux pour que je voie les beautés de ta loi!` },
  { livre: `Psaumes`, chapitre: 119, verset: 19, texte: `Je suis étranger sur la terre: Dévoile-moi le sens de tes commandements!` },
  { livre: `Psaumes`, chapitre: 119, verset: 20, texte: `Mon âme, à chaque instant, Est rongée du désir qui la porte vers tes préceptes.` },
  { livre: `Psaumes`, chapitre: 119, verset: 21, texte: `Tu repousses les orgueilleux, Ces maudits qui s’écartent de tes commandements.` },
  { livre: `Psaumes`, chapitre: 119, verset: 22, texte: `Éloigne de moi l’opprobre et le mépris, car j’ai gardé tes règles!` },
  { livre: `Psaumes`, chapitre: 119, verset: 23, texte: `Quand même des puissants s’uniraient contre moi, Ton serviteur encore méditerait tes lois.` },
  { livre: `Psaumes`, chapitre: 119, verset: 24, texte: `Tes ordres font tout mon plaisir, ils sont mes meilleurs conseillers.` },
  { livre: `Psaumes`, chapitre: 119, verset: 25, texte: `Mon âme colle à la poussière, rends-moi la vie par ta parole!` },
  { livre: `Psaumes`, chapitre: 119, verset: 26, texte: `Je t’ai soumis mes voies, et tu m’as répondu: Apprends-moi tes statuts!` },
  { livre: `Psaumes`, chapitre: 119, verset: 27, texte: `Fais-moi comprendre le sens de tes préceptes Pour que je réfléchisse à tes merveilles!` },
  { livre: `Psaumes`, chapitre: 119, verset: 28, texte: `Ma vie est remplie de tristesse, relève-moi par ta parole!` },
  { livre: `Psaumes`, chapitre: 119, verset: 29, texte: `Détourne-moi des chemins de mensonge Et, dans ta grâce, fais que je vive selon ta loi!` },
  { livre: `Psaumes`, chapitre: 119, verset: 30, texte: `J’ai choisi le chemin de la fidélité, je me suis aligné sur tes décrets.` },
  { livre: `Psaumes`, chapitre: 119, verset: 31, texte: `Je me tiens attaché à tes édits, Seigneur: Que je ne sois pas confondu!` },
  { livre: `Psaumes`, chapitre: 119, verset: 32, texte: `Je veux courir sur le chemin de tes commandements, Puisque tu mets mon cœur à l’aise.` },
  { livre: `Psaumes`, chapitre: 119, verset: 33, texte: `Seigneur, enseigne-moi la voie de tes décrets, Je les suivrai pas à pas jusqu’au bout.` },
  { livre: `Psaumes`, chapitre: 119, verset: 34, texte: `Fais-moi comprendre comment garder ta loi; Je la tiendrai de tout mon cœur.` },
  { livre: `Psaumes`, chapitre: 119, verset: 35, texte: `Fais-moi marcher sur le sentier de tes commandements, Car je m’y plais!` },
  { livre: `Psaumes`, chapitre: 119, verset: 36, texte: `Fais que mon cœur incline vers tes règles, et non pas vers le gain!` },
  { livre: `Psaumes`, chapitre: 119, verset: 37, texte: `Détourne mes regards des choses vaines, Et fais-moi vivre selon tes voies!` },
  { livre: `Psaumes`, chapitre: 119, verset: 38, texte: `Accomplis tes promesses envers ton serviteur; Elles sont pour ceux qui te craignent.` },
  { livre: `Psaumes`, chapitre: 119, verset: 39, texte: `Écarte loin de moi l’opprobre dont j’ai peur, Toi, dont les jugements sont bienfaisants!` },
  { livre: `Psaumes`, chapitre: 119, verset: 40, texte: `J’ai la passion de tes préceptes, vivifie-moi par ta justice!` },
  { livre: `Psaumes`, chapitre: 119, verset: 41, texte: `Que ton amour, Seigneur, vienne sur moi, Et ton salut, tel que tu l’as promis!` },
  { livre: `Psaumes`, chapitre: 119, verset: 42, texte: `Alors, je pourrai répliquer à celui qui m’outrage, Car j’ai mis mon espoir en ta parole.` },
  { livre: `Psaumes`, chapitre: 119, verset: 43, texte: `Ne retire pas de ma bouche la parole de vérité, Car j’ai mis mon espoir en tes enseignements.` },
  { livre: `Psaumes`, chapitre: 119, verset: 44, texte: `J’observerai ta loi toujours et à jamais,` },
  { livre: `Psaumes`, chapitre: 119, verset: 45, texte: `Et je pourrai marcher dans la vraie liberté, Car je recherche tes statuts.` },
  { livre: `Psaumes`, chapitre: 119, verset: 46, texte: `Je rendrai témoignage à tes préceptes Devant des rois, sans avoir à rougir.` },
  { livre: `Psaumes`, chapitre: 119, verset: 47, texte: `Je ferai mes délices de tes commandements que j’aime tant.` },
  { livre: `Psaumes`, chapitre: 119, verset: 48, texte: `Je tends les mains vers tes commandements que je chéris. Je veux méditer tes préceptes.` },
  { livre: `Psaumes`, chapitre: 119, verset: 49, texte: `Veuille te souvenir de ta parole En faveur de ton serviteur, car tu m’as donné l’espérance:` },
  { livre: `Psaumes`, chapitre: 119, verset: 50, texte: `Elle a été mon réconfort dans mon chagrin, Ta promesse m’a fait revivre.` },
  { livre: `Psaumes`, chapitre: 119, verset: 51, texte: `Des orgueilleux se sont beaucoup moqués de moi, Je n’ai pas dévié de ta loi.` },
  { livre: `Psaumes`, chapitre: 119, verset: 52, texte: `Je me souviens de tes jugements d’autrefois, Seigneur, j’en suis réconforté.` },
  { livre: `Psaumes`, chapitre: 119, verset: 53, texte: `Je suis troublé de voir les impies délaisser ta loi.` },
  { livre: `Psaumes`, chapitre: 119, verset: 54, texte: `J’ai fait de tes lois mon cantique dans ma demeure passagère.` },
  { livre: `Psaumes`, chapitre: 119, verset: 55, texte: `La nuit, Seigneur, j’ai ton nom en mémoire pour observer ta loi.` },
  { livre: `Psaumes`, chapitre: 119, verset: 56, texte: `Voici le bien qui m’appartient: C’est de me conformer à tes commandements.` },
  { livre: `Psaumes`, chapitre: 119, verset: 57, texte: `Mon lot, Seigneur, je l’ai promis, c’est d’obéir à ta parole.` },
  { livre: `Psaumes`, chapitre: 119, verset: 58, texte: `J’ai cherché ta faveur de tout mon cœur; Que, selon ta promesse, tu me sois favorable!` },
  { livre: `Psaumes`, chapitre: 119, verset: 59, texte: `J’examine mes voies et je règle mes pas d’après tes exigences.` },
  { livre: `Psaumes`, chapitre: 119, verset: 60, texte: `Je me suis empressé, je n’ai pas différé d’observer tes préceptes.` },
  { livre: `Psaumes`, chapitre: 119, verset: 61, texte: `Les filets des méchants m’ont entouré sans que j’oublie ta loi.` },
  { livre: `Psaumes`, chapitre: 119, verset: 62, texte: `Je me lève au cœur de la nuit afin de te louer pour tes justes décrets.` },
  { livre: `Psaumes`, chapitre: 119, verset: 63, texte: `Je suis le compagnon de tous ceux Qui t’adorent et pratiquent tes lois.` },
  { livre: `Psaumes`, chapitre: 119, verset: 64, texte: `Seigneur, la terre entière est comblée de ta grâce, Apprends-moi tes statuts!` },
  { livre: `Psaumes`, chapitre: 119, verset: 65, texte: `Tu as traité avec bonté ton serviteur, Conformément à ta promesse, ô Éternel!` },
  { livre: `Psaumes`, chapitre: 119, verset: 66, texte: `Apprends-moi le discernement et la sagesse, Car j’ai foi en tes ordres!` },
  { livre: `Psaumes`, chapitre: 119, verset: 67, texte: `Avant d’être humilié, je faisais fausse route, Mais maintenant, j’observe ta parole.` },
  { livre: `Psaumes`, chapitre: 119, verset: 68, texte: `Que tu es bon et bienfaisant: instruis-moi dans tes volontés!` },
  { livre: `Psaumes`, chapitre: 119, verset: 69, texte: `Des orgueilleux m’accablent de mensonges, Mais moi, de tout mon cœur, je garde tes préceptes.` },
  { livre: `Psaumes`, chapitre: 119, verset: 70, texte: `Leur cœur est insensible comme la graisse. Moi, je fais mes délices de ton enseignement.` },
  { livre: `Psaumes`, chapitre: 119, verset: 71, texte: `Il m’était bon d’être humilié afin d’apprendre À mieux connaître tes volontés.` },
  { livre: `Psaumes`, chapitre: 119, verset: 72, texte: `Les enseignements de ta bouche Sont plus précieux pour moi que mille objets d’or et d’argent.` },
  { livre: `Psaumes`, chapitre: 119, verset: 73, texte: `Tes mains m’ont façonné, m’ont affermi, Rends-moi intelligent pour que j’apprenne tes prescriptions!` },
  { livre: `Psaumes`, chapitre: 119, verset: 74, texte: `En me voyant, ceux qui t’adorent se réjouiront, Car je m’attends à ta parole.` },
  { livre: `Psaumes`, chapitre: 119, verset: 75, texte: `Je sais, Seigneur, que tes décrets sont justes: Si tu m’as humilié, c’est par fidélité.` },
  { livre: `Psaumes`, chapitre: 119, verset: 76, texte: `Que ton amour soit ma consolation Conformément à la promesse faite à ton serviteur!` },
  { livre: `Psaumes`, chapitre: 119, verset: 77, texte: `Que ta miséricorde pénètre en moi pour que je vive, Car ton enseignement fait mes délices.` },
  { livre: `Psaumes`, chapitre: 119, verset: 78, texte: `Qu’ils soient confus, les orgueilleux qui, à tort, me maltraitent! Moi, je médite sur tes décrets.` },
  { livre: `Psaumes`, chapitre: 119, verset: 79, texte: `Que ceux qui te respectent se retournent vers moi, Ceux qui connaissent tes statuts!` },
  { livre: `Psaumes`, chapitre: 119, verset: 80, texte: `Que mon cœur soit intègre pour suivre tes préceptes, Pour que je ne sois pas confus!` },
  { livre: `Psaumes`, chapitre: 119, verset: 81, texte: `Mon âme se consume et languit dans l’attente de ton salut, J’espère en ta parole.` },
  { livre: `Psaumes`, chapitre: 119, verset: 82, texte: `Mes yeux se sont usés à sonder tes promesses Pendant que je me dis: «Quand viendras-tu me consoler?»` },
  { livre: `Psaumes`, chapitre: 119, verset: 83, texte: `Je suis mis au rebut comme une outre enfumée, Pourtant, je n’oublie pas tes ordonnances.` },
  { livre: `Psaumes`, chapitre: 119, verset: 84, texte: `Combien ton serviteur a-t-il de jours à vivre? Quand donc vas-tu juger ceux qui me persécutent?` },
  { livre: `Psaumes`, chapitre: 119, verset: 85, texte: `Vois: des orgueilleux creusent Des pièges pour me perdre au mépris de ta loi.` },
  { livre: `Psaumes`, chapitre: 119, verset: 86, texte: `Dans tes commandements, tout est fidélité. Viens donc à mon secours: des menteurs me poursuivent!` },
  { livre: `Psaumes`, chapitre: 119, verset: 87, texte: `Il s’en fallait de peu qu’ils ne m’aient terrassé, Moi qui n’avais pas délaissé tes ordonnances.` },
  { livre: `Psaumes`, chapitre: 119, verset: 88, texte: `Vivifie-moi dans ton amour pour que j’observe Les ordres de ta bouche!` },
  { livre: `Psaumes`, chapitre: 119, verset: 89, texte: `Ta parole, Seigneur, est éternelle et immuable comme les cieux!` },
  { livre: `Psaumes`, chapitre: 119, verset: 90, texte: `Ta vérité demeure de siècle en siècle. Tu as fondé la terre afin qu’elle subsiste.` },
  { livre: `Psaumes`, chapitre: 119, verset: 91, texte: `Selon tes ordonnances, tout subsiste aujourd’hui, Car l’univers entier doit te servir.` },
  { livre: `Psaumes`, chapitre: 119, verset: 92, texte: `Si ton enseignement n’eût pas fait mes délices, J’aurais depuis longtemps péri dans ma misère.` },
  { livre: `Psaumes`, chapitre: 119, verset: 93, texte: `Jamais, durant ma vie, je n’oublierai tes ordres, Car c’est par eux que tu me vivifies.` },
  { livre: `Psaumes`, chapitre: 119, verset: 94, texte: `Je suis à toi: viens me sauver! Car je m’applique à suivre tes préceptes:` },
  { livre: `Psaumes`, chapitre: 119, verset: 95, texte: `Des méchants escomptent ma perte, Moi, je réfléchis à tes ordres.` },
  { livre: `Psaumes`, chapitre: 119, verset: 96, texte: `J’ai bien vu des limites à toute œuvre parfaite, Mais ton commandement est d’une ampleur sans fin.` },
  { livre: `Psaumes`, chapitre: 119, verset: 97, texte: `Combien j’aime ta loi! Je la médite tout le jour.` },
  { livre: `Psaumes`, chapitre: 119, verset: 98, texte: `Ton ordre me rend sage plus que mes ennemis Car je fais miennes pour toujours tes volontés.` },
  { livre: `Psaumes`, chapitre: 119, verset: 99, texte: `Je suis plus avisé que tous mes maîtres Parce que je médite tes exigences.` },
  { livre: `Psaumes`, chapitre: 119, verset: 100, texte: `Je suis plus sage que des vieillards en respectant tes règles.` },
  { livre: `Psaumes`, chapitre: 119, verset: 101, texte: `J’ai retenu mes pas, loin des mauvais sentiers Afin de suivre ta parole.` },
  { livre: `Psaumes`, chapitre: 119, verset: 102, texte: `Je ne me suis pas écarté de tes décrets, car tu m’as éclairé.` },
  { livre: `Psaumes`, chapitre: 119, verset: 103, texte: `Quelle douceur je trouve à ta parole! Elle est meilleure que le miel.` },
  { livre: `Psaumes`, chapitre: 119, verset: 104, texte: `J’ai puisé mon savoir dans tes préceptes, Aussi, je hais toute voie mensongère.` },
  { livre: `Psaumes`, chapitre: 119, verset: 105, texte: `Ta parole est une lumière qui éclaire mes pas, Elle est la lampe qui rayonne illuminant ma route.` },
  { livre: `Psaumes`, chapitre: 119, verset: 106, texte: `J’ai promis solennellement – et je tiendrai promesse – D’observer tes justes sentences.` },
  { livre: `Psaumes`, chapitre: 119, verset: 107, texte: `Je suis plongé dans la misère; Comme le promet ta parole, Seigneur, vivifie-moi!` },
  { livre: `Psaumes`, chapitre: 119, verset: 108, texte: `Accueille avec faveur, Seigneur, l’offrande de ma bouche Et enseigne-moi tes décrets!` },
  { livre: `Psaumes`, chapitre: 119, verset: 109, texte: `Ma vie est sans cesse en danger, mais je n’oublie rien de ta loi.` },
  { livre: `Psaumes`, chapitre: 119, verset: 110, texte: `Des impies m’ont tendu des pièges, Mais je ne dévie pas de tes commandements.` },
  { livre: `Psaumes`, chapitre: 119, verset: 111, texte: `Tes préceptes sont pour jamais mon héritage: Ils font le bonheur de ma vie.` },
  { livre: `Psaumes`, chapitre: 119, verset: 112, texte: `J’ai incliné mon cœur à observer tes lois toujours, jusqu’à la fin.` },
  { livre: `Psaumes`, chapitre: 119, verset: 113, texte: `Je hais les indécis, mais j’aime ton enseignement.` },
  { livre: `Psaumes`, chapitre: 119, verset: 114, texte: `Tu es mon rempart, mon refuge, et ta parole est mon espoir.` },
  { livre: `Psaumes`, chapitre: 119, verset: 115, texte: `Éloignez-vous de moi, méchants, laissez-moi observer Les ordres de mon Dieu!` },
  { livre: `Psaumes`, chapitre: 119, verset: 116, texte: `Soutiens-moi selon ta promesse pour que je vive, Ne déçois pas mon espérance!` },
  { livre: `Psaumes`, chapitre: 119, verset: 117, texte: `Sois mon appui pour que je sois sauvé, Et je contemplerai sans cesse tes prescriptions.` },
  { livre: `Psaumes`, chapitre: 119, verset: 118, texte: `Tu renverses avec mépris ceux qui s’écartent de tes lois, Car leur pensée n’est que mensonge.` },
  { livre: `Psaumes`, chapitre: 119, verset: 119, texte: `Tu ôtes comme des scories tous les réprouvés de la terre, Aussi, je m’attache à tes ordres.` },
  { livre: `Psaumes`, chapitre: 119, verset: 120, texte: `L’effroi que tu m’inspires fait frissonner ma chair, Devant tes décisions, j’adore.` },
  { livre: `Psaumes`, chapitre: 119, verset: 121, texte: `J’ai agi selon la droiture et la justice; Ne m’abandonne pas à mes persécuteurs!` },
  { livre: `Psaumes`, chapitre: 119, verset: 122, texte: `Accorde ta caution à ton serviteur pour son bien. Ne laisse pas les arrogants me torturer!` },
  { livre: `Psaumes`, chapitre: 119, verset: 123, texte: `Mes yeux languissent après ta délivrance et ta parole de justice.` },
  { livre: `Psaumes`, chapitre: 119, verset: 124, texte: `Agis envers ton serviteur selon ta grâce Et apprends-moi tes volontés!` },
  { livre: `Psaumes`, chapitre: 119, verset: 125, texte: `Je suis ton serviteur: Donne-moi du discernement pour comprendre tes ordres!` },
  { livre: `Psaumes`, chapitre: 119, verset: 126, texte: `Pour toi, Seigneur, le temps d’agir est arrivé, Car on viole tes décrets.` },
  { livre: `Psaumes`, chapitre: 119, verset: 127, texte: `Mais moi, j’aime tes volontés bien plus que l’or le plus précieux.` },
  { livre: `Psaumes`, chapitre: 119, verset: 128, texte: `C’est pourquoi je me règle d’après tous tes préceptes, Et c’est pourquoi je hais tout chemin de mensonge.` },
  { livre: `Psaumes`, chapitre: 119, verset: 129, texte: `Je suis émerveillé par tes enseignements, Aussi, je veux les observer.` },
  { livre: `Psaumes`, chapitre: 119, verset: 130, texte: `Quand on découvre tes paroles, c’est la lumière, Et les simples comprennent.` },
  { livre: `Psaumes`, chapitre: 119, verset: 131, texte: `La bouche grandement ouverte, J’aspire avec avidité tes prescriptions.` },
  { livre: `Psaumes`, chapitre: 119, verset: 132, texte: `De grâce, tourne-toi vers moi Comme tu le fais d’habitude envers ceux qui aiment ton nom!` },
  { livre: `Psaumes`, chapitre: 119, verset: 133, texte: `Que tes promesses affermissent mes pas Pour qu’aucun mal ne domine sur moi!` },
  { livre: `Psaumes`, chapitre: 119, verset: 134, texte: `Libère-moi de l’oppression des hommes Pour que je puisse observer tes préceptes!` },
  { livre: `Psaumes`, chapitre: 119, verset: 135, texte: `Que, pour ton serviteur, ta face s’illumine, Et apprends-moi tes volontés!` },
  { livre: `Psaumes`, chapitre: 119, verset: 136, texte: `Mes yeux versent des flots de larmes, car on n’observe pas ta loi.` },
  { livre: `Psaumes`, chapitre: 119, verset: 137, texte: `Éternel, tu es juste, et tes sentences sont équitables.` },
  { livre: `Psaumes`, chapitre: 119, verset: 138, texte: `Tu as fondé tous tes décrets sur la justice, Ils sont tout à fait infaillibles.` },
  { livre: `Psaumes`, chapitre: 119, verset: 139, texte: `Mon zèle me consumera, car ceux qui s’opposent à moi Mettent en oubli tes paroles.` },
  { livre: `Psaumes`, chapitre: 119, verset: 140, texte: `Tes ordres sont à toute épreuve, Aussi ton serviteur les aime avec ferveur.` },
  { livre: `Psaumes`, chapitre: 119, verset: 141, texte: `Je suis petit et méprisé, mais je n’oublie pas tes préceptes.` },
  { livre: `Psaumes`, chapitre: 119, verset: 142, texte: `Ta justice est juste à jamais, et ta loi n’est que vérité.` },
  { livre: `Psaumes`, chapitre: 119, verset: 143, texte: `Malgré la détresse et l’angoisse qui ont fondu sur moi, Tes volontés font mes délices.` },
  { livre: `Psaumes`, chapitre: 119, verset: 144, texte: `Tes règles sont à toujours justes, Donne-moi du discernement pour que je vive!` },
  { livre: `Psaumes`, chapitre: 119, verset: 145, texte: `Je crie vers toi du fond du cœur, Éternel, réponds-moi, Je voudrais observer tes lois.` },
  { livre: `Psaumes`, chapitre: 119, verset: 146, texte: `Quand je t’appelle, sauve-moi, pour que je suive tes préceptes!` },
  { livre: `Psaumes`, chapitre: 119, verset: 147, texte: `Je me lève avant l’aube pour implorer ton aide, J’ai foi en tes paroles.` },
  { livre: `Psaumes`, chapitre: 119, verset: 148, texte: `Avant que la nuit ne finisse, Mes yeux sont déjà éveillés pour réfléchir sur ta promesse.` },
  { livre: `Psaumes`, chapitre: 119, verset: 149, texte: `Dans ton amour, écoute-moi, Seigneur, Et fais-moi vivre selon tes ordonnances!` },
  { livre: `Psaumes`, chapitre: 119, verset: 150, texte: `Ceux qui poursuivent l’infamie sont maintenant tout près de moi, Ils sont étrangers à ta loi;` },
  { livre: `Psaumes`, chapitre: 119, verset: 151, texte: `Mais toi aussi, Seigneur, tu te tiens près de moi, Tous tes commandements ne sont que vérité.` },
  { livre: `Psaumes`, chapitre: 119, verset: 152, texte: `Je sais depuis longtemps que tu as établi tes ordres pour toujours.` },
  { livre: `Psaumes`, chapitre: 119, verset: 153, texte: `Regarde ma misère, sauve-moi du danger! Car moi, je n’oublie pas ta loi.` },
  { livre: `Psaumes`, chapitre: 119, verset: 154, texte: `Plaide ma cause et défends-moi, Fais-moi revivre par ta promesse!` },
  { livre: `Psaumes`, chapitre: 119, verset: 155, texte: `La salut est loin des impies, car ils négligent tes décrets.` },
  { livre: `Psaumes`, chapitre: 119, verset: 156, texte: `Seigneur, ta tendresse est immense, fais-moi vivre selon ta loi!` },
  { livre: `Psaumes`, chapitre: 119, verset: 157, texte: `Mes ennemis sont innombrables, mes persécuteurs me harcèlent, Mais je ne me détourne pas de tes enseignements.` },
  { livre: `Psaumes`, chapitre: 119, verset: 158, texte: `Je vois avec dégoût des traîtres qui n’observent pas ta parole.` },
  { livre: `Psaumes`, chapitre: 119, verset: 159, texte: `Mais vois, Seigneur, combien j’aime tes ordres: Vivifie-moi selon ta grâce!` },
  { livre: `Psaumes`, chapitre: 119, verset: 160, texte: `La vérité de ta parole est primordiale, Tous les décrets de ta justice sont éternels.` },
  { livre: `Psaumes`, chapitre: 119, verset: 161, texte: `Des puissants m’ont persécuté sans cause ni raison, Mais mon cœur n’a tremblé que devant tes paroles.` },
  { livre: `Psaumes`, chapitre: 119, verset: 162, texte: `Je me réjouis de tes promesses comme on trouve un grand butin.` },
  { livre: `Psaumes`, chapitre: 119, verset: 163, texte: `Je hais le mal, je le déteste; j’aime ta loi.` },
  { livre: `Psaumes`, chapitre: 119, verset: 164, texte: `Sept fois par jour, je redis tes louanges pour les décrets de ta justice.` },
  { livre: `Psaumes`, chapitre: 119, verset: 165, texte: `Grande est la paix des amis de ta loi: Aucun obstacle ne les fera tomber.` },
  { livre: `Psaumes`, chapitre: 119, verset: 166, texte: `Ô Éternel, j’espère en ton salut, Et j’obéis à tes commandements.` },
  { livre: `Psaumes`, chapitre: 119, verset: 167, texte: `J’ai observé tes volontés, car je les aime infiniment.` },
  { livre: `Psaumes`, chapitre: 119, verset: 168, texte: `Je veux garder tes prescriptions et tes statuts: Tous mes chemins sont sous tes yeux.` },
  { livre: `Psaumes`, chapitre: 119, verset: 169, texte: `Seigneur, que ma prière parvienne jusqu’à toi! Rends-moi intelligent conformément à ta parole!` },
  { livre: `Psaumes`, chapitre: 119, verset: 170, texte: `Que ma supplication accède en ta présence! Délivre-moi comme tu l’as promis!` },
  { livre: `Psaumes`, chapitre: 119, verset: 171, texte: `Que la louange jaillisse de mes lèvres, Car tu m’enseignes tes volontés.` },
  { livre: `Psaumes`, chapitre: 119, verset: 172, texte: `Ma langue entonne un hymne à ta promesse, Car tout est équité dans tes commandements.` },
  { livre: `Psaumes`, chapitre: 119, verset: 173, texte: `Étends ta main, viens à mon aide, car j’ai choisi tes prescriptions.` },
  { livre: `Psaumes`, chapitre: 119, verset: 174, texte: `Je suis tendu vers ton salut, ô Éternel! Tout mon plaisir est dans ta loi.` },
  { livre: `Psaumes`, chapitre: 119, verset: 175, texte: `Fais que je vive pour te louer! Et que tes jugements soient mon appui!` },
  { livre: `Psaumes`, chapitre: 119, verset: 176, texte: `J’étais errant comme une brebis égarée; Oh! viens chercher ton serviteur! Car je n’oublie jamais tes volontés.` },
  { livre: `Psaumes`, chapitre: 120, verset: 1, texte: `Cantique des pèlerinages. Vers le Seigneur, dans ma détresse, J’ai appelé, et il m’a répondu.` },
  { livre: `Psaumes`, chapitre: 120, verset: 2, texte: `Ô Éternel, délivre-moi des lèvres fausses, Des langues mensongères!` },
  { livre: `Psaumes`, chapitre: 120, verset: 3, texte: `De quel profit, et de quel avantage Sont-elles donc, ces langues mensongères?` },
  { livre: `Psaumes`, chapitre: 120, verset: 4, texte: `Ce sont des flèches bien aiguisées d’un homme armé, Mêlées de braises et de genêts tout embrasés.` },
  { livre: `Psaumes`, chapitre: 120, verset: 5, texte: `Malheur à moi, car mon exil s’est prolongé dans le pays lointain! Je vis parmi les tentes de Kédar.` },
  { livre: `Psaumes`, chapitre: 120, verset: 6, texte: `Bien trop longtemps j’ai habité Parmi des gens qui détestent la paix.` },
  { livre: `Psaumes`, chapitre: 120, verset: 7, texte: `Je veux la paix, mais quand j’en parle, Eux, ils sont pour la guerre.` },
  { livre: `Psaumes`, chapitre: 121, verset: 1, texte: `Cantique des pèlerinages. Je lève les yeux vers les monts. D’où viendra le secours?` },
  { livre: `Psaumes`, chapitre: 121, verset: 2, texte: `Mon secours vient de l’Éternel qui a fait le ciel et la terre.` },
  { livre: `Psaumes`, chapitre: 121, verset: 3, texte: `Il ne permettra pas que ton pied vienne à trébucher, Car celui qui te garde ne sommeille jamais.` },
  { livre: `Psaumes`, chapitre: 121, verset: 4, texte: `Non, jamais il ne dort, jamais il ne sommeille, le gardien d’Israël.` },
  { livre: `Psaumes`, chapitre: 121, verset: 5, texte: `Le Seigneur est ton protecteur, le Seigneur est ton ombre, Il est à ta main droite,` },
  { livre: `Psaumes`, chapitre: 121, verset: 6, texte: `Et le soleil, durant le jour, ne te frappera pas, Ni la lune pendant la nuit.` },
  { livre: `Psaumes`, chapitre: 121, verset: 7, texte: `L’Éternel te préservera de tout malheur: il veille sur ton âme.` },
  { livre: `Psaumes`, chapitre: 121, verset: 8, texte: `Le Seigneur veillera sur ton départ et ton retour, Dès maintenant et à jamais.` },
  { livre: `Psaumes`, chapitre: 122, verset: 1, texte: `Cantique des pèlerinages. De David. Je suis dans la joie lorsque l’on me dit: Nous allons monter à la maison du Seigneur!` },
  { livre: `Psaumes`, chapitre: 122, verset: 2, texte: `Oui, nos pas s’arrêtent devant tes portiques, ô Jérusalem!` },
  { livre: `Psaumes`, chapitre: 122, verset: 3, texte: `Ô Jérusalem, toi qui es bâtie comme une cité, Avec harmonie, avec unité!` },
  { livre: `Psaumes`, chapitre: 122, verset: 4, texte: `C’est là qu’affluent les tribus; oui, les tribus du Seigneur! C’est la loi en Israël d’y célébrer le Seigneur en louant son nom.` },
  { livre: `Psaumes`, chapitre: 122, verset: 5, texte: `C’est là que sont établis les sièges du jugement Et c’est là que règne la famille de David.` },
  { livre: `Psaumes`, chapitre: 122, verset: 6, texte: `Priez pour la paix de Jérusalem, Et que ceux qui t’aiment soient heureux dans le repos!` },
  { livre: `Psaumes`, chapitre: 122, verset: 7, texte: `Que la paix soit dans tes murs Et que la prospérité règne en tes palais!` },
  { livre: `Psaumes`, chapitre: 122, verset: 8, texte: `Pour mes frères, mes amis, je me plais à dire: «Que la paix soit avec toi!»` },
  { livre: `Psaumes`, chapitre: 122, verset: 9, texte: `À cause de la maison de l’Éternel, notre Dieu, Je souhaite ton bonheur.` },
  { livre: `Psaumes`, chapitre: 123, verset: 1, texte: `Cantique des pèlerinages. J’ai levé mes yeux vers toi, toi qui sièges dans les cieux.` },
  { livre: `Psaumes`, chapitre: 123, verset: 2, texte: `Voici, tels des serviteurs Qui gardent leurs yeux fixés sur la main de leur seigneur, Comme une servante fixe ses regards sur la main de sa maîtresse, Ainsi nos regards se tournent vers le Seigneur, notre Dieu, Dans l’attente de sa grâce.` },
  { livre: `Psaumes`, chapitre: 123, verset: 3, texte: `Aie pitié de nous, Seigneur! Use de grâce envers nous! Car nous en avons assez du mépris qu’on nous témoigne.` },
  { livre: `Psaumes`, chapitre: 123, verset: 4, texte: `Oui, notre âme est saturée des insultes des prospères Et du mépris des hautains.` },
  { livre: `Psaumes`, chapitre: 124, verset: 1, texte: `Cantique des pèlerinages. De David. Si le Seigneur n’avait pas été avec nous – Israël peut le dire –` },
  { livre: `Psaumes`, chapitre: 124, verset: 2, texte: `Si le Seigneur n’avait pas été avec nous, Lorsque des hommes sont venus contre nous pour nous attaquer,` },
  { livre: `Psaumes`, chapitre: 124, verset: 3, texte: `Alors, ils nous auraient engloutis tout vivants Dans l’ardeur de leur rage déchaînée contre nous.` },
  { livre: `Psaumes`, chapitre: 124, verset: 4, texte: `Le flot nous aurait entraînés et, comme un torrent débordant, Il aurait passé sur notre âme.` },
  { livre: `Psaumes`, chapitre: 124, verset: 5, texte: `Alors, des eaux tumultueuses nous auraient submergés.` },
  { livre: `Psaumes`, chapitre: 124, verset: 6, texte: `Béni soit le Seigneur, lui qui ne leur a pas permis De nous déchirer de leurs dents!` },
  { livre: `Psaumes`, chapitre: 124, verset: 7, texte: `Nous avons pu nous échapper comme un passereau libéré du filet des chasseurs: le filet s’est rompu et nous nous sommes libérés.` },
  { livre: `Psaumes`, chapitre: 124, verset: 8, texte: `Notre secours est dans le nom de l’Éternel Qui a fait le ciel et la terre.` },
  { livre: `Psaumes`, chapitre: 125, verset: 1, texte: `Cantique des pèlerinages. Ceux qui s’appuient sur le Seigneur sont semblables au mont Sion: Il est inébranlable et demeure à jamais.` },
  { livre: `Psaumes`, chapitre: 125, verset: 2, texte: `Comme Jérusalem a des montagnes autour d’elle, Ainsi le Seigneur Dieu entoure aussi son peuple, Dès maintenant et pour l’éternité.` },
  { livre: `Psaumes`, chapitre: 125, verset: 3, texte: `Il ne permettra pas qu’un pouvoir sacrilège Fasse peser son poids sur le destin des justes, Pour qu’ils n’en viennent pas À étendre leurs mains vers des actions coupables.` },
  { livre: `Psaumes`, chapitre: 125, verset: 4, texte: `Seigneur, accorde ta faveur À ceux qui font du bien et qui sont droits de cœur!` },
  { livre: `Psaumes`, chapitre: 125, verset: 5, texte: `Mais ceux qui se détournent vers des voies tortueuses, Que le Seigneur les chasse avec les malfaiteurs! Que la paix soit sur Israël!` },
  { livre: `Psaumes`, chapitre: 126, verset: 1, texte: `Cantique des pèlerinages. Quand Dieu a ramené les captifs de Sion, Nous étions en plein rêve.` },
  { livre: `Psaumes`, chapitre: 126, verset: 2, texte: `Soudain, notre bouche s’emplit de chants joyeux, Notre langue exultait. Alors, on se disait dans les autres nations: «Le Seigneur fait pour eux des choses merveilleuses!»` },
  { livre: `Psaumes`, chapitre: 126, verset: 3, texte: `Oui, le Seigneur a fait pour nous de grandes choses: Nous sommes dans la joie.` },
  { livre: `Psaumes`, chapitre: 126, verset: 4, texte: `Seigneur, fais revenir ceux qui restent captifs, Comme les torrents coulent soudain dans le Midi.` },
  { livre: `Psaumes`, chapitre: 126, verset: 5, texte: `Qui sème dans les larmes moissonne dans la joie!` },
  { livre: `Psaumes`, chapitre: 126, verset: 6, texte: `Qui s’en va tout en pleurs En portant sa semence qu’il lance à la volée, Revient rempli de joie et chantant d’allégresse Quand il porte ses gerbes.` },
  { livre: `Psaumes`, chapitre: 127, verset: 1, texte: `Cantique des pèlerinages. De Salomon. Si la maison n’est pas bâtie par le Seigneur, Les bâtisseurs peinent en vain. Si le Seigneur ne garde pas la ville, la garde veille en vain.` },
  { livre: `Psaumes`, chapitre: 127, verset: 2, texte: `Oui, il est vain de vous lever matin et de vous coucher tard Pour gagner dans la peine un bout de pain. Car (Dieu) en donne autant à celui qu’il chérit pendant qu’il dort.` },
  { livre: `Psaumes`, chapitre: 127, verset: 3, texte: `Voyez, des fils sont bien un héritage donné par l’Éternel, Et leur naissance est une récompense.` },
  { livre: `Psaumes`, chapitre: 127, verset: 4, texte: `Ils sont comme les flèches dans la main d’un héros, Les fils de la jeunesse.` },
  { livre: `Psaumes`, chapitre: 127, verset: 5, texte: `Bienheureux l’homme bien armé dont le carquois en est rempli! Il ne sera jamais confus en plaidant contre l’ennemi Aux portes de la ville.` },
  { livre: `Psaumes`, chapitre: 128, verset: 1, texte: `Cantique des pèlerinages. Heureux quiconque adore Dieu et marche dans ses voies!` },
  { livre: `Psaumes`, chapitre: 128, verset: 2, texte: `Oui, tu te nourriras du travail de tes mains, tout ira bien pour toi,` },
  { livre: `Psaumes`, chapitre: 128, verset: 3, texte: `Dans ton foyer, ta femme sera comme une vigne chargée de fruits, Et, autour de ta table, tes fils ressembleront aux rameaux d’olivier.` },
  { livre: `Psaumes`, chapitre: 128, verset: 4, texte: `Ainsi sera béni tout homme qui craint Dieu.` },
  { livre: `Psaumes`, chapitre: 128, verset: 5, texte: `Que du mont de Sion le Seigneur te bénisse Et que tu puisses voir Jérusalem heureuse tous les jours de ta vie!` },
  { livre: `Psaumes`, chapitre: 128, verset: 6, texte: `Que tu voies les enfants de tes (propres) enfants! Que la paix soit sur Israël!` },
  { livre: `Psaumes`, chapitre: 129, verset: 1, texte: `Cantique des pèlerinages. Depuis ma jeunesse, on m’a combattu. Qu’Israël le dise:` },
  { livre: `Psaumes`, chapitre: 129, verset: 2, texte: `Depuis ma jeunesse, on m’a combattu, Mais ils n’ont pas pu l’emporter sur moi.` },
  { livre: `Psaumes`, chapitre: 129, verset: 3, texte: `Ils ont labouré mon dos, en y traçant leurs sillons.` },
  { livre: `Psaumes`, chapitre: 129, verset: 4, texte: `Le Seigneur est juste et il a brisé le joug des méchants.` },
  { livre: `Psaumes`, chapitre: 129, verset: 5, texte: `Qu’ils soient confondus et qu’ils battent en retraite, Tous les ennemis de Jérusalem.` },
  { livre: `Psaumes`, chapitre: 129, verset: 6, texte: `Qu’ils soient comme l’herbe poussant sur les toits Et qui se dessèche avant qu’on l’arrache,` },
  { livre: `Psaumes`, chapitre: 129, verset: 7, texte: `Dont le moissonneur n’emplit pas sa main, Ni celui qui glane ne fait de brassée,` },
  { livre: `Psaumes`, chapitre: 129, verset: 8, texte: `Pour que nul passant ne puisse leur dire: «Que Dieu vous bénisse! Nous vous bénissons au nom du Seigneur».` },
  { livre: `Psaumes`, chapitre: 130, verset: 1, texte: `Cantique des pèlerinages. Du fond des profondeurs, je crie vers toi, Seigneur.` },
  { livre: `Psaumes`, chapitre: 130, verset: 2, texte: `Seigneur, entends ma voix! Incline ton oreille vers ma voix suppliante!` },
  { livre: `Psaumes`, chapitre: 130, verset: 3, texte: `Si tu gardais le compte de nos fautes, Seigneur, Éternel, qui pourrait subsister devant toi?` },
  { livre: `Psaumes`, chapitre: 130, verset: 4, texte: `Voici que le pardon se trouve auprès de toi Afin que l’on t’adore.` },
  { livre: `Psaumes`, chapitre: 130, verset: 5, texte: `J’espère en l’Éternel, mon âme espère en lui, Comptant sur sa parole.` },
  { livre: `Psaumes`, chapitre: 130, verset: 6, texte: `Je guette l’Éternel bien plus que les guetteurs N’attendent le matin, Oui, plus que les guetteurs n’attendent le matin.` },
  { livre: `Psaumes`, chapitre: 130, verset: 7, texte: `Ô Israël, mets ton espoir en l’Éternel, Car il dispose de la grâce: On trouve auprès de lui la pleine délivrance.` },
  { livre: `Psaumes`, chapitre: 130, verset: 8, texte: `Lui seul rachètera Israël de ses fautes.` },
  { livre: `Psaumes`, chapitre: 131, verset: 1, texte: `Cantique des pèlerinages. De David. Seigneur, Mon cœur ne s’enfle pas d’orgueil, Mes yeux n’ont pas visé trop haut, Je n’ai pas poursuivi des objectifs trop vastes, Trop merveilleux pour moi.` },
  { livre: `Psaumes`, chapitre: 131, verset: 2, texte: `Bien au contraire: je tiens mon âme dans le calme Et j’ai fait taire mes désirs. Comme un nourrisson rassasié dans les bras de sa mère, Telle est mon âme en moi.` },
  { livre: `Psaumes`, chapitre: 131, verset: 3, texte: `Israël, mets ton espérance en l’Éternel, Dès maintenant et pour toujours.` },
  { livre: `Psaumes`, chapitre: 132, verset: 1, texte: `Cantique des pèlerinages. Ô Éternel, rappelle-toi David et toutes ses souffrances` },
  { livre: `Psaumes`, chapitre: 132, verset: 2, texte: `Quand il fit ce serment au Seigneur Éternel, Qu’il adressa ce vœu au Puissant de Jacob:` },
  { livre: `Psaumes`, chapitre: 132, verset: 3, texte: `Je ne veux pas entrer chez moi dans ma demeure, Je ne veux pas monter sur mon lit de repos,` },
  { livre: `Psaumes`, chapitre: 132, verset: 4, texte: `Je ne veux pas donner repos à mes paupières Ni sommeil à mes yeux,` },
  { livre: `Psaumes`, chapitre: 132, verset: 5, texte: `Avant d’avoir trouvé un lieu pour le Seigneur Et une résidence au Puissant de Jacob.` },
  { livre: `Psaumes`, chapitre: 132, verset: 6, texte: `Oui, on nous a parlé de l’arche à Ephrata, Nous l’avons retrouvée dans les champs de Jaar.` },
  { livre: `Psaumes`, chapitre: 132, verset: 7, texte: `Allons jusqu’à l’endroit où l’Éternel demeure! Venez, prosternons-nous devant son piédestal!` },
  { livre: `Psaumes`, chapitre: 132, verset: 8, texte: `Lève-toi, ô Seigneur, et viens vers ta demeure! Oh! viens avec ton arche où réside ta force!` },
  { livre: `Psaumes`, chapitre: 132, verset: 9, texte: `Que tes prêtres revêtent leurs vêtements de fête, Que tes adorateurs poussent des cris de joie!` },
  { livre: `Psaumes`, chapitre: 132, verset: 10, texte: `Pour l’amour de David qui fut ton serviteur, N’écarte pas le roi que tu as consacré!` },
  { livre: `Psaumes`, chapitre: 132, verset: 11, texte: `Dieu a fait à David ce serment véridique, Il ne reviendra pas sur ce qu’il a promis: «Je mettrai sur ton trône un fils issu de toi.` },
  { livre: `Psaumes`, chapitre: 132, verset: 12, texte: `Si tes enfants observent mon alliance et ma règle Que je leur ai données, leurs propres fils aussi Siégeront sur ton trône à toujours, à jamais».` },
  { livre: `Psaumes`, chapitre: 132, verset: 13, texte: `Parce que le Seigneur a fait choix de Sion, Oui, il l’a désirée pour son habitation:` },
  { livre: `Psaumes`, chapitre: 132, verset: 14, texte: `«C’est mon lieu de repos pour les siècles des siècles. Là, je résiderai, car je l’ai désiré.` },
  { livre: `Psaumes`, chapitre: 132, verset: 15, texte: `Oui, je les bénirai et je les comblerai d’abondantes ressources. Je donnerai du pain aux pauvres parmi eux.` },
  { livre: `Psaumes`, chapitre: 132, verset: 16, texte: `Je vêtirai ses prêtres d’un manteau de salut. Et ses adorateurs exulteront de joie.` },
  { livre: `Psaumes`, chapitre: 132, verset: 17, texte: `Je ferai refleurir la race de David, Et je préparerai le flambeau de mon Oint.` },
  { livre: `Psaumes`, chapitre: 132, verset: 18, texte: `Mais tous ses ennemis seront couverts de honte, Alors que, sur son front, brillera sa couronne».` },
  { livre: `Psaumes`, chapitre: 133, verset: 0, texte: `Cantique des pèlerinages. De David. Oh! Quel plaisir et quel bonheur Lorsque des frères sont à demeure unis ensemble!` },
  { livre: `Psaumes`, chapitre: 133, verset: 1, texte: `C’est comme l’huile parfumée répandue sur la tête, Qui descend sur la barbe, sur la barbe d’Aaron, Et coule jusqu’au bord de son manteau.` },
  { livre: `Psaumes`, chapitre: 133, verset: 2, texte: `C’est comme la rosée qui descend de l’Hermon, Sur le mont de Sion.` },
  { livre: `Psaumes`, chapitre: 133, verset: 3, texte: `C’est là que le Seigneur accorde sa bénédiction Et la vie, pour toujours.` },
  { livre: `Psaumes`, chapitre: 134, verset: 1, texte: `Cantique des pèlerinages. Bénissez le Seigneur, Vous tous, ses serviteurs, Vous qui restez debout Tout au long de la nuit Au temple du Seigneur!` },
  { livre: `Psaumes`, chapitre: 134, verset: 2, texte: `Que, dans la sainteté, Vos mains soient élevées Pour bénir le Seigneur!` },
  { livre: `Psaumes`, chapitre: 134, verset: 3, texte: `Oui, que depuis Sion, Le Seigneur te bénisse, Lui qui a fait les cieux Et qui a fait la terre.` },
  { livre: `Psaumes`, chapitre: 135, verset: 1, texte: `Loué soit le Seigneur! Célébrez le nom du Seigneur! Louez-le, vous ses serviteurs,` },
  { livre: `Psaumes`, chapitre: 135, verset: 2, texte: `Vous qui veillez dans sa maison, dans les parvis de notre Dieu!` },
  { livre: `Psaumes`, chapitre: 135, verset: 3, texte: `Loué soit le Seigneur, car le Seigneur est bon! Célébrez sur la harpe la gloire de son nom, car il est favorable!` },
  { livre: `Psaumes`, chapitre: 135, verset: 4, texte: `Le Seigneur s’est choisi (la maison de) Jacob, Israël est son bien.` },
  { livre: `Psaumes`, chapitre: 135, verset: 5, texte: `Je sais, en vérité, que l’Éternel est grand Et que notre Seigneur domine tous les dieux.` },
  { livre: `Psaumes`, chapitre: 135, verset: 6, texte: `Le Seigneur accomplit toutes ses volontés au ciel et sur la terre, Sur la mer et dans les abîmes.` },
  { livre: `Psaumes`, chapitre: 135, verset: 7, texte: `Des confins de la terre, il fait monter les brumes. Il forge les éclairs au milieu de la pluie, Il déchaîne le vent qu’il tenait en réserve.` },
  { livre: `Psaumes`, chapitre: 135, verset: 8, texte: `C’est lui qui a frappé les premiers-nés d’Égypte Depuis les hommes jusqu’au bétail.` },
  { livre: `Psaumes`, chapitre: 135, verset: 9, texte: `Il a réalisé des signes, des prodiges, en plein cœur de l’Égypte Contre le pharaon et tous ses serviteurs.` },
  { livre: `Psaumes`, chapitre: 135, verset: 10, texte: `C’est lui qui a frappé de nombreuses nations Et qui a fait périr des souverains puissants:` },
  { livre: `Psaumes`, chapitre: 135, verset: 11, texte: `Sihon, roi Amorite et Og, roi de Basan, et tous les rois de Canaan.` },
  { livre: `Psaumes`, chapitre: 135, verset: 12, texte: `Puis il donna leurs terres en héritage à Israël son peuple.` },
  { livre: `Psaumes`, chapitre: 135, verset: 13, texte: `Seigneur, ton nom demeure pour toute éternité. Seigneur, ton souvenir durera d’âge en âge.` },
  { livre: `Psaumes`, chapitre: 135, verset: 14, texte: `Car (Dieu notre) Seigneur fait justice à son peuple Et il a compassion de (tous) ses serviteurs.` },
  { livre: `Psaumes`, chapitre: 135, verset: 15, texte: `Les idoles des peuples, c’est de l’argent, de l’or, Ouvrage de mains d’hommes:` },
  { livre: `Psaumes`, chapitre: 135, verset: 16, texte: `Elles ont une bouche, oui, mais ne parlent pas, Et elles ont deux yeux, mais elles ne voient pas;` },
  { livre: `Psaumes`, chapitre: 135, verset: 17, texte: `Elles ont deux oreilles, mais qui n’entendent pas. Il n’y a pas de souffle qui anime leur bouche.` },
  { livre: `Psaumes`, chapitre: 135, verset: 18, texte: `Ils leur ressemblent bien, ceux qui les confectionnent, Tous ceux qui se confient en elles.` },
  { livre: `Psaumes`, chapitre: 135, verset: 19, texte: `Ô maison d’Israël, bénissez le Seigneur! Et vous, maison d’Aaron, bénissez le Seigneur!` },
  { livre: `Psaumes`, chapitre: 135, verset: 20, texte: `Vous, maison de Lévi, bénissez le Seigneur! Vous tous qui l’adorez, bénissez le Seigneur!` },
  { livre: `Psaumes`, chapitre: 135, verset: 21, texte: `Béni soit le Seigneur depuis le mont Sion, Le Seigneur dont le trône est à Jérusalem! Loué soit le Seigneur!` },
  { livre: `Psaumes`, chapitre: 136, verset: 1, texte: `Célébrez le Seigneur, Car il est bon, car son amour est éternel.` },
  { livre: `Psaumes`, chapitre: 136, verset: 2, texte: `Louez le Dieu des dieux, Car son amour est éternel.` },
  { livre: `Psaumes`, chapitre: 136, verset: 3, texte: `Louez, rendez hommage au Seigneur des seigneurs, Car son amour est éternel.` },
  { livre: `Psaumes`, chapitre: 136, verset: 4, texte: `Lui seul fait des miracles et de grandes merveilles, Car son amour est éternel.` },
  { livre: `Psaumes`, chapitre: 136, verset: 5, texte: `Il a créé les cieux avec intelligence, Car son amour est éternel.` },
  { livre: `Psaumes`, chapitre: 136, verset: 6, texte: `Il a fondé la terre en la gagnant sur l’eau, Car son amour est éternel.` },
  { livre: `Psaumes`, chapitre: 136, verset: 7, texte: `Il a fait les étoiles, tous les grands luminaires, Car son amour est éternel.` },
  { livre: `Psaumes`, chapitre: 136, verset: 8, texte: `Il a fait le soleil pour gouverner le jour, Car son amour est éternel.` },
  { livre: `Psaumes`, chapitre: 136, verset: 9, texte: `La lune et tous les astres pour gouverner la nuit, Car son amour est éternel.` },
  { livre: `Psaumes`, chapitre: 136, verset: 10, texte: `Il a frappé l’Égypte avec ses premiers-nés, Car son amour est éternel.` },
  { livre: `Psaumes`, chapitre: 136, verset: 11, texte: `Et il a fait sortir Israël de chez eux, Car son amour est éternel.` },
  { livre: `Psaumes`, chapitre: 136, verset: 12, texte: `Par une main puissante et un bras étendu, Car son amour est éternel.` },
  { livre: `Psaumes`, chapitre: 136, verset: 13, texte: `Il fendit la mer Rouge et la coupa en deux, Car son amour est éternel.` },
  { livre: `Psaumes`, chapitre: 136, verset: 14, texte: `Il la fit traverser par Israël (son peuple), Car son amour est éternel.` },
  { livre: `Psaumes`, chapitre: 136, verset: 15, texte: `Il lança dans ses flots l’armée du pharaon, Car son amour est éternel.` },
  { livre: `Psaumes`, chapitre: 136, verset: 16, texte: `Il dirigea son peuple à travers le désert, Car son amour est éternel.` },
  { livre: `Psaumes`, chapitre: 136, verset: 17, texte: `Il frappa de grands rois (et des princes puissants,) Car son amour est éternel.` },
  { livre: `Psaumes`, chapitre: 136, verset: 18, texte: `Il fit périr des rois, des rois majestueux, Car son amour est éternel.` },
  { livre: `Psaumes`, chapitre: 136, verset: 19, texte: `Il fit périr Sihon le roi des Amorites, Car son amour est éternel.` },
  { livre: `Psaumes`, chapitre: 136, verset: 20, texte: `Et il fit périr Og – Og, le roi de Basan, Car son amour est éternel.` },
  { livre: `Psaumes`, chapitre: 136, verset: 21, texte: `Il donna leur pays, leur terre en héritage, Car son amour est éternel,` },
  { livre: `Psaumes`, chapitre: 136, verset: 22, texte: `Au peuple d’Israël qui est son serviteur, Car son amour est éternel.` },
  { livre: `Psaumes`, chapitre: 136, verset: 23, texte: `Dans notre humiliation, il se souvint de nous, Car son amour est éternel.` },
  { livre: `Psaumes`, chapitre: 136, verset: 24, texte: `Il nous a délivrés de (tous) nos ennemis, Car son amour est éternel.` },
  { livre: `Psaumes`, chapitre: 136, verset: 25, texte: `Il distribue le pain à tout être vivant, Car son amour est éternel.` },
  { livre: `Psaumes`, chapitre: 136, verset: 26, texte: `Célébrez, glorifiez le Dieu (qui règne) aux cieux Car son amour est éternel.` },
  { livre: `Psaumes`, chapitre: 137, verset: 1, texte: `Au bord des fleuves de Babylone, Nous nous étions assis et nous pleurions en pensant à Sion.` },
  { livre: `Psaumes`, chapitre: 137, verset: 2, texte: `Aux saules de leurs rives, nous suspendions nos harpes.` },
  { livre: `Psaumes`, chapitre: 137, verset: 3, texte: `Car là-bas nos vainqueurs nous réclamaient des chants, Ceux qui nous opprimaient voulaient des airs joyeux: «Chantez-nous, disaient-ils, des hymnes de Sion!»` },
  { livre: `Psaumes`, chapitre: 137, verset: 4, texte: `Comment peut-on chanter Les hymnes du Seigneur sur un sol étranger?` },
  { livre: `Psaumes`, chapitre: 137, verset: 5, texte: `Si jamais je t’oublie, ô toi, Jérusalem, que ma droite m’oublie!` },
  { livre: `Psaumes`, chapitre: 137, verset: 6, texte: `Oui, je veux que ma langue se colle à mon palais Si je ne pense plus à toi, Jérusalem. Si je ne te mets plus avant toute autre joie.` },
  { livre: `Psaumes`, chapitre: 137, verset: 7, texte: `Souviens-toi, ô Seigneur, des fils d’Édom, Et de ce jour où, à Jérusalem, ils s’écriaient: «Détruisez-la! Détruisez-la! Rasez-la jusqu’aux fondations!»` },
  { livre: `Psaumes`, chapitre: 137, verset: 8, texte: `Ô Babylone! Tu seras dévastée! Heureux qui te rendra ce que tu nous as fait!` },
  { livre: `Psaumes`, chapitre: 137, verset: 9, texte: `Heureux qui saisira tes nourrissons Pour les briser contre le roc!` },
  { livre: `Psaumes`, chapitre: 138, verset: 1, texte: `De David. Je te célèbre de tout mon cœur, et, devant Dieu, je veux chanter.` },
  { livre: `Psaumes`, chapitre: 138, verset: 2, texte: `Je me prosterne dans ton saint temple Et je célèbre ton nom, (Seigneur,) Pour ton amour et pour ta fidélité, Car tu as réalisé tout ce que tu as promis dans ta parole Et ton renom s’est accru au-dessus de toutes choses.` },
  { livre: `Psaumes`, chapitre: 138, verset: 3, texte: `Le jour où j’ai appelé, tu m’as répondu, (Seigneur,) Tu m’as donné du courage.` },
  { livre: `Psaumes`, chapitre: 138, verset: 4, texte: `Que tous les rois de la terre te rendent grâces, Seigneur, En entendant tes promesses!` },
  { livre: `Psaumes`, chapitre: 138, verset: 5, texte: `Et qu’ils célèbrent toutes les voies du Seigneur! Grande est la gloire de l’Éternel!` },
  { livre: `Psaumes`, chapitre: 138, verset: 6, texte: `Si haut que soit le Seigneur, Il voit les humbles, mais il repère de loin les orgueilleux.` },
  { livre: `Psaumes`, chapitre: 138, verset: 7, texte: `Lorsque je marche dans la détresse, C’est toi qui me fais revivre, Ta main s’abat sur la furie de mes rivaux, Et ta puissance me sauve.` },
  { livre: `Psaumes`, chapitre: 138, verset: 8, texte: `Le Seigneur me soutiendra, il agira en ma faveur. Seigneur, ta grâce dure toujours. Ne laisse pas inachevé ce que tes mains ont œuvré!` },
  { livre: `Psaumes`, chapitre: 139, verset: 1, texte: `Au chef de chœur. Psaume de David. Seigneur, tu me sondes et tu me connais,` },
  { livre: `Psaumes`, chapitre: 139, verset: 2, texte: `Tu sais tout de moi: que je sois assis ou que je me lève. Tu comprends de loin tout ce que je pense.` },
  { livre: `Psaumes`, chapitre: 139, verset: 3, texte: `Tu sais quand je marche et quand je me couche, Et tous mes chemins te sont familiers.` },
  { livre: `Psaumes`, chapitre: 139, verset: 4, texte: `Avant que ma langue dise une parole, Déjà, ô Seigneur, tu la connaissais entièrement.` },
  { livre: `Psaumes`, chapitre: 139, verset: 5, texte: `Tu es devant moi et derrière moi: Partout tu m’entoures, tu étends ta main sur moi (et me gardes).` },
  { livre: `Psaumes`, chapitre: 139, verset: 6, texte: `Merveilleux savoir hors de ma portée, Savoir trop sublime: je ne puis l’atteindre.` },
  { livre: `Psaumes`, chapitre: 139, verset: 7, texte: `Où pourrais-je aller loin de ton Esprit? Où pourrais-je fuir hors de ta présence?` },
  { livre: `Psaumes`, chapitre: 139, verset: 8, texte: `Si je monte aux cieux, tu es déjà là, Et si je descends au séjour des morts, t’y voilà encore.` },
  { livre: `Psaumes`, chapitre: 139, verset: 9, texte: `Et si j’endossais les ailes de l’aube Pour me réfugier aux confins des mers,` },
  { livre: `Psaumes`, chapitre: 139, verset: 10, texte: `Là aussi ta main me dirigerait, Ta droite pourrait s’emparer de moi.` },
  { livre: `Psaumes`, chapitre: 139, verset: 11, texte: `Et si je me dis: du moins les ténèbres m’envelopperont, Alors, la nuit même se change en lumière tout autour de moi.` },
  { livre: `Psaumes`, chapitre: 139, verset: 12, texte: `Car l’obscurité n’a plus rien d’obscur pour toi, (ô Seigneur). La nuit resplendit comme le plein jour: Lumière ou ténèbres, c’est pareil pour toi.` },
  { livre: `Psaumes`, chapitre: 139, verset: 13, texte: `Tu as façonné mon corps tout entier Quand tu m’as tissé au sein de ma mère.` },
  { livre: `Psaumes`, chapitre: 139, verset: 14, texte: `Je veux te louer d’avoir fait de moi Une créature extraordinaire et si admirable: Tu fais des merveilles, et mon être entier le reconnaît bien.` },
  { livre: `Psaumes`, chapitre: 139, verset: 15, texte: `Mon corps n’était pas caché devant toi Quand, dans le mystère, je fus façonné Dans les lieux secrets au sein de la terre.` },
  { livre: `Psaumes`, chapitre: 139, verset: 16, texte: `Je n’étais encore qu’une masse informe, Mais tu me voyais, et, dans ton (grand) livre, Chacun de ces jours que tu me destines Étaient tous inscrits avant que l’un d’eux ne vienne à paraître.` },
  { livre: `Psaumes`, chapitre: 139, verset: 17, texte: `Mais pour moi, ô Dieu, Que tes intentions sont impénétrables Et que tes desseins sont incalculables!` },
  { livre: `Psaumes`, chapitre: 139, verset: 18, texte: `Si je me mettais à les dénombrer, Ils surpasseraient tous les grains de sable (qui bordent les mers). Dès que je m’éveille, je suis avec toi.` },
  { livre: `Psaumes`, chapitre: 139, verset: 19, texte: `Puisses-tu, ô Dieu, supprimer l’impie! Hommes sanguinaires, restez loin de moi!` },
  { livre: `Psaumes`, chapitre: 139, verset: 20, texte: `Car tes adversaires profèrent sur toi des discours infâmes. Ils prennent ton nom en vain, (ô Seigneur).` },
  { livre: `Psaumes`, chapitre: 139, verset: 21, texte: `Ne devrais-je pas, Seigneur, les haïr, ceux qui te haïssent Et prendre en dégoût ceux qui te combattent?` },
  { livre: `Psaumes`, chapitre: 139, verset: 22, texte: `Oui, je les déteste d’une haine extrême, Ils sont devenus mes ennemis mêmes.` },
  { livre: `Psaumes`, chapitre: 139, verset: 23, texte: `Sonde-moi, ô Dieu, et connais mon cœur, Examine-moi, comprends mes pensées.` },
  { livre: `Psaumes`, chapitre: 139, verset: 24, texte: `Vois si j’ai choisi la mauvaise route Et ramène-moi dans le droit chemin de l’éternité!` },
  { livre: `Psaumes`, chapitre: 140, verset: 0, texte: `Au chef de chœur. Psaume de David.` },
  { livre: `Psaumes`, chapitre: 140, verset: 1, texte: `Seigneur, délivre-moi des gens méchants! Préserve et sauve-moi des gens violents!` },
  { livre: `Psaumes`, chapitre: 140, verset: 2, texte: `Ils méditent le mal au fond du cœur Et ils cherchent la guerre jour après jour.` },
  { livre: `Psaumes`, chapitre: 140, verset: 3, texte: `Ils aiguisent leur langue comme un serpent, Du venin de vipère est sous leurs lèvres.` },
  { livre: `Psaumes`, chapitre: 140, verset: 4, texte: `Seigneur, garantis-moi des mains impies! Préserve et sauve-moi des gens violents! Ils ont prémédité déjà ma chute!` },
  { livre: `Psaumes`, chapitre: 140, verset: 5, texte: `Ils m’ont dressé des pièges et des collets; Ils ont tendu des cordes et des filets Tout au long de la route pour m’attraper.` },
  { livre: `Psaumes`, chapitre: 140, verset: 6, texte: `Mais j’ai dit au Seigneur: «Tu es mon Dieu! Je te prie d’écouter ma voix plaintive.` },
  { livre: `Psaumes`, chapitre: 140, verset: 7, texte: `Tu es, Seigneur, ma force et mon salut. Tu as casqué ma tête pour le combat.` },
  { livre: `Psaumes`, chapitre: 140, verset: 8, texte: `Ne cède pas, Seigneur à ces méchants! Ne leur accorde pas ce qu’ils désirent! Ne fais pas réussir leurs perfidies, Car ils triompheraient.` },
  { livre: `Psaumes`, chapitre: 140, verset: 9, texte: `Que sur la tête de ceux qui m’environnent Retourne enfin le péché de leurs lèvres!` },
  { livre: `Psaumes`, chapitre: 140, verset: 10, texte: `Que des charbons se déversent sur eux! Que dans le feu, ils soient précipités, Dans une fosse d’où ils ne pourront plus se relever!` },
  { livre: `Psaumes`, chapitre: 140, verset: 11, texte: `Que les mauvaises langues quittent la terre! Que l’homme violent soit pourchassé bien vite».` },
  { livre: `Psaumes`, chapitre: 140, verset: 12, texte: `Je sais que le Seigneur rendra justice aux pauvres; Aux affligés, il fera droit.` },
  { livre: `Psaumes`, chapitre: 140, verset: 13, texte: `Alors, ceux qui sont justes loueront ton nom. Les cœurs droits se tiendront en ta présence.` },
  { livre: `Psaumes`, chapitre: 141, verset: 1, texte: `Psaume de David. Seigneur, je t’ai invoqué, viens en hâte auprès de moi! Prête l’oreille à ma voix quand je crie vers toi!` },
  { livre: `Psaumes`, chapitre: 141, verset: 2, texte: `Considère ma prière, comme une offrande d’encens, Et mes mains tendues vers toi, comme l’oblation du soir.` },
  { livre: `Psaumes`, chapitre: 141, verset: 3, texte: `Exerce ta surveillance sur ma bouche, ô Éternel! Veille aux portes de mes lèvres!` },
  { livre: `Psaumes`, chapitre: 141, verset: 4, texte: `Ne permets pas à mon cœur de s’abandonner au mal Ni de fomenter le crime avec les gens malfaisants! Je ne veux plus partager leurs plaisirs et leurs festins!` },
  { livre: `Psaumes`, chapitre: 141, verset: 5, texte: `Si le juste me reprend, c’est une preuve d’amour. Qu’il me fasse des reproches, c’est un parfum sur ma tête Qu’elle ne refuse pas. Pourtant aux persécutions des méchants J’opposerai, sans me lasser, ma prière.` },
  { livre: `Psaumes`, chapitre: 141, verset: 6, texte: `Que leurs juges soient jetés aux flancs des rochers Et l’on comprendra combien mes paroles étaient agréables.` },
  { livre: `Psaumes`, chapitre: 141, verset: 7, texte: `Tout comme lorsqu’on laboure et qu’on fend la terre, (Leurs) os seront dispersés devant le séjour des morts.` },
  { livre: `Psaumes`, chapitre: 141, verset: 8, texte: `C’est vers toi, Seigneur, mon Maître, que se tournent mes regards; Je cherche en toi mon refuge. N’abandonne pas mon âme!` },
  { livre: `Psaumes`, chapitre: 141, verset: 9, texte: `Préserve-moi des filets qu’ils ont tendus sous mes pas Et des traquenards de ces artisans du mal!` },
  { livre: `Psaumes`, chapitre: 141, verset: 10, texte: `Que les méchants tous ensemble Tombent dans leurs propres pièges Tandis que j’échapperai et poursuivrai mon chemin.` },
  { livre: `Psaumes`, chapitre: 142, verset: 0, texte: `Poème didactique de David qu’il pria quand il était dans la caverne.` },
  { livre: `Psaumes`, chapitre: 142, verset: 1, texte: `À pleine voix, je crie vers le Seigneur. À pleine voix, je supplie le Seigneur.` },
  { livre: `Psaumes`, chapitre: 142, verset: 2, texte: `En sa présence, je déverse ma plainte. En sa présence, j’expose ma détresse.` },
  { livre: `Psaumes`, chapitre: 142, verset: 3, texte: `Quand mon esprit est abattu en moi, C’est toi, (Seigneur,) qui connais mon sentier. Sur mon chemin, ils m’ont tendu des pièges.` },
  { livre: `Psaumes`, chapitre: 142, verset: 4, texte: `Regarde à droite: il n’y a plus personne, Pas même un seul qui veuille me connaître! Je ne sais plus où chercher un refuge Et nul ne veut s’inquiéter de ma vie.` },
  { livre: `Psaumes`, chapitre: 142, verset: 5, texte: `Vers toi, Seigneur, je lance mon appel, Je crie, je dis: «Toi seul es mon abri! Tu es ma part au pays des vivants!` },
  { livre: `Psaumes`, chapitre: 142, verset: 6, texte: `Sois attentif à mes supplications! Je suis si faible, je suis si misérable. Délivre-moi de mes persécuteurs! Ils sont trop forts, bien plus puissants que moi.` },
  { livre: `Psaumes`, chapitre: 142, verset: 7, texte: `Libère-moi, car mon âme est captive, Pour que je puisse rendre hommage à ton nom! Autour de moi, les justes feront cercle Quand tu m’auras comblé de ta faveur».` },
  { livre: `Psaumes`, chapitre: 143, verset: 1, texte: `Psaume de David. Seigneur, écoute lorsque je prie, prête l’oreille à ma demande! Tu es fidèle et tu es juste, réponds-moi donc!` },
  { livre: `Psaumes`, chapitre: 143, verset: 2, texte: `Ne juge pas ton serviteur! Car nul n’est juste devant toi.` },
  { livre: `Psaumes`, chapitre: 143, verset: 3, texte: `Un ennemi cherche à me perdre et il écrase ma vie à terre, Il m’a fait habiter dans les ténèbres Comme les morts des temps passés.` },
  { livre: `Psaumes`, chapitre: 143, verset: 4, texte: `Mon esprit tombe en défaillance. Mon cœur se glace dans ma poitrine.` },
  { livre: `Psaumes`, chapitre: 143, verset: 5, texte: `Je me souviens des jours anciens, Je me redis tout ce que tu as fait. Je réfléchis sur l’œuvre de tes mains.` },
  { livre: `Psaumes`, chapitre: 143, verset: 6, texte: `Me voici devant toi: je tends les mains vers toi, Mon âme a soif de toi comme une terre aride.` },
  { livre: `Psaumes`, chapitre: 143, verset: 7, texte: `Ne tarde pas, Seigneur, Hâte-toi de répondre, car mon esprit défaille. Ne cache pas ta face pour que je ne sois pas Semblable à ceux que l’on enterre.` },
  { livre: `Psaumes`, chapitre: 143, verset: 8, texte: `Dès le matin, fais-moi sentir ta grâce, car j’ai confiance en toi! Fais-moi connaître la voie que je dois suivre, Car mes désirs se concentrent sur toi!` },
  { livre: `Psaumes`, chapitre: 143, verset: 9, texte: `Délivre-moi, Seigneur, de (tous) mes ennemis, Car c’est en toi que je me réfugie!` },
  { livre: `Psaumes`, chapitre: 143, verset: 10, texte: `Enseigne-moi pour que je fasse ta volonté Puisque tu es mon Dieu! Ton bon Esprit me conduira sur un sol aplani.` },
  { livre: `Psaumes`, chapitre: 143, verset: 11, texte: `Pour l’honneur de ton nom, Seigneur, toi qui es juste, Tu me feras revivre, et tu feras sortir mon âme de l’angoisse.` },
  { livre: `Psaumes`, chapitre: 143, verset: 12, texte: `Dans ton amour, tu chasseras mes ennemis, Et tu feras périr tous ceux qui veulent nuire à mon âme Puisque je suis ton serviteur.` },
  { livre: `Psaumes`, chapitre: 144, verset: 1, texte: `De David. Béni soit le Seigneur, lui qui est mon rocher, Qui exerce mes mains pour le combat, Qui prépare mes doigts pour la bataille.` },
  { livre: `Psaumes`, chapitre: 144, verset: 2, texte: `Il est mon bienfaiteur, il est ma forteresse et ma haute retraite, C’est lui qui me libère. Il est mon bouclier où je trouve un abri: Il me soumet les peuples.` },
  { livre: `Psaumes`, chapitre: 144, verset: 3, texte: `Seigneur, qu’est-ce que l’homme pour que tu le connaisses? Et le fils des mortels pour que tu t’en soucies?` },
  { livre: `Psaumes`, chapitre: 144, verset: 4, texte: `Il est semblable au vent, Sa vie est fugitive comme une ombre qui passe.` },
  { livre: `Psaumes`, chapitre: 144, verset: 5, texte: `Seigneur, déploie tes cieux et descends ici-bas! Viens toucher les montagnes et qu’elles soient fumantes!` },
  { livre: `Psaumes`, chapitre: 144, verset: 6, texte: `Décoche des éclairs! Disperse l’ennemi! Envoie sur eux tes flèches et mets-les en déroute!` },
  { livre: `Psaumes`, chapitre: 144, verset: 7, texte: `D’en haut, étends les mains, sauve-moi du danger! Ah, viens me délivrer des eaux tumultueuses, De la main des barbares` },
  { livre: `Psaumes`, chapitre: 144, verset: 8, texte: `Dont la bouche est menteuse Et dont tous les serments ne sont que des parjures.` },
  { livre: `Psaumes`, chapitre: 144, verset: 9, texte: `Je chanterai pour toi, ô Dieu, un chant nouveau, Et je jouerai pour toi sur la harpe à dix cordes,` },
  { livre: `Psaumes`, chapitre: 144, verset: 10, texte: `Car c’est toi qui assures le triomphe des rois, Et c’est toi qui préserves de l’épée meurtrière David, ton serviteur.` },
  { livre: `Psaumes`, chapitre: 144, verset: 11, texte: `Viens m’arracher, (Seigneur,) et viens me délivrer De la main des barbares dont la bouche est menteuse Et dont tous les serments ne sont que des parjures!` },
  { livre: `Psaumes`, chapitre: 144, verset: 12, texte: `Nos fils, dès leur jeune âge, sont pareils à des plants Bien cultivés qui poussent et nos filles ressemblent Aux colonnes sculptées à l’angle d’un palais!` },
  { livre: `Psaumes`, chapitre: 144, verset: 13, texte: `Nos greniers sont tout pleins, ils regorgent de biens De diverses espèces, et le menu bétail se compte par milliers, Même par dix milliers. Il remplit nos campagnes,` },
  { livre: `Psaumes`, chapitre: 144, verset: 14, texte: `Et nos bêtes de somme sont lourdement chargées! Il n’y a, dans nos murs, ni lézarde ni brèche! On n’entend point de cris sur nos places publiques!` },
  { livre: `Psaumes`, chapitre: 144, verset: 15, texte: `Heureux sera le peuple gratifié de tels biens! Heureux sera le peuple dont le Seigneur est Dieu!` },
  { livre: `Psaumes`, chapitre: 145, verset: 1, texte: `Chant de louange. De David. Je t’exalterai, ô mon Dieu, mon Roi, Et je bénirai ton nom à jamais, à perpétuité.` },
  { livre: `Psaumes`, chapitre: 145, verset: 2, texte: `Oui, jour après jour, je te bénirai, Je célébrerai ton nom à jamais, à perpétuité.` },
  { livre: `Psaumes`, chapitre: 145, verset: 3, texte: `Le Seigneur est grand, et très digne de louanges, Sa grandeur est insondable.` },
  { livre: `Psaumes`, chapitre: 145, verset: 4, texte: `De génération en génération, On glorifie tes ouvrages et l’on publie tes exploits.` },
  { livre: `Psaumes`, chapitre: 145, verset: 5, texte: `Je rappellerai l’éclat et la gloire de ta majesté.` },
  { livre: `Psaumes`, chapitre: 145, verset: 6, texte: `Je méditerai le récit de tes merveilles. On s’entretiendra de ta force redoutable. Je raconterai combien tu es grand.` },
  { livre: `Psaumes`, chapitre: 145, verset: 7, texte: `On évoquera ta grande bonté, on chantera ta justice.` },
  { livre: `Psaumes`, chapitre: 145, verset: 8, texte: `Le Seigneur est plein de grâce et de compassion, Lent à la colère et rempli d’amour.` },
  { livre: `Psaumes`, chapitre: 145, verset: 9, texte: `Le Seigneur est bon envers tous les hommes Et plein de tendresse pour toutes ses créatures.` },
  { livre: `Psaumes`, chapitre: 145, verset: 10, texte: `Que toutes tes œuvres te louent, ô Seigneur, Et que ceux qui t’aiment sachent te bénir!` },
  { livre: `Psaumes`, chapitre: 145, verset: 11, texte: `Ils diront la gloire de ta royauté et proclameront ta force` },
  { livre: `Psaumes`, chapitre: 145, verset: 12, texte: `En faisant connaître aux hommes tes actes puissants, L’éclat et la gloire de ta royauté.` },
  { livre: `Psaumes`, chapitre: 145, verset: 13, texte: `Tu règnes sur tous les siècles et ta seigneurie S’étend d’âge en âge. Le Seigneur est toujours vrai et fidèle à ses promesses, Il est plein d’amour dans toutes ses œuvres.` },
  { livre: `Psaumes`, chapitre: 145, verset: 14, texte: `Le Seigneur soutient tous ceux qui faiblissent Et il rend confiance à tous ceux qui sont courbés.` },
  { livre: `Psaumes`, chapitre: 145, verset: 15, texte: `Les regards de tous sont tournés vers toi, Et tu donnes à chacun ce qu’il faut pour se nourrir Au temps opportun.` },
  { livre: `Psaumes`, chapitre: 145, verset: 16, texte: `Tu ouvres ta main et tu rassasies, Dans ta bienveillance, tout être vivant.` },
  { livre: `Psaumes`, chapitre: 145, verset: 17, texte: `Le Seigneur est juste dans toutes ses voies, Il est plein d’amour dans toutes ses œuvres.` },
  { livre: `Psaumes`, chapitre: 145, verset: 18, texte: `Le Seigneur est proche de ceux qui l’invoquent De tous ceux qui, dans leur cœur, l’invoquent sincèrement.` },
  { livre: `Psaumes`, chapitre: 145, verset: 19, texte: `Il accomplit les désirs de ceux qui l’adorent, Il écoutera leur cri et les sauvera.` },
  { livre: `Psaumes`, chapitre: 145, verset: 20, texte: `Le Seigneur protège tous ceux qui l’aiment vraiment, Mais il détruit les méchants.` },
  { livre: `Psaumes`, chapitre: 145, verset: 21, texte: `Je proclamerai la louange du Seigneur et toutes les créatures Béniront son nom très saint dans toute l’éternité.` },
  { livre: `Psaumes`, chapitre: 146, verset: 1, texte: `Louez le Seigneur! Toi, mon âme, chante les louanges du Seigneur!` },
  { livre: `Psaumes`, chapitre: 146, verset: 2, texte: `Je veux louer le Seigneur tant que je vivrai, Je veux célébrer mon Dieu tant que je serai.` },
  { livre: `Psaumes`, chapitre: 146, verset: 3, texte: `Ne mettez pas votre foi dans les puissants de ce monde, Car ce ne sont que des hommes incapables de sauver!` },
  { livre: `Psaumes`, chapitre: 146, verset: 4, texte: `Dès qu’ils ont poussé leur dernier soupir, Ils retournent à la terre et, au même instant, Leurs projets s’évanouissent.` },
  { livre: `Psaumes`, chapitre: 146, verset: 5, texte: `Heureux est celui qui a pour appui Le Dieu de Jacob et dont l’espérance Est dans le Seigneur son Dieu:` },
  { livre: `Psaumes`, chapitre: 146, verset: 6, texte: `C’est le Dieu qui a créé les cieux, la terre et la mer Avec tout ce qui s’y trouve. Il garde à jamais sa fidélité.` },
  { livre: `Psaumes`, chapitre: 146, verset: 7, texte: `Il fait droit aux opprimés; il nourrit les affamés; Le Seigneur relâche ceux qui étaient en prison.` },
  { livre: `Psaumes`, chapitre: 146, verset: 8, texte: `Le Seigneur ouvre les yeux de ceux qui ne voyaient pas. Le Seigneur redresse ceux qui sont courbés. Le Seigneur aime les justes.` },
  { livre: `Psaumes`, chapitre: 146, verset: 9, texte: `Il protège l’étranger, le Seigneur soutient L’orphelin comme la veuve, Mais il fait dévier la voie des méchants.` },
  { livre: `Psaumes`, chapitre: 146, verset: 10, texte: `Le Seigneur est Roi pour l’éternité. Il est ton Dieu, ô Sion, de génération en génération. Louez le Seigneur!` },
  { livre: `Psaumes`, chapitre: 147, verset: 1, texte: `Loué soit le Seigneur! Il est bon de chanter des psaumes à (la gloire de) notre Dieu, Car la louange est douce, et elle lui revient.` },
  { livre: `Psaumes`, chapitre: 147, verset: 2, texte: `Le Seigneur rebâtit la cité de Jérusalem, Il y rassemblera les bannis d’Israël.` },
  { livre: `Psaumes`, chapitre: 147, verset: 3, texte: `C’est lui qui guérit ceux Qui ont le cœur brisé, qui panse leurs blessures!` },
  { livre: `Psaumes`, chapitre: 147, verset: 4, texte: `C’est lui qui détermine le nombre des étoiles, Il les appelle toutes et leur donne leur nom.` },
  { livre: `Psaumes`, chapitre: 147, verset: 5, texte: `Notre Seigneur est grand, Son pouvoir est immense, sa science est infinie.` },
  { livre: `Psaumes`, chapitre: 147, verset: 6, texte: `Le Seigneur affermit les pauvres, Mais il renverse les méchants et les abaisse jusqu’à terre.` },
  { livre: `Psaumes`, chapitre: 147, verset: 7, texte: `Chantez pour le Seigneur votre reconnaissance! Célébrez notre Dieu aux sons de la cithare!` },
  { livre: `Psaumes`, chapitre: 147, verset: 8, texte: `Il couvre les cieux de nuages, Prépare la pluie pour la terre, fait germer l’herbe sur les monts.` },
  { livre: `Psaumes`, chapitre: 147, verset: 9, texte: `Il donne la pâture aux troupeaux de bétail, Aux petits du corbeau que la faim fait crier.` },
  { livre: `Psaumes`, chapitre: 147, verset: 10, texte: `Il ne prend pas plaisir aux chevaux vigoureux, La force du guerrier ne l’intéresse pas.` },
  { livre: `Psaumes`, chapitre: 147, verset: 11, texte: `Le Seigneur prend plaisir en ceux qui le révèrent, En ceux qui se confient à sa miséricorde.` },
  { livre: `Psaumes`, chapitre: 147, verset: 12, texte: `Ô toi, Jérusalem, célèbre le Seigneur! Célèbre les louanges de ton Dieu, ô Sion!` },
  { livre: `Psaumes`, chapitre: 147, verset: 13, texte: `Car il a renforcé les verrous de tes portes, Il a béni tes fils qui habitent chez toi,` },
  { livre: `Psaumes`, chapitre: 147, verset: 14, texte: `Il fait régner la paix sur tout ton territoire, Et il te rassasie de la fleur du froment.` },
  { livre: `Psaumes`, chapitre: 147, verset: 15, texte: `Il envoie à la terre ses ordres: Sa parole y parvient aussitôt.` },
  { livre: `Psaumes`, chapitre: 147, verset: 16, texte: `Il fait tomber la neige: on dirait de la laine, Il saupoudre de givre: on dirait de la cendre.` },
  { livre: `Psaumes`, chapitre: 147, verset: 17, texte: `Il jette par poignées ses glaçons en cristaux, Mais qui peut supporter sa froidure et son gel?` },
  { livre: `Psaumes`, chapitre: 147, verset: 18, texte: `Dès qu’il en donne l’ordre, aussitôt, tout dégèle, S’il déchaîne son vent, à nouveau, les eaux coulent.` },
  { livre: `Psaumes`, chapitre: 147, verset: 19, texte: `C’est lui qui fit connaître sa parole à Jacob Et ses commandements, ses lois à Israël.` },
  { livre: `Psaumes`, chapitre: 147, verset: 20, texte: `Il n’a traité ainsi aucune autre nation, Aussi ses volontés leur restent inconnues. Loué soit le Seigneur!` },
  { livre: `Psaumes`, chapitre: 148, verset: 1, texte: `Louez le Seigneur Louez-le du haut des cieux! Louez-le, dans les hauteurs!` },
  { livre: `Psaumes`, chapitre: 148, verset: 2, texte: `Louez-le, vous tous ses anges! Louez-le, vous ses armées!` },
  { livre: `Psaumes`, chapitre: 148, verset: 3, texte: `Louez-le, soleil et lune! Louez-le, astres brillants!` },
  { livre: `Psaumes`, chapitre: 148, verset: 4, texte: `Louez-le, ô cieux des cieux, Et vous, espaces sans fin au-dessus de tous les cieux!` },
  { livre: `Psaumes`, chapitre: 148, verset: 5, texte: `Qu’ils louent le nom du Seigneur! Car il commanda et tout fut créé.` },
  { livre: `Psaumes`, chapitre: 148, verset: 6, texte: `Il a tout fixé pour l’éternité Selon des lois immuables que nul ne modifiera.` },
  { livre: `Psaumes`, chapitre: 148, verset: 7, texte: `Louez le Seigneur du sein de la terre, Vous, monstres marins, et vous tous, abîmes,` },
  { livre: `Psaumes`, chapitre: 148, verset: 8, texte: `Feu et grêle et neige et brume, Vents d’ouragan et cyclones qui exécutez ses ordres!` },
  { livre: `Psaumes`, chapitre: 148, verset: 9, texte: `Vous, montagnes et collines, arbres fruitiers, tous les cèdres,` },
  { livre: `Psaumes`, chapitre: 148, verset: 10, texte: `Gibier et bêtes de somme, tout ce qui rampe et qui vole,` },
  { livre: `Psaumes`, chapitre: 148, verset: 11, texte: `Rois du monde et tous les peuples, princes, juges de la terre,` },
  { livre: `Psaumes`, chapitre: 148, verset: 12, texte: `Jeunes gens et jeunes filles, les vieillards et les enfants,` },
  { livre: `Psaumes`, chapitre: 148, verset: 13, texte: `Qu’ils louent le nom du Seigneur! Car son nom seul est sublime Et sa majesté rayonne sur la terre et dans les cieux.` },
  { livre: `Psaumes`, chapitre: 148, verset: 14, texte: `Il a relevé la puissance de son peuple. C’est un sujet de louanges pour tous ceux qui l’aiment, Pour les enfants d’Israël et pour tout le peuple, Le peuple qui lui est proche. Louez le Seigneur!` },
  { livre: `Psaumes`, chapitre: 149, verset: 1, texte: `Loué soit le Seigneur! Chantez pour le Seigneur un cantique nouveau! Célébrez ses louanges dans l’assemblée des siens!` },
  { livre: `Psaumes`, chapitre: 149, verset: 2, texte: `Israël, mets ta joie en celui qui t’a fait! Que les fils de Sion éclatent d’allégresse à cause de leur roi!` },
  { livre: `Psaumes`, chapitre: 149, verset: 3, texte: `Qu’ils célèbrent son nom par des chœurs et des danses, Qu’ils jouent en son honneur avec le tambourin Et au son des cithares!` },
  { livre: `Psaumes`, chapitre: 149, verset: 4, texte: `Car le Seigneur chérit son peuple bien-aimé, Et il accorde aux humbles le salut pour parure.` },
  { livre: `Psaumes`, chapitre: 149, verset: 5, texte: `Que les fidèles soient tout triomphants de gloire! Qu’ils chantent sur leur couche,` },
  { livre: `Psaumes`, chapitre: 149, verset: 6, texte: `Qu’à pleine voix ils chantent les éloges de Dieu Et tiennent dans leurs mains l’épée à deux tranchants!` },
  { livre: `Psaumes`, chapitre: 149, verset: 7, texte: `Ainsi, ils tireront vengeance des nations Et ils infligeront leur châtiment aux peuples,` },
  { livre: `Psaumes`, chapitre: 149, verset: 8, texte: `Ils lieront leurs rois avec de lourdes chaînes Et mettront à leurs princes des entraves de fer` },
  { livre: `Psaumes`, chapitre: 149, verset: 9, texte: `Pour accomplir sur eux le jugement prescrit. C’est l’honneur qui revient à chacun des fidèles. Loué soit le Seigneur!` },
  { livre: `Psaumes`, chapitre: 150, verset: 1, texte: `Louez l’Éternel! Louez le Dieu fort Dans son sanctuaire! Louez-le au ciel, Siège de sa gloire!` },
  { livre: `Psaumes`, chapitre: 150, verset: 2, texte: `Louez-le pour ses hauts faits, Louez-le pour sa grandeur Qui est infinie!` },
  { livre: `Psaumes`, chapitre: 150, verset: 3, texte: `Louez-le au son du cor, Louez-le avec le luth Et sur la cithare!` },
  { livre: `Psaumes`, chapitre: 150, verset: 4, texte: `Louez-le avec des danses Et au son des tambourins! Louez-le avec la harpe Et avec la flûte!` },
  { livre: `Psaumes`, chapitre: 150, verset: 5, texte: `Louez-le par les cymbales Bien retentissantes! Louez-le par les cymbales Des jours de triomphe!` },
  { livre: `Psaumes`, chapitre: 150, verset: 6, texte: `Que tout ce qui vit, Tout ce qui respire Puisse louer le Seigneur! Louez l’Éternel!` },
];

export const modulelouangevivante: ModuleVersion = {
  version: versionlouangevivante,
  versets,
};
